// Generated by scripts/gen-l10n.mjs (articles, id) — 不要手改;改翻譯請改 scripts/out/l10n/id/ 再重 build。
window.ARTICLES_L10N=window.ARTICLES_L10N||{};window.ARTICLES_L10N["id"]={"a-n5-1":{"title":"Satu Hariku","topic":"Kehidupan sehari-hari","trans":["Setiap pagi aku bangun jam enam. Aku cuci muka, lalu sarapan.","Jam setengah delapan aku berangkat dari rumah dan naik kereta ke kantor. Kerjanya mulai dari jam sembilan.","Saat makan siang, aku makan ramen di kedai dekat kantor. Enak sekali.","Jam enam sore pekerjaanku selesai. Aku pulang ke rumah dan memasak makan malam.","Malam hari, aku belajar bahasa Jepang sebentar, lalu tidur jam sebelas.","Di akhir pekan hampir tidak ada pekerjaan. Aku jalan-jalan di taman bersama teman, nonton film, dan sebagainya.","Meski setiap hari sibuk, bahasa Jepangku makin lama makin bagus sedikit demi sedikit, dan aku senang."],"vocab":["bangun (tidur)","wajah","perusahaan, kantor","siang","membuat, memasak"],"grammar":[{"t":"に (waktu)","note":"Untuk menunjuk waktu tertentu, tambahkan 「に」: 六時に、十一時に。「毎朝」 adalah keterangan waktu relatif, jadi tidak pakai に."},{"t":"で (kendaraan/tempat)","note":"Alat transportasi pakai で: 電車で. Tempat berlangsungnya suatu kegiatan juga pakai で: 店で食べる."},{"t":"Penyambung bentuk て","note":"Untuk menyambung satu kegiatan ke kegiatan berikutnya, pakai bentuk て: 顔を洗って、朝ごはんを食べます。"}]},"a-n5-2":{"title":"日本の朝ごはん","topic":"Budaya","trans":["Sarapan tradisional Jepang adalah nasi dan sup miso.","Selain itu, ikan bakar dan telur juga sering dimakan. Nori (rumput laut kering) juga populer.","Belakangan ini, sarapan dengan roti dan kopi juga banyak. Terutama disukai anak muda.","Di pagi hari yang sibuk, ada juga orang yang hanya makan onigiri. Apa sarapan di negaramu?","Sarapan roti dengan kopi memang populer, tapi aku tetap lebih suka nasi dan sup miso.","Kalau sarapan dengan cukup di pagi hari, kita bisa menjalani seharian dengan penuh semangat."],"vocab":["tradisional","memanggang, membakar","populer, disukai banyak orang","muda","sibuk"],"grammar":[{"t":"や (penyebutan sebagian)","note":"Menyebut beberapa contoh saja, dan menyiratkan masih ada yang lain: 魚や卵、パンやコーヒー。"},{"t":"だけ","note":"Artinya \"hanya\": おにぎりだけ = hanya onigiri."},{"t":"が人気があります","note":"Artinya \"~ populer\"; hal yang populer ditandai dengan が."}]},"a-n4-1":{"title":"Hanami (Melihat Bunga Sakura)","topic":"Budaya","trans":["Begitu musim semi tiba, bunga sakura mekar di berbagai penjuru Jepang.","Orang-orang berkumpul di taman, lalu makan bekal dan minum sake di bawah pohon sakura. Kegiatan ini disebut 「お花見」.","Sakura sangat indah, tetapi masa mekarnya singkat, hanya sekitar satu minggu. Karena itu, semua orang menantikan musim ini.","Sakura yang disinari lampu di malam hari juga indah. Kamu harus coba melihatnya sekali saja.","Tradisi hanami sudah ada sejak dulu. Orang zaman dahulu juga menikmati musim semi sambil memandangi bunga sakura.","Namun, ada juga masalah seperti menyerobot tempat dan sampah, jadi penting untuk menjaga sopan santun."],"vocab":["mekar (bunga)","berkumpul","periode, masa","dinanti-nantikan, kesenangan","indah"],"grammar":[{"t":"~と (syarat yang pasti)","note":"Artinya \"begitu ~ maka ~\", hasil yang terjadi secara alami: 春になると、桜が咲く。"},{"t":"~たり~たり","note":"Menyebutkan beberapa contoh tindakan dan menyiratkan masih ada yang lain: 食べたり飲んだりする。"},{"t":"~てみる","note":"Mencoba melakukan sesuatu: 行ってみてください。"}]},"a-n4-3":{"title":"Menyusuri Kyoto, Kota Kuno","topic":"Wisata","trans":["Kyoto adalah kota yang lebih dari seribu tahun lalu menjadi ibu kota Jepang. Sampai sekarang, masih banyak kuil dan tempat suci kuno yang bertahan di sana.","Sakura di musim semi dan daun merah di musim gugur sangat indah, dan setiap musim menampilkan wajah yang berbeda. Karena itu, berapa kali pun kamu berkunjung, kamu tidak akan bosan.","Saat jalan-jalan di Kyoto, kami sarankan berjalan santai tanpa terburu-buru. Kalau berbelok ke gang kecil, kamu bisa menemukan kuil yang tenang dan kafe bergaya zaman dulu.","Tidak hanya tempat wisata terkenal, kalau kamu mampir ke toko-toko kecil yang sering didatangi warga lokal, kamu akan melihat pesona Kyoto yang sebenarnya.","Kyoto menampilkan wajah yang berbeda di setiap musim. Sakura di musim semi dan daun merah di musim gugur sangat indah.","Menjaga bangunan-bangunan tua sambil tetap menerima budaya baru, itulah pesona Kyoto."],"vocab":[{"w":"首都","m":"ibu kota"},{"w":"残る","m":"tersisa, bertahan"},{"w":"訪れる","m":"mengunjungi"},{"w":"曲がる","m":"berbelok"},{"w":"魅力","m":"pesona, daya tarik"}],"grammar":[{"t":"~ごとに","note":"Artinya \"setiap ~\": 季節ごとに = setiap musim."},{"t":"~ても(pengandaian)","note":"Artinya \"meskipun ~\": 何度訪れてもあきない (berapa kali pun berkunjung tidak akan bosan)."},{"t":"~だけでなく","note":"Artinya \"tidak hanya ~ (tetapi juga)\": 観光地だけでなく、小さな店も (tidak hanya tempat wisata, tetapi juga toko-toko kecil)."}]},"a-n3-1":{"title":"Kemudahan Minimarket","topic":"Kehidupan","trans":["Minimarket di Jepang buka 24 jam dan sangat praktis.","Tidak hanya makanan dan minuman, kamu juga bisa membeli majalah dan barang kebutuhan sehari-hari. Selain itu, kamu juga bisa membayar tagihan listrik, air, dan sebagainya, serta mengirim paket.","Karena ada ATM bank juga, kamu bisa menarik uang kapan saja. Ada juga mesin yang bisa dipakai untuk fotokopi dan memesan tiket.","Berkat layanan-layanan ini, minimarket telah menjadi bagian yang tidak tergantikan dalam kehidupan kita.","Namun, di balik kemudahan itu, tersembunyi juga masalah seperti kerja keras orang-orang yang bekerja 24 jam dan limbah makanan.","Jangan menganggap kemudahan itu sebagai hal yang biasa. Aku ingin juga memikirkan orang-orang yang menopang sistem tersebut."],"vocab":[{"w":"便利","m":"praktis, mudah"},{"w":"支払い","m":"pembayaran"},{"w":"発送","m":"pengiriman"},{"w":"欠かせない","m":"tidak tergantikan, tak bisa dilepaskan"},{"w":"存在","m":"keberadaan, sosok"}],"grammar":[{"t":"~だけでなく","note":"Artinya \"tidak hanya ~ (tetapi juga)\"."},{"t":"~ので","note":"Artinya \"karena ~\", terdengar lebih objektif dan lembut: ATM があるので (karena ada ATM)."},{"t":"~おかげで","note":"Artinya \"berkat ~\", untuk sebab yang positif: サービスのおかげで (berkat layanan)."}]},"a-n3-2":{"title":"Hal yang Kupelajari dari Hidup Sendiri","topic":"Kehidupan","trans":["Setelah masuk universitas, aku mulai tinggal sendiri untuk pertama kalinya. Awalnya aku senang karena bisa bebas.","Tapi setelah benar-benar menjalaninya, aku harus mengurus semuanya sendiri, mulai dari memasak, mencuci, sampai bersih-bersih. Aku jadi sadar lagi betapa banyak hal yang selama ini dilakukan orang tuaku untukku.","Aku juga mulai memikirkan cara menggunakan uang. Dengan uang bulanan yang terbatas, kita jadi secara alami bisa menilai mana yang benar-benar dibutuhkan.","Hidup sendiri memang banyak susahnya, tapi kita jadi mampu mengurus diri sendiri. Dan yang terpenting, aku jadi jauh lebih memahami betapa berharganya keluarga dibanding dulu.","Hidup sendiri memang kadang terasa sepi, tapi sebagai gantinya kita bisa memakai waktu kita dengan bebas.","Aku menyadari betapa berharganya keluarga juga baru setelah mulai hidup terpisah dari mereka."],"vocab":["hidup sendiri (tinggal sendiri)","mencuci pakaian","sekali lagi, lagi","penilaian, keputusan","patut disyukuri, berharga"],"grammar":[{"t":"~てみると","note":"「setelah benar-benar mencoba ~, (ternyata)」: 暮らしてみると。"},{"t":"~なければならない","note":"「harus ~」, menyatakan kewajiban: 自分でやらなければならない。"},{"t":"~ようになる","note":"「jadi ~」, perubahan yang terjadi secara alami: 考えるようになった。"}]},"a-n3-3":{"title":"Budaya Sentō (Pemandian Umum)","topic":"Budaya","trans":["Sentō adalah pemandian umum yang dipakai ramai-ramai. Dulu banyak orang yang di rumahnya tidak ada kamar mandi, jadi sentō adalah tempat yang tidak bisa dilepaskan dari kehidupan sehari-hari.","Seiring kamar mandi pribadi makin umum di rumah-rumah, jumlah sentō terus berkurang. Tapi belakangan ini, daya tariknya dinilai kembali.","Berendam pelan-pelan di bak yang luas membuat bukan hanya tubuh, tapi juga hati ikut rileks. Kadang percakapan pun mengalir begitu saja dengan orang tak dikenal yang duduk di sebelah kita.","Mungkin karena terlalu mengejar kemudahan, kita perlahan-lahan kehilangan hubungan dengan sesama. Di zaman seperti ini, sentō adalah tempat yang mengingatkan kita pada jarak antarmanusia yang hangat.","Sentō bukan sekadar tempat untuk membersihkan badan, tapi juga tempat warga sekitar bertemu dan bertegur sapa.","Sekarang, ketika hampir setiap rumah punya kamar mandi, jumlah sentō memang menurun, tetapi banyak juga orang yang kembali menghargai kehangatannya."],"vocab":["umum","menyebar, menjadi umum","menilai kembali, melihat dengan cara baru","ikatan, hubungan","jarak"],"grammar":[{"t":"~とは","note":"「yang disebut ~ (adalah)」, untuk membuat definisi: 銭湯とは~のことだ。"},{"t":"~ていく","note":"「makin lama makin ~」, tren perubahan: 減っていった。"},{"t":"~つつある","note":"「sedang perlahan ~」, gaya tulisan: 失いつつある。"}]},"a-n3-4":{"title":"Angka Kelahiran yang Terus Menurun","topic":"Berita","trans":["Saat ini jumlah anak di Jepang terus berkurang. Fenomena ini disebut 「少子化」 (penurunan angka kelahiran).","Penyebabnya tidak hanya satu. Makin banyak orang yang tidak menikah, beban biaya membesarkan anak yang besar, serta sulitnya menyeimbangkan pekerjaan dan pengasuhan anak, dan berbagai alasan lain saling bertumpuk.","Kalau anak berkurang, jumlah orang yang bekerja di masa depan juga ikut berkurang. Akibatnya, kekuatan ekonomi bisa melemah, atau sistem yang menopang para lansia bisa sulit dipertahankan.","Pemerintah sedang menjalankan berbagai langkah, tetapi hasilnya belum cukup. Bagaimana seluruh masyarakat menciptakan lingkungan yang mudah untuk membesarkan anak sedang diuji.","Konon, latar belakang penurunan angka kelahiran adalah besarnya beban untuk menikah dan membesarkan anak.","Kalau terus begini, jumlah pekerja akan berkurang, dan menopang seluruh masyarakat akan menjadi sulit."],"vocab":["berkurang","beban","menyeimbangkan dua hal sekaligus (mis. kerja dan keluarga)","menopang","langkah penanggulangan"],"grammar":[{"t":"~続ける","note":"「terus ~」: 減り続けている。"},{"t":"~たり~たりする","note":"Menyebutkan beberapa contoh kemungkinan keadaan: 弱くなったり、立ちゆかなくなったり。"},{"t":"~おそれがある","note":"「ada kekhawatiran/kemungkinan ~」, untuk hal negatif: 立ちゆかなくなるおそれがある。"}]},"a-n3-5":{"title":"飲みニケーション","topic":"Tempat Kerja","trans":["Di perusahaan Jepang, sering kali orang pergi minum bersama rekan kerja atau atasan setelah bekerja. Kebiasaan ini disebut 「飲みニケーション」 (komunikasi sambil minum).","Di acara minum, orang bisa mengungkapkan isi hati yang biasanya sulit dikatakan, dan bisa mengobrol santai dengan atasan. Banyak orang juga menganggapnya kesempatan bagus untuk mempererat hubungan.","Di sisi lain, di kalangan generasi muda, makin banyak yang berpikir, 「仕事のあとの時間は自分のために使いたい」 (ingin memakai waktu setelah kerja untuk diri sendiri). Tidak sedikit pula yang merasa keberatan kalau dipaksa ikut.","Sekarang cara kerja dan nilai-nilai hidup makin beragam, sehingga bentuk 飲みニケーション pun mungkin sedikit demi sedikit sedang berubah.","Namun, di antara anak muda zaman sekarang, makin banyak yang ingin memisahkan pekerjaan dan kehidupan pribadi dengan jelas.","Idealnya, kepercayaan bisa dibangun lewat obrolan sehari-hari tanpa perlu bergantung pada alkohol."],"vocab":["rekan kerja","isi hati yang sebenarnya","santai, tidak kaku","paksaan","beragam"],"grammar":[{"t":"~にくい","note":"「sulit ~」: 言いにくい。"},{"t":"一方で","note":"「di sisi lain」, untuk kontras: ~という人も多い。一方で、~。"},{"t":"~つつある","note":"「sedang perlahan ~」: 変わりつつある。"}]},"a-n2-1":{"title":"Perubahan Cara Bekerja","topic":"Masyarakat","trans":["Dalam beberapa tahun terakhir, seiring berkembangnya internet, cara bekerja berubah drastis.","Semakin banyak perusahaan yang menerapkan \"telework\", yaitu bekerja dari rumah tanpa pergi ke kantor. Waktu perjalanan ke tempat kerja memang berkurang, tetapi di sisi lain muncul masalah: batas antara pekerjaan dan kehidupan pribadi jadi sulit dibedakan.","Selain itu, semakin banyak juga orang yang bekerja dengan mengatur waktunya sendiri, bukan dengan jam yang sudah ditentukan.","Menyesuaikan diri dengan perubahan seperti ini, kita juga perlu terus memikirkan cara bekerja yang baru.","Seiring meluasnya telework, kebebasan dalam memilih tempat dan waktu bekerja meningkat; namun di sisi lain, muncul pula tantangan berupa batas antara pekerjaan dan kehidupan pribadi yang jadi kabur.","Ke depannya, yang dibutuhkan adalah masyarakat yang memungkinkan setiap orang memilih cara bekerja yang cocok untuk dirinya."],"vocab":["perkembangan","menerapkan, mengadopsi","pembedaan, perbedaan","penyesuaian, pengaturan","perlu, kebutuhan"],"grammar":[{"t":"~にともなって","note":"「seiring ~」, menunjukkan perubahan yang berjalan bersamaan: 発達にともなって."},{"t":"一方で","note":"「di sisi lain」, mengontraskan dua sisi: sisi baik dan sisi buruk."},{"t":"~ていく","note":"「terus ~ (ke depan)」, menunjukkan kelanjutan: 考えていく必要がある."}]},"a-n2-2":{"title":"Soal \"Membaca Suasana\"","topic":"Budaya","trans":["Dalam bahasa Jepang ada ungkapan 「空気を読む」 (membaca suasana). Artinya peka terhadap suasana di tempat itu dan perasaan lawan bicara, lalu bertindak dengan tepat meski tidak dikatakan secara jelas.","Misalnya, saat semua orang di rapat setuju, butuh keberanian bagi satu orang saja untuk menyampaikan pendapat yang berbeda. Kebanyakan orang akan \"membaca suasana\" dan sengaja menahan diri untuk tidak bicara.","Kepekaan ini sudah lama berguna untuk menghindari benturan antarmanusia dan menjaga keharmonisan kelompok. Namun di sisi lain, ada juga masalah: pendapat yang benar-benar dibutuhkan jadi tidak bisa disampaikan, dan suara kelompok minoritas pun tenggelam.","Kemampuan membaca suasana memang salah satu ciri khas masyarakat Jepang. Tapi bukankah keberanian untuk sesekali tidak membaca suasana dan bersuara juga patut dihargai?","Membaca suasana bisa menjadi bentuk kebaikan hati karena peduli pada orang lain, tetapi kalau berlebihan, kita jadi tidak bisa menyampaikan pendapat sendiri.","Yang penting mungkin adalah keseimbangan antara menyesuaikan diri dengan sekitar dan menyampaikan pikiran sendiri."],"vocab":["suasana","peka, menangkap (perasaan)","benturan, konflik","harmoni, keselarasan","ciri khas"],"grammar":[{"t":"~うえで","note":"「dalam hal ~ / saat ~」: 調和を保つうえで役立つ."},{"t":"その反面","note":"「di sisi lain, sebaliknya」: 役立つ。その反面、問題もある."},{"t":"~べきではないだろうか","note":"「bukankah seharusnya ~?」, cara halus untuk menyatakan pendapat: 大切にされるべきではないか."}]},"a-n5-3":{"title":"Foto Keluarga","topic":"Keluarga","trans":["Ini foto keluargaku. Semuanya ada lima orang.","Yang di tengah adalah ayah dan ibuku. Ayahku karyawan kantoran, dan ibuku guru.","Yang di sebelah kanan adalah kakak laki-lakiku. Dia mahasiswa dan sangat jago main sepak bola.","Anak kecil di sebelah kiri adalah adik perempuanku. Usianya sembilan tahun dan dia suka menggambar.","Semua anggota keluargaku sangat suka anjing. Yang ada di depan foto adalah anjing kami, 「マロ」.","Di hari libur, kami sering pergi ke taman bersama-sama dan berfoto.","Meskipun tinggal berjauhan, aku menelepon keluarga sebulan sekali. Keluarga adalah hartaku yang paling berharga."],"vocab":["keluarga","karyawan kantoran","mahasiswa","suka","harta berharga"],"grammar":[{"t":"〜で (menyambung kalimat)","note":"Nomina + で bisa menyambung dua kalimat: 「ちちは会社員で、ははは先生です」. Artinya menjelaskan dua hal secara berurutan, mirip \"dan\" atau koma dalam bahasa Indonesia."},{"t":"〜が (objek kemampuan/kesukaan)","note":"Objek kemampuan atau kesukaan ditandai dengan が: 「サッカーが上手」「犬が好き」."},{"t":"〜のが","note":"Verba + のが mengubah suatu kegiatan menjadi nomina: 「絵をかくのが好き」 (suka menggambar)."}]},"a-n5-4":{"title":"Belanja di Minimarket","topic":"Kehidupan","trans":["Aku pergi ke minimarket setiap hari. Letaknya di sebelah kantor, jadi sangat praktis.","Pagi hari aku membeli onigiri dan kopi. Totalnya sekitar tiga ratus yen.","Di minimarket, kamu juga bisa membayar tagihan listrik dan air.","Kamu juga bisa mengirim paket dan menarik uang tunai.","Malam hari, kalau perut lapar, aku membeli oden yang hangat. Di musim dingin oden sangat populer.","Akhir-akhir ini petunjuk dalam bahasa asing juga makin banyak, jadi ramah bagi orang yang datang dari luar negeri.","Meski tokonya kecil, kita bisa melakukan banyak hal di sana, dan minimarket tidak tergantikan dalam kehidupan di Jepang."],"vocab":["praktis, nyaman","membayar","mengirim, mengeluarkan","populer, digemari","kehidupan"],"grammar":[{"t":"〜ことができる","note":"Verba bentuk kamus + ことができる menyatakan kemampuan/kemungkinan (bisa): 「はらうことができる」."},{"t":"〜たり〜たりする","note":"Menyebutkan beberapa contoh kegiatan: 「出したり、おろしたりする」 (mengirim paket, menarik uang, dan sebagainya)."},{"t":"〜ので","note":"ので dipakai untuk alasan yang objektif: 「となりにあるので、べんりです」 (karena ada di sebelah, jadi praktis)."}]},"a-n2-3":{"title":"Lapor, Kabari, Konsultasi","topic":"Dunia Kerja","trans":["Begitu masuk perusahaan Jepang, hal pertama yang diajarkan adalah pentingnya 「報連相(ほうれんそう)」. Ini adalah singkatan yang diambil dari huruf awal 「報告・連絡・相談」 (lapor, kabari, konsultasi).","Kamu 「melapor」 kepada atasan tentang perkembangan pekerjaan, 「mengabari」 orang-orang terkait soal informasi yang dibutuhkan, dan 「berkonsultasi」 sedini mungkin saat ragu mengambil keputusan. Bisa tidaknya kamu melakukan ini sangat menentukan lancar tidaknya pekerjaan.","Kalau kamu memendam masalah sendirian dan terlambat melapor, kesalahan kecil bisa berkembang menjadi masalah besar. Sebaliknya, kalau kamu rajin berbagi informasi, orang-orang di sekitarmu bisa cepat membantu.","Hōrensō bukan sekadar aturan. Saat bekerja dalam tim, ini adalah komunikasi dasar untuk membangun rasa saling percaya.","Di tempat kerja yang hōrensō-nya tidak berjalan baik, kesalahan kecil mudah berkembang menjadi masalah besar.","Sebaliknya, rajin berbagi informasi akan meningkatkan kepercayaan dan efisiensi seluruh tim."],"vocab":[{"w":"具合","m":"keadaan, kondisi"},{"w":"迷う","m":"ragu, bingung"},{"w":"抱え込む","m":"memikul sendirian, memendam sendiri"},{"w":"信頼","m":"kepercayaan"},{"w":"築く","m":"membangun, membina"}],"grammar":[{"t":"~かどうか","note":"Artinya \"apakah ~ atau tidak\" (kalimat tanya tidak langsung): できるかどうかで変わる。"},{"t":"~かねない","note":"Artinya \"bisa jadi ~ (hal buruk)\": トラブルに発展しかねない。"},{"t":"~うえで","note":"Artinya \"dalam hal ~, saat ~\": チームで働くうえで。"}]},"a-n2-4":{"title":"Memikirkan Dampak Pariwisata Berlebihan","topic":"Wisata","trans":["Belakangan ini, tempat wisata populer didatangi banyak wisatawan dari dalam dan luar negeri. Di satu sisi pariwisata membawa keuntungan besar bagi daerah, di sisi lain juga memunculkan masalah yang disebut 「観光公害」 (dampak buruk pariwisata, overtourism).","Misalnya, jalanan penuh sesak oleh wisatawan sampai warga tidak bisa lewat, serta sampah dan pelanggaran etika makin bertambah. Kehidupan orang-orang yang dulu hidup tenang pun jadi terganggu.","Menghadapi masalah ini, mulai muncul daerah yang membatasi jumlah pengunjung dan menerapkan pajak wisata. Namun, kalau aturan diperketat terlalu jauh, daya tarik wisata itu sendiri bisa hilang.","Yang penting mungkin adalah pengunjung tidak lupa menghormati warga setempat. Justru karena menghargai budaya dan aturan di tempat itu, pariwisata bisa menjadi sesuatu yang berharga bagi wisatawan maupun warga, bukan?","Di satu sisi pariwisata membawa uang bagi daerah, tetapi di sisi lain juga bisa mengganggu kehidupan warga.","Yang dibutuhkan saat ini adalah sistem yang membuat pengunjung dan warga sama-sama merasa nyaman."],"vocab":[{"w":"押し寄せる","m":"berdatangan, membanjir"},{"w":"利益","m":"keuntungan, manfaat"},{"w":"脅かす","m":"mengancam, mengganggu"},{"w":"制限","m":"pembatasan"},{"w":"尊重","m":"menghormati, menghargai"}],"grammar":[{"t":"~に対して","note":"Artinya \"terhadap ~, menghadapi ~\": 問題に対して。"},{"t":"~かねない","note":"Artinya \"bisa jadi ~ (hal buruk)\": 失われかねない。"},{"t":"~てこそ","note":"Artinya \"justru dengan ~ barulah\": 尊重してこそ豊かになる。"}]},"a-n5-5":{"title":"Kotaku","topic":"Kehidupan","trans":["Aku tinggal di sebuah kota kecil. Letaknya dekat laut, dan udaranya bersih.","Di kota ini tidak ada gedung besar, tetapi ada kantor pos, rumah sakit, dan supermarket.","Dari stasiun ke rumah, jalan kaki sekitar sepuluh menit. Di tengah jalan ada sungai, jadi aku menyeberangi jembatan.","Di musim semi, bunga sakura di tepi sungai sangat indah, dan banyak orang datang untuk melihat bunga (hanami).","Di dekat sini ada kuil tua yang tenang dan membuat hati nyaman.","Belanja memang agak kurang praktis, tetapi semua orang ramah, jadi ini kota yang enak ditinggali.","Aku sangat suka kota ini. Aku ingin terus tinggal di sini."],"vocab":["tinggal","dekat; sekitar","menyeberangi; melewati","ramah; baik hati","tenang; sepi"],"grammar":[{"t":"〜やすい","note":"Bentuk ます (tanpa ます) + やすい artinya mudah: 「すみやすい」berarti enak/mudah ditinggali."},{"t":"〜たい","note":"Bentuk ます (tanpa ます) + たい menyatakan keinginan: 「住みたい」berarti ingin tinggal."},{"t":"〜が(逆接)","note":"Dalam 「ふべんですが、しんせつです」, が menghubungkan dua hal yang bertentangan, seperti \"tetapi\"."}]},"a-n4-4":{"title":"Perjalanan Solo Pertamaku","topic":"Perjalanan","trans":["Bulan lalu, aku pergi traveling sendirian untuk pertama kalinya. Tujuannya Kanazawa, tempat yang sudah lama membuatku penasaran.","Sebelum berangkat aku agak cemas, tapi menyusun rencana sendiri ternyata lebih seru dari yang kukira.","Pagi-pagi aku naik Shinkansen dan tiba di Kanazawa lewat tengah hari. Stasiunnya besar sekali, aku sampai kaget.","Pertama, aku pergi melihat taman yang terkenal. Cuacanya bagus, jadi aku banyak mengambil foto.","Malam harinya aku makan hidangan laut segar di pasar. Karena sendirian, aku bisa memesan apa saja yang kusuka sebanyak yang kumau.","Berjalan sendirian di kota yang asing memang agak sepi, tapi terasa bebas dan sangat menyenangkan.","Dari perjalanan ini, aku jadi percaya diri bahwa sendirian pun aku bisa mengatasinya. Aku ingin pergi lagi."],"vocab":["traveling sendirian","menyusun rencana","segar","bebas; kebebasan","percaya diri"],"grammar":[{"t":"〜より","note":"「思ったより楽しい」berarti lebih ~ daripada yang dikira."},{"t":"〜だけ","note":"「好きなだけ注文できる」menyatakan batas: sebanyak yang diinginkan."},{"t":"〜という〜","note":"Dalam 「何とかなるという自信」, という menjelaskan isi dari kata benda setelahnya: percaya diri bahwa pasti bisa diatasi."}]},"a-n1-1":{"title":"Pemanasan Global dan Kehidupan Kita","topic":"Lingkungan","trans":["Pemanasan global bukan lagi cerita tentang masa depan yang jauh, melainkan masalah yang berdampak langsung pada kehidupan kita.","Kerusakan tanaman pertanian akibat cuaca ekstrem dan bencana akibat naiknya permukaan laut semakin parah dari tahun ke tahun. Menghadapi situasi seperti ini, mungkin kamu merasa bahwa yang bisa dilakukan setiap orang itu sangat terbatas.","Namun, justru akumulasi hal-hal kecil, seperti mengurangi pemborosan listrik dan menggunakan transportasi umum, itulah yang membawa perubahan besar.","Demi mewariskan bumi yang kaya kepada generasi mendatang, kita dituntut untuk mengambil tindakan sekarang juga.","Pemanasan global bukan cerita tentang negara yang jauh, melainkan masalah yang berkaitan langsung dengan meja makan dan kehidupan sehari-hari kita.","Jangan lupa bahwa akumulasi tindakan kecil dari setiap orang pada akhirnya akan menghasilkan perubahan yang besar."],"vocab":["menimbulkan (dampak), memengaruhi","kerugian, kerusakan, bencana","serius, parah","akumulasi, tumpukan","generasi"],"grammar":[{"t":"~ばかりだ","note":"「terus-menerus, makin ~」perubahan satu arah (memburuk): 深刻さを増すばかりだ。"},{"t":"~こそ","note":"「justru ~」penekanan: 積み重ねこそが変化につながる。"},{"t":"~ためにも","note":"「demi ~ juga」: 世代に残すためにも行動を。"}]},"a-n1-2":{"title":"Makna \"Belajar\" yang Dipertanyakan di Era AI","topic":"Berita","trans":["Dengan cepatnya penyebaran AI generatif, hambatan untuk memperoleh pengetahuan menjadi lebih rendah daripada sebelumnya. Kalau ada pertanyaan, cukup bertanya, dan AI langsung memberikan jawabannya seketika.","Dalam situasi seperti ini, mulai terdengar suara yang berkata, \"Bukankah manusia sudah tidak perlu lagi berusaha belajar?\" Namun, pendapat itu tampaknya keliru memahami hakikat dari kegiatan belajar.","Belajar bukan sekadar mendapatkan jawaban. Menilai kebenaran informasi, membandingkan berbagai pemikiran, dan membuat keputusan dengan caramu sendiri. Justru dalam proses itulah kemampuan berpikir dibentuk. Apakah kamu bisa menelaah jawaban dari AI secara kritis, itu benar-benar bergantung pada kedalaman belajar orang tersebut.","Justru karena ini zaman ketika jawaban mudah didapat, sikap yang terus bertanya \"kenapa bisa begitu?\" menjadi lebih penting daripada sebelumnya. Makna belajar bukannya hilang, malah sedang dipertanyakan kembali.","Justru karena kita hidup di zaman ketika ada AI yang langsung memberi jawaban, sikap yang terus bertanya \"kenapa bisa begitu?\" menjadi semakin penting.","Daripada menimbun pengetahuan, bagaimana cara menggunakannya dan bagaimana menilainya akan menjadi inti dari belajar ke depan."],"vocab":["penyebaran, popularisasi","hakikat, esensi","menilai dengan cermat, membedakan","telaah, pengkajian teliti","mempertanyakan kembali"],"grammar":[{"t":"~により","note":"「karena ~, melalui ~」: 普及により、低くなった。"},{"t":"~どころか","note":"「jangankan ~, malah ~」: 失われるどころか、問い直されている。"},{"t":"~からこそ","note":"「justru karena ~」: 時代だからこそ、重要になっている。"}]},"a-n4-6":{"title":"Festival Musim Panas","topic":"Budaya","trans":["Di musim panas Jepang, festival musim panas diadakan di berbagai tempat. Begitu malam tiba, banyak orang memakai yukata dan berkumpul di kuil Shinto atau kuil Buddha.","Di area festival berjejer banyak kios. Orang-orang makan takoyaki dan es serut, bermain menangkap ikan mas, dan semuanya tampak senang.","Menjelang akhir malam, kembang api besar diluncurkan. Terdengar bunyi \"dor\" yang keras, lalu saat cahaya menyebar di langit malam, semua orang berseru \"wah\".","Festival musim panas adalah acara yang menjadi kenangan penting musim panas di Jepang. Kalau ada kesempatan, cobalah pergi dengan memakai yukata."],"vocab":["festival musim panas","mengadakan, membuka","yukata (kimono musim panas)","kuil Shinto","kios, warung pinggir jalan","berjejer","menangkap ikan mas (permainan)","kembang api","langit malam","acara, upacara tradisional","kesempatan"],"grammar":[{"t":"〜たり〜たりする","note":"Menyebutkan beberapa contoh kegiatan: 食べたり、すくいをしたり。"},{"t":"〜と(hasil alami)","note":"「光が広がると」begitu ~, maka ~. Menyatakan hasil yang terjadi secara alami."},{"t":"〜てみてください","note":"「行ってみてください」cobalah melakukan ~."}]},"a-n3-7":{"title":"Waspadai Sengatan Panas","topic":"Kehidupan","trans":["Beberapa tahun terakhir, musim panas di Jepang semakin panas. Terutama dari Juli sampai Agustus, hari dengan suhu di atas 35 derajat bukan hal yang aneh.","Yang harus diwaspadai di tengah panas seperti ini adalah sengatan panas (heatstroke). Kalau tubuh kekurangan cairan, bisa timbul pusing dan sakit kepala, dan dalam kasus parah bahkan bisa mengancam nyawa.","Untuk mencegah sengatan panas, yang penting adalah sering minum air sedikit demi sedikit sebelum merasa haus. Menghindari keluar rumah di jam-jam terpanas dan memakai AC dengan bijak juga baik.","Tidak sedikit orang yang kondisi tubuhnya memburuk saat masih merasa \"aku masih baik-baik saja\". Mari saling mengingatkan dengan orang di sekitar dan melewati musim panas yang terik ini dengan sehat."],"vocab":["beberapa tahun terakhir","sengatan panas (heatstroke)","suhu udara","melebihi","kadar air dalam tubuh, cairan","sakit kepala","nyawa","menyangkut, berkaitan dengan","mencegah","rentang waktu","keluar rumah","kondisi tubuh","mengatasi, melewati"],"grammar":[{"t":"〜から〜にかけて","note":"「七月から八月にかけて」menyatakan rentang waktu secara garis besar, dari ~ sampai ~."},{"t":"〜うちに","note":"「思っているうちに」selama keadaan ~ masih berlangsung (tanpa sadar jadi ~)."},{"t":"〜なければならない","note":"「気をつけなければならない」menyatakan kewajiban, harus ~."}]},"a-n2-6":{"title":"Hargai Tidurmu","topic":"Kesehatan","trans":["Di tengah kesibukan sehari-hari, waktu tidur adalah hal yang paling sering tanpa sadar dikorbankan. Padahal, tidur yang berkualitas sangat penting untuk menjalani hidup sehat.","Kalau kurang tidur, konsentrasi menurun dan kondisi tubuh pun memburuk. Mungkin banyak juga yang pekerjaan atau belajarnya tidak lancar karena mengantuk di siang hari.","Supaya bisa tidur nyenyak, yang pertama penting adalah mengatur ritme hidup. Biasakan tidur dan bangun pada jam yang sama setiap hari.","Selain itu, sebaiknya hindari melihat ponsel sebelum tidur sebisa mungkin. Sebab, cahaya layar yang terang bisa membuat otak terjaga.","Meski hanya selisih beberapa jam, kebiasaan yang menumpuk setiap hari akan menjadi perbedaan besar. Bagaimana kalau kamu mulai dengan tidur lebih awal?"],"vocab":[{"w":"削って","m":"memangkas, mengorbankan"},{"w":"睡眠","m":"tidur"},{"w":"欠かせない","m":"tak boleh dilewatkan, sangat penting"},{"w":"集中力","m":"daya konsentrasi"},{"w":"眠気","m":"rasa kantuk"},{"w":"整える","m":"mengatur, merapikan"},{"w":"避けた","m":"menghindari"},{"w":"積み重ね","m":"penumpukan, akumulasi"}],"grammar":[{"t":"~がち","note":"「Cenderung, sering ...」: つい削ってしまいがち。"},{"t":"~うえで","note":"「Dalam hal ...」: 健康な生活を送るうえで欠かせない。"},{"t":"~たほうがよい","note":"Saran, \"sebaiknya ...\": スマホを見るのは避けたほうがよい。"}]},"a-n1-4":{"title":"Agar Bisa Berenang di Lautan Informasi","topic":"Media","trans":["Berkat menyebarnya smartphone, kita kini bisa mengakses informasi dalam jumlah sangat besar kapan saja dan di mana saja. Namun, di balik kemudahan itu tersembunyi jebakan yang tidak boleh diabaikan.","Internet dibanjiri informasi yang belum jelas benar atau salahnya. Di antaranya, tidak sedikit hoaks yang disebarkan dengan niat jahat. Kemampuan membedakan fakta dari opini kini dibutuhkan lebih dari sebelumnya.","Yang lebih merepotkan lagi adalah sistem yang hanya menampilkan informasi yang sesuai dengan selera kita. Tanpa sadar, wawasan kita menyempit dan kita mudah terjebak dalam pemikiran yang berat sebelah.","Yang penting adalah sikap tidak menelan mentah-mentah satu informasi, melainkan memeriksanya dengan merujuk ke beberapa sumber. Saat membagikan informasi pun, kita harus bertanggung jawab atas isinya.","Kemampuan membaca dan memahami informasi dengan benar sudah bukan lagi milik segelintir ahli saja. Ini adalah bekal wajib yang seharusnya dimiliki setiap orang untuk bertahan hidup di zaman sekarang."],"vocab":[{"w":"普及","m":"penyebaran luas, menjadi umum"},{"w":"膨大","m":"sangat besar, melimpah"},{"w":"真偽","m":"benar atau palsu, keaslian"},{"w":"拡散","m":"menyebar, menyebarkan"},{"w":"厄介","m":"merepotkan, rumit"},{"w":"視野","m":"wawasan, sudut pandang"},{"w":"鵜呑み","m":"menelan mentah-mentah, percaya begitu saja"},{"w":"教養","m":"bekal pengetahuan, wawasan umum"}],"grammar":[{"t":"~ないうちに","note":"「知らず知らずのうちに」= tanpa disadari, tanpa terasa."},{"t":"~ばかり","note":"Menyatakan pembatasan atau hanya satu hal yang menonjol: 好みに合う情報ばかりが表示される (yang ditampilkan hanya informasi yang sesuai selera)."},{"t":"もはや~ない","note":"「sudah tidak lagi ~」: もはや専門家だけのものではない (sudah bukan lagi milik para ahli saja)."}]},"a-n1-5":{"title":"Makanan yang Dibuang","topic":"Masyarakat","trans":["Makanan yang sebenarnya masih bisa dimakan tetapi dibuang, atau yang disebut food loss (pemborosan makanan), telah menjadi masalah dunia. Di Jepang pun, konon jutaan ton makanan dibuang sia-sia setiap tahun.","Di sisi lain, di dunia ini banyak orang yang tidak bisa makan dengan cukup. Di balik kelimpahan makanan yang tampak seperti lambang kemakmuran, terjadi ketimpangan yang serius.","Penyebab food loss bukan hanya sisa makanan dari rumah tangga dan restoran. Kenyataan bahwa produk yang seharusnya masih bisa dijual dibuang dalam jumlah besar dengan alasan tanggal kedaluwarsa (batas kualitas) juga tidak boleh diabaikan.","Untuk menyelesaikan masalah ini, upaya perusahaan tentu saja penting, tetapi perubahan kesadaran setiap orang juga sangat diperlukan. Kebiasaan sederhana seperti tidak membeli berlebihan dan tidak memasak berlebihan akan menjadi langkah besar.","Menghargai sumber daya yang terbatas juga merupakan tanggung jawab kita kepada generasi berikutnya. Gaya hidup yang tidak menyia-nyiakan makanan kini kembali dipertanyakan."],"vocab":[{"w":"廃棄","m":"membuang, menyingkirkan"},{"w":"大勢","m":"banyak orang"},{"w":"飽食","m":"kekenyangan, hidup berkecukupan"},{"w":"不均衡","m":"ketimpangan, tidak seimbang"},{"w":"賞味期限","m":"batas waktu terbaik untuk dikonsumsi (best before)"},{"w":"処分","m":"membuang, menangani, penghapusan"},{"w":"欠かせない","m":"tidak boleh tidak ada, sangat penting"},{"w":"資源","m":"sumber daya"}],"grammar":[{"t":"~のに","note":"Menyatakan pertentangan (padahal): まだ食べられるのに捨てられる (padahal masih bisa dimakan, tetapi dibuang)."},{"t":"~はもちろん","note":"「~tentu saja, apalagi」: 企業の取り組みはもちろん (upaya perusahaan tentu saja)."},{"t":"見逃せない","note":"「tidak boleh diabaikan」: 現状も見逃せない (kenyataan saat ini pun tidak boleh diabaikan)."}]},"a-n4-5":{"title":"Sehari Kerja Paruh Waktu","topic":"Pekerjaan","trans":["Sambil kuliah, aku kerja paruh waktu di kafe. Tiga kali seminggu, dengan shift dari sore sampai malam.","Setelah sampai di toko, pertama-tama aku ganti baju dengan seragam, lalu mencuci tangan sampai bersih.","Pekerjaanku antara lain mencatat pesanan, membuat kopi, dan membereskan meja.","Saat sibuk, rasanya capek sekali, tapi kalau pelanggan bilang 「ありがとう」, rasa lelahku langsung hilang.","Di awal, aku cuma bikin kesalahan dan sering ditegur oleh senior. Tapi sedikit demi sedikit, hal yang bisa kulakukan makin banyak.","Berkat kerja paruh waktu ini, bukan cuma uang yang kudapat, aku juga belajar cara berbicara dengan orang dan pentingnya kerja sama tim.","Menyeimbangkan kerja dengan kuliah memang tidak mudah, tapi kurasa ini pengalaman yang bagus sebelum terjun ke masyarakat."],"vocab":[{"w":"通う","m":"pulang-pergi, bersekolah/berangkat (ke sekolah/kantor)"},{"w":"着がえる","m":"ganti baju"},{"w":"片づける","m":"membereskan, merapikan"},{"w":"先輩","m":"senior"},{"w":"経験","m":"pengalaman"}],"grammar":[{"t":"〜ながら","note":"Kata kerja bentuk ます (tanpa ます) + ながら menyatakan dua hal dilakukan bersamaan: 「通いながら働く」(bekerja sambil kuliah)."},{"t":"〜ばかり","note":"「失敗ばかり」berarti melulu/hanya, yaitu terus-terusan terjadi hal yang sama."},{"t":"〜おかげで","note":"「アルバイトのおかげで」menyatakan penyebab yang baik, artinya berkat."}]},"a-n3-6":{"title":"Empat Musim dan Perayaan Tahunan di Jepang","topic":"Budaya","trans":["Jepang punya empat musim, yaitu semi, panas, gugur, dan dingin, dan perayaan yang sesuai dengan tiap musim masih dijaga sampai sekarang.","Musim semi adalah musim sakura. Orang-orang berkumpul di taman dan merayakan datangnya musim semi sambil makan di bawah bunga.","Begitu musim panas tiba, berbagai tempat mengadakan festival dan pesta kembang api, dan suasananya ramai oleh orang-orang yang memakai yukata.","Musim gugur disebut juga 「食欲の秋」 dan 「読書の秋」, dan banyak orang menikmati daun musim gugur yang memerah di udara yang mulai sejuk.","Di musim dingin ada Tahun Baru. Biasanya keluarga berkumpul menyantap hidangan osechi, lalu pergi ke kuil untuk 初詣 (kunjungan pertama tahun ini).","Perayaan seperti ini menjadi kesempatan untuk merasakan pergantian musim dan mempererat hubungan dengan keluarga dan warga sekitar.","Di tengah kehidupan yang serba praktis pun, hati yang menghargai irama alam kemungkinan besar akan terus diwariskan ke depannya."],"vocab":[{"w":"季節","m":"musim"},{"w":"行事","m":"acara, perayaan"},{"w":"祝う","m":"merayakan"},{"w":"一般的","m":"umum, lazim"},{"w":"受けつぐ","m":"mewarisi, meneruskan"}],"grammar":[{"t":"〜に合わせて","note":"「季節に合わせた行事」menyatakan menyesuaikan dengan sesuatu."},{"t":"〜と言われる","note":"「食欲の秋と言われる」berarti orang umumnya menyebutnya begitu / disebut sebagai."},{"t":"〜だろう","note":"「受けつがれていくだろう」menyatakan dugaan (mungkin/kemungkinan besar)."}]},"a-n2-5":{"title":"Pembayaran Nontunai yang Kian Meluas","topic":"Masyarakat","trans":["Dalam beberapa tahun terakhir, pembayaran nontunai juga berkembang pesat di Jepang. Dulu banyak toko yang hanya menerima uang tunai, tetapi sekarang makin banyak toko yang bisa dibayar dengan ponsel pintar atau kartu.","Pembayaran nontunai punya keuntungan: pembayarannya cepat dan uang jadi lebih mudah diatur. Kamu tidak perlu mencari uang receh di kasir, dan kapan serta berapa banyak yang kamu belanjakan tercatat dengan sendirinya.","Di sisi lain, masih ada masalah yang tersisa. Kalau terjadi pemadaman listrik atau gangguan jaringan, ada risiko kita tidak bisa membayar. Perhatian untuk orang yang mudah boros dan untuk lansia yang kurang mahir mengoperasikan mesin juga tidak boleh diabaikan.","Bagaimana menyeimbangkan kemudahan dan rasa aman? Yang dibutuhkan adalah masyarakat tempat uang tunai dan pembayaran nontunai bisa hidup berdampingan dengan baik."],"vocab":["pembayaran, penyelesaian transaksi","dengan cepat, pesat","uang tunai","membayar","keuntungan, kelebihan","uang receh","catatan","masalah yang harus diselesaikan, tantangan","pemadaman listrik","gangguan jaringan komunikasi","risiko, kekhawatiran","perhatian, pertimbangan","hidup berdampingan","meminta, menuntut, membutuhkan"],"grammar":[{"t":"〜てくる (perubahan)","note":"「広がってきた」menyatakan perubahan atau tren yang berlangsung sampai sekarang."},{"t":"〜恐れがある","note":"「できなくなる恐れがある」menyatakan adanya kemungkinan (buruk) terjadi."},{"t":"一方(で)","note":"「一方で、課題も残されている」dipakai untuk mengemukakan sisi lain yang berlawanan."}]},"a-n1-3":{"title":"Penuaan dan Rendahnya Angka Kelahiran: Masalah yang Sulit","topic":"Masyarakat","trans":["Jepang mengalami penurunan angka kelahiran dan penuaan penduduk dengan kecepatan yang belum pernah terlihat di dunia. Proporsi lansia dalam total penduduk naik dari tahun ke tahun, sementara jumlah anak yang lahir terus menurun.","Dampak dari tren ini bisa mengguncang fondasi sistem jaminan sosial. Sebab, biaya pensiun, layanan kesehatan, dan perawatan lansia terus bertambah, sementara generasi usia produktif yang menopangnya makin sedikit.","Sebagai langkah penanganan, sedang dibahas antara lain penyempurnaan sistem yang mendukung keseimbangan antara mengasuh anak dan bekerja, serta perluasan penerimaan tenaga kerja asing. Namun, semuanya bukan masalah yang bisa diselesaikan dalam waktu singkat.","Di balik turunnya angka kelahiran, ada faktor-faktor rumit yang saling berkaitan, seperti kecemasan ekonomi dan beragamnya nilai hidup. Ini bukan masalah yang selesai hanya dengan membagikan subsidi.","Penuaan dan rendahnya angka kelahiran kini sudah menjadi kenyataan yang tidak bisa dihindari. Bagaimana seluruh masyarakat menghadapinya, dan negara seperti apa yang akan diwariskan kepada generasi berikutnya? Justru sekarang diskusi yang serius sangat dibutuhkan."],"vocab":["proporsi, rasio","kecenderungan, tren","fondasi, inti","perawatan lansia, pengasuhan orang sakit","menyeimbangkan dua hal, menjalankan keduanya","dalam waktu singkat, sekejap","angka kelahiran","faktor, penyebab"],"grammar":[{"t":"~かねない","note":"「bisa saja terjadi ~ (hal buruk)」: 根幹を揺るがしかねない = bisa mengguncang fondasi."},{"t":"~一方で","note":"membandingkan dua sisi: 費用は増える一方で、現役世代は減る (biaya bertambah, sementara generasi produktif berkurang)."},{"t":"~ではないのだ","note":"menegaskan penyangkalan atau menarik kesimpulan: 済むという話ではないのだ (bukan masalah yang selesai begitu saja)."}]},"a-n2-7":{"title":"Sedia Payung Sebelum Hujan","topic":"Kehidupan","trans":["Jepang adalah negara yang sering mengalami bencana alam seperti gempa bumi dan topan. Kita tidak tahu kapan bencana akan terjadi, jadi sangat penting untuk bersiap-siap sejak jauh hari.","Pertama, mulailah dari hal-hal yang bisa kamu lakukan di rumah. Siapkan air, makanan, senter, dan sebagainya, lalu simpan di tempat yang bisa langsung dibawa keluar. Dengan begitu kamu akan merasa lebih tenang.","Jangan lupa juga untuk berdiskusi dengan keluarga sebelumnya. Kalau suatu saat kalian terpisah, asalkan sudah menentukan tempat berkumpul, kamu bisa bertindak dengan tenang tanpa panik.","Selain itu, mengetahui tempat-tempat berbahaya di daerah tempat tinggalmu juga sangat berguna. Lihatlah peta yang dibagikan oleh kantor pemerintah kota dan sebagainya, lalu pastikan jalan menuju tempat pengungsian.","Meskipun bencana tidak bisa dicegah, kerusakan bisa dikurangi. Kewaspadaan kecil dalam keseharian akan melindungi dirimu dan keluargamu saat keadaan darurat tiba."],"vocab":["bencana","bersiap, berjaga-jaga","senter","bisa dibawa keluar","tempat pengungsian","kerusakan, korban","kewaspadaan, perhatian","melindungi, menjaga"],"grammar":[{"t":"~ておく","note":"Melakukan sesuatu terlebih dahulu: 備えておく (bersiap lebih dulu), 決めておく (menentukan lebih dulu)."},{"t":"~てはいけない","note":"Larangan, \"tidak boleh\": 話し合っておくことも忘れてはいけない (jangan lupa berdiskusi lebih dulu)."},{"t":"いざというとき","note":"Ungkapan tetap yang berarti \"saat genting / saat keadaan darurat\": いざというときに守る (melindungi saat keadaan darurat)."}]},"a-n5-6":{"title":"Hobiku","topic":"Hobi","trans":["Hobiku adalah memotret.","Di hari libur, aku membawa kamera dan jalan-jalan di kota.","Aku memotret bunga dan burung.","Saat berhasil mengambil foto yang bagus, aku senang sekali.","Kadang-kadang aku mengirim foto ke teman.","Temanku bilang: 「じょうずですね」 (bagus ya).","Aku ingin kamera baru, tapi harganya mahal, jadi sekarang aku sedang menabung."],"vocab":["hobi","foto","memotret, mengambil (foto)","berjalan kaki","mengirim","menabung (uang)"],"grammar":[{"t":"しゅみは~ことです","note":"\"Hobiku adalah melakukan ~\": kalimat diakhiri こと yang membuat kata kerja menjadi kata benda. しゅみは しゃしんを とる ことです。"},{"t":"~とき","note":"\"saat ~\": とれた とき (saat berhasil memotret)."},{"t":"~が ほしい","note":"\"ingin ~ (benda)\": benda yang diinginkan memakai が. カメラが ほしいです。"}]},"a-n5-7":{"title":"Mengirim Paket di Kantor Pos","topic":"Kehidupan","trans":["Hari ini aku mau pergi ke kantor pos untuk mengirim paket.","Di loket, aku bilang, 「これを 台湾へ おねがいします」 (Tolong kirim ini ke Taiwan).","Petugas loket bertanya, 「船便ですか、航空便ですか」 (Lewat laut atau lewat udara?).","Kirim lewat laut murah, tapi butuh waktu sekitar satu bulan. Kirim lewat udara cepat, tapi mahal.","Aku memilih lewat udara. Setelah menulis nama dan alamat di formulir, aku membayar.","Waktu aku bertanya 「いつ とどきますか」 (Kapan sampainya?), dia memberi tahu aku 「一週間ぐらいです」 (Sekitar satu minggu).","Dalam perjalanan pulang, aku membeli perangko di minimarket dan juga mengirim kartu pos."],"vocab":["kantor pos","barang bawaan, paket","loket","kiriman lewat laut","kiriman lewat udara","formulir, kertas","alamat","perangko","sampai, tiba"],"grammar":[{"t":"～てから","note":"Menyelesaikan hal pertama dulu, baru melakukan hal kedua. 「書いてから はらいます」 = bayar setelah selesai menulis, jadi urutannya jelas."},{"t":"～と いいます／ききます","note":"Mengutip kata-kata yang diucapkan atau ditanyakan. Taruh seluruh kalimat sebelum 「と」: 「これを おねがいします」と いいます。"},{"t":"～に いきます(tujuan)","note":"Bentuk ます verba tanpa ます + に いきます = pergi untuk melakukan sesuatu. 「おくりに いきます」 = pergi untuk mengirim (barang)."}]},"a-n4-8":{"title":"Mengurus Administrasi di Kantor Kelurahan","topic":"Kehidupan","trans":["Setelah pindah rumah, kamu harus pergi ke kantor kelurahan (区役所) dalam waktu empat belas hari.","Di loket, aku bilang 「転入届を出したいんですが」 (Saya ingin mengajukan laporan pindah masuk), lalu aku diberi nomor antrean.","Sampai namaku dipanggil, aku duduk di kursi dan menunggu. Selama menunggu, aku menulis alamat dan tanggal lahir di dokumen lebih dulu.","Setelah melihat kartu izin tinggal (在留カード), petugas menuliskan alamat baru di bagian belakangnya untukku.","Di hari yang sama, kamu juga bisa mengurus asuransi kesehatan nasional. Karena loketnya berbeda, aku pindah dari lantai satu ke lantai dua.","Semuanya selesai dalam waktu sekitar satu jam, tapi karena bisa mengurusnya hanya dengan bahasa Jepang, aku jadi sedikit lebih percaya diri.","Kalau ada yang tidak kamu mengerti, sebaiknya tanya saja tanpa sungkan. Petugasnya akan berbicara pelan-pelan."],"vocab":["kantor kelurahan/kecamatan (di Jepang)","prosedur, urusan administrasi","laporan pindah masuk","nomor antrean","dokumen","tanggal lahir","kartu izin tinggal","asuransi kesehatan nasional","sungkan, segan"],"grammar":[{"t":"～なければなりません","note":"Menyatakan kewajiban: harus dilakukan. 「十四日以内に行かなければなりません」 = harus pergi dalam empat belas hari, karena itu aturan."},{"t":"～ておく","note":"Melakukan sesuatu lebih dulu sebagai persiapan. 「書いておきました」 = menulisnya selagi menunggu, jadi nanti tidak panik."},{"t":"～てくれる","note":"Orang lain melakukan sesuatu untukku, dengan nuansa terima kasih. 「書いてくれました」 = (dia) menuliskannya untukku."}]},"a-n2-8":{"title":"Memilih Pindah ke Daerah Pedesaan","topic":"Masyarakat","trans":["Katanya, belakangan ini makin banyak orang yang meninggalkan kota dan pindah ke daerah pedesaan.","Alasan terbesarnya adalah makin populernya kerja jarak jauh, sehingga kita bisa bekerja di mana pun tinggal.","Biaya sewa kurang dari separuh harga di kota, tidak perlu berdesakan saat berangkat kerja, dan hidup dikelilingi alam pun terlihat menarik.","Tapi, pindah ke desa sama sekali bukan hal yang mudah.","Banyak daerah yang tidak bisa dijalani tanpa mobil, dan kadang terasa tidak praktis dari segi layanan kesehatan dan pendidikan.","Bisa atau tidaknya berbaur dengan hubungan sosial di lingkungan setempat juga disebut-sebut sebagai tantangan besar.","Yang penting mungkin bukan memutuskan hanya berdasarkan impian, tapi benar-benar datang beberapa kali dan memastikan sendiri seperti apa kehidupan di tempat itu."],"vocab":[{"w":"移住","m":"pindah (ke daerah lain), migrasi"},{"w":"普及","m":"populer, tersebar luas"},{"w":"家賃","m":"uang sewa (rumah)"},{"w":"無縁","m":"tidak ada kaitan, tidak berhubungan"},{"w":"溶け込む","m":"berbaur, menyatu"},{"w":"課題","m":"tantangan, masalah yang harus diatasi"},{"w":"足を運ぶ","m":"datang langsung, pergi ke suatu tempat"},{"w":"確かめる","m":"memastikan, memeriksa"}],"grammar":[{"t":"~という(kabar)","note":"「katanya ~」: 増えているという。という di akhir kalimat menandakan kabar yang didengar atau kutipan."},{"t":"~によって","note":"「karena ~, seiring dengan ~」: 普及によって~ようになった。Menyatakan sebab atau cara."},{"t":"決して~ない","note":"「sama sekali tidak ~」: 決して簡単なものではない。Kata keterangan yang selalu berpasangan dengan bentuk negatif."},{"t":"~かどうか","note":"「apakah ~ atau tidak」: 溶け込めるかどうか。"},{"t":"~のではなく","note":"「bukan ~ melainkan …」: 理想だけで決めるのではなく、実際に確かめる。"}]},"a-n1-7":{"title":"Bahasa Jepang yang Terus Berubah","topic":"Bahasa","trans":["Pernahkah kamu mendengar istilah 「ら抜き言葉」 (kata tanpa ら)?","Itu cara bicara seperti mengucapkan 「食べられる」 menjadi 「食べれる」, dan sering dikritik sebagai bahasa Jepang yang salah.","Namun, dari sudut pandang linguistik, ada juga pendapat bahwa ini bukan sekadar 「kekacauan」, melainkan perubahan yang masuk akal.","Sebab 「見られる」 punya beberapa arti sekaligus, yaitu pasif, hormat, dan potensial, sedangkan kalau 「見れる」, sekilas langsung terlihat bahwa artinya potensial (bisa melihat).","Lagi pula, bahasa memang selalu terus berubah.","Bahasa Jepang yang sekarang kita yakini 「benar」 pun, di mata orang seratus tahun lalu, tidak lain hanyalah bahasa yang kacau.","Daripada meratapi perubahan, bukankah lebih baik memikirkan mengapa bahasa berubah seperti itu? Dengan begitu, mungkin kita bisa lebih dekat dengan hakikat bahasa."],"vocab":[{"w":"批判","m":"kritik, kecaman"},{"w":"乱れ","m":"kekacauan, penyimpangan"},{"w":"合理的","m":"masuk akal, rasional"},{"w":"受身","m":"(bentuk) pasif"},{"w":"尊敬","m":"hormat (bentuk hormat)"},{"w":"嘆く","m":"meratapi, menyesali"},{"w":"本質","m":"hakikat, esensi"},{"w":"近づく","m":"mendekati"}],"grammar":[{"t":"~にほかならない","note":"「tidak lain adalah ~, tak lain ialah ~」: 乱れた言葉にほかならない。Pernyataan tegas dalam bahasa tulis."},{"t":"~ゆく","note":"「semakin ~ (bahasa tulis)」: 変わりゆく日本語。Bentuk klasik dari ていく, menyatakan perubahan yang terus berlangsung."},{"t":"単なる~ではなく","note":"「bukan sekadar ~」: 単なる「乱れ」ではなく、合理的な変化。"},{"t":"~のではないだろうか","note":"「bukankah ~? (pendapat yang halus)」: 近づけるのではないだろうか。Menyampaikan pendapat dengan lembut lewat pertanyaan retoris."}]},"a-n1-8":{"title":"Tenaga Kerja Asing dan Masa Depan Masyarakat Jepang","topic":"Masyarakat","trans":["Di masa kini, ketika kekurangan tenaga kerja sudah menjadi masalah struktural, penerimaan tenaga kerja asing telah memasuki tahap yang tidak bisa lagi disebut sekadar solusi sementara.","Sistem seperti Keterampilan Khusus (Tokutei Ginō) dan Tenaga Ahli Tingkat Tinggi telah dibangun, dan jumlah warga asing yang tinggal di Jepang terus memecahkan rekor tertinggi. Namun, bertambahnya jumlah tidak serta-merta berarti mereka akan menetap.","Hambatan bahasa, mencari tempat tinggal, pendidikan anak — kalau fondasi kehidupan belum terbentuk, seberapa pun tunjangan dan kondisi kerjanya diperbaiki, orang tidak akan benar-benar berakar.","Kalau sudah level perusahaan, setelah merekrut pun mereka perlu bertanggung jawab atas pendidikan bahasa Jepang dan membangun hubungan dengan masyarakat sekitar.","Kesadaran pihak yang menerima juga ikut dipertanyakan. Apakah kita bisa menghadapi mereka bukan sebagai \"tenaga kerja\", melainkan sebagai tetangga yang hidup di lingkungan yang sama?","Apa pun sistemnya, yang pada akhirnya menentukan apakah seseorang akan menetap mungkin adalah akumulasi hubungan sehari-hari sedikit demi sedikit.","Perdebatan tentang tenaga kerja asing sebenarnya adalah dua sisi dari satu mata uang yang sama dengan pertanyaan: masyarakat seperti apa yang ingin diwujudkan oleh Jepang?"],"vocab":[{"w":"人手不足","m":"kekurangan tenaga kerja"},{"w":"受け入れ","m":"penerimaan"},{"w":"一時しのぎ","m":"solusi sementara"},{"w":"特定技能","m":"Keterampilan Khusus (kategori visa)"},{"w":"定着","m":"menetap, berakar"},{"w":"待遇","m":"perlakuan, kondisi dan tunjangan kerja"},{"w":"根を下ろす","m":"berakar, menetap"},{"w":"表裏一体","m":"dua sisi dari satu hal yang sama"},{"w":"問われる","m":"dipertanyakan, dimintai pertanggungjawaban"}],"grammar":[{"t":"～ともなると","note":"Kalau sudah sampai pada tingkat/posisi tertentu, keadaannya jadi berbeda. 「企業ともなると」= kalau sudah level perusahaan, tanggung jawabnya jadi lebih besar."},{"t":"～いかんによらず","note":"Apa pun keadaan hal sebelumnya, hasilnya tidak terpengaruh. 「制度のいかんによらず」= apa pun sistemnya."},{"t":"～たところで","note":"Meskipun dilakukan, tetap tidak ada gunanya; diikuti hasil negatif. 「改善したところで、根を下ろさない」= meskipun diperbaiki, tetap tidak akan berakar."},{"t":"～わけではない","note":"Negasi sebagian. 「定着を意味するわけではない」= bukan berarti pasti akan menetap."}]},"a-n5-8":{"title":"ぎんこうで こうざを つくる","topic":"Kehidupan","trans":["Hari ini aku pergi ke bank untuk membuat rekening.","Petugas di loket berkata, \"Tolong berikan kartu izin tinggal dan stempel Anda.\"","Aku mengeluarkan kartu dan stempel dari tas.","Aku menulis nama, alamat, dan nomor telepon di formulir. Karena kanjinya sulit, aku menulisnya pelan-pelan.","Petugas memberi tahu, \"Kartu ATM akan sampai ke rumah dalam sekitar dua minggu.\"","Buku tabungan bisa kudapat hari itu juga. Ini buku tabungan Jepang pertamaku.","Aku sedikit gugup, tapi senang karena bisa mengurusnya hanya dengan bahasa Jepang."],"vocab":[{"w":"銀行","m":"bank"},{"w":"口座","m":"rekening"},{"w":"印鑑","m":"stempel pribadi"},{"w":"用紙","m":"formulir"},{"w":"電話番号","m":"nomor telepon"},{"w":"通帳","m":"buku tabungan"},{"w":"届く","m":"sampai, tiba"},{"w":"緊張する","m":"gugup, tegang"}],"grammar":[{"t":"～に いきます(目的)","note":"Bentuk ます kata kerja tanpa ます + に いきます = pergi untuk melakukan sesuatu. 「こうざを つくりに いきます」= pergi untuk membuat rekening."},{"t":"～と いいました","note":"Mengutip ucapan orang lain; seluruh kalimat kutipan diletakkan sebelum 「と」."},{"t":"～てくれる","note":"Orang lain melakukan sesuatu untukku, dengan nuansa terima kasih. 「おしえて くれました」= (dia) memberi tahu aku."}]},"a-n3-9":{"title":"Mencari Kamar di Jepang","topic":"Kehidupan","trans":["Menyewa kamar di Jepang ternyata lebih merepotkan daripada yang dibayangkan.","Pertama, kamu pergi ke agen properti dan menyampaikan anggaran uang sewa serta lokasi yang kamu inginkan. Kalau kamu menambahkan syarat \"jalan kaki dalam waktu sepuluh menit dari stasiun\", uang sewa langsung melonjak.","Meskipun sudah menemukan kamar yang kamu suka, kamu tidak bisa langsung memutuskan. Sebab di awal kamu butuh uang dalam jumlah cukup besar, seperti uang jaminan, uang terima kasih untuk pemilik, dan biaya jasa agen.","Untuk orang asing, biasanya kamu diminta menyiapkan penjamin. Belakangan ini lebih umum memakai perusahaan penjamin, dan kamu menandatangani kontrak dengan membayar sekitar setengah dari uang sewa bulanan.","Supaya lolos seleksi, sebaiknya kamu menyiapkan dokumen yang menunjukkan tempat kerja dan penghasilanmu sejak awal.","Saat melihat kamar langsung, selain cahaya matahari dan kebisingan, sebaiknya kamu juga memeriksa tempat untuk menaruh mesin cuci dan jumlah stopkontaknya. Justru bagian yang tidak terlihat di foto itulah yang membuat survei langsung terasa berarti.","Kelihatannya merepotkan, tetapi hanya dengan mengetahui langkah-langkah ini, pindahan berikutnya pasti akan jauh lebih mudah."],"vocab":["agen properti","uang sewa","uang jaminan (shikikin)","uang terima kasih untuk pemilik (reikin, tidak dikembalikan)","biaya jasa agen","penjamin","seleksi, pemeriksaan","melihat kamar langsung","cahaya matahari (paparan sinar)","merepotkan, butuh usaha"],"grammar":[{"t":"～ように(tujuan)","note":"Menyatakan keadaan yang ingin dicapai; biasanya didahului bentuk potensial atau kata kerja tanpa unsur kehendak. 「審査に通るように」= supaya (bisa) lolos seleksi."},{"t":"～ほうがいい","note":"Saran. 「そろえておいたほうがいい」= sebaiknya disiapkan dulu; nadanya lebih lembut daripada perintah, tetapi tetap jelas."},{"t":"～こそ","note":"Menegaskan \"justru yang ini\". 「わからない部分こそ」= justru bagian yang tidak kelihatan itulah (yang penting)."}]},"a-n2-9":{"title":"Perpanjangan Status Tinggal: Rintangan yang Harus Dilalui","topic":"Masyarakat","trans":["Bagi orang asing yang tinggal di Jepang, perpanjangan status tinggal adalah rintangan yang tidak bisa dihindari.","Pengajuan bisa dilakukan mulai tiga bulan sebelum masa berlaku habis, tetapi menyiapkan dokumen butuh waktu, jadi tidak ada ruginya bergerak lebih awal.","Yang dibutuhkan, selain formulir permohonan, antara lain surat keterangan pajak penduduk, bukti pembayaran pajak, dan surat keterangan kerja. Bagi orang yang baru pindah kerja, kadang kontrak kerja juga diminta.","Dalam pemeriksaan, yang dinilai adalah apakah penghasilanmu stabil dan apakah pajak serta iuran pensiun sudah dibayar dengan benar.","Dengan kata lain, akibat dari mengurus berbagai keperluan sehari-hari dengan menunda-nunda akan datang sekaligus pada saat ini.","Loket imigrasi ramai, sehingga makin banyak orang memakai pengajuan online. Seiring dengan itu, alur prosedurnya pun sedikit demi sedikit berubah.","Beberapa minggu sampai hasilnya keluar memang membuat gelisah, tetapi kalau dokumen yang dibutuhkan sudah lengkap dan kamu melapor dengan jujur, tidak perlu terlalu takut."],"vocab":["status tinggal (visa)","perpanjangan","rintangan, ujian berat","surat keterangan pajak penduduk","bukti pembayaran pajak","surat keterangan kerja","kantor imigrasi","pelaporan","menanggung akibatnya nanti"],"grammar":[{"t":"～に越したことはない","note":"Artinya \"tidak ada yang lebih baik daripada…\", yaitu cara yang paling aman. 「早めに動くに越したことはない」= makin cepat bertindak makin baik."},{"t":"～というわけだ","note":"Menarik kesimpulan dari hal sebelumnya. 「回ってくるというわけだ」= jadi, begitulah hasilnya."},{"t":"～に伴って／それに伴い","note":"Seiring satu hal berubah, hal lain ikut berubah. 「それに伴い、流れも変わりつつある」= seiring dengan itu, alurnya juga sedang berubah."},{"t":"～つつある","note":"Sedang berubah secara bertahap; lebih formal/tulis daripada 「ている」. 「変わりつつある」= sedang berubah perlahan."}]},"a-n4-9":{"title":"Pergi ke Dokter Gigi","topic":"Kehidupan","trans":["Karena gigiku mulai sakit sejak tiga hari lalu, aku membuat janji dengan dokter gigi di dekat rumah.","Setelah menunjukkan kartu asuransi di resepsionis, aku diminta mengisi formulir anamnesis. Isinya antara lain sejak kapan sakitnya dan apakah giginya ngilu kalau kena yang dingin.","Dokter bilang, 「虫歯が一本ありますね」 (ada satu gigi berlubang), lalu menunjukkan foto rontgen kepadaku.","Hari ini giginya hanya dibor dan diberi obat, lalu aku diminta datang lagi minggu depan.","Setelah perawatan, aku juga diajari cara menyikat gigi. Katanya, kalau menyikat terlalu keras, gusi bisa terluka.","Di Jepang, kita harus bolak-balik ke dokter gigi berkali-kali, tapi sebagai gantinya gigi kita dirawat dengan sangat teliti.","Menurutku, sebaiknya kita periksa sekali setengah tahun sebelum gigi mulai sakit."],"vocab":[{"w":"歯医者","m":"dokter gigi"},{"w":"予約","m":"janji, reservasi"},{"w":"保険証","m":"kartu asuransi kesehatan"},{"w":"問診票","m":"formulir anamnesis (pertanyaan kondisi pasien)"},{"w":"しみる","m":"ngilu (karena dingin/panas)"},{"w":"虫歯","m":"gigi berlubang"},{"w":"治療","m":"perawatan, pengobatan"},{"w":"歯ぐき","m":"gusi"},{"w":"検診","m":"pemeriksaan kesehatan"}],"grammar":[{"t":"～ように言われる","note":"Diminta/disuruh melakukan sesuatu (perintah tidak langsung). 「書くように言われました」= diminta untuk menulis/mengisi."},{"t":"～そうです(kabarnya)","note":"Katanya, kabarnya. 「傷めてしまうそうです」= katanya bisa melukai; informasinya berasal dari orang lain."},{"t":"～なければなりません","note":"Harus. 「通わなければなりません」= harus bolak-balik berkali-kali."}]},"a-n3-10":{"title":"Aturan Membuang Sampah","topic":"Kehidupan","trans":["Setelah mulai tinggal di Jepang, hal pertama yang membuatku bingung adalah cara memilah sampah.","Sampah yang bisa dibakar, sampah yang tidak bisa dibakar, sampah daur ulang — pemilahan dan hari pengambilannya berbeda-beda di tiap distrik. Setelah pindah rumah, sebaiknya kamu cek dulu tabel daftar yang bisa diambil di kantor kota.","Botol plastik dibuang setelah label dan tutupnya dilepas, lalu bagian dalamnya dibilas sedikit. Kelihatannya merepotkan, tapi katanya langkah kecil inilah yang menentukan apakah botol bisa didaur ulang.","Waktu membuang juga ada aturannya. Di banyak daerah, sampah harus dikeluarkan paling lambat pukul delapan pagi di hari pengambilan. Soalnya kalau dikeluarkan malam sebelumnya, sampah bisa diobrak-abrik burung gagak.","Sampah besar harus didaftarkan lebih dulu lewat telepon atau internet, lalu kamu membeli stiker di minimarket dan menempelkannya. Tidak sedikit orang yang meletakkannya begitu saja tanpa tahu hal ini dan akhirnya ditegur.","Awalnya aku merasa aturannya terlalu rumit, tapi lama-lama aku jadi terbiasa.","Cara membuang sampah mungkin adalah 「共通ルール」 (aturan bersama) pertama untuk hidup di suatu daerah."],"vocab":[{"w":"戸惑う","m":"bingung, kebingungan"},{"w":"分類","m":"pemilahan, klasifikasi"},{"w":"資源ゴミ","m":"sampah daur ulang"},{"w":"一覧表","m":"tabel daftar"},{"w":"すすぐ","m":"membilas"},{"w":"ひと手間","m":"satu langkah ekstra, sedikit usaha tambahan"},{"w":"荒らす","m":"mengobrak-abrik, merusak"},{"w":"粗大ゴミ","m":"sampah besar (perabot dll.)"},{"w":"申し込む","m":"mendaftar, mengajukan"}],"grammar":[{"t":"～によって(tergantung…)","note":"Berbeda-beda tergantung hal yang disebut sebelumnya. 「区によって分類も違う」= pemilahannya juga berbeda tergantung distrik."},{"t":"～らしい(kabarnya)","note":"Menyimpulkan berdasarkan informasi yang didengar. 「決まるらしい」= katanya begitulah yang menentukan."},{"t":"～ているうちに","note":"Selama melakukan sesuatu, tanpa sadar terjadi perubahan. 「住んでいるうちに慣れてきた」= lama-lama tinggal di sini, aku jadi terbiasa."}]},"a-n5-9":{"title":"Sehari Bermain di Taman","topic":"Kehidupan","trans":["Hari Sabtu cuacanya cerah. Aku sudah janjian dengan temanku untuk pergi ke taman. Kami bertemu di stasiun pukul sembilan pagi.","Malam sebelumnya, aku membuat bekal. Isinya telur dadar gulung, onigiri, dan sayuran. Aku juga membuat sedikit untuk temanku.","Kami pergi ke taman naik sepeda. Di sepanjang jalan ada banyak pohon sakura. Angin terasa menyenangkan.","Kami makan bekal di bangku taman. Rasanya enak sekali. Temanku juga bilang enak.","Setelah makan, aku dan temanku main bulu tangkis, foto-foto, dan sebagainya. Semua orang tampak senang.","Sore harinya aku pulang ke rumah. Memang sedikit capek, tapi hari ini sangat menyenangkan. Minggu depan aku ingin pergi ke taman lagi."],"vocab":["hari Sabtu","cuaca","teman","taman","janji","bekal (bento)","telur dadar gulung","onigiri (nasi kepal)","sepeda","foto"],"grammar":[{"t":"へ(arah)","note":"Menunjukkan arah perpindahan, sering dipakai dengan kata kerja seperti「行く」: 「こうえんへ 行く」(pergi ke taman)."},{"t":"bentuk た+あと","note":"Kata kerja bentuk た + 「あと」berarti \"setelah ~\": 「たべた あと、あそびました」(setelah makan, aku bermain)."},{"t":"~たり~たりする","note":"Menyebutkan beberapa contoh tindakan atau keadaan: 「バドミントンを したり、しゃしんを とったり しました」(main bulu tangkis, foto-foto, dan sebagainya)."},{"t":"も(juga)","note":"Berarti \"juga\", dipasang setelah kata benda: 「ともだちも おいしいと いいました」(temanku juga bilang enak)."}]},"a-n4-10":{"title":"Kasir Swalayan","topic":"Kehidupan","trans":["Minggu lalu, aku pertama kalinya memakai kasir swalayan di supermarket dekat rumah. Walaupun tidak ada pegawai toko, kita bisa membayar belanjaan sendiri.","Pertama, keluarkan barang dari keranjang satu per satu, lalu dekatkan barcode ke mesin. Kalau terdengar bunyi, itu tandanya barang berhasil dipindai.","Selanjutnya, sambil melihat layar, pilih cara pembayaran: tunai atau kartu. Kalau bayar tunai, masukkan uangnya ke tempat memasukkan uang.","Karena baru pertama kali, aku tidak tahu harus menekan di mana dan sempat bingung. Tapi waktu aku kesulitan, pegawai toko yang ada di dekat situ langsung membantuku.","Kasir swalayan tidak perlu antre di kasir, jadi sangat praktis saat kita buru-buru. Hanya saja, mungkin agak sulit bagi orang yang belum terbiasa.","Kalau sudah terbiasa dengan cara pakainya, siapa pun bisa memakainya dengan mudah. Bagi kamu yang mau mencobanya, coba dulu dengan pelan-pelan sambil melihat layar ya."],"vocab":["pegawai toko","barang","mesin","layar","uang tunai","membayar","memilih","bingung, ragu","membantu","terbiasa"],"grammar":[{"t":"~てくれる","note":"Orang lain melakukan sesuatu untuk kita: 「店員さんが 手伝って くれました」(pegawai toko membantuku)."},{"t":"~なくてもいい","note":"Menyatakan bahwa sesuatu tidak perlu dilakukan: 「レジに ならばなくても いいです」(tidak perlu antre di kasir)."},{"t":"~ずつ","note":"Berarti \"masing-masing / per ~\" dengan jumlah yang sama: 「一つずつ とりだす」(mengeluarkan satu per satu)."},{"t":"~か~か","note":"Menyatakan pilihan di antara dua hal: 「げんきんか カードか」(tunai atau kartu)."}]},"a-n2-10":{"title":"Praktik Houren-sou: Lapor, Kabar, Konsultasi","topic":"Dunia Kerja","trans":["「報・連・相」 (houren-sou) yang sering disebut di tempat kerja Jepang itu mudah diingat, tapi sulit dipraktikkan.","Yang paling sering bikin karyawan asing bingung adalah soal menilai: apakah boleh melapor saat kesimpulan belum keluar?","Jawabannya langsung saja: tidak apa-apa meski belum ada kesimpulan. Justru saat kemajuan pekerjaan kurang lancar, kamu diharapkan membagikannya lebih awal.","Sebab, yang ingin diketahui atasan bukan laporan yang sempurna, melainkan satu kalimat sebelum risikonya terlambat ditangani.","「〇〇の件、今のところ半分ほど進んでいますが、資料待ちで少し遅れそうです」——segini saja sudah cukup berfungsi.","Konsultasi juga sama: tidak masalah datang tanpa membawa jawaban. Asalkan kamu bisa mengungkapkan dengan kata-kata di mana kamu bingung, itu sendiri sudah cukup sebagai konsultasi.","Kalau houren-sou dipandang bukan sebagai tata krama hubungan atasan-bawahan, melainkan sebagai sistem untuk mencegah masalah di dalam tim, bebannya pasti jauh terasa lebih ringan."],"vocab":[{"w":"実践","m":"praktik, penerapan"},{"w":"とりわけ","m":"terutama, khususnya"},{"w":"つまずく","m":"tersandung, terhambat"},{"w":"進捗","m":"kemajuan, progres"},{"w":"思わしくない","m":"kurang memuaskan, kurang lancar"},{"w":"手遅れ","m":"sudah terlambat"},{"w":"言語化","m":"menyatakan dengan kata-kata"},{"w":"作法","m":"tata krama, aturan"},{"w":"仕組み","m":"sistem, mekanisme"}],"grammar":[{"t":"～となると","note":"Kalau sudah sampai pada situasi tertentu, keadaannya jadi lain. 「実践となると難しい」= kalau soal praktik, jadi sulit."},{"t":"～こそ","note":"Menekankan \"justru pada saat itu\". 「思わしくないときこそ」= justru saat kurang lancar (itulah yang paling perlu)."},{"t":"～ても構わない","note":"Meskipun… tidak masalah. 「行っても構わない」= boleh saja pergi."},{"t":"～というより","note":"Daripada dibilang A, lebih tepat B. 「作法というより仕組み」= daripada dibilang tata krama, lebih tepat disebut sistem."}]},"a-n1-9":{"title":"Rasa Jarak dalam Hunian Jepang","topic":"Budaya","trans":["Dalam hunian Jepang, cara menjaga jarak yang tidak pernah diucapkan tertanam di mana-mana.","Lihat saja satu kebiasaan melepas sepatu di genkan: di sana sudah ditarik garis jelas yang memisahkan \"luar\" dan \"dalam\". Gerakan melangkahi agari-kamachi (undakan pintu masuk) bukan sekadar berpindah tempat, melainkan bisa dibilang ritual untuk berganti suasana.","Sekat seperti fusuma dan shouji sangat menarik karena tidak menutup sepenuhnya. Selembar tipis yang meneruskan suara dan kehadiran, tapi tetap dianggap sudah memisahkan ruangan—justru ketidaktegasan inilah mungkin kearifan untuk hidup bersama orang lain di rumah yang sempit.","Kini, saat apartemen menjadi hunian utama pun, perasaan itu tetap bertahan dalam bentuk yang berbeda. Kepedulian yang nyaris berlebihan terhadap suara aktivitas sehari-hari bukan semata karena dindingnya tipis, melainkan kelanjutan dari tata krama untuk tidak melanggar wilayah satu sama lain.","Hanya saja, rasa jarak seperti ini sulit dibaca oleh orang dari luar. Perlukah menyapa, sampai sejauh mana boleh masuk—justru karena tidak tertulis, kita sering bingung.","Tapi kalau dilihat dari sisi sebaliknya, itu juga berarti takarannya diserahkan kepada masing-masing orang.","Hunian mungkin adalah tempat pertanyaan \"bagaimana mengukur jarak dengan orang lain\" diulang dengan tenang setiap hari."],"vocab":[{"w":"随所","m":"di mana-mana, di banyak tempat"},{"w":"隔てる","m":"memisahkan, menyekat"},{"w":"上がり框","m":"undakan/ambang di pintu masuk rumah"},{"w":"儀式","m":"ritual, upacara"},{"w":"仕切り","m":"sekat, pembatas"},{"w":"示唆に富む","m":"penuh makna, memberi banyak petunjuk"},{"w":"気配","m":"tanda kehadiran, suasana"},{"w":"配慮","m":"kepedulian, pertimbangan"},{"w":"侵す","m":"melanggar, mengusik"},{"w":"委ねる","m":"menyerahkan, mempercayakan"}],"grammar":[{"t":"～をとっても","note":"Mengambil satu contoh saja. 「習慣ひとつをとっても」= bahkan kalau ambil satu kebiasaan saja."},{"t":"～ゆえに／～ゆえ","note":"Ungkapan sebab ragam tulis. 「壁の薄さゆえ」= karena dindingnya tipis."},{"t":"～というより","note":"Daripada dibilang A, lebih tepat B. Dipakai untuk meralat ucapan dan mengarahkan fokus ke bagian belakang."},{"t":"裏を返せば","note":"Kalau dibalik. Dipakai untuk melihat hal yang sama dari sisi sebaliknya."}]},"a-n3-11":{"title":"Pentingnya Hōrensō (報連相)","topic":"Dunia Kerja","trans":["Di perusahaan Jepang, 「報連相」 sering disebut sangat penting. Ini adalah istilah gabungan dari tiga hal: laporan, kabar (komunikasi), dan konsultasi.","Menyampaikan perkembangan pekerjaan kepada atasan disebut laporan. Kalau terjadi masalah, kamu diharapkan segera melapor.","Kabar (komunikasi) berarti menyampaikan informasi yang diperlukan kepada orang yang bersangkutan. Misalnya saat jadwal berubah, memberi kabar lebih awal dianggap penting.","Konsultasi berarti bertanya kepada atasan atau rekan kerja tentang hal yang tidak bisa kamu putuskan sendiri. Meski hal kecil, kalau dikonsultasikan, kamu bisa mencegah kesalahan besar.","Bagi karyawan asing, kebiasaan hōrensō ini mungkin terasa sulit pada awalnya. Sebab, di negara asal mereka, ada kalanya orang yang mengambil keputusan dan bekerja sendiri justru dihargai.","Namun, kalau kamu menjalankan hōrensō dengan benar, kamu akan lebih mudah mendapat kepercayaan di dalam tim. Kalau kamu bekerja di perusahaan Jepang, memahami cara berpikir ini pasti akan berguna."],"vocab":["singkatan dari laporan, kabar, dan konsultasi","laporan; melapor","kabar; komunikasi; menghubungi","konsultasi; berunding","perkembangan; kemajuan (pekerjaan)","atasan","rekan kerja","kepercayaan","penilaian; keputusan","penilaian; apresiasi"],"grammar":[{"t":"~と言われています","note":"Menyatakan \"katanya ~\" atau \"dikatakan ~\", misalnya: 「報連相が大切だと言われています」(Hōrensō dikatakan penting)."},{"t":"~ことです","note":"Mengubah kalimat verba menjadi frasa benda yang berarti \"~ itu adalah hal/tindakan ...\", misalnya: 「情報を伝えることです」(Yaitu menyampaikan informasi)."},{"t":"~ば","note":"Menyatakan syarat \"kalau ~\", misalnya: 「相談すれば、失敗を防げます」(Kalau berkonsultasi, kesalahan bisa dicegah)."},{"t":"~かもしれません","note":"Menyatakan dugaan \"mungkin ~\", misalnya: 「難しく感じられるかもしれません」(Mungkin akan terasa sulit)."}]},"a-n5-10":{"title":"Memesan Makanan di Restoran","topic":"Kehidupan Sehari-hari","trans":["Hari ini, aku pergi ke restoran bersama temanku.","Aku melihat menu, lalu memilih makanan.","Aku memanggil pelayan. Aku memesan paket makan (teishoku) dan teh.","Makanannya datang dengan cepat. Rasanya enak sekali.","Setelah makan, aku membayar di kasir. Bisa pakai kartu juga, jadi praktis."],"vocab":["restoran","menu","pelayan","memanggil","paket makan (teishoku)","memesan","masakan; hidangan","kasir","membayar","praktis; mudah"],"grammar":[{"t":"〜て、〜(bentuk て untuk menyambung)","note":"Bentuk て pada verba menyambung dua tindakan, misalnya: 「メニュー を みて、りょうり を えらびました。」"},{"t":"〜ました(bentuk lampau)","note":"Menyatakan tindakan yang sudah terjadi di masa lalu, misalnya: 「てんいん さん を よびました。」"},{"t":"〜あと、〜","note":"Menyatakan \"setelah melakukan ~\", misalnya: 「たべた あと、レジ で おかね を はらいました。」"},{"t":"〜も","note":"Berarti \"juga\", misalnya: 「カード も つかえて、べんり でした。」"}]},"a-n5-11":{"title":"Kartu IC Pertamaku","topic":"Kehidupan","trans":["Setelah datang ke Jepang, untuk pertama kalinya aku membeli kartu IC di stasiun. Aku memasukkan seribu yen ke mesin.","Saat naik kereta, kamu tinggal menempelkan kartu di gerbang tiket. Akan terdengar bunyi \"bip\" yang pendek.","Tidak perlu buang waktu untuk membeli tiket. Praktis banget.","Dan bukan cuma kereta, bus dan minimarket juga bisa pakai kartu ini.","Kemarin, di gerbang tiket tiba-tiba terdengar bunyi \"ping-pong\" yang keras. Ternyata saldo di kartuku kurang.","Petugas stasiun bilang, \"Silakan isi saldo di mesin yang di sebelah sana.\"","Sekarang, sebelum masuk stasiun, aku selalu mengecek saldo kartuku dulu."],"vocab":["stasiun","mesin","gerbang tiket","tiket","praktis, nyaman","cukup","petugas stasiun","memberi tahu, mengajar","isi saldo, top up"],"grammar":[{"t":"～とき","note":"Artinya \"saat melakukan sesuatu\". Kata kerja bentuk kamus + とき: 「でんしゃ に のる とき」 = saat naik kereta."},{"t":"～ことができる","note":"Menyatakan kemampuan atau kemungkinan. Kata kerja bentuk kamus + ことができる: 「つかう こと が できます」 = bisa dipakai."},{"t":"～まえに","note":"Artinya \"sebelum melakukan sesuatu\". Kata kerja selalu memakai bentuk kamus: 「えき に 入る まえ に」 = sebelum masuk stasiun."}]},"a-n4-12":{"title":"Vaksin Flu","topic":"Kesehatan","trans":["Begitu masuk bulan Oktober, di klinik dekat rumah ditempel pengumuman \"Vaksin flu sudah dimulai\".","Musim dingin tahun lalu aku terkena flu, dan harus izin tidak masuk kerja selama seminggu penuh.","Karena itu, tahun ini aku memutuskan untuk divaksin lebih awal.","Aku membuat janji lewat telepon dulu, lalu datang. Di resepsionis, aku diberi formulir pemeriksaan. Kita mengukur suhu badan, lalu menulis kondisi tubuh kita.","Suntiknya tidak sesakit yang kubayangkan. Setelah selesai, aku diminta beristirahat sebentar di ruang tunggu.","Vaksin tidak bisa memakai asuransi kesehatan, jadi terasa agak mahal. Katanya harga berbeda-beda tergantung rumah sakit, dan aku membayar 3.500 yen.","Katanya butuh sekitar dua minggu sampai vaksinnya bekerja. Kalau divaksin sebelum flu mewabah, kamu bisa menjalani musim dingin dengan tenang."],"vocab":["vaksinasi, vaksin","resepsionis, meja pendaftaran","lebih awal","menyerahkan","kondisi","suntik","ruang tunggu","asuransi kesehatan","efek, khasiat","mewabah, sedang tren"],"grammar":[{"t":"～なければなりません","note":"Harus, terpaksa. 「休まなければなりませんでした」 = (waktu itu) terpaksa izin tidak masuk."},{"t":"～ことにする","note":"Memutuskan sendiri. 「受けることにしました」 = memutuskan untuk divaksin."},{"t":"～そうです(kabar)","note":"Katanya. 「違うそうですが」「かかるそうです」 = kabar dari orang lain, bukan sesuatu yang dipastikan sendiri."},{"t":"～ておく","note":"Melakukan sesuatu lebih dulu sebagai persiapan. 「受けておく」 = divaksin dulu (sebelum wabah)."}]},"a-n4-11":{"title":"Hari Aku Meninggalkan Payung di Kereta","topic":"Kehidupan sehari-hari","trans":["Hari ini aku meninggalkan payungku di dalam kereta. Saat sadar, kereta sudah sampai di stasiun berikutnya. Aku bingung sekali, jadi aku memutuskan untuk pergi ke pusat barang hilang di stasiun.","Aku menjelaskan kepada petugas bahwa payungku hilang. Petugas berkata, \"Tolong sebutkan ciri-cirinya,\" jadi aku menyebutkan warna dan bentuknya. Aku bilang, \"Payungnya hitam dan gagangnya agak bengkok.\" Petugas berkata, \"Tolong tunggu sebentar, saya cari dulu,\" lalu ia pun mencarikannya untukku.","Setelah menunggu beberapa saat, petugas bilang sepertinya payung yang mirip sudah ketemu. Waktu payung itu dibawakan dari bagian dalam, ternyata memang benar itu payungku. Aku bisa langsung menerimanya kembali dan benar-benar merasa lega. Mulai sekarang, aku akan memeriksa dulu apakah ada barang yang tertinggal setiap kali turun dari kereta."],"vocab":["barang yang tertinggal/hilang","sadar, menyadari","bingung, kesulitan","ciri khas, ciri-ciri","bengkok, melengkung","ditemukan","menerima, mengambil","merasa lega","memastikan, mengecek"],"grammar":[{"t":"〜たら","note":"Menyatakan bahwa setelah suatu tindakan terjadi, muncul hasil atau penemuan berikutnya, sering dengan nuansa kejutan. Contoh: 「気がついたら、もう電車は次の駅に着いていました。」"},{"t":"Bentuk potensial","note":"Menyatakan kemampuan atau kemungkinan untuk melakukan sesuatu. Contoh: 「すぐに受け取れて、本当にほっとしました。」"},{"t":"Ungkapan memberi-menerima (〜てくれる/〜てもらう)","note":"Menyatakan bahwa orang lain melakukan sesuatu untuk kita, atau kita mendapat bantuan setelah meminta orang lain melakukannya. Contoh: 「係の人は…と言ってくれました。」、「奥から傘を持ってきてもらったら」"},{"t":"〜そうだ(様態)","note":"Menyatakan dugaan bahwa sesuatu akan terjadi berdasarkan tampilan atau situasi. Contoh: 「同じような傘が見つかりそうだと言われました。」"}]},"a-n3-12":{"title":"Dasar-dasar Email Bisnis","topic":"Tempat kerja","trans":["Saat bekerja di perusahaan Jepang, ada beberapa aturan dasar dalam menulis email. Berbeda dengan telepon, email punya keuntungan karena bisa dibaca oleh penerima pada waktu yang cocok untuknya. Kalau salah menulis, kesannya bisa jadi tidak sopan, jadi karyawan baru biasanya banyak belajar dari senior.","Pertama, penting untuk menulis subjek email dengan singkat agar isinya langsung bisa dipahami sekilas. Daripada hanya menulis \"Soal rapat\", lebih baik menulis secara spesifik seperti \"Soal jadwal rapat minggu depan\". Kalau subjeknya tidak jelas, penerima yang sedang sibuk mungkin akan terlewat membaca emailnya. Namun, bukan berarti subjek yang panjang itu lebih baik; kamu juga perlu berusaha merangkumnya dengan singkat.","Di awal email, kalimat 「お世話になっております」 sering dipakai. Ini adalah sapaan yang menunjukkan rasa terima kasih atas hubungan dengan lawan bicara, dan dipakai untuk orang di luar maupun di dalam perusahaan. Untuk orang yang pertama kali dihubungi, kadang dipakai ungkapan seperti 「はじめてご連絡いたします」. Pada isi email, kamu dituntut menulis dengan sopan memakai kalimat-kalimat pendek agar maksudnya tersampaikan dengan jelas.","Banyak orang menutup email dengan kalimat 「よろしくお願いいたします」. Dengan kalimat ini, seluruh tulisan memberi kesan sopan, dan penerima pun bisa membacanya dengan nyaman. Selain itu, membalas email secepat mungkin setelah menerimanya juga termasuk etika yang penting. Bahkan kalau belum bisa langsung menjawab, mengirim satu kalimat seperti 「確認して後日ご連絡します」 akan membuat penerima tenang."],"vocab":["subjek email","ringkas, singkat dan jelas","konkret, spesifik","terlewat membaca/melihat","sopan, teliti","balasan (surat/email)","etika, sopan santun","tenang, lega","karyawan baru","keuntungan, kelebihan"],"grammar":[{"t":"〜ように","note":"Menyatakan melakukan sesuatu demi mencapai tujuan atau keadaan tertentu. Dalam teks: 「件名は一目で内容がわかるように、簡潔に書くことが大切です」."},{"t":"〜わけではない","note":"Menyatakan bahwa tidak sepenuhnya begitu; sebuah penyangkalan sebagian yang halus. Dalam teks: 「件名を長くしすぎればよいというわけではなく」."},{"t":"〜ことにする","note":"Menyatakan cara yang diputuskan sendiri atau kebiasaan yang dijalani. Dalam teks: 「よろしくお願いいたします、という言葉で締めることにしている人が多いです」."},{"t":"〜ておく","note":"Menyatakan melakukan sesuatu terlebih dahulu demi kemudahan di kemudian hari. Dalam teks: 「確認して後日ご連絡します、と一言送っておくと安心されます」."}]},"a-n4-13":{"title":"Hari Shichi-Go-San","topic":"Budaya","trans":["Pada suatu hari Sabtu di bulan November, aku pergi jalan-jalan ke kuil Shinto di dekat rumah bersama temanku. Di halaman kuil ada banyak anak yang memakai kimono cantik bersama keluarga mereka. Seorang anak perempuan kecil memakai kimono merah dan berfoto dengan gembira.","Temanku yang orang Jepang, Tanaka, memberi tahu aku bahwa ini adalah Shichi-Go-San. Shichi-Go-San adalah tradisi untuk merayakan pertumbuhan anak-anak yang berusia tiga, lima, dan tujuh tahun. Keluarga meminta pihak kuil mendoakan anak mereka, dan memohon agar anak tumbuh sehat.","Tanaka menunjuk kantong kertas panjang yang dipegang anak-anak itu. Di dalamnya ada permen panjang dan tipis bernama Chitose-ame. Katanya, permen itu membawa harapan keluarga agar sang anak berumur panjang. Tanaka bilang, Chitose-ame juga bisa dibeli di toko kue Jepang dan tempat sejenisnya. Kalau suatu hari nanti aku punya anak, aku juga ingin menyiapkan Chitose-ame untuk merayakannya."],"vocab":["kuil Shinto","halaman kuil","kimono","pertumbuhan","merayakan","acara, upacara, tradisi","tumbuh besar","Chitose-ame (permen panjang dan tipis sebagai doa berumur panjang)","umur panjang","harapan, permohonan"],"grammar":[{"t":"〜てくれる/〜てもらう","note":"Menyatakan bahwa orang lain melakukan sesuatu untuk kita. 「田中さんが…教えてくれました」berarti orang itu berinisiatif membantu; 「お祈りをしてもらって」berarti meminta orang lain melakukan sesuatu dan kita mendapat manfaatnya."},{"t":"〜そうだ(tampak・kabarnya)","note":"Setelah akar kata sifat-i atau kata kerja, artinya \"kelihatannya...\": 「うれしそうに写真をとっていました」. Setelah bentuk biasa, artinya kabar yang didengar, \"katanya...\": 「願いがこめられているそうです」."},{"t":"〜たら","note":"Menyatakan pengandaian atau syarat, \"kalau...\": 「もし将来子どもができたら、わたしも…お祝いしたいです」."},{"t":"Bentuk potensial","note":"Menyatakan \"bisa...\". 「買える」adalah bentuk potensial dari 「買う」: 「和菓子屋さんなどでも買える」."}]},"a-n5-13":{"title":"Belanja di Musim Dingin","topic":"Kehidupan","trans":["Akhir-akhir ini cuaca jadi sangat dingin. Hari Sabtu, aku pergi ke toko bersama temanku.","Aku ingin mantel hitam. Temanku bilang, \"Yang merah juga bagus, lho.\" Aku bertanya kepada pegawai toko, \"Boleh dicoba?\"","Mantel merah itu sangat cantik. Aku membeli mantel, sarung tangan, dan syal. Semuanya berwarna kesukaanku."],"vocab":["hari Sabtu","teman","toko","mantel","sarung tangan","syal","hitam","merah","warna","bertanya (bentuk lampau dari 聞く)"],"grammar":[{"t":"〜く なりました","note":"Hilangkan 「い」 pada kata sifat-i, tambahkan 「く」 lalu 「なりました」 untuk menyatakan perubahan keadaan. Contoh: 「さいきん とても さむく なりました。」"},{"t":"〜が ほしい です","note":"Menyatakan ingin memiliki sesuatu. Untuk bentuk lampau, pakai 「ほしかった です」. Contoh: 「わたし は 黒い コート が ほしかった です。」"},{"t":"〜ても いい ですか","note":"Dipakai untuk meminta izin, \"Boleh...?\", misalnya bertanya kepada pegawai toko saat ingin mencoba pakaian. Contoh: 「きても いい ですか」."},{"t":"A と B と C を 買いました","note":"「と」 menghubungkan kata benda, artinya \"A, B, dan C\". Contoh: 「コート と てぶくろ と マフラー を 買いました。」"}]},"a-n3-13":{"title":"Kalau Ada Surat Pemberitahuan Tidak Ada di Rumah","topic":"Kehidupan","trans":["Sepulang kerja, ada selembar kertas di kotak surat. Itu \"slip pemberitahuan tidak ada di rumah\" dari jasa kurir.","Karena paket datang saat aku tidak ada di rumah, aku harus meminta mereka mengantarnya sekali lagi. Ini disebut \"再配達\" (pengantaran ulang).","Dulu biasanya kita menelepon nomor yang tertulis di kertas, tapi sekarang bisa diajukan dengan mudah lewat ponsel. Kamu cukup memindai kode QR di kertas itu, lalu memilih hari dan rentang waktu yang kamu mau.","Namun, di slip itu juga tertulis batas waktu penyimpanan. Kalau tidak segera diurus, paketnya bisa dikembalikan ke pengirim, jadi hati-hati ya.","Di sisi lain, pengantaran ulang memerlukan bahan bakar truk dan tenaga kerja. Sekarang, saat kekurangan pengemudi sudah menjadi masalah sosial, kita diharapkan bisa menerima paket dalam sekali antar sebisa mungkin.","Nah, yang praktis untuk itu adalah \"置き配\" (paket ditaruh di depan pintu) dan boks paket. Kalau paket ditaruh di depan pintu atau di dalam boks, kamu tetap bisa menerimanya walau tidak ada di rumah.","Belakangan ini, saat berbelanja online, aku juga berusaha memikirkan cara menerima paketnya sekalian. Memang usaha kecil, tapi kebiasaan ini menyenangkan untuk diriku sendiri dan juga untuk para kurir."],"vocab":["kotak surat","jasa kurir (pengiriman paket ke rumah)","slip pemberitahuan tidak ada di rumah","tidak ada di rumah","pengantaran ulang","rentang waktu","batas waktu penyimpanan","pengirim","tenaga kerja","paket ditaruh di depan pintu","belanja online, pesan lewat katalog/pos"],"grammar":[{"t":"～ように頼む","note":"Meminta orang lain melakukan sesuatu (isi permintaan disampaikan secara tidak langsung). 「届けてくれるように頼まなければならない」= harus meminta mereka mengantarkannya lagi."},{"t":"～だけで済む","note":"Cukup dengan melakukan ~ saja, tidak perlu yang lain. 「選ぶだけで済む」= cukup memilih saja, beres."},{"t":"～ないと","note":"\"Kalau tidak ~ (nanti ...)\", biasanya diikuti hasil yang buruk. 「早めに手続きしないと、…返されてしまう」."},{"t":"～ようにしている","note":"Kebiasaan yang sengaja dijaga. 「考えるようにしている」= aku berusaha selalu memikirkannya."}]},"a-n2-11":{"title":"「お通し」di Izakaya","topic":"Budaya","trans":["Saat duduk di izakaya Jepang, kadang ada piring kecil yang diantar padahal kamu tidak memesannya. Itulah yang disebut「お通し」.","Di wilayah Kansai, ini juga sering disebut「突き出し」. Isinya berbeda-beda tergantung tokonya, misalnya edamame, makanan rebus, atau sayuran berbumbu.","Di antara orang yang baru pertama kali datang ke Jepang, tidak sedikit yang bingung saat melihat ada biaya お通し di tagihan, lalu bertanya-tanya apakah itu penagihan yang tidak adil.","Harga umumnya katanya sekitar tiga ratus sampai lima ratus yen, dan bagi toko artinya mirip dengan biaya tempat duduk.","Ada juga pandangan bahwa ini bentuk perhatian agar tamu tidak bosan menunggu sampai makanan keluar.","Meski begitu, bisa menolak atau tidaknya tergantung kebijakan toko, dan belakangan makin banyak toko yang tidak menyajikan お通し. Kalau kamu penasaran, cukup tanyakan sebentar saat masuk ke toko.","Kalau tahu latar belakangnya, piring kecil yang belum pernah kamu lihat pun bisa dinikmati sebagai bagian dari budaya minum di Jepang, bukan?"],"vocab":["izakaya (kedai minum ala Jepang)","mangkuk/piring kecil","お通し (hidangan pembuka kecil di izakaya)","pembayaran, tagihan","penambahan, dijumlahkan","bingung, kebingungan","harga umum, harga pasaran","makna, konotasi","tidak ada kegiatan, bosan menganggur","perhatian, kepedulian","kebijakan"],"grammar":[{"t":"～際(に)","note":"\"Pada saat ~\", lebih formal daripada「とき」. 「会計の際に」= saat membayar."},{"t":"～次第","note":"\"Tergantung ~\". 「店の方針次第であり」= tergantung kebijakan toko."},{"t":"～つつある","note":"Suatu perubahan sedang terus berlangsung. 「増えつつある」= sedang terus bertambah."},{"t":"とはいえ","note":"\"Meski begitu\"; mengakui pernyataan sebelumnya, lalu menambahkan keberatan atau sudut pandang yang berlawanan."}]},"a-n3-14":{"title":"Ayo Berburu Daun Momiji","topic":"Budaya","trans":["Akhir Oktober, rekan kerjaku, Tanaka, mengajakku: 「今週末、紅葉を見に行きませんか」(\"Akhir pekan ini mau pergi melihat daun momiji?\"). Di Jepang, menikmati daun yang berubah warna di gunung atau taman saat musim gugur disebut 「紅葉狩り」, dan kegiatan ini sudah disukai sejak dulu. Aku suka daun momiji, tapi aku dengar tempat-tempat terkenal itu ramai sekali, jadi aku agak khawatir.","Tanaka mengusulkan, 「人込みを避けるために、朝早く出発するのはどうでしょうか」(\"Supaya terhindar dari keramaian, bagaimana kalau berangkat pagi-pagi?\"). Katanya, kalau sudah siang, tempat parkir dan jalan jadi macet, jadi kalau kita sampai sebelum tengah hari, kita bisa berjalan dengan santai. Hari kerja memang sering lebih sepi, tapi tidak selalu tenang, jadi sebaiknya jangan berharap terlalu tinggi.","Selanjutnya, kami memutuskan untuk mencari 「紅葉情報」 (info daun momiji) yang dipublikasikan di situs asosiasi pariwisata dan situs cuaca. Di sana, kondisi pohon dijelaskan dengan mudah dipahami lewat kata-kata seperti 「色づき始め」 dan 「見ごろ」. Tanaka mengingatkanku agar memeriksanya lagi sebelum berangkat, karena waktu terbaik untuk melihatnya berbeda-beda di tiap tempat. Setelah berdiskusi, kami memilih taman kecil dekat pegunungan dan memutuskan pergi naik kereta paling pagi.","Hari itu aku agak mengantuk, tapi bangun pagi ternyata sepadan: di jalan hampir tidak ada orang. Daun-daun merah dan kuning disinari cahaya pagi, sampai-sampai udaranya pun terlihat ikut berwarna. Di tengah hari-hari yang sibuk, kesempatan untuk merasakan pergantian musim dengan santai tidak banyak. Saat pulang, aku berterima kasih: 「誘ってくださって、ありがとうございました」(\"Terima kasih sudah mengajak saya\"). Tanaka tertawa dan berkata 「来年も行きましょう」, jadi aku sudah tidak sabar menantikan musim gugur berikutnya."],"vocab":["berburu/melihat daun momiji (musim gugur)","rekan kerja","keramaian, kerumunan orang","menghindari","usul, saran","info daun momiji (perubahan warna)","waktu terbaik untuk dinikmati","berubah warna, menjadi berwarna","menyinari","kesempatan"],"grammar":[{"t":"〜ように(permintaan・tujuan)","note":"Dipakai untuk menyatakan melakukan sesuatu agar suatu keadaan tercapai, atau meminta/menyarankan orang lain melakukan sesuatu. Contoh: 「確認するように田中さんが教えてくれた」「午前のうちに着くようにすれば」."},{"t":"〜わけではない","note":"Artinya \"bukan berarti ...\"; negasi sebagian. Contoh: 「いつも静かなわけではないので」."},{"t":"〜ことにする","note":"Menyatakan keputusan pembicara sendiri untuk melakukan sesuatu. Contoh: 「紅葉情報を調べることにした」「朝一番の電車で行くことにした」."},{"t":"Keigo (くださる)","note":"「〜てくださる」adalah bentuk hormat dari「〜てくれる」, dipakai untuk berterima kasih atas kebaikan orang lain. Contoh: 「誘ってくださって、ありがとうございました」."}]},"a-n5-12":{"title":"Oden di Minimarket","topic":"Kehidupan","trans":["Pada suatu malam musim dingin, aku masuk ke minimarket. Di samping kasir ada oden. Baunya enak, dan perutku jadi lapar.","Aku berkata, 「だいこん と たまご を ください」(\"Minta lobak dan telurnya, ya\"). Pegawai toko bertanya, 「つゆ と からし は いりますか」(\"Mau kuah dan karashi?\"). Aku menjawab, 「つゆ だけ ください」(\"Kuahnya saja, ya\").","Sesampainya di rumah, aku langsung memakannya. Oden yang panas itu membuat badanku jadi hangat."],"vocab":["oden (rebusan khas Jepang)","lobak putih (daikon)","telur","kasir","kuah","karashi (mustard Jepang yang pedas)","pegawai toko","bau, aroma","hangat","masuk"],"grammar":[{"t":"〜を ください","note":"Dipakai untuk meminta sesuatu atau memesan. Contoh: 「だいこん と たまご を ください」. Kalau hanya mau satu hal, pakai「だけ」, contoh: 「つゆ だけ ください」."},{"t":"〜と 言いました/聞きました","note":"「と」dipakai untuk mengutip isi ucapan atau pertanyaan. Contoh: 「てんいん さん が『つゆ と からし は いりますか』と 聞きました」."},{"t":"Kata kerja bentuk て、〜","note":"Bentuk「て」menghubungkan beberapa tindakan atau menyatakan sebab. Contoh: 「いい におい が して、おなか が すきました」「うち に かえって、すぐ 食べました」."},{"t":"Kata sifat い → 〜く なります","note":"Menyatakan perubahan keadaan. Contoh: 「からだ が あたたかく なりました」(badanku menjadi hangat)."}]},"a-n2-12":{"title":"Memikirkan Hari Terima Kasih Kerja","topic":"Masyarakat","trans":["Tanggal 23 November adalah 「勤労感謝の日」, hari libur nasional yang setiap tahunnya membuat banyak perusahaan dan sekolah libur. Kalau hanya melihat namanya, orang mudah mengira ini hari khusus untuk para pekerja, tetapi asal-usulnya sebenarnya agak berbeda. Sejak dulu di Jepang, setiap musim gugur diadakan upacara bernama 「新嘗祭」, yaitu mempersembahkan biji-bijian baru hasil panen tahun itu kepada para dewa sebagai ungkapan terima kasih. 「新嘗祭」 adalah perayaan untuk merayakan panen dan berterima kasih atas karunia alam, yang mencerminkan cara pandang masyarakat yang menghargai pertanian.","Setelah perang, saat sistem negara ditinjau ulang secara besar-besaran, bentuk hari libur pun ikut ditata kembali. Pada tahun 1948 ditetapkan 「国民の祝日に関する法律」, dan hari ini menjadi hari libur nasional dengan nama 「勤労感謝の日」. Tujuan yang tercantum dalam undang-undang itu adalah menghargai kerja, merayakan produksi, dan menjadi hari ketika sesama warga saling berterima kasih. Akan lebih mudah dipahami jika kita melihatnya begini: rasa terima kasih kepada para dewa meluas menjadi rasa terima kasih terhadap kegiatan bekerja dan menghasilkan sesuatu itu sendiri.","Di zaman sekarang, seiring cara bekerja yang makin beragam, gambaran yang muncul di benak kita saat mendengar kata 「勤労」 juga berubah. Selain orang yang bekerja di pabrik dan sawah ladang, pekerjaan yang menopang kehidupan kita, seperti toko, logistik, layanan kesehatan, dan perawatan lansia, jumlahnya tak terhitung. Lagi pula, di antara pekerjaan itu ada yang jangankan libur di hari libur nasional, malah terpaksa bekerja lebih keras dari biasanya. Kemudahan yang kita anggap biasa ini berdiri di atas usaha orang-orang tersebut.","Lalu, tindakan apa saja yang bisa kita lakukan untuk mewujudkan rasa terima kasih? Cukup dengan mengucapkan 「ありがとうございます」 kepada orang yang mengantar paket atau pegawai toko, perasaan kita sudah tersampaikan dengan baik. Di tempat kerja pun, mengakui hasil kerja rekan dan mengucapkan terima kasih adalah kebiasaan kecil yang bisa langsung dimulai dengan hari ini sebagai pemicunya. Perlu diingat juga bahwa aturan masuk kerja atau libur di hari libur nasional berbeda-beda di tiap perusahaan, jadi untuk detailnya, tolong cek penjelasan dari perusahaanmu. Bukankah rasa terima kasih baru bermakna jika diucapkan dalam kehidupan sehari-hari, bukan hanya pada satu hari libur?"],"vocab":["asal-usul","新嘗祭 (upacara syukur atas panen biji-bijian baru)","panen, hasil panen","sistem","tujuan, maksud","beragam","logistik","menopang, mendukung","berdiri di atas, terbentuk dari"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring satu hal berubah, hal lain ikut berubah. Contoh: 「働き方が多様になるに伴って、『勤労』という言葉から思い浮かべる姿も変わってきた」"},{"t":"〜どころか","note":"Berarti \"jangankan ..., malah ...\"; menyangkal bagian pertama dan menekankan bagian kedua. Contoh: 「祝日であっても休むどころか、いつも以上に働かざるを得ない」"},{"t":"〜ざるを得ない","note":"Berarti \"terpaksa ...\" atau \"tidak bisa tidak ...\"; tidak ada pilihan lain karena keadaan. Contoh: 「いつも以上に働かざるを得ないものもある」"},{"t":"〜をきっかけに","note":"Menyatakan memulai sesuatu dengan suatu peristiwa sebagai pemicu atau kesempatan. Contoh: 「この日をきっかけにすぐ始められる小さな習慣である」"}]},"a-n5-14":{"title":"Teman dan Nabe","topic":"Kehidupan","trans":["Pada suatu hari di musim dingin, aku makan nabe (hot pot) di rumah bersama teman-teman. Pertama, kami semua pergi ke supermarket. Kami membeli sawi putih, tahu, dan daging.","Di rumah, kami memotong sayuran lalu memasukkannya ke panci. Sayuran dimasukkan lebih dulu, dagingnya belakangan. Ruangan jadi hangat.","Kalau makan bersama-sama, rasanya enak. Malam itu dingin, tapi menyenangkan."],"vocab":["musim dingin","panci; nabe (hot pot)","supermarket","sawi putih","tahu","daging","memasukkan","lebih dulu","hangat","semuanya"],"grammar":[{"t":"〜て、〜(bentuk て kata kerja)","note":"Bentuk て menyambung dua tindakan, artinya melakukan yang pertama lalu yang kedua. Contoh: 「やさい を 切って、なべ に 入れました。」"},{"t":"〜と、〜","note":"Menyatakan hasil atau perasaan yang umum, \"kalau melakukan ..., maka ...\". Contoh: 「いっしょ に たべる と、おいしい です。」"},{"t":"〜く なります","note":"Kata sifat-い diubah menjadi 「〜く」 lalu ditambah 「なります」 untuk menyatakan perubahan keadaan. Contoh: 「へや が あたたかく なりました。」"},{"t":"〜が、〜","note":"Diletakkan di akhir klausa untuk menyatakan pertentangan, \"meskipun ..., tetapi ...\". Contoh: 「さむい よる でした が、たのしかった です。」"}]},"a-n3-15":{"title":"Penyesuaian Pajak Akhir Tahun untuk Pertama Kalinya","topic":"Tempat Kerja","trans":["Menjelang akhir tahun, departemen HR mengirimkan email berjudul 「年末調整のご案内」 beserta dokumennya. Di dokumen itu ada kolom untuk mengisi status tanggungan keluarga dan premi asuransi, dan aku bingung harus mulai menulis dari mana. Ini pertama kalinya aku bekerja di Jepang, jadi istilah 「年末調整」 itu sendiri pun belum pernah kudengar.","Waktu aku bertanya pada Tanaka-san yang duduk di sebelahku, dia bilang, 「毎年の手続きですから、心配はいりませんよ」. Katanya, pajak yang dipotong dari gaji tiap bulan itu hanya perhitungan sementara, dan di akhir tahun pajak setahun penuh dihitung ulang. Karena pajak berubah tergantung kondisi keluarga dan premi asuransi yang dibayar, mengisinya dengan benar itu penting. Tapi cara mengisinya sedikit berbeda di tiap perusahaan, jadi aku disuruh bertanya langsung ke HR untuk hal yang tidak kupahami.","Keesokan harinya, aku menemui Sato-san dari HR untuk bertanya. Sambil menunjukkan contoh pengisian, dia menjelaskan satu per satu dengan teliti. Katanya, kalau ada asuransi yang kamu bayar sendiri, kadang kamu juga butuh surat keterangan dari perusahaan asuransi. Bukannya aku tidak suka bertanya, tapi HR kelihatannya sibuk sehingga aku merasa sungkan menyapa mereka. Namun Sato-san tersenyum dan menjawab, 「初めてなら聞いて当然ですよ」.","Setelah pulang, aku memutuskan untuk mencari dokumen asuransi di rumah dan memeriksa isi yang harus ditulis dengan santai. Prosedur rincian dan cara pengumpulannya berbeda-beda di tiap perusahaan, jadi pastikan kamu membaca penjelasan dari perusahaanmu. Penyesuaian pajak akhir tahun memang kelihatan merepotkan, tapi aku jadi paham bahwa ini prosedur penting untuk menyesuaikan pajak setahun penuh dengan benar."],"vocab":[{"w":"年末調整","m":"penyesuaian pajak akhir tahun (penghitungan ulang pajak penghasilan di akhir tahun)"},{"w":"人事部","m":"departemen HR"},{"w":"扶養","m":"tanggungan (menafkahi anggota keluarga)"},{"w":"保険料","m":"premi asuransi"},{"w":"手続き","m":"prosedur, urusan administrasi"},{"w":"記入例","m":"contoh pengisian"},{"w":"証明書","m":"surat keterangan, sertifikat"},{"w":"確認","m":"memeriksa, konfirmasi"},{"w":"丁寧","m":"teliti, sopan"},{"w":"給料","m":"gaji"}],"grammar":[{"t":"〜ように言われた","note":"Menyatakan bahwa kita disuruh atau diminta melakukan sesuatu (kalimat tidak langsung). Contoh: 「わからない点は人事に直接聞くように言われた」"},{"t":"〜わけではない","note":"Berarti \"bukan berarti ...\"; negasi sebagian untuk menepis kesalahpahaman. Contoh: 「質問するのが嫌なわけではなかったが」"},{"t":"〜ことにする","note":"Menyatakan keputusan pembicara sendiri untuk melakukan sesuatu. Contoh: 「ゆっくり確認することにした」"},{"t":"〜そうだ(kabar yang didengar)","note":"Dipasang setelah bentuk biasa untuk menyampaikan kabar yang didengar dari orang lain. Contoh: 「年末に一年分を計算し直すのだそうだ」"}]},"a-n4-14":{"title":"Tagihan Listrik di Musim Dingin","topic":"Kehidupan","trans":["Musim dingin di Jepang jauh lebih dingin dari yang kubayangkan, bahkan di dalam rumah. Di kamar yang sudah tua, udara dingin masuk lewat jendela, jadi walaupun pemanas dinyalakan, ruangan susah menghangat. Bulan lalu, aku kaget waktu melihat tagihan: biaya listriknya lebih tinggi dari biasanya. Waktu aku cerita ke teman, dia mengajariku berbagai tips hemat.","Pertama, aku pakai selimut listrik dan menghangatkan futon sebelum tidur. Katanya, kalau menyalakan humidifier, walaupun suhu ruangan sama, rasanya jadi lebih hangat. Setelah mengganti dengan gorden tebal, rasa dingin di dekat jendela berkurang cukup banyak. Aku juga mengatur suhu pemanas sedikit lebih rendah dan memakai jaket di rumah.","Tanaka-san memberitahuku bahwa sebaiknya pemanas di ruangan yang tidak dipakai dimatikan. Soal paket tarif, sebaiknya kamu tanyakan detailnya ke perusahaan listrik. Kalau terus melakukan usaha-usaha kecil, sepertinya aku bisa melewati musim dingin tanpa terlalu memikirkan tagihan listrik."],"vocab":[{"w":"暖房","m":"pemanas ruangan"},{"w":"冷気","m":"udara dingin"},{"w":"請求書","m":"tagihan, surat penagihan"},{"w":"電気代","m":"biaya listrik"},{"w":"節約","m":"hemat, berhemat"},{"w":"電気毛布","m":"selimut listrik"},{"w":"加湿器","m":"humidifier (pelembap udara)"},{"w":"厚い","m":"tebal"},{"w":"設定温度","m":"suhu yang diatur"},{"w":"工夫","m":"akal, siasat, ide kreatif"}],"grammar":[{"t":"〜たら","note":"Berarti \"setelah melakukan ~ (ternyata ...)\" atau syarat/pengandaian. Contoh: 「請求書を見たら、電気代がいつもより高くて」「厚いカーテンに換えたら、窓の近くの冷たさがかなり減りました」。"},{"t":"Bentuk potensial","note":"Menyatakan \"bisa ...\". Contoh: 「あたたかく感じられる」「過ごせそうです」. Kata kerja ichidan memakai 「られる」, kata kerja godan mengubah akhir ke baris e + る."},{"t":"〜そうだ","note":"Ada dua pemakaian: setelah bentuk biasa berarti \"katanya\", setelah bentuk ます tanpa ます berarti \"sepertinya/kelihatannya\". Contoh: 「あたたかく感じられるそうです」(katanya), 「過ごせそうです」(kelihatannya)."},{"t":"〜てもらう/〜てくれる","note":"Menyatakan menerima kebaikan dari orang lain (ungkapan memberi-menerima). Contoh: 「いろいろ教えてもらいました」「教えてくれました」. 〜てもらう memakai diri sendiri sebagai subjek, 〜てくれる memakai orang lain sebagai subjek."}]},"eh-n5-2":{"title":"Tersesat di Stasiun","topic":"Buku Bergambar","trans":["Hari ini cuacanya cerah. Tanutaro naik kereta ke pantai.","Stasiunnya besar sekali. Orangnya juga banyak. Kereta ke pantai ada di peron nomor berapa ya? Tanutaro tidak tahu.","Dia melihat peta, tapi malah makin bingung. Tanutaro jadi pusing.","Saat itu, Kon si rubah datang. Dia bertanya, 「Ada apa?」","Tanutaro bertanya, 「Permisi, kereta ke pantai ada di mana?」","Kon memberi tahu, 「Di peron 3, lho. Naik tangga di sana ya.」","Tanutaro bilang 「Terima kasih」, lalu berlari. Dia berhasil naik keretanya!"],"vocab":[{"w":"駅","m":"stasiun"},{"w":"迷子","m":"anak/orang yang tersesat"},{"w":"電車","m":"kereta listrik"},{"w":"番線","m":"peron nomor …"},{"w":"地図","m":"peta"},{"w":"困る","m":"kesulitan, bingung harus bagaimana"},{"w":"階段","m":"tangga"},{"w":"上る","m":"naik, mendaki"},{"w":"教える","m":"memberi tahu, mengajar"},{"w":"間に合う","m":"keburu, sempat"}],"grammar":[{"t":"〜てください","note":"Kata kerja bentuk て + ください, untuk meminta orang lain melakukan sesuatu dengan sopan. Contoh: あそこの かいだんを のぼって ください。"},{"t":"Kata tanya (どこ・何)","note":"Untuk menanyakan tempat pakai「どこ」, untuk menanyakan nomor peron pakai「何ばんせん」. Contoh: うみへ 行く でんしゃは どこですか。"},{"t":"〜くなります","note":"Kata sifat-い: buang い + くなります, artinya \"menjadi …\". Berlaku juga untuk ない: わからない→わからなく なりました (jadi makin tidak mengerti)."}]},"eh-n4-1":{"title":"Hari Aku Masuk Angin","topic":"Buku Bergambar","trans":["Begitu bangun pagi, kepalanya sakit dan tenggorokannya juga sangat sakit. Sepertinya dia juga demam.","Tanutaro menelepon kantor dan berkata, 「Maaf, saya masuk angin, jadi hari ini mohon izinkan saya libur.」","Lalu dia pergi ke klinik di dekat rumah. Di bagian pendaftaran dia mengeluarkan kartu asuransi kesehatan dan mengisi formulir pemeriksaan.","Dokter bertanya, 「Sejak kapan?」 Dia menjawab, 「Sejak tadi malam, dan saya juga batuk.」","Dokter berkata, 「Cuma masuk angin biasa. Sebaiknya minum obat dan istirahat yang cukup.」","Malam itu, Kon datang membawakan bubur. Hangat dan enak sekali.","Tiga hari kemudian, Tanutaro sudah benar-benar sehat. Pergi ke rumah sakit di Jepang agak menakutkan, tapi sekarang dia sudah baik-baik saja."],"vocab":[{"w":"熱","m":"demam, suhu badan tinggi"},{"w":"休む","m":"libur (tidak masuk), istirahat"},{"w":"受付","m":"meja resepsi, pendaftaran"},{"w":"保険証","m":"kartu asuransi kesehatan"},{"w":"問診票","m":"formulir pemeriksaan (anamnesis)"},{"w":"お医者さん","m":"dokter"},{"w":"薬","m":"obat"},{"w":"おかゆ","m":"bubur"},{"w":"すっかり","m":"sepenuhnya, benar-benar"},{"w":"元気","m":"sehat, bersemangat"}],"grammar":[{"t":"〜ので","note":"Menyatakan sebab/alasan. Lebih halus daripada「から」, sering dipakai saat izin libur atau minta maaf. Contoh: かぜをひいたので、今日は休ませてください。"},{"t":"〜ほうがいいです","note":"Kata kerja bentuk た + ほうがいいです, untuk memberi saran \"sebaiknya …\". Contoh: ゆっくり休んだほうがいいですよ。"},{"t":"受身形 (bentuk pasif)","note":"「(orang)に〜られる」berarti dikenai suatu tindakan oleh orang lain. Contoh: お医者さんに「いつからですか」と聞かれました。"},{"t":"〜てくれます","note":"Orang lain melakukan sesuatu untukku (dengan rasa terima kasih). Contoh: コンちゃんがおかゆを持ってきてくれました。"}]},"a-n3-16":{"title":"Saat Kartu Pos Berkabung Datang","topic":"Budaya","trans":["Di awal November, aku menerima sebuah kartu pos dari Tanaka-san, rekan kerjaku di kantor. Saat kubuka, tertulis 「喪中につき、年始のご挨拶をご遠慮申し上げます」 (karena sedang berkabung, kami mohon maaf tidak mengirim salam tahun baru). Baru saat itulah aku tahu bahwa ayah Tanaka-san meninggal musim panas tahun ini.","Ini disebut 「喪中はがき」, yaitu kartu pos yang dipakai orang yang keluarganya baru ditimpa duka untuk memberi tahu bahwa mereka tidak mengirim kartu tahun baru. Kebiasaan ini muncul dari pemikiran bahwa selama masa berkabung kita menahan diri dari perayaan. Kartu ini biasanya tiba sebelum persiapan kartu tahun baru dimulai, supaya penerimanya diberi tahu lebih awal. 喪中はがき hanyalah pemberitahuan bahwa 「私は年賀状を出せません」 (aku tidak bisa mengirim kartu tahun baru), bukan permintaan untuk dibalas.","Aku sempat bingung, tetapi setelah bertanya kepada rekan kerja, aku memutuskan untuk tidak mengirim kartu tahun baru kepada Tanaka-san. Aku juga diberi tahu bahwa kalau beberapa saat setelah tahun baru lewat aku mengirim 「寒中見舞い」, perasaanku akan tersampaikan. 寒中見舞い adalah surat salam yang menanyakan kabar kesehatan seseorang di musim dingin, dan isinya tidak memuat ucapan selamat. Dalam isinya aku berusaha menuliskan terima kasih atas kartu pos itu dan kata-kata yang menunjukkan perhatian kepada keluarga Tanaka-san.","Cara menangani kartu tahun baru di kantor berbeda-beda tergantung tempat kerjanya, jadi untuk detailnya sebaiknya kamu cek penjelasan dari perusahaan. Kebiasaan mengirim kartu tahun baru memang pelan-pelan berkurang, tetapi budaya menyampaikan perasaan lewat salam musiman masih dihargai sampai sekarang. Dari pengalaman kali ini, aku belajar bahwa memahami keadaan orang lain dan mengubah bentuk salam juga merupakan etika penting di tempat kerja."],"vocab":["masa berkabung","kartu tahun baru","meninggal","salam, sapaan","menahan diri, sungkan (melakukan sesuatu)","menahan diri, menghindari","kartu salam musim dingin (surat salam di musim dingin)","memperhatikan, mengkhawatirkan (kondisi orang lain)","kebiasaan, adat","berusaha memperhatikan, berupaya"],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan yang dibuat sendiri. Contoh: 「田中さんには年賀状を出さないことにした。」"},{"t":"〜わけではない","note":"Berarti \"bukan berarti ...\"; dipakai untuk menyangkal sebagian atau meluruskan salah paham. Contoh: 「返事を求めているわけではない。」"},{"t":"〜ように心がける","note":"Menyatakan usaha dan perhatian khusus demi mencapai suatu tujuan. Contoh: 「お礼と、田中さんの家族を思う言葉を入れるように心がけた。」"},{"t":"〜によって違う","note":"Berarti \"berbeda tergantung ...\". Contoh: 「会社の年賀状の扱いは職場によって違う。」"}]},"a-n4-15":{"title":"Bersih-bersih Akhir Tahun, Mulai Lebih Awal Yuk","topic":"Kehidupan","trans":["Setiap kali bulan Desember tiba, bersih-bersih besar itu melelahkan, dan aku selalu kecapekan. Tahun ini, sebelum Desember, aku mencoba menulis daftar tempat yang akan dibersihkan. Ada dapur, kamar mandi, jendela, pintu masuk, dan masih banyak lagi.","Berikutnya, aku membeli cairan pembersih dan spons di toko obat. Pegawai toko memberi tahu bahwa pembersih untuk kamar mandi juga bisa menghilangkan jamur. Kalau semuanya dikerjakan sekaligus pasti capek, jadi aku memutuskan membersihkan satu tempat saja setiap minggu. Aku menetapkannya begini: minggu ini dapur, minggu depan kamar mandi.","Waktu aku bercerita kepada teman sekamarku, Lin, dia bilang mau mengerjakannya bersama. Aku bertugas di dapur dan kamar mandi, sedangkan Lin bertugas di jendela dan pintu masuk. Untuk sampah besar, aku perlu mengecek cara membuangnya lewat panduan dari kantor kelurahan (区役所). Kata temanku, kalau mulai lebih awal, perasaan juga jadi lebih ringan. Kalau dengan cara ini, kurasa akhir tahun nanti aku bisa istirahat dengan santai."],"vocab":["bersih-bersih besar","akhir tahun","dapur","cairan pembersih, deterjen","setiap minggu","sekaligus, dalam satu waktu","bertanggung jawab, bertugas","kantor distrik (kantor pemerintah tingkat distrik)","perasaan, suasana hati"],"grammar":[{"t":"〜たら","note":"Menyatakan \"setelah melakukan sesuatu / kalau\", biasanya diikuti perkembangan berikutnya. Contoh dalam teks: 「ルームメイトのリンさんにも話したら、いっしょにやると言ってくれました。」"},{"t":"Bentuk potensial (可能形)","note":"Menyatakan \"bisa melakukan\". Contoh dalam teks: 「おふろ用の洗剤はカビも落とせると教えてくれました。」(落とす→落とせる), 「ゆっくり休めそうだ」(休む→休める)"},{"t":"〜てくれる (memberi/menerima)","note":"Menyatakan bahwa orang lain melakukan sesuatu untukku, dengan nuansa terima kasih. Contoh dalam teks: 「店の人が、…教えてくれました。」「いっしょにやると言ってくれました。」"},{"t":"〜そうだ","note":"Punya dua pemakaian: ① setelah bentuk ます tanpa ます, berarti \"kelihatannya akan / sepertinya\", seperti 「休めそうだ」; ② setelah bentuk biasa, berarti kabar yang didengar dari orang lain (\"katanya\"), seperti 「気持ちも楽になるそうです」."}]},"a-n2-13":{"title":"Pesta Akhir Tahun yang Berubah, Kepedulian yang Tak Berubah","topic":"Tempat Kerja","trans":["Setiap akhir tahun menjelang, di tempat kerja Jepang topik 「忘年会」 dulu muncul dengan sendirinya. Acara ini bermakna melupakan kerja keras setahun dan mempererat hubungan, dan dulu ikut serta dianggap hal yang wajar. Namun belakangan ini, makin banyak orang yang ingin memakai waktu sepulang kerja untuk diri sendiri dan tidak mau ikut. Seiring dengan itu, makin banyak perusahaan yang menghentikan pesta malam dan menggantinya dengan makan siang bersama, atau membuat kehadiran jadi bebas.","Latar belakangnya adalah nilai-nilai yang makin beragam, serta keadaan orang yang ingin mengutamakan keseimbangan antara pekerjaan dengan keluarga atau perawatan orang tua. Tidak sedikit karyawan muda yang merasa duduk semeja dengan atasan jauh dari menyenangkan, malah hanya melelahkan karena harus menjaga sikap. Di sisi lain, memang benar ada juga yang menganggapnya kesempatan berharga untuk berbincang dengan rekan yang biasanya jarang diajak bicara, sehingga mereka menyambut baik acara ini. Bagi perusahaan, memaksa bisa menimbulkan ketidakpuasan, jadi mau tidak mau harus mencari bentuk acara yang memperhatikan keadaan masing-masing.","Saat menolak ajakan, dasarnya adalah berterima kasih dulu karena sudah diajak. Misalnya, kalau kamu menolak dengan 「お誘いありがとうございます。あいにく先約がありまして」, tidak akan ada yang tersinggung. Menjelaskan alasan terlalu rinci kadang terdengar seperti dalih, jadi sampaikan dengan singkat lalu tambahkan 「またの機会にぜひ」 agar lebih baik. Sebaliknya, kalau kamu ikut dan tidak bisa minum alkohol, kamu boleh bersulang dengan teh oolong, dan memberi tahu di awal bahwa kamu akan pulang lebih awal akan membuatmu lebih tenang.","Sebaiknya kita menghindari anggapan bahwa orang yang tidak ikut itu dingin, atau menilai orang yang ikut hanya sekadar basa-basi. Pihak panitia juga, kalau menambahkan satu kalimat 「参加は自由です」 saat mengirim undangan, akan sangat meringankan beban mental orang yang menolak. Bukankah yang penting bukan bentuknya itu sendiri, melainkan sikap yang berusaha menghargai keadaan dan perasaan satu sama lain? Meskipun pesta akhir tahun berubah menjadi makan siang bersama, tempat ini tetap menjadi wadah untuk menumbuhkan rasa saling percaya antarmanusia."],"vocab":[{"w":"忘年会","m":"pesta akhir tahun"},{"w":"親睦","m":"keakraban, mempererat hubungan"},{"w":"価値観","m":"nilai-nilai (pandangan hidup)"},{"w":"両立","m":"menyeimbangkan, berjalan beriringan"},{"w":"強制","m":"paksaan, memaksa"},{"w":"配慮","m":"pertimbangan, perhatian"},{"w":"先約","m":"janji yang sudah ada sebelumnya"},{"w":"幹事","m":"panitia, penyelenggara acara"},{"w":"尊重","m":"menghargai, menghormati"}],"grammar":[{"t":"〜に伴って","note":"Berarti \"seiring dengan…\": saat satu hal berubah, hal lain ikut berubah. Contoh: 「それに伴って、夜の宴会をやめて昼のランチ会にしたり…する会社も目立つようになった」."},{"t":"〜どころか","note":"Berarti \"jangankan…, malah…\": menyangkal hal pertama lalu menyatakan kenyataan yang berlawanan atau lebih ekstrem. Contoh: 「気楽に楽しめるどころか、気を使って疲れるだけだと感じる」."},{"t":"〜かねない","note":"Dipakai dengan bentuk ます tanpa ます pada kata kerja, berarti \"bisa saja terjadi (hal yang buruk)\". Contoh: 「強制すれば不満が高まりかねない」."},{"t":"〜ざるを得ない","note":"Berarti \"mau tidak mau harus…\": tidak ada pilihan lain selain melakukannya. Contoh: 「それぞれの事情に配慮した形を探さざるを得ない」."}]},"eh-n5-1":{"title":"Pertama Kali ke Minimarket","topic":"Buku Bergambar","trans":["Tanutaro datang ke Jepang kemarin. Hari ini dia akan pergi ke minimarket untuk pertama kalinya.","Di dalam toko sangat terang. Ada banyak onigiri, roti, dan minuman.","Tanutaro memilih satu bento dan satu teh. Dia membawanya ke kasir.","Pegawai toko bertanya, 「あたためますか」. Tanutaro tidak tahu artinya.","「あたためますか」 artinya 「あつく しますか」, yaitu \"Mau dihangatkan?\" Tanutaro menjawab, 「はい、おねがいします」.","Lalu pegawai toko bertanya, \"Perlu kantong?\" Kali ini dia mengerti. Dia menjawab, \"Tidak usah, tidak apa-apa.\"","Bento yang hangat itu enak sekali. Tanutaro ingin pergi ke minimarket lagi."],"vocab":[{"w":"コンビニ","m":"minimarket"},{"w":"初めて","m":"pertama kali"},{"w":"お弁当","m":"bento, kotak makan siang"},{"w":"選ぶ","m":"memilih"},{"w":"レジ","m":"kasir"},{"w":"店員","m":"pegawai toko"},{"w":"温める","m":"menghangatkan, memanaskan"},{"w":"意味","m":"arti, makna"},{"w":"袋","m":"kantong, tas plastik"},{"w":"答える","m":"menjawab"}],"grammar":[{"t":"〜という","note":"「A という いみです」= artinya A, dipakai untuk menjelaskan sebuah kata. Contoh: 「あたためますか」は「あつく しますか」と いう いみです。"},{"t":"〜たいです","note":"Kata kerja bentuk ます tanpa ます + たいです, berarti \"ingin melakukan…\". Contoh: また コンビニに 行きたいです。"},{"t":"〜と(menyebutkan daftar)","note":"Kata benda と kata benda, menyebutkan semua barangnya satu per satu (\"dan\"). Contoh: おべんとうを 一つと おちゃを 一つ。"}]},"a-n2-7-n3":{"title":"Siap Sedia Sebelum Terjadi","topic":"Kehidupan","trans":["Jepang dikenal sebagai negara yang sering mengalami bencana alam seperti gempa bumi dan topan. Justru karena bencana tidak bisa diduga kapan terjadinya, penting untuk bersiap sejak hari-hari biasa.","Pertama, mulai saja dari hal yang bisa kamu lakukan di rumah. Kalau kamu sudah menyiapkan air, makanan, senter, dan sebagainya, kamu akan lebih tenang saat keadaan darurat. Usahakan menaruh barang-barang itu di tempat yang bisa langsung dibawa keluar.","Jangan lupa juga berdiskusi dengan keluarga sebelumnya, karena saat bencana anggota keluarga bisa saja terpisah. Kalau sudah menentukan tempat berkumpul, kamu bisa bertindak tanpa panik. Selain itu, mengetahui tempat-tempat berbahaya di daerah tempat tinggalmu juga sangat berguna. Lihatlah peta yang dibagikan balai kota dan sebagainya, lalu pastikan jalan menuju tempat pengungsian.","Meskipun bencana itu sendiri tidak bisa dicegah, kerugiannya bisa dikurangi. Berkat kewaspadaan kecil sehari-hari, kamu bisa melindungi diri sendiri dan keluargamu saat keadaan darurat."],"vocab":["bencana alam","hari-hari biasa, sehari-hari","bersiap, berjaga-jaga","persiapan, menyiapkan","senter","membawa keluar","terpisah, tersesat dari rombongan","tempat pengungsian","kerugian, korban/dampak bencana","kewaspadaan, perhatian"],"grammar":[{"t":"〜だからこそ","note":"Berarti \"justru karena begitu, maka lebih...\". Dipakai untuk menekankan alasan. Contoh: 「いつ起こるか分からない災害だからこそ、日ごろから備えておくことが大切です」."},{"t":"〜ておく","note":"Menyatakan melakukan sesuatu terlebih dahulu sebagai persiapan untuk nanti. Contoh: 「水や食料、懐中電灯などを用意しておくと、いざというときに安心です」."},{"t":"〜ようにする","note":"Menyatakan berusaha membiasakan diri atau berusaha sebisa mungkin melakukan sesuatu. Contoh: 「すぐに持ち出せる場所に置いておくようにしましょう」."},{"t":"〜によって","note":"Menyatakan cara atau sebab: \"dengan, berkat, melalui\". Contoh: 「ふだんのちょっとした心がけによって、いざというときに自分や家族を守ることができるのです」."}]},"a-n2-7-n4":{"title":"Ayo Bersiap Menghadapi Bencana","topic":"Kehidupan","trans":["Jepang adalah negara yang sering mengalami bencana alam seperti gempa bumi dan topan. Karena tidak tahu kapan datangnya, penting untuk bersiap sejak sekarang.","Pertama, mulai dari hal yang bisa kamu lakukan di rumah. Kalau sudah menyiapkan air, makanan, dan senter, hatimu akan lebih tenang. Taruh di tempat yang bisa langsung dibawa keluar. Bicarakan juga dengan keluargamu, lalu tentukan tempat berkumpul kalau kalian terpisah.","Mengetahui tempat-tempat berbahaya di kotamu juga penting. Lihat peta dari balai kota, lalu pastikan jalan menuju tempat pengungsian. Meskipun bencana tidak bisa dicegah, kerugiannya bisa dikurangi. Kewaspadaan kecil sehari-hari akan melindungi dirimu dan keluargamu."],"vocab":["gempa bumi","topan","persiapan","penting, berharga","tenang, lega","menyiapkan, persiapan","berdiskusi, bermusyawarah","menentukan, memutuskan","berbahaya, bahaya","tempat pengungsian"],"grammar":[{"t":"〜ておく","note":"Menyatakan melakukan sesuatu terlebih dahulu. Contoh: 「ふだんから準備しておくことが大切です」「決めておきましょう」."},{"t":"〜ので","note":"Menyatakan sebab atau alasan, nuansanya lebih lembut daripada 「から」. Contoh: 「いつ来るか分からないので、ふだんから準備しておくことが大切です」."},{"t":"〜ましょう","note":"Dipakai untuk mengajak melakukan sesuatu bersama atau memberi saran. Contoh: 「まず、家でできることから始めましょう」."},{"t":"〜ても/〜ことができる","note":"「〜ても」berarti \"meskipun... tetap...\"; 「ことができる」berarti \"bisa melakukan\". Contoh: 「災害は防げなくても、被害を少なくすることはできます」."}]},"a-n3-1-n2":{"title":"Kemudahan Minimarket yang Menopang Kehidupan","topic":"Kehidupan","trans":["Minimarket (konbini) di Jepang buka 24 jam, dan kemudahan karena bisa dipakai kapan saja menjadi daya tarik besarnya. Selain makanan dan minuman, majalah dan barang kebutuhan sehari-hari pun bisa dibeli, jadi hampir semua yang dibutuhkan untuk hidup sehari-hari tersedia di satu tempat. Daripada disebut sekadar toko makanan, konbini lebih tepat disebut fasilitas dekat yang menopang kehidupan kita.","Selain itu, urusan penting yang tak terpisahkan dari kehidupan, seperti membayar tagihan listrik, air, dan gas atau mengirim paket, juga bisa diselesaikan di sana. Karena ada ATM bank, kamu bisa menarik uang kapan saja saat butuh. Ada juga mesin untuk fotokopi dan pemesanan tiket, jadi peran toko ini tidak hanya terbatas pada berbelanja.","Berkat layanan-layanan ini yang makin lengkap, konbini menjadi sesuatu yang tak tergantikan dalam hidup kita. Bagi orang yang sibuk dan tidak punya waktu, adanya tempat untuk menyelesaikan urusan dalam waktu singkat sangat membantu. Sekarang, mungkin tidak sedikit orang yang merasa membayangkan hidup tanpa konbini saja sudah sulit.","Namun, di balik kemudahan itu tersembunyi masalah seperti kerja keras orang-orang yang bekerja 24 jam dan food loss (pemborosan makanan). Toko yang selalu buka berarti ada orang yang harus terus bekerja bahkan di malam hari. Kita cenderung menganggap kemudahan sebagai hal yang biasa, padahal itu baru bisa ada berkat usaha banyak orang. Kita ingin tidak hanya menikmati kemudahannya, tetapi juga memperhatikan orang-orang yang menopang sistem itu."],"vocab":["kemudahan, kepraktisan","tagihan layanan publik (listrik, air, gas, dll.)","pengiriman","prosedur, urusan administrasi","pemasangan, penempatan","kelengkapan, peningkatan mutu","tak tergantikan, tak terpisahkan","food loss, pemborosan makanan","hal yang wajar, biasa","menopang, mendukung"],"grammar":[{"t":"〜にとどまらない","note":"Artinya \"tidak hanya terbatas pada ～\"; cakupannya lebih luas dari yang dibayangkan. Contoh: 「店の役割は買い物だけにとどまらない」."},{"t":"〜といった","note":"Dipakai untuk menyebut contoh-contoh yang mewakili, artinya \"seperti ～\". Contoh: 「食品ロスといった問題が隠れている」."},{"t":"〜がちだ","note":"Dipasang setelah bentuk ます kata kerja tanpa ます, menunjukkan kecenderungan yang kurang baik: \"cenderung ～\". Contoh: 「便利さを当たり前のものと考えがちだ」."},{"t":"〜て初めて","note":"Artinya \"baru setelah ～ barulah (bisa) ...\"; menekankan bahwa bagian pertama adalah syarat mutlak. Contoh: 「多くの人の努力があって初めて成り立っている」."}]},"a-n3-1-n4":{"title":"Kemudahan Minimarket","topic":"Kehidupan","trans":["Minimarket (konbini) di Jepang buka 24 jam dan sangat praktis.","Tidak hanya makanan dan minuman, majalah dan barang kebutuhan sehari-hari juga bisa dibeli. Selain itu, kamu juga bisa membayar tagihan listrik, air, dan gas, serta mengirim paket.","Karena ada ATM bank juga, kamu bisa menarik uang kapan saja. Ada juga mesin untuk fotokopi dan pemesanan tiket. Berkat layanan ini, konbini menjadi tempat yang penting dalam kehidupan kita.","Tapi, di balik kemudahannya ada juga masalah. Orang yang bekerja 24 jam sangat kelelahan. Ada juga masalah food loss, yaitu makanan yang terbuang sia-sia. Aku ingin kita tidak menganggap kemudahan itu hal yang biasa, dan juga memikirkan orang-orang yang bekerja di sana."],"vocab":["praktis, mudah","majalah","barang kebutuhan sehari-hari","tagihan listrik, air, gas, dll.","barang bawaan, paket","reservasi, pemesanan","mesin","penting, berharga","masalah","food loss, makanan terbuang"],"grammar":[{"t":"〜ので","note":"Menyatakan sebab atau alasan, nadanya lebih lembut daripada「から」. Contoh: 「銀行のATMもあるので、いつでもお金をおろせます」"},{"t":"〜たり、〜たりする","note":"Menyebutkan beberapa tindakan atau hal sebagai contoh. Contoh: 「公共料金をはらったり、荷物を送ったりもできます」"},{"t":"Bentuk potensial (〜られる/〜える)","note":"Menyatakan \"bisa melakukan ~\". Contoh: 「雑誌や日用品も買えます」「お金をおろせます」"},{"t":"〜ないで","note":"Menyatakan \"tanpa melakukan ~, (melainkan) ...\". Contoh: 「べんりさを当たり前だと思わないで、はたらく人のことも考えたいです」"}]},"a-n3-8-n2":{"title":"Alur Berobat ke Rumah Sakit di Jepang","topic":"Kehidupan","trans":["Saat pertama kali demam di Jepang, aku tidak tahu harus berbuat apa dan merasa sangat cemas. Kalau badan sedang tidak enak di tempat yang belum familier, rasa tidak berdaya sering terasa lebih besar daripada penyakitnya sendiri. Waktu aku bertanya pada temanku, dia menyarankan, \"Sebaiknya pergi dulu ke dokter penyakit dalam yang dekat.\"","Di rumah sakit, alur yang umum adalah menunjukkan kartu asuransi kesehatan di bagian pendaftaran, lalu menulis keluhan di formulir pemeriksaan. Saat diperiksa, kamu akan ditanya hal-hal seperti 「いつから痛いですか」(Sejak kapan sakitnya?) dan 「アレルギーはありますか」(Apakah kamu punya alergi?). Isi pertanyaannya kurang lebih sudah pasti, jadi kalau kamu memikirkan jawabannya lebih dulu, kamu tidak akan panik.","Setelah pemeriksaan selesai, kamu akan menerima resep, lalu membawanya ke apotek untuk mengambil obat. Awalnya mungkin terasa banyak langkahnya, tetapi kalau sudah pernah mencoba sekali, tidak sulit kok. Biaya yang paling kupikirkan juga ternyata jauh lebih murah daripada perkiraanku. Sebab, kalau sudah ikut asuransi kesehatan, bagian yang harus kita bayar sendiri di rumah sakit hanya tiga puluh persen.","Kalau kamu kurang percaya diri dengan bahasanya, sebaiknya tulis keluhanmu di kertas lalu tunjukkan ke dokter. Cara menyampaikan maksud belum tentu hanya dengan berbicara. Walaupun tidak bisa bicara dengan lancar, masih banyak cara untuk menyampaikannya, jadi tidak perlu terlalu khawatir."],"vocab":["menangani, mengatasi","merasa tak berdaya, cemas","badan tidak enak, kesehatan menurun","formulir pemeriksaan (anamnesis)","gejala","panik, gugup","resep dokter","mendaftar, ikut serta (asuransi)","biaya yang ditanggung sendiri","cara, sarana"],"grammar":[{"t":"〜たところ","note":"Menyatakan bahwa setelah melakukan sesuatu, muncul hasil atau penemuan tertentu. Contoh: 「友達に相談したところ、『まず近くの内科に行ったほうがいいよ』とアドバイスをもらった」."},{"t":"〜といった","note":"Dipakai untuk menyebutkan contoh, artinya \"seperti ~\". Contoh: 「『いつから痛いですか』『アレルギーはありますか』といった質問をされる」."},{"t":"〜ずに済む","note":"Menyatakan bahwa sesuatu bisa selesai tanpa harus melakukan hal tertentu, atau hasil buruk bisa dihindari. Contoh: 「事前に答えを考えておけば慌てずに済む」."},{"t":"〜とは限らない","note":"Berarti \"belum tentu ~\", negasi sebagian. Contoh: 「意思を伝える手段は、話すことだけとは限らない」."}]},"a-n3-8-n4":{"title":"Pergi ke Rumah Sakit di Jepang","topic":"Kehidupan","trans":["Saat pertama kali demam di Jepang, aku tidak tahu harus bagaimana dan merasa cemas. Waktu bertanya pada temanku, dia bilang, \"Sebaiknya pergi ke dokter penyakit dalam yang dekat.\"","Di rumah sakit, pertama-tama kamu menunjukkan kartu asuransi kesehatan dan menulis keluhan di kertas. Kamu akan ditanya, \"Sejak kapan sakitnya?\" atau \"Apakah kamu punya alergi?\" Setelah pemeriksaan selesai, kamu akan mendapat kertas yang disebut resep. Bawa kertas itu ke apotek lalu ambil obatnya.","Biaya rumah sakit lebih murah daripada yang kukira. Soalnya kalau sudah ikut asuransi, yang kita bayar sendiri hanya tiga puluh persen. Kalau kamu khawatir soal bahasa, sebaiknya tulis keluhanmu di kertas lalu tunjukkan ke dokter. Ada banyak cara untuk menyampaikannya, jadi tidak perlu khawatir."],"vocab":["demam, suhu badan","cemas, tidak tenang","penyakit dalam","kartu asuransi kesehatan","gejala","pemeriksaan dokter","apotek","menerima, mengambil","biaya, tarif","menyampaikan"],"grammar":[{"t":"〜たほうがいい","note":"Dipakai untuk memberi saran, artinya \"sebaiknya ~\". Contoh: 「近くの内科に行ったほうがいいよ」. Dipasang pada bentuk た dari kata kerja."},{"t":"〜たら","note":"Berarti \"setelah ~\" atau \"kalau ~\". Contoh: 「診察が終わったら、処方箋という紙をもらいます」."},{"t":"〜ば(〜ていれば)","note":"Menyatakan syarat, \"kalau ~\". Contoh: 「保険に入っていれば、自分で払うのは三割だけだからです」."},{"t":"〜ので","note":"Menyatakan sebab atau alasan dengan nada yang lebih lembut, \"karena ~\". Contoh: 「伝える方法はたくさんあるので、心配しなくても大丈夫です」."}]},"a-n3-9-n2":{"title":"Alur Mencari Kamar di Jepang dan Hal-hal yang Perlu Diperhatikan","topic":"Kehidupan","trans":["Menyewa kamar di Jepang itu jauh lebih merepotkan daripada yang dibayangkan banyak orang asing. Prosesnya dimulai dengan mengunjungi agen properti, lalu menyampaikan anggaran sewa dan daerah yang kamu inginkan kepada stafnya. Kalau kamu menambahkan syarat «jalan kaki maksimal sepuluh menit dari stasiun», harga sewanya langsung melonjak.","Meski sudah menemukan kamar yang kamu suka, kamu tidak bisa langsung memutuskan kontrak saat itu juga. Soalnya, saat masuk kamu harus menyiapkan uang dalam jumlah cukup besar, seperti uang jaminan (shikikin), uang terima kasih untuk pemilik (reikin), dan biaya jasa agen. Bagi orang asing, tidak jarang diminta menyediakan penjamin saat kontrak. Belakangan ini, memakai perusahaan penjamin sebagai pengganti penjamin pribadi sudah jadi hal yang umum, dan kamu membayar sekitar setengah dari uang sewa saat membuat kontrak.","Agar lolos pemeriksaan, sebaiknya kamu menyiapkan dokumen yang bisa membuktikan tempat kerja dan penghasilanmu sejak awal. Saat melihat kamar langsung, kamu sebaiknya memeriksa bukan hanya cahaya matahari dan kebisingan, tetapi juga tempat untuk menaruh mesin cuci dan jumlah stopkontaknya. Justru bagian-bagian yang tidak terlihat dari foto itulah yang membuat datang langsung jadi bermakna.","Langkah-langkah seperti ini mungkin terasa merepotkan bagi orang yang baru pertama kali mengalaminya. Namun, hanya dengan mengetahui alurnya lebih dulu, beban persiapan akan jauh berbeda. Karena itu, saat pindahan berikutnya, kamu pasti bisa mencari kamar dengan jauh lebih mudah daripada kali ini."],"vocab":["agen properti","uang sewa","uang jaminan (dikembalikan saat keluar)","uang terima kasih untuk pemilik kamar (reikin)","biaya jasa agen","penjamin","pemeriksaan, seleksi","melihat kamar langsung","cahaya matahari, penyinaran","kebisingan"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring berubahnya satu hal, hal lain ikut berubah. Contoh: 「条件を加えると、それに伴って家賃は一気に高くなってしまう」"},{"t":"〜わけにはいかない","note":"Menyatakan tidak bisa melakukan sesuatu karena alasan logika, etika, atau keadaan. Contoh: 「その場ですぐに契約を決めるわけにはいかない」"},{"t":"〜にあたって","note":"Menyatakan 'saat/ketika akan melakukan sesuatu', biasanya dipakai dalam situasi formal. Contoh: 「契約にあたって保証人を求められることが少なくない」"},{"t":"〜こそ","note":"Menekankan kata sebelumnya, artinya 'justru ini'. Contoh: 「写真ではわからない部分こそ、実際に足を運んで見る意味があるといえる」"}]},"a-n3-9-n4":{"title":"Mencari Kamar di Jepang","topic":"Kehidupan","trans":["Menyewa kamar di Jepang lebih merepotkan daripada yang dibayangkan. Pertama, kamu pergi ke agen properti, lalu menyampaikan anggaran sewa dan lokasi yang kamu inginkan. Kalau kamu menetapkan syarat jalan kaki maksimal sepuluh menit dari stasiun, uang sewanya jadi jauh lebih mahal.","Meski sudah menemukan kamar yang bagus, kamu tidak bisa langsung memutuskan. Soalnya, di awal kamu butuh banyak uang, seperti uang jaminan (shikikin), uang terima kasih untuk pemilik (reikin), dan biaya jasa agen. Orang asing sering diberi tahu bahwa mereka butuh penjamin. Sekarang banyak orang memakai perusahaan penjamin, dan membayar sekitar setengah dari uang sewa saat membuat kontrak. Supaya lolos pemeriksaan, sebaiknya kamu menyiapkan dokumen yang menunjukkan pekerjaan dan penghasilanmu.","Karena tidak kelihatan dari foto, sebaiknya kamu datang langsung untuk memeriksa cahaya matahari dan suara dari luar. Tempat untuk menaruh mesin cuci dan jumlah stopkontaknya juga sebaiknya dilihat dulu. Kelihatannya repot, tetapi kalau kamu sudah tahu alurnya, pindahan berikutnya akan jadi lebih mudah."],"vocab":["kamar","tenaga dan waktu, kerepotan","agen properti","uang sewa","anggaran","penjamin","kontrak, membuat kontrak","dokumen","persiapan, menyiapkan","konfirmasi, memeriksa"],"grammar":[{"t":"〜ても","note":"Menyatakan 'meskipun ~, tetap ~'. Contoh: 「いい部屋が見つかっても、すぐには決められない」"},{"t":"〜ように","note":"Menyatakan tujuan atau hasil yang ingin dicapai, 'agar/supaya ~'. Contoh: 「審査に通るように、仕事と収入がわかる書類を準備しておくといい」"},{"t":"〜ておく","note":"Menyatakan melakukan sesuatu lebih dulu sebagai persiapan. Contoh: 「書類を準備しておくといい」「見ておいたほうがいい」"},{"t":"〜たほうがいい","note":"Menyatakan 'sebaiknya ~', dipakai untuk memberi saran. Contoh: 「コンセントの数も、見ておいたほうがいい」"}]},"a-n3-12-n2":{"title":"Etika Dasar Email Bisnis","topic":"Dunia Kerja","trans":["Kalau bekerja di perusahaan Jepang, kamu perlu tahu aturan dasar menulis email. Berbeda dengan telepon, email bisa dibaca penerima kapan pun waktunya cocok. Tapi di sisi lain, tergantung cara menulisnya, email bisa saja memberi kesan tidak sopan. Karena itu, karyawan baru biasanya memperhatikan cara menulis para senior dan belajar sedikit demi sedikit.","Pertama, subjek email penting ditulis singkat supaya isinya langsung terlihat jelas. Hanya menulis 「会議の件」 saja tidak cukup. Menulis yang spesifik seperti 「来週の会議の日程について」 lebih mudah dipahami. Kalau subjeknya tidak jelas, ada risiko email terlewat oleh penerima yang sedang sibuk. Meski begitu, subjek yang lebih panjang belum tentu lebih baik, jadi kamu juga perlu berusaha merangkumnya dengan singkat.","Di awal email, salam 「お世話になっております」 sering dipakai. Ini ungkapan terima kasih atas hubungan baik dengan lawan bicara, dan bisa dipakai untuk orang di luar maupun di dalam perusahaan. Untuk orang yang baru pertama kali kamu hubungi, kadang dipakai ungkapan seperti 「はじめてご連絡いたします」. Pada isi email, kamu diharapkan menulis dengan sopan dalam kalimat-kalimat pendek agar keperluanmu tersampaikan dengan tepat.","Di bagian akhir, banyak orang menutup email dengan kalimat 「よろしくお願いいたします」. Hanya dengan satu kalimat ini, seluruh tulisan terasa sopan dan penerima pun bisa membacanya dengan nyaman. Selain itu, membalas email secepat mungkin setelah menerimanya juga salah satu etika penting. Bahkan kalau belum bisa langsung menjawab, cukup kirim satu kalimat seperti 「確認して後日ご連絡します」, dan penerima pasti merasa tenang."],"vocab":["tidak bisa dilewatkan, sangat penting","kondisi/kesempatan (cocok atau tidak), keadaan","kesan","singkat dan jelas","terlewat (tidak sengaja terbaca), tidak memperhatikan","usaha, akal, kreativitas","keperluan, urusan","dituntut, diharapkan","menutup, mengakhiri","balasan (surat/email)"],"grammar":[{"t":"〜うえで","note":"Menyatakan \"dalam hal/proses melakukan ~\", biasanya diikuti hal yang penting atau perlu. Contoh: 「日本の会社で働くうえで、メールの書き方の基本的なルールを知っておくことは欠かせません」"},{"t":"〜反面","note":"Menyatakan satu hal punya dua sisi yang berlawanan: \"memang ~, tetapi di sisi lain ~\". Contoh: 「相手の都合のよい時間に読んでもらえる反面、書き方次第では失礼な印象を与えかねません」"},{"t":"〜かねない","note":"Dipakai dengan bentuk ます verba tanpa ます, berarti \"bisa saja berakibat buruk\". Contoh: 「書き方次第では失礼な印象を与えかねません」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu ~\", untuk menyangkal anggapan yang terlalu mutlak. Contoh: 「件名は長ければ長いほどよいとは限らず、短くまとめる工夫も必要です」"}]},"a-n3-12-n4":{"title":"Dasar-Dasar Email Bisnis","topic":"Dunia Kerja","trans":["Kalau bekerja di perusahaan Jepang, ada beberapa aturan dasar untuk menulis email. Email praktis karena penerima bisa membacanya kapan pun waktunya cocok. Kalau salah menulis, kamu bisa dianggap tidak sopan, jadi karyawan baru belajar dari para senior.","Pertama, subjek email penting ditulis singkat supaya isinya langsung terlihat jelas. Jangan hanya menulis 「会議の件」, lebih baik tulis 「来週の会議の日程について」. Kalau subjeknya tidak jelas, penerima yang sibuk mungkin tidak akan membaca emailnya.","Di awal email, ungkapan 「お世話になっております」 sering dipakai. Ini ungkapan untuk menyampaikan rasa terima kasih, dan bisa dipakai untuk orang di luar maupun di dalam perusahaan. Banyak orang mengakhiri email dengan 「よろしくお願いいたします」. Setelah menerima email, membalas secepat mungkin juga etika yang penting. Kalau belum bisa langsung menjawab, kirim saja 「確認してあとで連絡します」 supaya penerima tenang."],"vocab":["subjek (email), judul","jadwal, agenda","penting","tidak sopan","karyawan baru","(waktu) cocok, keadaan","terima kasih","luar perusahaan","balasan, jawaban","tenang, lega"],"grammar":[{"t":"〜ので","note":"Menyatakan sebab atau alasan dengan nada yang lebih lembut. Contoh: 「相手が都合のいい時間に読めるので便利です」"},{"t":"〜ように","note":"Menyatakan tujuan atau keadaan, \"supaya ~\". Contoh: 「一目で内容がわかるように、短く書くことが大切です」"},{"t":"〜と(syarat)","note":"Menyatakan \"kalau/begitu ~ maka ~\", sering diikuti hasil atau saran. Contoh: 「件名がわかりにくいと、忙しい相手はメールを読まないかもしれません」"},{"t":"〜たら","note":"Berarti \"kalau/setelah ~\", menjelaskan tindakan yang dilakukan sesudah sesuatu terjadi. Contoh: 「メールをもらったら、できるだけ早く返事をするのも大切なマナーです」"}]},"a-n4-2-n2":{"title":"Etika di Dalam Kereta dan Cara Berpikir Orang Jepang","topic":"Kehidupan","trans":["Di dalam kereta Jepang, suasananya begitu tenang sampai hampir tidak terdengar suara orang mengobrol. Kebanyakan penumpang membaca buku, melihat ponsel, atau memejamkan mata untuk beristirahat, menghabiskan waktu dengan cara masing-masing. Sambil memperhatikan sekitar, mereka menikmati waktu mereka sendiri dengan tenang.","Terutama, menelepon di dalam kereta umumnya dianggap melanggar etika. Kalau benar-benar ingin bicara, kamu terpaksa turun dari kereta dulu baru menelepon. Selain itu, di dekat kursi prioritas, kamu kadang diminta untuk mematikan ponsel, karena ada kemungkinan mengganggu alat medis seperti alat pacu jantung.","Di balik etika seperti ini ada cara berpikir orang Jepang: \"jangan merepotkan orang di sekitar\". Ini lebih tepat disebut kebiasaan yang didasari rasa peduli satu sama lain daripada aturan tertulis. Membayangkan bagaimana tindakan kita memengaruhi orang di sekitar adalah titik awal dari cara berpikir ini.","Etika seperti ini sangat penting agar banyak orang bisa naik kereta dengan nyaman. Yang penting bukan hanya mementingkan kenyamanan diri sendiri, tetapi bertindak dengan memikirkan orang lain juga. Dengan begitu, ruang yang nyaman bagi semua orang akan tetap terjaga."],"vocab":[{"w":"思い思い","m":"sesuka hati masing-masing, dengan cara sendiri-sendiri"},{"w":"周囲","m":"sekeliling, orang-orang di sekitar"},{"w":"違反","m":"pelanggaran, melanggar"},{"w":"見なされる","m":"dianggap, dipandang sebagai"},{"w":"電源","m":"sumber daya listrik, tombol daya"},{"w":"おそれ","m":"kemungkinan buruk, kekhawatiran"},{"w":"背景","m":"latar belakang"},{"w":"迷惑","m":"gangguan, merepotkan"},{"w":"明文化","m":"menuliskan secara resmi, menjadikan aturan tertulis"},{"w":"欠かせない","m":"tidak bisa dilewatkan, sangat penting"}],"grammar":[{"t":"〜ざるを得ない","note":"Menyatakan terpaksa melakukan sesuatu karena tidak ada pilihan lain. Contoh: 「どうしても話したいときは、いったん電車を降りてからかけざるを得ません」"},{"t":"〜というより","note":"Berarti \"daripada disebut ..., lebih tepat disebut ...\", dipakai untuk meralat cara menyebut sesuatu. Contoh: 「明文化されたルールというより、お互いへの思いやりに基づいた習慣だと言えます」"},{"t":"〜おそれがある","note":"Menyatakan ada kemungkinan terjadi hal buruk; sering dipakai dalam bahasa tulis. Contoh: 「ペースメーカーなどの医療機器に影響を与えるおそれがあるからです」"},{"t":"〜に基づく","note":"Berarti \"berdasarkan ...\" atau \"bertumpu pada ...\". Contoh: 「お互いへの思いやりに基づいた習慣だと言えます」"}]},"a-n4-2-n3":{"title":"Etika di Dalam Kereta","topic":"Kehidupan","trans":["Katanya, dibandingkan negara lain, suasana di dalam kereta Jepang sangat tenang. Banyak orang menghabiskan waktu dengan membaca buku, melihat ponsel, atau memejamkan mata untuk beristirahat.","Menelepon di dalam kereta dianggap melanggar etika. Kalau benar-benar ingin bicara, biasanya orang turun dulu di stasiun lalu menelepon. Selain itu, di dekat kursi prioritas, kamu kadang diminta untuk mematikan ponsel, karena bisa jadi mengganggu alat medis seperti alat pacu jantung.","Di balik etika seperti ini ada cara berpikir orang Jepang: \"jangan merepotkan orang di sekitar\". Etika ini dijaga bukan karena aturan, melainkan lebih karena rasa peduli satu sama lain. Dengan begitu, suasana tenang di dalam kereta tercipta berkat perhatian kepada orang di sekitar.","Etika seperti ini ada agar banyak orang bisa naik kereta dengan nyaman. Kalau kita bertindak dengan memikirkan bukan hanya diri sendiri tetapi juga orang di sekitar, semua orang pasti bisa merasa nyaman."],"vocab":[{"w":"違反","m":"pelanggaran, melanggar"},{"w":"優先席","m":"kursi prioritas"},{"w":"電源","m":"sumber daya listrik, tombol daya"},{"w":"医療機器","m":"alat medis"},{"w":"影響","m":"pengaruh, dampak"},{"w":"背景","m":"latar belakang"},{"w":"迷惑","m":"gangguan, merepotkan"},{"w":"思いやり","m":"kepedulian, empati"},{"w":"気づかい","m":"perhatian, rasa sungkan kepada orang lain"},{"w":"快適","m":"nyaman"}],"grammar":[{"t":"〜ように(お願い・要求)","note":"Menyatakan isi permintaan atau perintah. Contoh: 「携帯電話の電源を切るようにお願いされる場合もあります」"},{"t":"〜というより","note":"Berarti \"daripada disebut ..., lebih tepat disebut ...\". Contoh: 「ルールだからというより、お互いへの思いやりから守られているのです」"},{"t":"〜によって","note":"Menyatakan sebab, cara, atau dasar (\"oleh\", \"berkat\"). Contoh: 「周りへの気づかいによって作られているのです」"},{"t":"〜ための+名詞","note":"Menyatakan tujuan dan menerangkan kata benda di belakangnya (\"untuk ...\"). Contoh: 「たくさんの人が気持ちよく電車を利用するためのものです」"}]},"a-n4-8-n2":{"title":"Alur Mengurus Dokumen di Kantor Kelurahan (Kantor Distrik)","topic":"Kehidupan","trans":["Di Jepang, ketika pindah rumah, kamu wajib datang ke kantor distrik (区役所) dalam waktu empat belas hari untuk melapor soal alamat barumu. Di loket, aku bilang「転入届を出したいのですが」, lalu menerima nomor antrean. Nomor antrean dibagikan sebagai sistem agar orang dilayani sesuai urutan, jadi walaupun sedang ramai, suasananya tidak mudah kacau.","Sampai namaku dipanggil, aku terpaksa duduk menunggu, tapi selama itu aku mengisi alamat dan tanggal lahir di formulir. Setelah giliranku tiba dan aku menuju loket, petugas memeriksa kartu izin tinggal (在留カード) dan menuliskan alamat baruku di bagian belakangnya. Kartu izin tinggal adalah dokumen penting yang membuktikan identitas, jadi sangat penting agar alamat barunya tercatat dengan benar.","Di hari yang sama, kamu juga bisa menyelesaikan pengurusan asuransi kesehatan nasional, tetapi loketnya berbeda, jadi aku pindah dari lantai satu ke lantai dua. Loket yang dibedakan menurut jenis urusan mungkin terasa agak merepotkan selama kamu belum terbiasa. Semuanya selesai dalam waktu sekitar satu jam, tapi kesannya prosesnya berjalan lebih lancar daripada yang kukira. Selain itu, karena bisa menyelesaikan urusan hanya dengan bahasa Jepang, aku jadi sedikit lebih percaya diri bahwa aku bisa terus tinggal di sini.","Kalau ada yang tidak kamu mengerti, menurutku sebaiknya kamu bertanya saja tanpa sungkan. Petugas juga berbicara pelan-pelan dan sopan kepada warga asing, jadi kamu tidak perlu ragu untuk bertanya ulang. Meski kamu kurang percaya diri dengan bahasa Jepangmu, belum tentu mengurus dokumen di loket itu sulit. Kalau kamu maju sambil memeriksa satu per satu, urusan yang diperlukan seharusnya bisa selesai dengan tenang."],"vocab":[{"w":"届け出","m":"laporan, pendaftaran"},{"w":"窓口","m":"loket"},{"w":"番号札","m":"nomor antrean"},{"w":"仕組み","m":"sistem, mekanisme"},{"w":"記入","m":"mengisi (formulir)"},{"w":"裏面","m":"sisi belakang"},{"w":"証明","m":"bukti, pembuktian"},{"w":"担当","m":"penanggung jawab, bagian yang menangani"},{"w":"異なる","m":"berbeda"},{"w":"ためらう","m":"ragu-ragu"}],"grammar":[{"t":"〜に伴って","note":"Berarti \"seiring dengan ~\": perubahan di bagian depan diikuti perubahan di bagian belakang. Contoh: 「引っ越しに伴って、十四日以内に区役所へ行き」"},{"t":"〜ざるを得ない","note":"Berarti \"terpaksa ~\" atau \"tidak ada pilihan lain selain ~\". Contoh: 「椅子に座って待たざるを得ませんが」"},{"t":"〜に対して","note":"Berarti \"terhadap ~\", menunjukkan sasaran suatu tindakan atau sikap. Contoh: 「外国人の利用者に対しても、係の人はゆっくり丁寧に話してくれる」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu ~\", menyangkal anggapan bahwa pasti begitu. Contoh: 「窓口での手続きが難しいとは限りません」"}]},"a-n4-8-n3":{"title":"Mengurus Dokumen di Kantor Distrik","topic":"Kehidupan","trans":["Kalau kamu pindah rumah, kamu harus datang ke kantor distrik (区役所) dalam waktu empat belas hari untuk mengurus perubahan alamat. Waktu aku bilang「転入届を出したいのですが」di loket, aku diberi nomor antrean. Aku duduk menunggu sampai namaku dipanggil, dan selama itu aku menulis alamat dan tanggal lahir di formulir.","Setelah giliranku tiba, petugas memeriksa kartu izin tinggal (在留カード) milikku, lalu menuliskan alamat baru di bagian belakangnya. Karena di hari yang sama aku juga bisa mengurus asuransi kesehatan nasional, aku memutuskan untuk langsung mengurusnya sekalian. Tapi, karena loketnya berbeda, aku harus pindah dari lantai satu ke lantai dua.","Sampai semuanya selesai, butuh waktu sekitar satu jam. Meski begitu, karena bisa mengurusnya hanya dengan bahasa Jepang, aku jadi sedikit lebih percaya diri.","Menurutku, kalau ada yang tidak kamu mengerti, sebaiknya tanya saja ke petugas tanpa sungkan. Soalnya petugas akan bicara pelan-pelan supaya kita bisa mengerti."],"vocab":[{"w":"手続き","m":"prosedur, urusan administrasi"},{"w":"窓口","m":"loket"},{"w":"転入届","m":"laporan pindah masuk (pendaftaran alamat baru)"},{"w":"番号札","m":"nomor antrean"},{"w":"書類","m":"dokumen, formulir"},{"w":"在留カード","m":"kartu izin tinggal"},{"w":"確認","m":"memeriksa, memastikan"},{"w":"移動","m":"berpindah"},{"w":"自信","m":"percaya diri"},{"w":"遠慮","m":"sungkan, segan"}],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan yang diambil sendiri. Contoh: 「続けて行うことにしました」 (aku memutuskan untuk langsung mengurusnya sekalian)."},{"t":"〜ため(原因・理由)","note":"Cara yang agak formal untuk menyatakan sebab atau alasan. Contoh: 「窓口が違うため、一階から二階へ移動しなければなりませんでした」."},{"t":"〜ように","note":"Menyatakan tujuan, yaitu agar suatu keadaan terwujud. Contoh: 「こちらが分かるようにゆっくり話してくれる」 (bicara pelan-pelan supaya kita bisa mengerti)."},{"t":"Bentuk pasif (〜れる・〜られる)","note":"Menyatakan bahwa subjek dikenai tindakan oleh orang lain. Contoh: 「番号札を渡されました」「名前を呼ばれるまで」."}]},"a-n4-9-n2":{"title":"Hal yang Kusadari Setelah Rutin ke Dokter Gigi","topic":"Kehidupan","trans":["Sejak tiga hari lalu gigiku mulai sakit. Meski begitu, aku tidak bisa membiarkannya begitu saja, jadi aku membuat janji di dokter gigi dekat rumah. Setelah menunjukkan kartu asuransi kesehatan di resepsionis, pertama-tama aku diminta mengisi formulir anamnesis. Aku menjawab satu per satu pertanyaannya, seperti sejak kapan sakitnya mulai dan apakah gigiku terasa ngilu saat kena makanan atau minuman dingin.","Setelah pemeriksaan, dokter berkata, \"Ada satu gigi berlubang ya,\" lalu menjelaskan kondisinya sambil menunjukkan foto rontgen. Untuk hari ini, dokter hanya mengebor bagian yang bermasalah dan memasukkan obat, lalu aku diminta datang lagi minggu depan. Aku lega karena sudah tahu penyebabnya, tetapi agak kecewa saat mendengar bahwa perawatannya tidak selesai dalam satu kali kunjungan.","Setelah perawatan selesai, aku juga diberi arahan tentang cara menyikat gigi. Katanya, kalau menyikat terlalu keras dan menekan dengan kuat, gusi justru bisa terluka. Aku kaget karena baru tahu bahwa kebiasaan yang kulakukan tanpa pikir panjang setiap hari ternyata bisa jadi malah berdampak buruk.","Di dokter gigi Jepang, kita terpaksa datang berkali-kali, tetapi sebagai gantinya, setiap perawatan dilakukan dengan teliti. Memang repot bolak-balik ke sana, tetapi aku merasa perawatan yang teliti itu nilainya tidak tergantikan. Dari pengalaman kali ini, aku benar-benar sadar bahwa kita tidak seharusnya buru-buru datang setelah gigi terasa sakit, tetapi bertindak sebelum gejalanya muncul. Menurutku, memeriksakan diri setidaknya setahun dua kali adalah cara terbaik agar tidak merasakan sakit."],"vocab":["membiarkan begitu saja","kartu asuransi kesehatan","menunjukkan, mengajukan","formulir anamnesis (formulir riwayat keluhan)","bagian yang sakit","arahan, bimbingan","melukai, merusak","efek sebaliknya, malah memperburuk","berobat ke rumah sakit/klinik secara rutin","menyadari dengan sangat dalam"],"grammar":[{"t":"〜ものの","note":"Artinya \"meskipun ..., tetapi ...\"; bagian depan dan belakang saling bertentangan. Contoh: 「三日前から歯が痛み始めたものの、放っておくわけにもいかず」."},{"t":"〜かねない","note":"Dipasang pada bentuk ます verba tanpa ます. Artinya \"bisa saja terjadi (hal yang buruk)\". Contoh: 「実は逆効果になりかねないと知り」."},{"t":"〜ざるを得ない","note":"Artinya \"terpaksa harus ...\", dengan nuansa tidak ada pilihan lain. Contoh: 「何度も通院せざるを得ませんが」."},{"t":"〜とはいえ","note":"Artinya \"meski dikatakan ..., tetap saja ...\"; mengakui hal pertama, lalu menyampaikan pendapat yang berlawanan. Contoh: 「通う手間は確かに大きいとはいえ」."}]},"a-n4-9-n3":{"title":"Hari Pergi ke Dokter Gigi","topic":"Kehidupan","trans":["Karena gigiku mulai sakit sejak tiga hari lalu, aku membuat janji di dokter gigi dekat rumah. Setelah menunjukkan kartu asuransi kesehatan di resepsionis, aku diminta mengisi formulir anamnesis. Aku menulis hal-hal seperti sejak kapan sakitnya dan apakah giginya ngilu kena yang dingin.","Dokter berkata, \"Ada satu gigi berlubang ya,\" lalu menunjukkan foto rontgen. Hari ini dokter hanya mengebor gigi yang berlubang dan memasukkan obat, lalu aku diminta datang lagi minggu depan.","Setelah perawatan selesai, aku juga diajari cara menyikat gigi. Katanya, kalau menyikat terlalu keras dan menekan kuat, gusi kadang bisa terluka. Aku jadi tahu bahwa menyikat gigi yang kulakukan setiap hari pun ada cara yang benar.","Di dokter gigi Jepang, kita harus datang berkali-kali. Tetapi sebagai gantinya, setiap kunjungan dirawat dengan teliti, jadi kita bisa tenang. Daripada panik setelah gigi terasa sakit, menurutku lebih baik periksa setiap enam bulan sekali. Mulai sekarang, aku memutuskan untuk pergi ke dokter gigi lebih awal."],"vocab":["janji, reservasi","resepsionis, meja pendaftaran","mengisi, menuliskan","formulir anamnesis (formulir riwayat keluhan)","gigi berlubang","mengikis, mengebor","melukai, merusak","teliti, sopan","panik, gugup","pemeriksaan kesehatan"],"grammar":[{"t":"〜ように言われる","note":"Menyatakan diminta atau disuruh melakukan sesuatu, dengan mengutip isi perintah secara tidak langsung. Contoh: 「問診票に記入するように言われました」"},{"t":"〜について","note":"Artinya \"tentang ...\"; dipakai untuk menyebutkan topik. Contoh: 「歯みがきの仕方についても教えてもらいました」"},{"t":"〜ぶん","note":"Artinya \"sebagai gantinya, sebanding dengan itu\"; menunjukkan keuntungan atau hasil yang sepadan karena keadaan sebelumnya. Contoh: 「そのぶん一回ずつ丁寧に治療してくれる」"},{"t":"〜ことにする","note":"Menyatakan keputusan sendiri untuk melakukan sesuatu. Contoh: 「これからは早めに歯医者へ行くことにします」"}]},"a-n4-11-n2":{"title":"Hari Aku Meninggalkan Payung di Kereta","topic":"Kehidupan","trans":["Hari ini aku ceroboh dan meninggalkan payungku di kereta. Saat aku sadar, kereta sudah tiba di stasiun berikutnya dan payungku tidak ada lagi di tanganku. Aku sempat bingung harus berbuat apa, tapi akhirnya memutuskan untuk pergi ke pusat barang hilang di stasiun dan meminta bantuan.","Aku menjelaskan kepada petugas di loket, secara berurutan, bagaimana payungku bisa hilang. Petugas berkata, 「特徴を教えてください」, jadi aku menyebutkan warna dan bentuknya dulu. Aku menjelaskannya dengan spesifik: payungnya berwarna hitam dan gagangnya agak bengkok. Lalu petugas itu berkata, 「少し待ってください、探してみます」, dan langsung pergi mencarinya untukku.","Setelah menunggu beberapa saat, aku diberi kabar bahwa sepertinya payung yang mirip sudah ditemukan. Aku minta payung itu dibawa dari bagian dalam untuk kuperiksa, dan ternyata itu memang payungku, tanpa ada keraguan sedikit pun. Aku bisa langsung menerimanya di tempat dan merasa sangat lega dari lubuk hati. Karena sempat hampir menyerah, rasa leganya jadi terasa berkali-kali lipat.","Dari pengalaman kali ini, aku benar-benar sadar bahwa barang tertinggal bisa terjadi meski kita sudah berhati-hati. Mulai sekarang, aku berniat selalu memeriksa apakah ada barang yang tertinggal setiap kali turun dari kereta. Memang hanya kebiasaan kecil, tapi menurutku tidak malas melakukannya adalah cara terbaik agar tidak mengulangi kesalahan yang sama."],"vocab":[{"w":"到着","m":"tiba, sampai"},{"w":"手元","m":"di tangan, di dekat kita"},{"w":"途方に暮れる","m":"bingung harus berbuat apa, kehabisan akal"},{"w":"経緯","m":"kronologi, seluk-beluk kejadian"},{"w":"順を追って","m":"secara berurutan, selangkah demi selangkah"},{"w":"まぎれもなく","m":"tidak diragukan lagi, jelas sekali"},{"w":"ひとしお","m":"jauh lebih, terasa lebih dalam"},{"w":"痛感","m":"merasakan dengan sangat dalam, benar-benar sadar"},{"w":"心がける","m":"berusaha untuk selalu, membiasakan diri"},{"w":"怠る","m":"lalai, mengabaikan"}],"grammar":[{"t":"〜たところ","note":"Menyatakan bahwa setelah melakukan suatu hal, ditemukan suatu hasil; yang mengikuti biasanya fakta yang baru diketahui. Contoh: 「奥から傘を持ってきてもらって確認したところ、それはまぎれもなく私の傘でした」."},{"t":"〜だけに","note":"Menyatakan bahwa justru karena keadaan sebelumnya, perasaan atau hasil di belakangnya terasa jauh lebih kuat. Contoh: 「一時はあきらめかけていただけに、安心感はひとしおでした」."},{"t":"〜を通じて","note":"Menyatakan bahwa suatu hasil diperoleh melalui suatu pengalaman atau cara. Contoh: 「今回の経験を通じて、忘れ物は気をつけていても起こり得ることだと痛感しました」."},{"t":"〜かける","note":"Dipasang setelah bentuk ます kata kerja (tanpa ます), menyatakan tindakan yang baru setengah jalan atau hampir dilakukan. Contoh: 「一時はあきらめかけていただけに」."}]},"a-n4-11-n3":{"title":"Hari Aku Meninggalkan Payung di Kereta","topic":"Kehidupan","trans":["Hari ini aku meninggalkan payungku di kereta dan jadi panik sekali. Saat kereta tiba di stasiun berikutnya, aku baru sadar payungku tidak ada. Aku sempat bingung harus bagaimana, lalu memutuskan pergi ke pusat barang hilang di stasiun untuk bertanya.","Aku menjelaskan kepada petugas bahwa payungku hilang di kereta. Lalu aku ditanya, 「傘の特徴を教えていただけますか」, jadi aku menyebutkan warna dan bentuknya. Aku bercerita sedetail mungkin: payungnya berwarna hitam dan gagangnya agak bengkok. Petugas berkata, 「少しお待ちください、探してみます」, lalu pergi ke bagian dalam untuk mencarinya untukku.","Setelah menunggu beberapa saat, aku diberi tahu bahwa sepertinya payung yang mirip sudah ditemukan. Ketika kulihat payung yang dibawakan dari bagian dalam, ternyata itu memang payungku. Aku bisa langsung menerimanya, dan benar-benar merasa lega. Mulai sekarang, aku mau membiasakan diri memeriksa apakah ada barang yang tertinggal setiap kali turun dari kereta."],"vocab":[{"w":"置き忘れる","m":"meninggalkan barang di suatu tempat karena lupa"},{"w":"慌てる","m":"panik, gugup"},{"w":"気がつく","m":"sadar, menyadari"},{"w":"相談","m":"berkonsultasi, bertanya minta saran"},{"w":"係","m":"petugas yang bertanggung jawab"},{"w":"特徴","m":"ciri-ciri, ciri khas"},{"w":"柄","m":"gagang (payung dsb.)"},{"w":"曲がる","m":"bengkok, melengkung"},{"w":"受け取る","m":"menerima, mengambil"},{"w":"確認","m":"memastikan, memeriksa"}],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan yang diambil sendiri untuk melakukan sesuatu. Contoh: 「忘れ物センターへ行って相談することにしました」 (memutuskan pergi ke pusat barang hilang untuk bertanya)."},{"t":"〜ようだ","note":"Menyatakan dugaan atau kabar berdasarkan situasi, artinya \"sepertinya ~\". Contoh: 「似ている傘が見つかったようだと教えてもらいました」 (diberi tahu bahwa sepertinya payung yang mirip sudah ditemukan)."},{"t":"〜てもらう","note":"Menyatakan meminta orang lain melakukan sesuatu untuk kita, atau menerima bantuan dari orang lain. Contoh: 「奥から持ってきてもらった傘を見ると」 (ketika melihat payung yang dibawakan dari bagian dalam)."},{"t":"〜ようにする","note":"Menyatakan usaha untuk membiasakan diri atau sebisa mungkin melakukan sesuatu. Contoh: 「忘れ物がないか確認するようにしようと思います」 (aku akan berusaha memeriksa apakah ada barang yang tertinggal)."}]},"eh-n4-3":{"title":"Hadiah di Hari Hujan","topic":"Buku Bergambar","trans":["Sabtu depan adalah ulang tahun Kon. Syal biru yang selalu dipakai Kon sudah sangat tua.","Tanutaro berpikir untuk memberikan syal baru sebagai hadiah. Tapi hari itu hujan sejak pagi.","Tanutaro membuka payung dan pergi ke toko serba-serbi di kota. Di sana dia menemukan syal biru yang cantik.","Harganya agak mahal, tapi Tanutaro memutuskan untuk membelinya. Pegawai toko membungkusnya dengan rapi untuknya.","Dalam perjalanan pulang, hujan makin deras. Supaya hadiahnya tidak basah, Tanutaro memeluk erat tasnya sambil berlari.","Saat dia mengucapkan \"Selamat ulang tahun\" dan menyerahkan hadiahnya, Kon kaget sekali.","Kon yang memakai syal baru itu tersenyum dan berkata, \"Terima kasih, aku akan menjaganya baik-baik selamanya.\""],"vocab":["ulang tahun","syal","payung","toko serba-serbi","menemukan","membungkus","basah","memeluk, mendekap","terkejut","berharga, penting"],"grammar":[{"t":"〜うと思います","note":"Bentuk volisional kata kerja + と思います menyatakan niat melakukan sesuatu. Contoh: 新しいマフラーをプレゼントしようと思いました。"},{"t":"〜ことにします","note":"Bentuk kamus kata kerja + ことにします menyatakan keputusan yang kamu ambil sendiri. Contoh: それを買うことにしました。"},{"t":"〜ように(tujuan)","note":"「A ように、B」= melakukan B supaya A terjadi. Sebelum ように biasanya ada bentuk ない atau bentuk potensial. Contoh: プレゼントがぬれないように、かばんをしっかり抱えて走りました。"},{"t":"〜てくれます","note":"Orang lain melakukan sesuatu untukku. Contoh: 店員さんがきれいに包んでくれました。"}]},"a-n4-7":{"title":"Cara Membuang Sampah","topic":"Kehidupan","trans":["Setelah mulai tinggal di Jepang, hal yang paling mengejutkan bagiku adalah cara membuang sampah.","Sampah harus dipisah menjadi 「燃えるごみ」 (sampah yang bisa dibakar), 「燃えないごみ」 (sampah yang tidak bisa dibakar), 「資源ごみ」 (sampah daur ulang), dan sebagainya.","Hari pembuangannya juga sudah ditentukan. Di kotaku, sampah yang bisa dibakar dibuang pada hari Senin dan Kamis.","Sampah harus dibawa ke tempat yang sudah ditentukan sebelum jam delapan pagi.","Kalau salah memilah, kadang sampahnya tidak diangkut.","Awalnya kupikir ini merepotkan, tapi kalau sudah terbiasa, ternyata tidak sulit.","Berkat pemilahan sampah, kota selalu bersih."],"vocab":["terkejut, kaget","memisahkan, memilah","ditentukan, tetap","salah, keliru","merepotkan, repot","terbiasa","pemilahan (sampah)"],"grammar":[{"t":"~なければなりません","note":"「harus ~」: 分けなければなりません (harus dipisah/dipilah)."},{"t":"~までに","note":"「paling lambat ~ (batas waktu)」: 朝八時までに出します (dibuang sebelum jam delapan pagi). までに menunjukkan batas waktu, sedangkan まで menunjukkan kelanjutan suatu kegiatan sampai waktu tertentu."},{"t":"~てもらえない","note":"「tidak bisa meminta/mendapatkan orang lain melakukan ~ untuk kita」: 持って行ってもらえない (sampahnya tidak diangkut). Ini bentuk potensial negatif dari てもらう."},{"t":"~おかげで","note":"「berkat ~」: 分別のおかげで、町はきれいです (berkat pemilahan sampah, kota bersih)."}]},"a-n3-8":{"title":"Pergi ke Rumah Sakit di Jepang","topic":"Kehidupan","trans":["Waktu pertama kali demam di Jepang, aku tidak tahu harus berbuat apa dan merasa sangat cemas.","Waktu aku bertanya pada temanku, dia bilang, 「まず近くの内科に行ったほうがいいよ」 (sebaiknya kamu pergi dulu ke dokter penyakit dalam terdekat).","Di rumah sakit, pertama-tama kamu menunjukkan kartu asuransi kesehatan, lalu menulis gejalamu di formulir pemeriksaan.","Pertanyaan yang diajukan sebagian besar sudah standar, seperti 「いつから痛いですか」 (sejak kapan sakitnya?) dan 「アレルギーはありますか」 (apakah kamu punya alergi?).","Setelah pemeriksaan selesai, kamu mendapat resep, lalu mengambil obat di apotek.","Biayanya lebih murah dari dugaanku. Soalnya, kalau sudah terdaftar asuransi, yang kita bayar sendiri hanya tiga puluh persen.","Kalau kamu khawatir soal bahasa, tulis saja gejalamu di kertas lalu tunjukkan. Cara untuk menyampaikan maksud itu banyak sekali."],"vocab":["cemas, gelisah","konsultasi, bertanya untuk minta saran","kartu asuransi kesehatan","gejala","pemeriksaan (oleh dokter)","resep dokter","apotek","menerima, mengambil"],"grammar":[{"t":"~たほうがいい","note":"「sebaiknya ~ (saran)」: 行ったほうがいい (sebaiknya pergi)."},{"t":"~と(syarat)","note":"「begitu ~, (maka) ...」: 相談すると、教えてくれた / 診察が終わると. Setelah kejadian pertama, kejadian kedua terjadi secara alami."},{"t":"~より","note":"「daripada ~」: 思ったより安かった (lebih murah dari yang dikira)."},{"t":"~といい","note":"「~ saja, lebih baik ~ (saran)」: 書いて見せるといい (tulis saja lalu tunjukkan)."}]},"a-n1-6":{"title":"Yang Diwariskan","topic":"Budaya","trans":["Budaya tradisional dan keterampilan para pengrajin yang diwariskan di berbagai daerah adalah harta yang tak tergantikan, yang diasah dan diteruskan selama bertahun-tahun. Namun kini, sebagian besarnya berada di ambang kepunahan.","Penyebab terbesarnya adalah kurangnya penerus. Di saat para pelaku semakin menua, anak muda justru pindah ke kota, dan orang yang ingin mempelajari keterampilan itu pun berkurang dari tahun ke tahun.","Meski dikatakan menjaga tradisi, bukan berarti kita cukup mempertahankan bentuk lama begitu saja. Budaya baru bisa terus hidup hanya jika kita menciptakan nilai baru sesuai perubahan zaman.","Belakangan ini, upaya seperti memasukkan desain modern ke dalam kerajinan tradisional atau mempromosikannya ke luar negeri juga makin meluas. Perpaduan antara yang lama dan yang baru menjadi kunci untuk membuka jalan keluar.","Bagaimana kita menyambungkan apa yang telah dibangun para pendahulu kepada generasi berikutnya? Itu mungkin adalah pekerjaan rumah berat yang dibebankan kepada kita masing-masing."],"vocab":["pengrajin, ahli kerajinan","kelangsungan, keberlangsungan","berada di ambang, menghadapi (krisis)","penerus, pewaris","pelaku, penopang","perpaduan, peleburan","jalan keluar, harapan","para pendahulu, leluhur"],"grammar":[{"t":"~てこそ","note":"「Hanya dengan ~ barulah」: 新しい価値を生み出してこそ生き続けられる."},{"t":"~わけではない","note":"Negasi sebagian (bukan berarti ~): 昔のままを保てばよいというわけではない."},{"t":"~つつある","note":"「Sedang perlahan ~」: 試みも広がりつつある."}]},"a-n4-2":{"title":"Etika di Dalam Kereta","topic":"Kehidupan","trans":["Di dalam kereta Jepang sangat tenang. Banyak orang membaca buku, melihat ponsel, atau beristirahat dengan mata terpejam.","Menelepon di dalam kereta dianggap melanggar etika. Kalau ingin bicara, mereka menelepon setelah turun di stasiun.","Selain itu, di dekat kursi prioritas, kadang kamu diminta untuk mematikan ponsel. Sebab, ponsel bisa saja memengaruhi alat seperti alat pacu jantung.","Di balik etika ini ada pola pikir orang Jepang, yaitu \"tidak merepotkan orang di sekitar\". Lebih dari sekadar aturan, ini adalah bentuk kepedulian satu sama lain.","Etika ini dibuat agar banyak orang bisa naik kereta dengan nyaman.","Kalau kita tidak hanya memikirkan diri sendiri, tetapi juga orang di sekitar, semua orang bisa merasa nyaman."],"vocab":["tenang","pelanggaran, melanggar","kursi prioritas","pengaruh, memengaruhi","kepedulian, perhatian"],"grammar":[{"t":"~たり~たり","note":"Menyebutkan beberapa tindakan sebagai contoh: 読んだり、見たり、休んだり。"},{"t":"~ように言われる","note":"Diminta/disuruh melakukan ~: 電源を切るように言われる。"},{"t":"~という(mengutip/menamai)","note":"「~という考え方」mengutip isi atau nama, artinya \"pola pikir yang disebut ~\"."}]},"eh-n4-2":{"title":"Di Kedai Ramen","topic":"Picture book","trans":["Di dekat stasiun ada kedai ramen yang populer. Hari ini Tanutaro masuk ke sana untuk pertama kalinya.","Di pintu masuk ada mesin tiket. Katanya di kedai ini kita harus membeli tiket makan dulu.","Tapi tombolnya banyak sekali, dia tidak tahu harus menekan yang mana.","Lalu Kon yang ada di belakangnya memberi tahu, \"Yang paling kiri itu ramen biasa, lho.\"","Setelah duduk dan menyerahkan tiket makan, pelayan bertanya, \"Mau mi-nya seberapa keras?\"","Tanutaro menjawab, \"Agak keras, ya.\" 「かため」 artinya mi yang agak keras.","Kuah panas dan mi yang agak keras itu luar biasa enak. Tanutaro sampai menghabiskan semua kuahnya."],"vocab":["populer","pintu masuk","mesin tiket","tiket makan","menekan, mendorong","biasa, standar","tempat duduk","menyerahkan, memberikan","mi","semua, seluruhnya"],"grammar":[{"t":"〜そうです(伝聞)","note":"Bentuk biasa + そうです berarti \"katanya…\". Contoh: この店では、先に食券を買うそうです。"},{"t":"〜ばいい","note":"「どれを〜ばいいか」= \"sebaiknya … yang mana\". Contoh: どれを押せばいいかわかりません。"},{"t":"〜てしまいます","note":"Menunjukkan tindakan dilakukan sampai tuntas, sering juga bernuansa \"jadi tidak sengaja…\". Contoh: スープを全部飲んでしまいました。"},{"t":"〜と(syarat)","note":"「A と、B」= begitu A dilakukan, B terjadi. Contoh: 食券を渡すと、店員さんに聞かれました。"}]},"a-n2-5-n3":{"title":"Pembayaran Nontunai yang Semakin Meluas","topic":"Masyarakat","trans":["Dalam beberapa tahun terakhir, jumlah orang yang memakai pembayaran nontunai di Jepang juga meningkat pesat. Dulu banyak toko yang hanya menerima uang tunai, tetapi sekarang makin banyak toko yang bisa dibayar dengan ponsel pintar atau kartu.","Pembayaran nontunai punya keunggulan: bayarnya cepat dan uang jadi lebih mudah diatur. Karena tidak perlu mencari uang receh di kasir, waktu belanja pun jadi lebih singkat. Selain itu, kapan dan berapa banyak uang yang kamu keluarkan tercatat, jadi mudah dicek kembali nanti.","Di sisi lain, masih ada masalah yang harus diselesaikan. Kalau terjadi pemadaman listrik atau gangguan jaringan, ada kemungkinan kita tidak bisa membayar. Ada orang yang jadi boros tanpa sadar, dan ada juga lansia yang tidak pandai mengoperasikan mesin. Karena itu, kita tidak boleh lupa memberi perhatian kepada mereka.","Bagaimana cara menyeimbangkan kemudahan dan rasa aman? Yang dibutuhkan adalah masyarakat yang bisa memakai uang tunai dan pembayaran nontunai dengan baik."],"vocab":["pembayaran, penyelesaian transaksi","tiba-tiba, dengan cepat","pengelolaan, manajemen","uang receh","catatan","pemadaman listrik","gangguan, kerusakan","pengoperasian","lansia","perhatian, pertimbangan"],"grammar":[{"t":"〜やすい","note":"Dipasang setelah bentuk ます kata kerja (tanpa ます), artinya \"mudah untuk melakukan sesuatu\". Contoh: 「お金の管理がしやすい」「後で確認しやすい」."},{"t":"〜ため(sebab)","note":"Menyatakan sebab atau alasan, nuansanya lebih formal/tulisan dibanding 「から」. Contoh: 「小銭を探す必要がないため、買い物の時間が短くなる」."},{"t":"〜おそれがある","note":"Menyatakan adanya kemungkinan terjadi hal yang buruk. Contoh: 「支払いができなくなるおそれがある」."},{"t":"〜なければならない","note":"Menyatakan keharusan melakukan sesuatu. Contoh: 「まだ解決しなければならない問題もある」."}]},"a-n2-5-n4":{"title":"Pembayaran Nontunai yang Semakin Meluas","topic":"Masyarakat","trans":["Akhir-akhir ini, jumlah orang yang membayar secara nontunai di Jepang juga meningkat pesat. Dulu banyak toko yang hanya menerima uang tunai. Sekarang makin banyak toko yang bisa dibayar dengan ponsel pintar atau kartu.","Pembayaran nontunai itu cepat, dan mengatur uang juga mudah. Soalnya, kita tidak perlu mencari uang receh di kasir. Kapan dan berapa banyak uang yang dipakai juga tercatat.","Tapi, masih ada masalah. Kalau terjadi pemadaman listrik atau gangguan jaringan, mungkin kita tidak bisa membayar. Kita juga harus memikirkan orang yang boros dan para lansia yang tidak pandai memakai mesin. Masyarakat yang bisa memakai uang tunai dan nontunai sekaligus itu penting."],"vocab":["uang tunai","membayar","bertambah","uang receh","pengelolaan, manajemen","catatan","pemadaman listrik","mesin","lansia","masyarakat"],"grammar":[{"t":"〜なくてもいい","note":"Artinya \"tidak perlu melakukan ~ juga tidak apa-apa\". Contoh: 「レジで小銭を探さなくてもいいからです」"},{"t":"〜かもしれません","note":"Artinya \"mungkin ~\". Contoh: 「払えなくなるかもしれません」"},{"t":"〜なければなりません","note":"Artinya \"harus melakukan ~\". Contoh: 「お年寄りのことも考えなければなりません」"},{"t":"Kata kerja bentuk ます + すぎる","note":"Artinya \"melakukan sesuatu berlebihan, terlalu ~\". Contoh: 「使いすぎる人」"}]},"a-n1-2-n3":{"title":"AIの時代に「学ぶ」意味を考える","topic":"Berita","trans":["Karena AI generatif semakin meluas, mendapatkan pengetahuan jadi sangat mudah. Kalau ada hal yang tidak kamu mengerti, cukup tanya AI dan kamu langsung mendapat jawabannya.","Karena itu, mulai muncul orang yang berkata, \"Bukankah manusia tidak perlu lagi berusaha keras belajar?\" Namun, menurutku cara berpikir seperti itu melupakan makna belajar yang sebenarnya.","Belajar bukan sekadar mendapatkan jawaban. Kita memeriksa apakah informasi itu benar, membandingkan berbagai pendapat, lalu menilai sendiri. Justru karena ada proses itu, kemampuan berpikir bisa tumbuh sedikit demi sedikit. Bisa tidaknya seseorang mempertimbangkan dan memeriksa jawaban dari AI dengan saksama ditentukan oleh seberapa dalam pembelajarannya.","Justru karena ini zaman ketika jawaban mudah didapat, sikap terus bertanya \"kenapa bisa begitu?\" menjadi penting. Makna belajar bukannya hilang, melainkan sedang dipikirkan kembali. Daripada menimbun pengetahuan, bagaimana kita menggunakannya dan menilainya akan menjadi inti dari pembelajaran ke depan."],"vocab":["meluas, menyebar","mendapatkan, memperoleh","usaha, upaya keras","sebenarnya, sejati","informasi","memeriksa, memastikan","membandingkan","penilaian, keputusan","proses","sikap, pendirian"],"grammar":[{"t":"〜ため(sebab)","note":"Menyatakan sebab atau alasan. Sedikit lebih formal daripada「から」dan sering dipakai dalam tulisan. Contoh:「生成AIが広がったため、知識を手に入れることはとても簡単になった」"},{"t":"〜わけではない","note":"Berarti \"bukan berarti ...\". Ini adalah negasi sebagian agar kalimat tidak terdengar terlalu mutlak. Contoh:「学ぶ意味はなくなるわけではなく、むしろもう一度考え直されている」"},{"t":"〜によって","note":"Berarti \"tergantung pada ...\" atau \"ditentukan oleh ...\". Bisa juga menyatakan cara atau sebab. Contoh:「その人の学びの深さによって決まる」"},{"t":"〜かどうか","note":"Berarti \"apakah ... atau tidak\". Kalimat tanya ya/tidak disisipkan ke dalam kalimat lain. Contoh:「情報が正しいかどうかを確かめ」"}]},"a-n1-2-n4":{"title":"AIの時代に「学ぶ」意味を考える","topic":"Berita","trans":["Setelah AI meluas, hal yang ingin kita ketahui jadi bisa langsung dicari. Kalau ada yang tidak kamu mengerti, cukup tanya AI dan dia akan memberi tahu jawabannya. Karena itu, mulai muncul orang yang berkata, \"Manusia tidak perlu belajar lagi.\"","Tapi menurutku, belajar bukan sekadar menerima jawaban. Kita memikirkan apakah informasi itu benar dan membandingkan berbagai pendapat. Dengan berpikir dan memutuskan sendiri, kemampuan berpikir akan tumbuh. Bisa tidaknya kita menilai benar atau tidaknya jawaban AI ditentukan oleh seberapa banyak orang itu sudah belajar.","Justru karena ini zaman ketika jawaban mudah didapat, berpikir \"kenapa\" menjadi lebih penting. Daripada menghafal banyak pengetahuan, memikirkan cara menggunakannya akan jadi lebih penting. Makna belajar bukannya hilang, melainkan sedang dipikirkan kembali."],"vocab":["meluas, menyebar","mencari tahu, memeriksa","jawaban","membandingkan","berpikir, memikirkan","tumbuh, berkembang","mudah, sederhana","zaman, era","penting, berharga","makna, arti"],"grammar":[{"t":"〜ようになる","note":"Menyatakan perubahan, yaitu jadi bisa melakukan sesuatu. Contoh:「知りたいことをすぐに調べられるようになった」"},{"t":"〜なくてもいい","note":"Menyatakan tidak melakukan sesuatu pun tidak apa-apa atau tidak perlu. Contoh:「もう人が勉強しなくてもいい」"},{"t":"〜かどうか","note":"Berarti \"apakah ... atau tidak\". Pertanyaan disisipkan ke dalam kalimat. Contoh:「情報が正しいかどうかを考えて」"},{"t":"AよりB","note":"Berarti B lebih ... daripada A. Contoh:「知識をたくさん覚えるより、どう使うかを考えることが大事になるだろう」"}]},"a-n1-1-n3":{"title":"Pemanasan Global dan Kehidupan Kita","topic":"Lingkungan","trans":["Pemanasan global bukan lagi cerita tentang masa depan yang jauh, melainkan masalah yang berkaitan langsung dengan kehidupan kita. Cuaca ekstrem merusak hasil pertanian, dan naiknya permukaan air laut juga menimbulkan kerugian. Kerusakan seperti ini terus bertambah parah dari tahun ke tahun.","Melihat situasi seperti ini, mungkin kamu merasa bahwa hal yang bisa dilakukan setiap orang itu sedikit. Namun, mengurangi pemborosan listrik adalah hal yang bisa langsung kita lakukan juga. Selain itu, menggunakan transportasi umum seperti kereta dan bus juga salah satu cara yang baik. Justru akumulasi dari hal-hal kecil seperti inilah yang akan membawa perubahan besar.","Demi mewariskan bumi yang subur kepada generasi mendatang, kita dituntut untuk bertindak sekarang juga. Pemanasan global bukan cerita tentang negara yang jauh, tetapi juga berkaitan langsung dengan meja makan dan kehidupan kita. Jangan lupa bahwa tindakan kecil dari setiap orang pada akhirnya akan melahirkan perubahan besar."],"vocab":["cuaca ekstrem","hasil pertanian","kerugian, bencana","permukaan laut","serius, parah","transportasi umum","akumulasi, tumpukan","generasi","meja makan","dituntut, diharapkan"],"grammar":[{"t":"〜によって","note":"Menyatakan sebab atau cara, \"karena…\" atau \"dengan…\". Contoh: 「異常気象によって農作物が被害を受けたり」."},{"t":"〜一方だ","note":"Menyatakan kecenderungan yang terus bergerak ke satu arah, \"makin lama makin…\". Contoh: 「ますます深刻になる一方です」."},{"t":"〜ためにも","note":"Berarti \"demi… (tujuan), juga…\", menekankan pentingnya tujuan. Contoh: 「未来の世代に豊かな地球を残すためにも」."},{"t":"〜こそ","note":"Menegaskan kata di depannya, \"justru…\" atau \"itulah…\". Contoh: 「こうした小さな積み重ねこそが」."}]},"a-n1-1-n4":{"title":"Pemanasan Global dan Kehidupan Kita","topic":"Lingkungan","trans":["Pemanasan global bukan lagi cerita tentang masa depan yang jauh. Dampaknya sudah langsung terasa dalam kehidupan kita. Karena cuaca yang tidak biasa, sayuran dan padi mengalami kerusakan.","Permukaan air laut naik, dan orang yang kesulitan pun makin banyak. Kerusakan seperti ini makin parah setiap tahun. Mungkin kamu berpikir bahwa hal yang bisa dilakukan satu orang itu sedikit.","Tapi, kita bisa berusaha tidak memboroskan listrik, atau naik bus dan kereta. Kalau hal-hal kecil seperti itu terus dilakukan, akan membawa perubahan besar. Demi meninggalkan bumi yang bersih untuk orang-orang di masa depan, mari bergerak mulai sekarang. Pemanasan global adalah masalah yang juga berkaitan dengan makanan dan kehidupan kita. Aku harap kamu tidak lupa bahwa tindakan kecil bisa menciptakan perubahan besar."],"vocab":["bumi","masa depan","kehidupan","pengaruh, dampak","cuaca","kerugian, bencana","listrik","melanjutkan, terus melakukan","meninggalkan, menyisakan","lupa"],"grammar":[{"t":"〜ている","note":"Menyatakan keadaan atau perubahan yang sedang berlangsung. Contoh: 「野菜や米が被害を受けている」「困る人も増えている」"},{"t":"〜かもしれない","note":"Berarti \"mungkin\" atau \"bisa jadi\". Contoh: 「思うかもしれない」"},{"t":"〜ようにする","note":"Menyatakan usaha untuk menjadikannya kebiasaan atau berusaha melakukannya sebisa mungkin. Contoh: 「電気をむだに使わないようにしたり」"},{"t":"〜と(條件)","note":"Berarti \"kalau/begitu… maka…\", jika sesuatu dilakukan, hasilnya muncul secara alami. Contoh: 「小さなことを続けると、大きな変化につながる」"}]},"a-n1-4-n3":{"title":"情報の海を泳ぐために","topic":"Media","trans":["Berkat menyebarnya smartphone, kita jadi bisa melihat banyak informasi kapan pun dan di mana pun. Namun, di balik kemudahan itu tersembunyi bahaya yang sulit disadari.","Di internet ada banyak informasi yang tidak jelas benar atau tidaknya. Di antaranya, berita bohong yang sengaja disebarkan untuk menipu orang pun tidak sedikit. Kemampuan membedakan fakta dan opini kini lebih dibutuhkan daripada sebelumnya.","Yang lebih merepotkan adalah sistem yang hanya menampilkan informasi sesuai selera kita. Tanpa disadari, jangkauan yang kita lihat jadi menyempit dan cara berpikir kita mudah menjadi berat sebelah.","Yang penting adalah tidak langsung memercayai satu informasi saja, tetapi memeriksa beberapa sumber untuk memastikannya. Saat kamu sendiri membagikan informasi, kamu juga harus bertanggung jawab atas isinya.","Kemampuan membaca informasi dengan benar sudah bukan lagi milik segelintir ahli saja. Ini adalah pengetahuan yang harus dimiliki semua orang dan tak bisa dilepaskan dari kehidupan di zaman modern."],"vocab":["menyebar, meluas","bahaya","bersembunyi, tersembunyi","membedakan","sistem, mekanisme","jangkauan, cakupan","berat sebelah, condong","sumber informasi","tanggung jawab","menguasai, memiliki (kemampuan)"],"grammar":[{"t":"〜によって","note":"Menyatakan sebab atau cara, “karena ～ / dengan ～”. Contoh: 「スマートフォンが広まったことによって、私たちはいつでもどこでもたくさんの情報を見られるようになった」"},{"t":"〜ようになる","note":"Menyatakan perubahan keadaan atau kemampuan, “jadi bisa ～”. Contoh: 「たくさんの情報を見られるようになった」"},{"t":"〜ために","note":"Menyatakan tujuan, “untuk ～”. Contoh: 「わざと人をだますために広められるうそのニュース」"},{"t":"〜なければならない","note":"Menyatakan keharusan atau kewajiban, “harus ～”. Contoh: 「その内容に責任を持たなければならない」"}]},"a-n1-4-n4":{"title":"情報をじょうずに使うために","topic":"Media","trans":["Berkat smartphone, kita bisa melihat banyak informasi kapan saja. Tapi, itu bukan cuma praktis, ada juga masalah yang perlu diwaspadai.","Di internet ada banyak informasi yang tidak jelas benar atau tidaknya. Ada juga orang yang menyebarkan berita bohong dengan niat jahat. Karena itu, kemampuan memisahkan fakta dan opini lalu memikirkannya jadi sangat penting.","Yang lebih merepotkan, yang muncul hanya informasi yang kita sukai. Tanpa disadari, dunia yang kita lihat jadi menyempit. Yang penting adalah tidak langsung memercayai satu informasi, tetapi juga melihat informasi lain untuk memastikannya. Saat kamu sendiri membagikan informasi, kamu juga harus bertanggung jawab atas isinya. Kemampuan membaca informasi dengan benar sudah bukan lagi milik para ahli saja. Untuk hidup di zaman sekarang, ini adalah kemampuan penting yang sebaiknya dimiliki semua orang."],"vocab":["informasi","praktis, nyaman","masalah","benar, kenyataan","menyebarkan, mempromosikan","fakta","opini","memastikan","tanggung jawab","menguasai, memiliki (kemampuan)"],"grammar":[{"t":"〜ようになる","note":"Menyatakan perubahan, hal yang tadinya tidak bisa jadi bisa. Contoh: 「いつでもたくさんの情報が見られるようになった」"},{"t":"〜ないで","note":"Menyatakan “tidak melakukan sesuatu, melainkan melakukan hal lain”. Contoh: 「一つの情報をすぐ信じないで、ほかの情報も見て確かめることだ」"},{"t":"〜なければならない","note":"Menyatakan keharusan untuk melakukan sesuatu. Contoh: 「内容に責任を持たなければならない」"},{"t":"〜ばかり","note":"Menyatakan hampir semuanya hanya satu jenis hal. Contoh: 「自分が好きな情報ばかり出てくる」"}]},"a-n1-3-n3":{"title":"Masalah Penurunan Angka Kelahiran dan Penuaan Penduduk","topic":"Masyarakat","trans":["Di Jepang, angka kelahiran yang menurun dan penuaan penduduk berlangsung dengan kecepatan yang jarang ditemui bahkan di seluruh dunia. Persentase lansia dalam total penduduk naik sedikit demi sedikit setiap tahun. Di sisi lain, jumlah anak yang lahir terus berkurang.","Kalau terus begini, sistem jaminan sosial seperti pensiun, layanan kesehatan, dan perawatan lansia mungkin tidak bisa dipertahankan lagi. Sebab, biaya untuk semua itu terus naik, sementara generasi usia kerja yang menopangnya semakin sedikit.","Sebagai langkah penanganan, ada yang memikirkan untuk memperkuat sistem yang memudahkan orang menyeimbangkan antara mengurus anak dan bekerja. Menambah jumlah pekerja asing yang diterima juga sedang dibahas. Namun, tidak ada satu pun yang merupakan masalah yang bisa langsung diselesaikan.","Di balik berkurangnya jumlah anak, ada berbagai alasan, seperti kekhawatiran soal uang dan perubahan cara pandang. Karena itu, masalah ini tidak akan selesai hanya dengan membagikan subsidi. Penurunan angka kelahiran dan penuaan penduduk sudah menjadi kenyataan yang tidak bisa dihindari. Kita harus berpikir serius tentang bagaimana seluruh masyarakat menghadapinya dan negara seperti apa yang akan kita wariskan kepada generasi berikutnya."],"vocab":["penurunan angka kelahiran dan penuaan penduduk","persentase, proporsi","pensiun","perawatan lansia","menopang, mendukung","menyeimbangkan keduanya","menerima, menampung","latar belakang","subsidi","kenyataan"],"grammar":[{"t":"〜かもしれない","note":"Berarti \"mungkin\"; dugaan yang tidak dipastikan oleh pembicara. Contoh: 「社会保障の制度が続けられなくなるかもしれない」"},{"t":"〜やすい","note":"Dipasang setelah bentuk ます kata kerja (tanpa ます), berarti \"mudah untuk melakukan sesuatu\". Contoh: 「子育てと仕事を両立しやすくする制度」"},{"t":"〜わけではない","note":"Berarti \"bukan berarti ...\"; negasi sebagian yang menyangkal anggapan yang umumnya muncul. Contoh: 「補助金を配るだけで問題が解決するわけではない」"},{"t":"〜なければならない","note":"Berarti \"harus, wajib\"; menyatakan kewajiban atau keharusan. Contoh: 「真剣に考えなければならない」"}]},"a-n1-3-n4":{"title":"Masalah Penurunan Angka Kelahiran dan Penuaan Penduduk","topic":"Masyarakat","trans":["Di antara negara-negara di dunia, Jepang termasuk yang penuaan penduduk dan penurunan angka kelahirannya berlangsung sangat cepat. Persentase lansia perlahan naik setiap tahun. Tapi jumlah anak yang lahir terus berkurang.","Kalau terus begini, sistem penting dalam masyarakat bisa jadi kewalahan. Uang yang dipakai untuk pensiun, layanan kesehatan, dan perawatan lansia sepertinya akan terus bertambah. Tapi generasi usia kerja yang menopangnya justru perlahan berkurang.","Sebagai langkah penanganan, sedang dibahas sistem yang membuat orang lebih mudah bekerja sambil mengurus anak. Ada juga pembicaraan untuk menambah pekerja asing, tapi hal ini tidak bisa langsung diselesaikan. Alasan anak yang lahir semakin sedikit ada banyak, misalnya kekhawatiran soal uang. Penurunan angka kelahiran dan penuaan penduduk adalah masalah yang tidak bisa dihilangkan, jadi mari kita semua membahasnya dengan serius."],"vocab":["penurunan angka kelahiran dan penuaan penduduk","lansia","persentase, proporsi","bertambah","berkurang","pensiun","menopang, mendukung","sistem, institusi","penyelesaian, menyelesaikan","serius, sungguh-sungguh"],"grammar":[{"t":"〜かもしれません","note":"Berarti \"mungkin\"; dugaan yang tidak dipastikan oleh pembicara. Contoh: 「社会の大切な仕組みが大変になるかもしれません」"},{"t":"Kata kerja bentuk ます (tanpa ます) + そうです","note":"Menyatakan dugaan berdasarkan keadaan yang terlihat, \"sepertinya akan ...\". Contoh: 「これからも増えそうです」"},{"t":"〜ながら","note":"Menyatakan satu orang melakukan dua hal sekaligus, \"sambil ...\". Contoh: 「子育てをしながら働きやすくする制度」"},{"t":"〜ので","note":"Menyatakan sebab atau alasan, nadanya lebih halus daripada 「から」. Contoh: 「なくせない問題なので、みんなで真剣に話し合いましょう」"}]},"a-n1-6-n3":{"title":"Warisan yang Diturunkan","topic":"Budaya","trans":["Budaya tradisional dan keahlian para pengrajin yang diwariskan di berbagai penjuru Jepang adalah harta berharga yang telah diturunkan selama waktu yang sangat panjang. Namun kini, banyak di antaranya menghadapi krisis yang bisa membuatnya hilang.","Penyebab terbesarnya adalah kurangnya penerus yang mewarisi keahlian tersebut. Selain populasi yang makin menua, anak muda juga pergi ke kota, sehingga jumlah orang yang ingin belajar berkurang setiap tahun.","Meski dibilang menjaga tradisi, bukan berarti kita cukup mempertahankannya persis seperti dulu. Budaya baru bisa terus hidup dengan menciptakan nilai baru yang sesuai dengan perubahan zaman.","Belakangan ini, contoh memadukan desain modern ke dalam kerajinan tradisional semakin banyak. Upaya untuk memperkenalkan daya tariknya ke luar negeri juga sedikit demi sedikit meluas. Memadukan yang lama dengan yang baru mungkin akan menjadi kunci untuk membuka jalan. Bagaimana cara kita menyambungkan apa yang telah dibangun orang-orang terdahulu ke generasi berikutnya? Mungkin itu adalah pekerjaan rumah besar yang tersisa bagi kita masing-masing."],"vocab":["diwariskan, tersebar turun-temurun","pengrajin, perajin","mewarisi, meneruskan","harta, aset","krisis","menghadapi","penerus","penuaan populasi","menjaga, mempertahankan","menciptakan, melahirkan"],"grammar":[{"t":"〜というわけではない","note":"Berarti \"bukan berarti ...\", negasi sebagian. Contoh: 「昔のままを保てばいいというわけではない」"},{"t":"〜といっても","note":"Berarti \"meski dibilang ..., tetapi ...\", dipakai untuk menambah atau meluruskan kesan sebelumnya. Contoh: 「伝統を守るといっても、昔のままを保てばいいというわけではない」"},{"t":"〜によって","note":"Menyatakan cara atau sarana, \"dengan ...\" atau \"melalui ...\". Contoh: 「新しい価値を生み出すことによって、文化は生き続けることができる」"},{"t":"〜ため(に)","note":"Menyatakan sebab atau alasan, \"karena ...\". Contoh: 「若者が都市に出ていくため、学ぼうとする人は毎年減っている」"}]},"a-n1-6-n4":{"title":"Warisan yang Diturunkan","topic":"Budaya","trans":["Jepang punya banyak budaya dan keahlian pengrajin yang diwariskan sejak dulu. Semua itu adalah hal yang dijaga dengan hati-hati selama waktu yang panjang. Tapi sekarang, banyak di antaranya hampir hilang, dan hal ini sangat mengkhawatirkan.","Alasan utamanya adalah kurangnya orang yang meneruskan keahlian tersebut. Orang-orang yang punya keahlian makin lama makin tua. Anak muda pergi ke kota, dan jumlah orang yang belajar keahlian itu juga berkurang setiap tahun.","Untuk menjaga tradisi, tidak cukup hanya mempertahankannya seperti dulu. Menciptakan kelebihan baru yang sesuai dengan zaman juga penting. Belakangan ini, ada juga orang yang memasukkan desain baru ke dalam kerajinan lama. Orang yang memperkenalkan keunggulannya ke luar negeri juga makin banyak. Agar bisa mewariskan hal-hal lama kepada generasi berikutnya, kita juga ingin memikirkan apa yang bisa kita lakukan."],"vocab":["tradisi","pengrajin, perajin","keahlian, teknik","khawatir","alasan","kota","belajar","kerajinan","generasi"],"grammar":[{"t":"〜そうだ(樣態)","note":"Menyatakan sesuatu tampak hampir terjadi. Contoh: 「その多くがなくなりそうで」 berarti banyak di antaranya hampir hilang."},{"t":"〜てきた","note":"Menyatakan perubahan yang berlangsung terus sampai sekarang. Contoh: 「人も増えてきました」 berarti jumlah orangnya makin lama makin bertambah."},{"t":"〜ために","note":"Menyatakan tujuan, yaitu untuk melakukan sesuatu. Contoh: 「次の世代に残すために」 berarti demi mewariskannya kepada generasi berikutnya."},{"t":"〜たいです","note":"Menyatakan keinginan pembicara. Contoh: 「考えたいです」 berarti ingin memikirkannya."}]},"a-n1-5-n3":{"title":"捨てられる食べ物","topic":"Sosial","trans":["Makanan yang sebenarnya masih bisa dimakan tetapi malah dibuang telah menjadi masalah besar di seluruh dunia. Makanan seperti ini disebut 「食品ロス」 (food loss atau pemborosan makanan). Konon di Jepang pun, jutaan ton makanan dibuang sia-sia setiap tahunnya.","Di sisi lain, ada banyak orang di dunia yang tidak bisa makan dengan cukup. Di balik kehidupan yang tampak berlimpah makanan, kesenjangan besar sedang terjadi.","Penyebab pemborosan makanan bukan hanya sisa makanan dari rumah tangga atau restoran. Produk yang seharusnya masih bisa dijual pun banyak yang disingkirkan dengan alasan tanggal kedaluwarsa (batas waktu terbaik untuk dikonsumsi). Kondisi seperti ini tidak boleh dibiarkan begitu saja.","Untuk menyelesaikan masalah ini, upaya perusahaan tentu saja penting, dan kesadaran setiap orang juga penting. Kebiasaan kecil seperti tidak membeli berlebihan dan tidak memasak berlebihan bisa menjadi langkah besar. Menghargai sumber daya yang terbatas juga merupakan tanggung jawab kita kepada generasi berikutnya. Gaya hidup yang tidak menyia-nyiakan makanan kini kembali dibutuhkan."],"vocab":[{"w":"食品ロス","m":"pemborosan makanan"},{"w":"捨てる","m":"membuang"},{"w":"無駄","m":"sia-sia, mubazir"},{"w":"十分","m":"cukup, memadai"},{"w":"賞味期限","m":"batas waktu terbaik dikonsumsi (best before)"},{"w":"処分","m":"menyingkirkan, membuang"},{"w":"見逃す","m":"membiarkan begitu saja, mengabaikan"},{"w":"取り組み","m":"upaya, langkah"},{"w":"意識","m":"kesadaran"},{"w":"心がけ","m":"sikap berhati-hati, kebiasaan yang diperhatikan"}],"grammar":[{"t":"〜ように見える","note":"Artinya \"tampak seperti ...\". Contoh: 「食べ物があふれているように見える生活の裏で、大きな差が生まれているのです」"},{"t":"〜わけではない","note":"Artinya \"bukan berarti ...\". Ini negasi sebagian yang menyangkal anggapan tertentu dengan halus. Contoh: 「このような現状を、見逃していいわけではありません」"},{"t":"〜ためには","note":"Artinya \"untuk ... (kita harus ...)\". Diikuti syarat atau cara yang diperlukan. Contoh: 「この問題を解決するためには、企業の取り組みはもちろん、一人ひとりの意識も大切です」"},{"t":"〜はもちろん","note":"Artinya \"... tentu saja, bahkan ... juga\". Menyebut dulu contoh yang sudah pasti. Contoh: 「企業の取り組みはもちろん、一人ひとりの意識も大切です」"}]},"a-n1-5-n4":{"title":"捨てられる食べ物","topic":"Sosial","trans":["Makanan yang sebenarnya masih bisa dimakan tetapi malah dibuang telah menjadi masalah di seluruh dunia. Pemborosan makanan seperti ini disebut 「食品ロス」 (food loss). Konon di Jepang pun, setiap tahun sangat banyak makanan yang dibuang sia-sia.","Di sisi lain, ada banyak orang di dunia yang tidak bisa makan dengan cukup. Di balik negara-negara yang makanannya melimpah, terjadi kesenjangan yang sangat besar. Penyebab pemborosan makanan bukan hanya nasi atau lauk sisa di rumah dan restoran.","Produk yang masih bisa dijual pun sering dibuang dalam jumlah besar karena sudah lewat batas waktu terbaik untuk dikonsumsi. Untuk menyelesaikan masalah ini, upaya perusahaan dan kesadaran setiap orang sama-sama penting. Berusaha untuk tidak membeli terlalu banyak dan tidak memasak terlalu banyak akan menjadi langkah besar. Menghargai sumber daya yang terbatas juga merupakan tanggung jawab kita kepada generasi berikutnya. Mari kita pikirkan kembali sekarang tentang gaya hidup yang tidak menyia-nyiakan makanan."],"vocab":[{"w":"捨てられる","m":"dibuang"},{"w":"食品ロス","m":"pemborosan makanan"},{"w":"問題","m":"masalah"},{"w":"毎年","m":"setiap tahun"},{"w":"むだ","m":"sia-sia, mubazir"},{"w":"十分","m":"cukup"},{"w":"原因","m":"penyebab"},{"w":"解決","m":"penyelesaian, menyelesaikan"},{"w":"大切","m":"penting, berharga"},{"w":"責任","m":"tanggung jawab"}],"grammar":[{"t":"〜のに","note":"Artinya \"padahal ...\" atau \"meskipun ...\". Mengungkapkan rasa tidak puas atau sayang. Contoh: 「まだ食べられるのに捨てられてしまう食べ物が、世界で問題になっている」"},{"t":"〜そうだ(kabar yang didengar)","note":"Dipasang setelah bentuk biasa, artinya \"katanya ...\" atau \"konon ...\". Contoh: 「日本でも、毎年とても多くの食べ物がむだに捨てられているそうだ」"},{"t":"Bentuk potensial (食べられる)","note":"Kata kerja diubah ke bentuk potensial untuk menyatakan \"bisa ...\", sedangkan bentuk negatifnya berarti \"tidak bisa ...\". Contoh: 「世界にはご飯を十分に食べられない人がたくさんいる」"},{"t":"〜ようにする","note":"Artinya berusaha membiasakan atau mengusahakan sesuatu (negatifnya 「〜ないようにする」). Contoh: 「買いすぎない、作りすぎないようにするのが、大きな一歩になる」"}]},"a-n1-7-n3":{"title":"変わりゆく日本語","topic":"Bahasa","trans":["Pernahkah kamu mendengar istilah 「ら抜き言葉」 (kata tanpa ら)? Mengucapkan 「食べられる」 menjadi 「食べれる」 sering dianggap sebagai bahasa Jepang yang tidak benar. Karena bentuknya adalah 「食べられる」 yang 「ら」-nya dihilangkan, sebagian orang merasa terganggu mendengarnya.","Namun, kalau dilihat dari sudut pandang ilmu linguistik, ada juga pendapat bahwa ini bukan sekadar \"kerusakan bahasa\", melainkan perubahan yang masuk akal. 「見られる」 punya beberapa makna sekaligus, seperti pasif, hormat, dan potensial (bisa). Kalau 「見れる」, kita langsung tahu bahwa maknanya adalah \"bisa\". Perubahan ini diperkirakan terjadi karena bentuknya jadi lebih mudah dipahami.","Pada dasarnya, bahasa sudah terus berubah sejak dulu. Bahasa Jepang yang sekarang kita yakini \"benar\" pun, di mata orang seratus tahun lalu, mungkin hanyalah bahasa yang kacau. Kalau orang seratus tahun lalu mendengar bahasa Jepang masa kini, bisa jadi mereka juga akan merasa aneh.","Daripada meratapi perubahan, bukankah lebih baik memikirkan mengapa bahasa berubah? Dengan begitu, kita mungkin bisa lebih dekat dengan hakikat bahasa. Saat bahasa berubah, pasti ada alasannya."],"vocab":["linguistik","sudut pandang, posisi","sekadar, semata-mata","masuk akal, rasional","perubahan","pasif","hormat (bentuk hormat)","potensial (bisa melakukan)","meyakini, percaya","hakikat, esensi"],"grammar":[{"t":"〜ため(sebab・alasan)","note":"Menyatakan sebab atau alasan, lebih formal daripada 「から」. Contoh: 「分かりやすくなるため」 menjelaskan alasan terjadinya perubahan."},{"t":"〜にすぎない","note":"Artinya \"hanyalah, tidak lebih dari\", dengan nuansa \"tidak istimewa\". Contoh: 「乱れた言葉にすぎないでしょう」."},{"t":"〜より〜ほうが","note":"Membandingkan dua hal, artinya \"daripada A, lebih baik B\". Contoh: 「変化を悲しむより、なぜ変わるのかを考えるほうが」."},{"t":"〜はずだ","note":"Menyatakan dugaan berdasarkan logika atau akal sehat, artinya \"seharusnya, pasti\". Contoh: 「何か理由があるはずです」."}]},"a-n1-7-n4":{"title":"変わっていく日本語","topic":"Bahasa","trans":["Pernahkah kamu mendengar istilah 「ら抜き言葉」? Sekarang makin banyak orang yang mengucapkan 「食べられる」 menjadi 「食べれる」. Tapi cara bicara ini kadang dianggap sebagai bahasa Jepang yang tidak benar.","Sebagian peneliti bahasa berpendapat bahwa ini bukan perubahan yang buruk. 「見られる」 punya beberapa makna, jadi kadang sulit dibedakan. Tapi kalau 「見れる」, kita langsung tahu maknanya adalah \"bisa melihat\".","Lagi pula, bahasa sudah terus berubah sejak dulu. Bahasa Jepang yang sekarang dianggap benar pun, bagi orang seratus tahun lalu mungkin terdengar aneh. Daripada sedih karena perubahan, bagaimana kalau kita coba pikirkan kenapa bahasa berubah?"],"vocab":["bahasa, kata","mendengar (bentuk lampau dari 聞く)","benar","penelitian, riset","perubahan","arti, makna","mengerti, tahu","dulu, zaman dahulu","merasa sedih","berpikir (bentuk て dari 考える)"],"grammar":[{"t":"〜たことがある","note":"Menyatakan pernah mengalami sesuatu. Contoh: 「聞いたことがありますか」 menanyakan apakah lawan bicara pernah mendengarnya."},{"t":"〜ので","note":"Menyatakan sebab atau alasan, nuansanya lebih lembut daripada 「から」. Contoh: 「いくつか意味があるので、分かりにくいことがあります」"},{"t":"〜にくい","note":"Dipasang setelah bentuk ます kata kerja, artinya sulit melakukan sesuatu. Contoh: 「分かりにくいことがあります」"},{"t":"〜てくる","note":"Menyatakan perubahan yang berlangsung terus dari masa lalu hingga sekarang. Contoh: 「言葉は昔からずっと変わってきました」"}]},"a-n1-8-n3":{"title":"Tenaga Kerja Asing dan Masa Depan Masyarakat Jepang","topic":"Masyarakat","trans":["Masalah kekurangan tenaga kerja diperkirakan akan terus berlanjut. Karena itu, menerima orang asing tidak bisa lagi disebut sebagai solusi sementara.","Sejak sistem seperti Tokutei Ginou (Specified Skilled Worker) dibuat, jumlah orang asing yang tinggal di Jepang terus mencetak rekor tertinggi. Namun, bertambahnya jumlah orang tidak berarti mereka akan tinggal lama di Jepang.","Kalau fondasi kehidupan seperti bahasa yang tidak nyambung, mencari tempat tinggal, dan pendidikan anak belum siap, orang tidak akan menetap di Jepang meskipun gaji dan syaratnya diperbaiki.","Setelah mempekerjakan orang pun, perusahaan perlu mengajarkan bahasa Jepang dan membangun hubungan dengan warga sekitar.","Cara berpikir kita sebagai pihak yang menerima juga penting. Yang dipertanyakan adalah apakah kita bisa bergaul dengan mereka bukan hanya sebagai \"pekerja\", tetapi sebagai tetangga yang tinggal di wilayah yang sama.","Memang ada hal yang berubah karena sistem, tetapi yang pada akhirnya menentukan apakah seseorang akan tinggal lama mungkin adalah tumpukan interaksi kecil setiap hari.","Memikirkan masalah orang asing juga berarti memikirkan masyarakat seperti apa yang ingin diwujudkan Jepang."],"vocab":["tenaga kerja, tangan (untuk bekerja)","menerima","bersifat sementara","sistem, aturan","fondasi, dasar","menetap, tenang","perusahaan","wilayah, komunitas setempat","tetangga"],"grammar":[{"t":"〜ようになる/〜ようにする(ここでは〜と考えられている)","note":"Di teks ini 「考えられている」 (bentuk pasif) dipakai untuk menyatakan pandangan umum: 「人手が足りない問題は、これからも続くと考えられている」"},{"t":"〜からといって〜わけではない","note":"Artinya \"meskipun ada alasan tertentu, belum tentu ...\": 「人が増えたからといって、その人たちが日本に長く住むわけではない」"},{"t":"〜によって","note":"Menyatakan dasar, sebab, atau cara. Di sini artinya \"tergantung sistemnya\": 「制度によって変わる部分もあるが」"},{"t":"〜かどうか","note":"Artinya \"apakah ... atau tidak\", memasukkan pertanyaan ke dalam kalimat: 「同じ地域に住む隣人として付き合えるかどうかが問われている」"}]},"a-n1-8-n4":{"title":"Orang dari Luar Negeri dan Masa Depan Jepang","topic":"Masyarakat","trans":["Di Jepang saat ini, masalah kekurangan tenaga kerja terus berlanjut. Karena itu, meminta orang dari luar negeri untuk bekerja bukan lagi sekadar cara sementara.","Setelah sistem baru dibuat, jumlah orang asing yang tinggal di Jepang menjadi yang terbanyak sepanjang sejarah. Tapi, meski jumlahnya bertambah, belum tentu mereka akan tinggal di Jepang selamanya. Kalau bahasanya sulit, mencari rumah susah, atau khawatir dengan pelajaran anak, hidup jadi tidak stabil. Meski gajinya jadi lebih baik, kalau hidupnya tidak stabil, orang itu tidak bisa tinggal lama di Jepang.","Perusahaan juga perlu mengajarkan bahasa Jepang setelah mereka mulai bekerja, dan menciptakan kesempatan untuk bertemu dengan warga sekitar. Kita sebagai orang Jepang juga diharapkan tidak melihat orang asing hanya sebagai \"pekerja\", tetapi memikirkan mereka sebagai tetangga yang tinggal di kota yang sama. Memikirkan soal orang asing juga berarti memikirkan masyarakat seperti apa yang ingin diwujudkan Jepang."],"vocab":["kurang, tidak cukup","sistem, aturan","bertambah","kehidupan","stabil","gaji","wilayah, daerah","kesempatan","sebelah, tetangga","masyarakat"],"grammar":[{"t":"〜ても","note":"Artinya \"meskipun ... tetap ...\". Contoh: 「給料がよくなっても、生活が安定しなければ、その人は日本に長くいられない」"},{"t":"〜ば(bentuk pengandaian)","note":"Menyatakan syarat \"kalau ... maka ...\". Contoh: 「生活が安定しなければ、その人は日本に長くいられない」"},{"t":"〜とは限らない","note":"Artinya \"belum tentu ...\". Contoh: 「ずっと日本に住むとは限らない」"},{"t":"〜てほしい","note":"Menyatakan harapan agar orang lain melakukan sesuatu. Contoh: 「同じ町に住む隣の人として考えてほしい」"}]},"a-n2-1-n3":{"title":"Perubahan Cara Bekerja","topic":"Masyarakat","trans":["Dalam beberapa tahun terakhir, seiring berkembangnya internet, cara orang bekerja berubah drastis. Dulu pergi ke kantor untuk bekerja adalah hal yang biasa, tetapi sekarang makin banyak orang yang tidak begitu. Makin banyak perusahaan yang menerapkan 「テレワーク」, yaitu bekerja dari rumah tanpa pergi ke kantor.","Kerja jarak jauh punya keuntungan, yaitu waktu untuk perjalanan ke kantor jadi berkurang. Namun, ada juga masalah: batas antara pekerjaan dan kehidupan pribadi jadi sulit dibedakan. Selain itu, makin banyak juga orang yang tidak bekerja di jam yang sudah ditentukan, melainkan mengatur waktunya sendiri.","Dengan begitu, seiring meluasnya kerja jarak jauh, kebebasan dalam memilih tempat dan waktu kerja pun meningkat. Di sisi lain, muncul juga tantangan baru, yaitu batas antara pekerjaan dan kehidupan pribadi jadi kabur. Menyesuaikan diri dengan perubahan ini, kita juga perlu memikirkan cara bekerja yang baru.","Ke depannya, yang dibutuhkan adalah masyarakat yang memungkinkan setiap orang memilih cara bekerja yang cocok dengan dirinya. Untuk itu, menurutku penting bagi perusahaan maupun para pekerja untuk berusaha memahami pandangan satu sama lain."],"vocab":["perkembangan, berkembang","menerapkan, mengadopsi","perusahaan","pulang-pergi kerja, komuting","pembedaan, pemisahan","penyesuaian, mengatur","batas, garis pembatas","tantangan, masalah yang harus diselesaikan","dituntut, dibutuhkan"],"grammar":[{"t":"〜ことによって","note":"Berarti \"karena / melalui suatu hal\", untuk menyatakan sebab atau cara. Contoh: 「テレワークが広がったことによって、働く場所や時間の自由度は高くなりました」"},{"t":"〜一方で","note":"Berarti \"di satu sisi ..., di sisi lain ...\", biasanya diikuti hal yang berlawanan atau sisi yang berbeda. Contoh: 「その一方で、仕事と生活の境目があいまいになるという課題も生まれています」"},{"t":"〜に合わせて","note":"Berarti \"menyesuaikan dengan / sesuai dengan ...\". Contoh: 「こうした変化に合わせて、私たちも新しい働き方を考えていく必要があるでしょう」"},{"t":"〜のではなく","note":"Berarti \"bukan ..., melainkan ...\", menyangkal bagian pertama dan menekankan bagian kedua. Contoh: 「決まった時間に働くのではなく、自分で時間を調整して働く人も多くなりました」"}]},"a-n2-1-n4":{"title":"はたらき方の変化","topic":"Masyarakat","trans":["Karena internet makin praktis, cara bekerja berubah banyak.","Makin banyak perusahaan yang membiarkan orang bekerja dari rumah tanpa pergi ke kantor. Waktu naik kereta jadi berkurang, jadi terasa jauh lebih santai. Tapi, ada juga masalah: batas antara pekerjaan dan kehidupan pribadi jadi sulit dibedakan.","Selain itu, makin banyak juga orang yang menentukan waktu kerjanya sendiri.","Memang bisa bekerja dengan bebas, tetapi sepertinya ada juga orang yang lupa waktu untuk istirahat.","Ke depannya, masyarakat yang memungkinkan kita memilih cara bekerja yang cocok dengan diri sendiri itu penting.","Kita juga harus terus memikirkan cara bekerja yang baru."],"vocab":["praktis, mudah","berubah","bertambah","pembedaan, pemisahan","masalah","menentukan","bebas, kebebasan","lupa","masyarakat","penting"],"grammar":[{"t":"〜て(で)、〜(bentuk て untuk sebab・urutan)","note":"Bentuk て menghubungkan dua klausa untuk menyatakan sebab atau urutan. Contoh: 「インターネットが 便利に なって、はたらき方が 大きく 変わりました」"},{"t":"〜ないで","note":"Berarti \"tanpa melakukan ... (melainkan ...)\". Contoh: 「会社に 行かないで、家で 仕事を する」"},{"t":"Bentuk potensial (はたらける・えらべる)","note":"Menyatakan bisa melakukan sesuatu. Contoh: 「自由に はたらける」「自分に 合った はたらき方を えらべる」"},{"t":"〜ようだ","note":"Menyatakan dugaan berdasarkan keadaan: \"sepertinya ...\". Contoh: 「忘れて しまう 人も いるようです」"}]},"a-n1-9-n3":{"title":"住まいに残る人との距離","topic":"Budaya","trans":["Di rumah-rumah Jepang, cara menjaga jarak dengan orang lain yang tidak diucapkan secara jelas tersembunyi di banyak sudut. Misalnya, kebiasaan melepas sepatu di genkan (pintu masuk) menarik garis yang jelas antara \"luar\" dan \"dalam\". Gerakan melangkahi tepi lantai genkan bukan sekadar berpindah tempat, tetapi seperti ritual untuk mengganti suasana hati.","Sekat seperti fusuma (pintu geser kertas tebal) dan shoji (pintu geser kertas tipis) menarik karena tidak menutup ruangan sepenuhnya. Padahal hanya selembar tipis yang meneruskan suara dan keberadaan orang, ruangan tetap dianggap sudah terpisah. Ketidakjelasan ini mungkin adalah kearifan untuk hidup bersama orang lain di rumah yang sempit.","Bahkan sekarang, ketika rumah susun menjadi hunian utama, perasaan itu tetap ada dalam bentuk yang berbeda. Kita berhati-hati dengan suara aktivitas sehari-hari bukan semata karena dindingnya tipis. Hal ini dianggap terjadi karena tata krama sejak dulu untuk tidak melanggar wilayah satu sama lain masih berlanjut sampai sekarang.","Namun, rasa jarak seperti ini sulit dipahami oleh orang yang datang dari luar. Karena aturannya tidak tertulis, mereka sering bingung apakah perlu menyapa dan seberapa dekat boleh mendekat. Tetapi itu juga berarti takarannya diserahkan kepada masing-masing orang. Rumah mungkin adalah tempat di mana pertanyaan \"bagaimana mengukur jarak dengan orang lain\" diulang dengan tenang setiap hari."],"vocab":["genkan, pintu masuk","kebiasaan","ritual, upacara","sekat, pembatas ruangan","keberadaan, tanda-tanda","ambigu, tidak jelas","kearifan, kebijaksanaan","rumah susun, apartemen","wilayah, area","tata krama, aturan sopan santun"],"grammar":[{"t":"〜のようなもの","note":"Berarti \"semacam …\", dipakai untuk perumpamaan. Contoh: 「気持ちを切り替えるための儀式のようなものだ」 mengibaratkan gerakan melangkahi tepi lantai genkan sebagai sebuah ritual."},{"t":"〜ことにする","note":"Berarti menganggap sesuatu \"seolah-olah sudah …\", atau memutuskan untuk melakukan sesuatu. Di teks ini dipakai dalam arti \"dianggap sudah terpisah\". Contoh: 「それでも空間を分けたことにする」"},{"t":"〜わけではない","note":"Berarti \"bukan berarti …\", penyangkalan sebagian untuk menolak anggapan atau alasan yang umum. Contoh: 「壁が薄いからというわけではない」"},{"t":"〜ため(原因)","note":"Menyatakan sebab atau alasan, lebih formal daripada 「から」. Contoh: 「今も続いているためだと考えられる」"}]},"a-n1-9-n4":{"title":"住まいの中の距離感","topic":"Budaya","trans":["Di rumah Jepang, ada banyak cara menjaga jarak dengan orang lain yang tidak diucapkan. Kebiasaan melepas sepatu di genkan (pintu masuk) saja sudah punya garis pemisah antara luar dan dalam. Gerakan naik ke lantai dari genkan itu seperti ritual kecil untuk mengganti suasana hati.","Fusuma (pintu geser kertas tebal) dan shoji (pintu geser kertas tipis) meneruskan suara dan keberadaan orang, tetapi tetap memisahkan ruangan. Ketidakjelasan ini mungkin adalah kearifan untuk hidup bersama orang lain di rumah yang sempit. Sekarang memang banyak apartemen, tetapi perasaan itu tetap ada dalam bentuk yang berbeda. Berhati-hati dengan suara aktivitas sehari-hari juga merupakan tata krama untuk tidak memasuki wilayah satu sama lain.","Tetapi bagi orang yang datang dari luar negeri, rasa jarak ini sulit dipahami. Mereka bingung apakah perlu menyapa dan seberapa dekat boleh mendekat, karena tidak ada aturannya. Namun itu juga berarti setiap orang boleh memutuskan sendiri. Rumah mungkin adalah tempat untuk memikirkan jarak dengan orang lain dengan tenang setiap hari."],"vocab":["genkan, pintu masuk","kebiasaan","melepas sepatu","shoji (pintu geser kertas tipis)","kearifan, kebijaksanaan","perasaan, rasa","kehidupan sehari-hari","jarak","bingung, ragu","memutuskan"],"grammar":[{"t":"〜ようなものだ","note":"Berarti \"seperti …\", dipakai untuk perumpamaan. Contoh: 「気持ちを変える小さな儀式のようなものだ」"},{"t":"〜のに","note":"Berarti \"padahal …\" atau \"meskipun …\", menunjukkan adanya kontras antara bagian depan dan belakang. Contoh: 「音も人の様子も通すのに、部屋を分けてくれる」"},{"t":"〜にくい","note":"Dipasang setelah bentuk ます kata kerja (tanpa ます), berarti \"sulit …\". Contoh: 「この距離感は分かりにくい」"},{"t":"〜かもしれない","note":"Berarti \"mungkin …\", dugaan yang tidak terlalu pasti dari pembicara. Contoh: 「場所なのかもしれない」"}]},"a-n2-10-n3":{"title":"報告・連絡・相談を実際にやってみる","topic":"Dunia kerja","trans":["「報連相」sering dibicarakan di tempat kerja Jepang. Mengingatnya memang mudah, tapi praktiknya sulit. Karyawan asing terutama sering ragu: bolehkah melapor sebelum ada kesimpulan? Jawabannya langsung saja: boleh, kamu tetap bisa melapor meski belum ada kesimpulan.","Saat pekerjaan tidak berjalan sesuai harapan, justru itulah saatnya memberi tahu lebih awal. Sebab, yang ingin diketahui atasanmu bukan laporan yang sempurna, melainkan satu kalimat sebelum masalahnya membesar. Cukup bilang, \"Sekarang sudah sekitar setengah jalan, tapi masih menunggu materi, jadi sepertinya agak terlambat.\"","Saat berkonsultasi pun, tidak apa-apa kalau kamu belum punya jawaban. Konsultasi tidak selalu dilakukan untuk mendapatkan jawaban. Kalau kamu bisa menjelaskan di bagian mana kamu bingung, itu saja sudah menjadi konsultasi yang bagus.","Daripada sopan santun antara atasan dan bawahan, 「報連相」 lebih tepat disebut sistem untuk mencegah masalah dalam tim. Kalau kamu berpikir begitu, perasaanmu akan jauh lebih ringan."],"vocab":[{"w":"職場","m":"tempat kerja, lingkungan kerja"},{"w":"実際に","m":"sebenarnya, dalam praktik"},{"w":"結論","m":"kesimpulan"},{"w":"報告","m":"laporan, melapor"},{"w":"早め","m":"lebih awal, agak cepat"},{"w":"上司","m":"atasan"},{"w":"完璧","m":"sempurna"},{"w":"資料","m":"materi, dokumen"},{"w":"事故","m":"kecelakaan, insiden"},{"w":"仕組み","m":"sistem, mekanisme"}],"grammar":[{"t":"〜ように(様態・目標)","note":"Menyatakan \"sesuai dengan ～\" atau \"supaya ～\". Contoh: 「仕事が思うように進んでいないときほど」「そう考えるようにすれば」。"},{"t":"〜わけではない","note":"Berarti \"bukan berarti ～\", yaitu penyangkalan sebagian. Contoh: 「相談は、必ず答えをもらうために行くわけではないのです」。"},{"t":"〜というより","note":"Berarti \"daripada disebut ～, lebih tepat disebut …\". Contoh: 「上下関係のマナーというより、チームで事故を防ぐための仕組みです」。"},{"t":"〜ほど","note":"Berarti \"semakin ～, semakin …\", tingkatnya berubah sesuai kondisi. Contoh: 「進んでいないときほど、早めに伝えることが大切です」。"}]},"a-n2-10-n4":{"title":"報告・連絡・相談をやってみよう","topic":"Dunia kerja","trans":["Di perusahaan Jepang, orang sering memakai istilah 「報・連・相」. Mengingatnya mudah, tapi praktiknya sulit. Karyawan asing sering ragu, \"Kalau belum ada jawaban, boleh nggak ya aku bicara?\"","Tapi, tidak apa-apa meski belum ada jawaban. Kalau pekerjaan tidak berjalan sesuai harapan, sebaiknya kamu memberi tahu lebih awal. Yang ingin diketahui atasan bukan laporan yang sempurna, melainkan satu kalimat sebelum masalahnya membesar.","Misalnya, cukup bilang, \"Pekerjaan ini sekarang sudah selesai sekitar setengahnya. Tapi masih menunggu materi, jadi sepertinya agak terlambat.\" Saat berkonsultasi pun, kamu boleh datang meski belum punya jawaban. Kalau kamu bisa menceritakan di bagian mana kamu kesulitan, itu sudah jadi konsultasi. Kalau kamu menganggap 「報・連・相」 sebagai cara tim untuk mencegah kegagalan, perasaanmu akan jadi lebih ringan."],"vocab":[{"w":"会社","m":"perusahaan"},{"w":"社員","m":"karyawan"},{"w":"迷う","m":"ragu, bingung"},{"w":"答え","m":"jawaban"},{"w":"伝える","m":"menyampaikan, memberi tahu"},{"w":"上司","m":"atasan"},{"w":"問題","m":"masalah"},{"w":"資料","m":"materi, dokumen"},{"w":"遅れる","m":"terlambat, tertunda"},{"w":"困る","m":"kesulitan, repot"}],"grammar":[{"t":"〜ても大丈夫です","note":"Berarti \"tidak apa-apa meskipun ～\". Contoh: 「答えが出ていなくても大丈夫です」"},{"t":"〜たほうがいい","note":"Berarti \"sebaiknya ～\", dipakai untuk memberi saran. Contoh: 「早く伝えたほうがいいです」"},{"t":"〜そうだ(様態)","note":"Menyatakan dugaan berdasarkan keadaan sekarang: \"kelihatannya akan ～\". Contoh: 「少し遅れそうです」"},{"t":"〜と考えると","note":"Berarti \"kalau dianggap sebagai ～\", diikuti hasilnya. Contoh: 「防ぐための方法だと考えると、気持ちが楽になります」"}]},"a-n2-2-n3":{"title":"「空気を読む」ということ","topic":"Budaya","trans":["Dalam bahasa Jepang ada ungkapan 「空気を読む」 (membaca suasana) yang sering dipakai. Artinya, memikirkan suasana saat itu dan perasaan lawan bicara, lalu bertindak dengan tepat meskipun tidak diminta secara langsung. Misalnya, saat semua orang di rapat setuju, butuh keberanian untuk menjadi satu-satunya orang yang menolak. Karena itu, banyak orang memilih membaca suasana dan sengaja tidak mengatakan apa-apa.","Cara berpikir ini selama ini berguna untuk menghindari benturan antarorang dan menjaga keharmonisan bersama. Namun di sisi lain, ada kalanya pendapat yang benar-benar diperlukan jadi tidak bisa disampaikan. Selain itu, ada juga masalah suara orang-orang yang jumlahnya sedikit jadi hilang.","Kemampuan membaca suasana memang bisa dibilang salah satu ciri masyarakat Jepang. Tapi, bukankah keberanian untuk menyampaikan pendapat sendiri tanpa membaca suasana juga seharusnya dihargai pada saat tertentu?","Membaca suasana kadang juga menjadi bentuk kelembutan yang peduli pada orang lain. Namun, kalau sudah kelewatan, kita jadi tidak bisa menyampaikan pendapat sendiri. Yang penting adalah keseimbangan antara menyesuaikan diri dengan sekitar dan menyampaikan pikiran sendiri."],"vocab":["suasana","setuju","menentang, tidak setuju","keberanian","sengaja, dengan berani","keharmonisan","berguna, membantu","minoritas, jumlah kecil","ciri khas","peduli, memikirkan orang lain"],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan sendiri untuk melakukan sesuatu. Contoh di teks: 「あえて何も言わないことにする」, artinya sengaja memilih untuk tidak berkata apa-apa."},{"t":"〜ないように","note":"Menyatakan tujuan agar suatu keadaan tidak terjadi. Contoh di teks: 「人がぶつからないように」, artinya agar orang tidak saling berbenturan."},{"t":"〜ために","note":"Menyatakan tujuan, artinya \"demi/untuk ~\". Contoh di teks: 「みんなの調和を守るために役に立ってきた」."},{"t":"〜てしまう","note":"Menyatakan hasil yang tidak diharapkan atau tindakan yang sudah selesai. Contoh di teks: 「自分の意見が言えなくなってしまう」, yang membawa nuansa penyesalan."}]},"a-n2-2-n4":{"title":"「空気を読む」ってなに?","topic":"Budaya","trans":["Dalam bahasa Jepang ada ungkapan 「空気を読む」 (membaca suasana). Artinya, memikirkan situasi saat itu dan perasaan lawan bicara, lalu bertindak. Meskipun tidak dikatakan dengan jelas, kita tahu apa yang sebaiknya dilakukan.","Misalnya, anggap saja semua orang di rapat setuju. Saat itu, butuh keberanian untuk menjadi satu-satunya orang yang bilang tidak setuju. Karena itu, banyak orang \"membaca suasana\" dan tidak mengatakan apa-apa. Perasaan seperti ini selama ini berguna untuk menghindari pertengkaran dengan orang lain.","Tapi, ada juga kalanya pendapat yang benar-benar diperlukan jadi tidak bisa disampaikan. Ada juga kalanya suara orang-orang yang jumlahnya sedikit tidak terdengar. Menurutku, kadang keberanian untuk berbicara tanpa membaca suasana juga penting. Yang penting adalah keseimbangan antara menyesuaikan diri dengan sekitar dan menyampaikan pikiran sendiri."],"vocab":["udara; suasana","perasaan","rapat","setuju","menentang, tidak setuju","keberanian","pendapat","penting, berharga","menyesuaikan, menyamakan"],"grammar":[{"t":"〜なくても","note":"Menyatakan \"meskipun tidak ~\". Contoh: 「はっきり言われなくても、何をしたらいいか分かる」 artinya kita tahu harus berbuat apa meskipun tidak dikatakan dengan jelas."},{"t":"〜たらいいか","note":"Bentuk た pada kata kerja + ら, dipakai untuk bertanya \"sebaiknya bagaimana\". Contoh: 「何をしたらいいか分かる」."},{"t":"〜ために","note":"Menyatakan tujuan, \"demi/untuk ~\". Contoh: 「人とけんかしないために役に立ってきました」."},{"t":"Bentuk potensial (言えなくなる)","note":"Kata kerja bentuk potensial + なくなる, menyatakan menjadi tidak bisa melakukan sesuatu. Contoh: 「必要な意見が言えなくなる」."}]},"a-n2-4-n3":{"title":"Memikirkan Dampak Buruk Overtourism","topic":"Wisata","trans":["Beberapa tahun terakhir, tempat wisata populer didatangi banyak wisatawan, bukan hanya dari dalam negeri, tetapi juga dari luar negeri. Pariwisata memang membawa keuntungan besar bagi daerah, tetapi juga memunculkan masalah yang disebut 「観光公害」 (dampak buruk overtourism).","Misalnya, jalan penuh sesak oleh wisatawan sehingga warga kadang tidak bisa lewat. Selain itu, muncul juga masalah seperti sampah yang bertambah dan makin banyak orang yang tidak menaati sopan santun. Akibatnya, orang-orang yang dulu hidup tenang kini tidak bisa lagi menjalani hidup dengan nyaman.","Menghadapi masalah-masalah ini, ada daerah yang mulai menetapkan batas jumlah pengunjung yang boleh masuk dan menerapkan pajak wisata. Namun, kalau aturannya terlalu ketat, ada risiko daya tarik wisata itu sendiri justru hilang. Kita harus memikirkan dua hal sekaligus: menyelesaikan masalah dan menjaga agar tempat itu tetap menyenangkan untuk dikunjungi.","Yang penting, bukankah para pengunjung seharusnya tidak melupakan rasa hormat kepada penduduk setempat? Kalau budaya dan aturan di tempat itu dihargai, pariwisata seharusnya bisa menjadi hal yang berharga bagi wisatawan maupun warga. Yang dibutuhkan sekarang adalah sistem yang membuat pengunjung dan penduduk sama-sama nyaman."],"vocab":["「観光公害」 (dampak buruk overtourism)","keuntungan","daerah, wilayah","warga, penduduk","masuk (ke tempat)","daya tarik","ketat, keras","penyelesaian, menyelesaikan","rasa hormat","mengunjungi"],"grammar":[{"t":"〜だけでなく〜も","note":"Berarti \"bukan hanya ..., tetapi juga ...\". Contoh: 「国内だけでなく外国からも多くの旅行者が集まっている」."},{"t":"〜たり〜たりする","note":"Menyebutkan beberapa contoh tindakan atau keadaan. Contoh: 「ゴミが増えたり、マナーを守らない人が増えたりする」."},{"t":"〜おそれがある","note":"Menyatakan adanya kemungkinan terjadi hal buruk. Contoh: 「魅力がなくなってしまうおそれもある」."},{"t":"〜はずだ","note":"Menyatakan dugaan berdasarkan alasan yang masuk akal, \"seharusnya ...\". Contoh: 「豊かなものになるはずだ」."}]},"a-n2-4-n4":{"title":"Memikirkan Dampak Buruk Overtourism","topic":"Wisata","trans":["Tempat wisata populer didatangi banyak wisatawan dari dalam dan luar negeri. Uang masuk ke daerah, tetapi muncul juga masalah yang disebut 「観光公害」 (dampak buruk overtourism).","Misalnya, jalan penuh sesak oleh wisatawan sehingga warga tidak bisa lewat. Sampah bertambah dan orang yang tidak menaati sopan santun juga makin banyak. Kehidupan orang-orang yang dulu tinggal dengan tenang pun jadi memburuk.","Karena itu, ada daerah yang membatasi jumlah orang yang boleh masuk dan membuat pajak wisata. Tapi, kalau aturannya terlalu ketat, daya tarik wisata bisa saja hilang. Yang penting, wisatawan tidak melupakan rasa hormat kepada penduduk setempat. Kalau budaya dan aturan di tempat itu dihargai, semua orang bisa merasa nyaman."],"vocab":["tempat wisata","wisatawan","daerah, wilayah","masalah","warga, penduduk","menaati, menjaga","kehidupan","ketat, keras","penting, menghargai","lupa"],"grammar":[{"t":"〜たり〜たりする","note":"Menyebutkan beberapa contoh tindakan atau keadaan. Contoh: 「ゴミが増えたり、マナーを守らない人が増えたりします」"},{"t":"〜なくなる(可能形+ない+なる)","note":"Bentuk potensial negatif + 「なる」, berarti jadi tidak bisa melakukan sesuatu. Contoh: 「住民が通れなくなります」"},{"t":"〜すぎる","note":"Bentuk ます tanpa ます + すぎる, berarti melakukan sesuatu secara berlebihan. Contoh: 「ルールを厳しくしすぎると」"},{"t":"〜かもしれない","note":"Menyatakan kemungkinan, tetapi belum pasti. Contoh: 「観光の魅力がなくなるかもしれません」"}]},"a-n2-3-n3":{"title":"Lapor, Kabari, Konsultasi","topic":"Dunia Kerja","trans":["Begitu masuk perusahaan Jepang, hal pertama yang sering diajarkan adalah pentingnya 「報連相」. Ini adalah istilah yang diambil dari huruf pertama 「報告」「連絡」「相談」. Konon, ini adalah pola pikir yang sangat penting untuk memahami cara kerja orang Jepang.","Pertama-tama, penting untuk 「melapor」 kepada atasan sejauh mana pekerjaanmu sudah berjalan. Kepada orang-orang yang terkait, kamu perlu 「mengabari」 informasi yang dibutuhkan, dan saat bingung harus berbuat apa, segera 「berkonsultasi」. Hasil pekerjaan bisa sangat berbeda tergantung apakah kamu bisa melakukan hal-hal ini atau tidak.","Kalau kamu memendam masalah sendirian dan laporanmu terlambat, kesalahan kecil pun bisa berubah jadi masalah besar. Sebaliknya, kalau kamu rajin berbagi informasi, orang-orang di sekitarmu bisa cepat membantu. Di tempat kerja yang 報連相-nya tidak berjalan baik, kesalahan kecil mudah sekali menjadi masalah besar.","報連相 bukan sekadar aturan. Saat bekerja dalam tim, ini adalah komunikasi dasar yang dibutuhkan agar saling percaya. Rajin berbagi informasi tentunya akan meningkatkan kepercayaan dan efisiensi seluruh tim."],"vocab":["atasan","laporan, melapor","kabar, memberi tahu","konsultasi, berkonsultasi","bingung, ragu","memikul sendiri, memendam","berbagi","tempat kerja","kepercayaan","efisiensi"],"grammar":[{"t":"〜によって","note":"Artinya \"tergantung pada\" atau \"bergantung pada\". Contoh: 「これができるかどうかによって」, artinya hasilnya berbeda tergantung bisa atau tidaknya melakukan hal ini."},{"t":"〜わけではない","note":"Artinya \"bukan berarti ...\". Dipakai untuk menyangkal sebagian atau meluruskan salah paham. Contoh: 「ただのルールというわけではない」."},{"t":"〜ことがある/〜こともある","note":"Artinya \"kadang ...\" atau \"bisa saja ...\". Contoh: 「大きなトラブルになることもある」."},{"t":"〜てくれる","note":"Menunjukkan bahwa tindakan orang lain memberi manfaat bagi kita atau orang terkait. Contoh: 「信頼と効率を高めてくれるだろう」."}]},"a-n2-3-n4":{"title":"Lapor, Kabari, Konsultasi","topic":"Dunia Kerja","trans":["Begitu masuk perusahaan Jepang, hal pertama yang diajarkan kepadamu adalah pentingnya 「報連相」. Ini adalah istilah yang diambil dari huruf pertama 「報告」「連絡」「相談」.","Menyampaikan kondisi pekerjaan kepada atasan disebut 「報告」. Memberi tahu hal yang perlu kepada orang yang terkait disebut 「連絡」. Saat tidak tahu harus berbuat apa, segera bertanya disebut 「相談」. Hasil pekerjaan bisa sangat berbeda tergantung apakah kamu bisa melakukan hal-hal ini atau tidak.","Kalau kamu bingung sendirian dan laporanmu terlambat, kesalahan kecil mudah berubah jadi masalah besar. Sebaliknya, kalau kamu sering berbagi informasi, orang-orang di sekitarmu bisa cepat membantu. 報連相 bukan sekadar aturan. Saat bekerja dalam tim, ini adalah komunikasi penting agar saling percaya."],"vocab":["penting, berharga","laporan, melapor","kabar, memberi tahu","konsultasi, berkonsultasi","atasan","hubungan, terkait","terlambat, tertunda","informasi","berbagi","percaya, memercayai"],"grammar":[{"t":"〜と(syarat)","note":"Artinya \"begitu ... maka ...\" atau \"kalau ... maka ...\", menjelaskan hasil alami atau kebiasaan. Contoh: 「日本の会社に入ると、最初に「報連相」の大切さを教えてもらいます」、「報告が遅れると、小さなミスが大きな問題になりやすいです」."},{"t":"〜かどうか","note":"Artinya \"apakah ... atau tidak\", dipakai untuk memasukkan pertanyaan ya/tidak ke dalam kalimat. Contoh: 「これができるかどうかで、仕事の結果が大きく変わります」."},{"t":"〜やすい","note":"Dipasang setelah bentuk ます verba (tanpa ます), artinya \"mudah ...\" atau \"cenderung ...\". Contoh: 「小さなミスが大きな問題になりやすいです」."},{"t":"〜ば(syarat)/〜ための","note":"「〜ば」artinya \"kalau ... maka ...\", 「〜ための」artinya \"untuk ...\" atau \"demi ...\". Contoh: 「よく情報を共有すれば、まわりの人が早く助けられます」、「おたがいを信じるための大切なコミュニケーション」."}]},"a-n2-6-n3":{"title":"Hargai Tidurmu","topic":"Kesehatan","trans":["Kalau menjalani hari-hari yang sibuk, kita sering tanpa sadar memangkas waktu tidur lebih dulu. Padahal, tidur yang berkualitas adalah hal yang sangat penting untuk menjalani hidup sehat.","Kalau kurang tidur, konsentrasi bisa menurun dan kondisi tubuh pun bisa memburuk. Pasti tidak sedikit orang yang pekerjaan atau belajarnya jadi tidak lancar karena mengantuk di siang hari.","Supaya bisa tidur nyenyak, hal pertama yang penting adalah mengatur ritme hidup. Usahakan tidur dan bangun pada jam yang sama setiap hari. Selain itu, sebaiknya hindari melihat ponsel sebelum tidur sebisa mungkin. Sebab, cahaya terang dari layar membuat otak jadi terjaga.","Meski hanya selisih beberapa jam, kalau dilakukan setiap hari, hasilnya bisa jadi perbedaan besar. Bagaimana kalau mulai dari naik ke kasur sedikit lebih awal?"],"vocab":["tidur","memangkas, mengurangi (waktu, dll.)","kualitas","konsentrasi, daya fokus","kondisi, keadaan","rasa kantuk","mengatur, merapikan","berusaha memperhatikan, mengusahakan","otak","futon, kasur lipat Jepang"],"grammar":[{"t":"〜がちだ","note":"Menunjukkan kecenderungan mudah terjadinya sesuatu (biasanya yang kurang baik). Contoh: 「ついいちばん先に睡眠の時間を削ってしまいがちです」"},{"t":"〜のせいで","note":"Menunjukkan bahwa suatu sebab menyebabkan hasil yang buruk. Contoh: 「昼間の眠気のせいで、仕事や勉強がうまくいかない人も少なくないでしょう」"},{"t":"〜ように心がける","note":"Menunjukkan usaha untuk memperhatikan atau sebisa mungkin melakukan sesuatu. Contoh: 「毎日同じ時間に寝て、同じ時間に起きるように心がけましょう」"},{"t":"〜によって","note":"Menunjukkan sebab atau cara, menjelaskan pengaruh yang ditimbulkan sesuatu. Contoh: 「画面の明るい光によって、脳が目を覚ましてしまうからです」"}]},"a-n2-6-n4":{"title":"Hargai Waktu Tidurmu","topic":"Kesehatan","trans":["Kalau sedang sibuk, kita sering tanpa sadar mengurangi waktu tidur. Padahal tidur yang cukup itu penting supaya kita bisa hidup dengan sehat.","Kalau waktu tidur kurang, kita jadi tidak bisa berkonsentrasi. Kondisi tubuh juga bisa memburuk. Pasti banyak orang yang tidak bisa bekerja atau belajar karena mengantuk di siang hari.","Supaya bisa tidur nyenyak, hal pertama yang penting adalah membuat ritme hidup harian. Yuk, usahakan tidur dan bangun pada jam yang sama setiap hari. Sebaiknya jangan melihat ponsel sebelum tidur. Sebab, cahaya terang dari layar membuat otak jadi terjaga. Meski perbedaannya kecil, kalau dilakukan setiap hari, hasilnya bisa jadi selisih yang besar. Pertama-tama, coba mulai dengan naik ke kasur lebih awal."],"vocab":["sibuk","mengurangi","sehat, bersemangat","penting","konsentrasi, fokus","kondisi, keadaan","mengantuk","hidup, kehidupan sehari-hari","perbedaan","futon, kasur lipat Jepang"],"grammar":[{"t":"〜てしまう","note":"Menunjukkan bahwa sesuatu tidak sengaja dilakukan, atau hasilnya tidak diinginkan. Contoh: 「つい寝る時間を減らしてしまいます」「頭が起きてしまうからです」"},{"t":"〜ないと","note":"Artinya \"kalau tidak ..., maka ...\", menunjukkan syarat dan akibat. Contoh: 「寝る時間が足りないと、集中できなくなります」"},{"t":"〜ようにする","note":"Menunjukkan usaha untuk membiasakan diri atau sebisa mungkin melakukan sesuatu. Contoh: 「同じ時間に起きるようにしましょう」"},{"t":"〜たほうがいい","note":"Artinya \"sebaiknya ...\", dipakai untuk memberi saran. Contoh: 「見るのは、やめたほうがいいです」"}]},"a-n2-8-n3":{"title":"地方移住という選択","topic":"Masyarakat","trans":["Konon belakangan ini semakin banyak orang yang meninggalkan kota dan pindah ke daerah pedesaan. Salah satu alasan utamanya adalah kerja jarak jauh yang semakin meluas. Sekarang banyak orang bisa bekerja di mana pun mereka tinggal.","Sewa rumah di daerah pedesaan kurang dari separuh harga di kota, dan kita juga tidak perlu berdesakan saat jam sibuk berangkat kerja. Hidup dikelilingi alam tentu terlihat sangat menarik. Karena itu, sepertinya ada juga orang yang mulai serius memikirkan untuk pindah.","Namun, pindah ke daerah itu sama sekali bukan hal yang mudah. Banyak daerah yang tidak bisa ditinggali tanpa kendaraan, dan kadang terasa kurang praktis dari segi layanan kesehatan dan pendidikan. Selain itu, bisa atau tidaknya kita berbaur dengan baik dalam hubungan antarwarga setempat juga disebut-sebut sebagai tantangan besar. Mungkin ada juga orang yang bingung menghadapi kebiasaan dan cara bergaul yang berbeda dari kota.","Yang penting adalah jangan memutuskan hanya berdasarkan impian ideal. Sebaiknya kamu datang langsung ke tempat itu beberapa kali dan melihat sendiri seperti apa kehidupan di sana. Dengan begitu, bukankah kegagalan setelah pindah bisa dikurangi?"],"vocab":[{"w":"移住","m":"pindah (menetap di tempat lain)"},{"w":"広まる","m":"meluas, menyebar"},{"w":"家賃","m":"uang sewa rumah"},{"w":"魅力的","m":"menarik, memikat"},{"w":"地域","m":"daerah, wilayah"},{"w":"不便","m":"tidak praktis, kurang nyaman"},{"w":"溶け込む","m":"berbaur, membaur"},{"w":"課題","m":"tantangan, masalah yang harus diselesaikan"},{"w":"足を運ぶ","m":"datang langsung, mengunjungi"},{"w":"確かめる","m":"memastikan, memeriksa"}],"grammar":[{"t":"〜ようになる","note":"Menyatakan perubahan kemampuan atau keadaan: dulu tidak bisa, sekarang jadi bisa. Contoh: 「どこに住んでいても仕事ができるようになった人が多いのである」"},{"t":"〜かどうか","note":"Berarti \"apakah ~ atau tidak\", menyisipkan kalimat tanya ke dalam kalimat. Contoh: 「地域の人間関係にうまく溶け込めるかどうかも、大きな課題だと言われている」"},{"t":"〜と言われている","note":"Berarti \"katanya ~ / dikatakan bahwa ~\", dipakai untuk menyampaikan pendapat umum di masyarakat secara objektif. Contoh: 「大きな課題だと言われている」"},{"t":"〜のではないだろうか","note":"Cara halus menyampaikan pendapat pribadi: \"bukankah ~?\" atau \"mungkin ~\". Contoh: 「移住してからの失敗を減らせるのではないだろうか」"}]},"a-n2-8-n4":{"title":"いなかで暮らすという選択","topic":"Masyarakat","trans":["Katanya belakangan ini semakin banyak orang yang keluar dari kota besar dan pindah ke desa. Soalnya sekarang kita bisa bekerja lewat internet, jadi bisa bekerja di mana pun kita tinggal.","Sewa rumah di desa murah, dan kereta di pagi hari juga tidak penuh sesak. Dekat dengan gunung dan laut, serta bisa hidup di tengah alam yang indah, juga menjadi alasan kenapa desa disukai.","Tapi, pindah rumah itu tidak mudah. Banyak tempat yang tidak bisa ditinggali tanpa mobil, dan kadang rumah sakit atau sekolah yang jauh juga menyusahkan.","Selain itu, katanya bisa akrab atau tidak dengan tetangga juga masalah yang penting. Jadi, sebaiknya jangan memutuskan hanya berdasarkan impian ideal. Menurutku, sebaiknya kamu datang ke kota itu beberapa kali dan melihat sendiri kehidupan seperti apa yang bisa dijalani di sana."],"vocab":[{"w":"引っ越す","m":"pindah rumah"},{"w":"増える","m":"bertambah"},{"w":"働く","m":"bekerja"},{"w":"家賃","m":"uang sewa rumah"},{"w":"込む","m":"penuh sesak"},{"w":"自然","m":"alam"},{"w":"理由","m":"alasan"},{"w":"病院","m":"rumah sakit"},{"w":"近所","m":"tetangga, sekitar rumah"},{"w":"理想","m":"impian ideal, cita-cita"}],"grammar":[{"t":"〜そうだ(傳聞)","note":"Menyatakan kabar yang didengar dari orang lain (katanya ~). Contoh: 「いなかに引っ越す人が増えているそうだ」"},{"t":"〜ので","note":"Menyatakan sebab atau alasan. Contoh: 「インターネットで仕事ができるようになったので、どこに住んでも働ける」"},{"t":"可能形","note":"Menyatakan bisa melakukan sesuatu. Contoh: 「きれいな自然の中で暮らせる」"},{"t":"〜ないと〜ない/〜ほうがいい","note":"「車がないと生活できない」berarti tanpa itu tidak bisa; 「決めないほうがいい」berarti saran: sebaiknya jangan dilakukan"}]},"a-n2-9-n3":{"title":"Perpanjangan Status Tinggal, Gerbang yang Harus Dilewati","topic":"Masyarakat","trans":["Bagi orang asing yang tinggal di Jepang, perpanjangan status tinggal (在留資格) adalah gerbang penting yang pasti harus dilewati. Pengajuan perpanjangan bisa dilakukan mulai tiga bulan sebelum masa tinggal berakhir. Tapi karena menyiapkan dokumen butuh waktu, sebaiknya kamu bergerak secepat mungkin.","Selain formulir pengajuan, dokumen yang dibutuhkan antara lain surat keterangan pajak penduduk, bukti pembayaran pajak, dan surat keterangan kerja. Orang yang baru saja pindah kerja kadang diminta menyerahkan kontrak kerja. Dalam pemeriksaan, yang dilihat adalah apakah penghasilanmu stabil dan apakah pajak serta dana pensiun sudah dibayar dengan benar.","Artinya, bagi orang yang selama ini menunda-nunda urusan administrasi sehari-hari, masalah-masalah itu akan muncul sekaligus pada saat ini. Loket kantor imigrasi sangat ramai, sehingga makin banyak orang yang mengajukan secara online. Karena itu, alur prosedurnya pun perlahan-lahan ikut berubah.","Selama beberapa minggu sebelum hasilnya keluar, perasaanmu mungkin jadi gelisah. Tapi kalau kamu melengkapi dokumen yang diperlukan dan melapor dengan jujur, tidak perlu terlalu khawatir."],"vocab":[{"w":"在留資格","m":"status tinggal (izin tinggal di Jepang)"},{"w":"更新","m":"pembaruan, perpanjangan"},{"w":"関門","m":"gerbang, rintangan"},{"w":"申請","m":"pengajuan, permohonan"},{"w":"書類","m":"dokumen, berkas"},{"w":"審査","m":"pemeriksaan, seleksi"},{"w":"収入","m":"penghasilan"},{"w":"後回し","m":"menunda, mengesampingkan dulu"},{"w":"窓口","m":"loket"},{"w":"申告","m":"pelaporan, deklarasi"}],"grammar":[{"t":"〜ため","note":"Menyatakan sebab atau alasan, lebih formal/tertulis daripada「から」. Contoh:「書類の準備には時間がかかるため、できるだけ早く動いたほうがいいです」"},{"t":"〜たばかり","note":"Menyatakan baru saja selesai melakukan sesuatu. Contoh:「転職したばかりの人は、雇用契約書を出すように言われることもあります」"},{"t":"〜ように言われる","note":"Menyatakan diminta atau disuruh melakukan sesuatu. Contoh:「雇用契約書を出すように言われることもあります」"},{"t":"〜わけだ","note":"Menyatakan kesimpulan yang wajar, \"jadi begitulah…\" atau \"artinya…\". Contoh:「その問題がこの時期に一度に出てくるわけです」"}]},"a-n2-9-n4":{"title":"Perpanjangan Status Tinggal","topic":"Masyarakat","trans":["Orang asing yang tinggal di Jepang harus memperpanjang status tinggalnya (在留資格). Pengajuan bisa dilakukan mulai tiga bulan sebelum batas waktunya. Karena menyiapkan dokumen butuh waktu, sebaiknya mulai lebih awal.","Dokumen yang dibutuhkan antara lain formulir pengajuan, surat keterangan pajak penduduk, bukti pembayaran pajak, surat keterangan dari perusahaan, dan sebagainya. Orang yang baru saja ganti pekerjaan mungkin juga memerlukan dokumen kontrak kerja.","Dalam pemeriksaan, yang dilihat adalah apakah penghasilanmu stabil. Mereka juga melihat apakah pajak dan dana pensiun sudah dibayar dengan benar. Kalau kamu selalu membiarkan urusan administrasi tidak diurus, sepertinya kamu akan kesulitan saat perpanjangan. Loket kantor imigrasi dipenuhi banyak orang, jadi makin banyak yang mengajukan lewat internet. Sebelum hasilnya keluar memang bikin cemas, tapi kalau dokumennya lengkap dan kamu menulis dengan jujur, tidak perlu terlalu khawatir."],"vocab":[{"w":"在留資格","m":"status tinggal (izin tinggal)"},{"w":"更新","m":"pembaruan, perpanjangan"},{"w":"期限","m":"batas waktu"},{"w":"申請","m":"pengajuan, permohonan"},{"w":"書類","m":"dokumen"},{"w":"証明書","m":"surat keterangan"},{"w":"収入","m":"penghasilan"},{"w":"安定","m":"stabil"},{"w":"窓口","m":"loket"},{"w":"そろえる","m":"melengkapi, menyiapkan sampai lengkap"}],"grammar":[{"t":"〜なければなりません","note":"Menyatakan \"harus\". Contoh:「在留資格を更新しなければなりません」"},{"t":"〜たほうがいい","note":"Menyatakan \"sebaiknya melakukan ~\", dipakai untuk memberi saran. Contoh:「早めに始めたほうがいいです」"},{"t":"〜そうだ","note":"Menyatakan dugaan berdasarkan keadaan, \"sepertinya akan ~\". Contoh:「更新のときに困りそうです」"},{"t":"〜ば(bentuk pengandaian)","note":"Menyatakan \"kalau ~\". Contoh:「書類をそろえて本当のことを書けば、あまり心配しなくてもいいです」"}]},"a-n3-10-n2":{"title":"Yang Diajarkan Aturan Membuang Sampah kepada Kita","topic":"Kehidupan","trans":["Hal pertama yang membuatku bingung saat mulai tinggal di Jepang adalah cara memilah sampah yang aturannya jauh lebih rinci daripada yang kubayangkan. Kategori seperti sampah yang bisa dibakar, sampah yang tidak bisa dibakar, dan sampah daur ulang, standar maupun hari pengambilannya berbeda-beda di tiap distrik. Karena itu, setelah pindah rumah, sebaiknya kamu lebih dulu membaca daftar panduan yang bisa didapat di kantor pemerintah kota (市役所).","Saat membuang botol PET, aturan dasarnya adalah melepas label dan tutupnya, lalu membilas bagian dalamnya sebentar sebelum dibuang. Jujur saja, ini terasa merepotkan, tetapi katanya langkah kecil itulah yang menentukan apakah botol bisa didaur ulang atau tidak. Waktu membuangnya juga ada aturannya, di banyak daerah paling lambat pukul delapan pagi pada hari pengambilan. Kalau dibuang pada malam sebelumnya, ada kemungkinan sampah diacak-acak gagak, jadi membuang lebih awal belum tentu aman.","Untuk sampah berukuran besar, dibutuhkan lebih banyak prosedur daripada sampah biasa, dan mau tidak mau kamu harus mendaftar lebih dulu lewat telepon atau internet. Setelah mendaftar, alurnya adalah membeli stiker di minimarket lalu menempelkannya. Katanya, tidak sedikit orang yang tidak tahu sistem ini, langsung meletakkan begitu saja, lalu ditegur. Bagi orang yang datang dari luar negeri, selain hambatan bahasa, kesepakatan tidak tertulis seperti ini juga bisa menjadi beban.","Awalnya aku merasa aturannya terlalu rumit, tetapi seiring waktu tinggal di sini, semuanya menjadi kebiasaan dengan sendirinya. Membuang sampah setiap hari bukan sekadar pekerjaan rutin, tetapi juga tindakan yang menunjukkan perhatian kepada orang-orang di sekitar. Cara membuang sampah mungkin adalah \"aturan bersama\" pertama untuk hidup di suatu daerah."],"vocab":[{"w":"戸惑う","m":"bingung, kebingungan"},{"w":"基準","m":"standar, patokan"},{"w":"実情","m":"keadaan sebenarnya"},{"w":"目を通す","m":"melihat sekilas, membaca sepintas"},{"w":"すすぐ","m":"membilas"},{"w":"再利用","m":"penggunaan kembali, daur ulang"},{"w":"荒らす","m":"mengacak-acak, merusak"},{"w":"粗大ゴミ","m":"sampah berukuran besar"},{"w":"暗黙の了解","m":"kesepakatan tidak tertulis"},{"w":"配慮","m":"perhatian, pertimbangan"}],"grammar":[{"t":"〜に越したことはない","note":"Artinya \"lebih baik/sebaiknya melakukan ~\", dengan nada menyarankan. Contoh: 「市役所でもらえる一覧表に目を通しておくに越したことはない」"},{"t":"〜ざるを得ない","note":"Artinya \"mau tidak mau harus ~\", tidak ada pilihan lain. Contoh: 「事前に電話やネットで申し込まざるを得ない」"},{"t":"〜とは限らない","note":"Artinya \"belum tentu ~\", untuk menyangkal pernyataan yang mutlak. Contoh: 「早めに出せば安心とは限らない」"},{"t":"〜にとどまらず","note":"Artinya \"tidak hanya terbatas pada ~, tetapi juga lebih dari itu\". Contoh: 「単なる作業にとどまらず、地域の人々への配慮を示す行為でもある」"}]},"a-n3-10-n4":{"title":"Aturan Cara Membuang Sampah","topic":"Kehidupan","trans":["Setelah mulai tinggal di Jepang, hal pertama yang membuatku kesulitan adalah cara memilah sampah.","Ada sampah yang bisa dibakar, sampah yang tidak bisa dibakar, dan sampah daur ulang. Cara memilah dan hari pengambilannya berbeda-beda di tiap distrik tempat tinggal. Setelah pindah rumah, sebaiknya kamu melihat tabel yang bisa didapat di kantor pemerintah kota (市役所).","Botol PET dibuang setelah label dan tutupnya dilepas, lalu bagian dalamnya dibilas sedikit. Kelihatannya merepotkan, tetapi katanya langkah kecil ini menentukan apakah botol bisa dipakai lagi atau tidak.","Waktu membuang sampah juga sudah ditentukan, di banyak daerah paling lambat pukul delapan pagi pada hari itu. Soalnya kalau dibuang pada malam sebelumnya, gagak bisa membuat sampah berserakan.","Sampah besar harus didaftarkan lebih dulu lewat telepon atau internet. Lalu beli stiker di minimarket dan tempelkan pada sampahnya.","Tidak sedikit orang yang membuang sampah tanpa tahu aturan ini lalu ditegur.","Awalnya kupikir aturannya terlalu rumit, tetapi lama-lama aku terbiasa.","Cara membuang sampah mungkin adalah aturan bersama pertama untuk hidup di kota itu."],"vocab":[{"w":"困る","m":"kesulitan, bingung"},{"w":"分け方","m":"cara memilah"},{"w":"回収","m":"pengambilan, pengumpulan"},{"w":"引っ越す","m":"pindah rumah"},{"w":"洗う","m":"mencuci"},{"w":"面倒","m":"merepotkan"},{"w":"決まる","m":"ditentukan, diputuskan"},{"w":"申し込む","m":"mendaftar, mengajukan"},{"w":"注意する","m":"menegur, memperingatkan"},{"w":"慣れる","m":"terbiasa"}],"grammar":[{"t":"〜たら","note":"Artinya \"kalau/setelah melakukan ...\". Contoh: 「引っ越したら、市役所でもらえる表を見たほうがいいです」"},{"t":"〜たほうがいい","note":"Artinya \"sebaiknya ...\", dipakai untuk memberi saran. Contoh: 「市役所でもらえる表を見たほうがいいです」"},{"t":"〜そうだ(tampak/kabarnya)","note":"「面倒そうです」berarti tampaknya; 「決まるそうです」berarti katanya. Contoh: 「このひと手間で、もう一度使えるかどうかが決まるそうです」"},{"t":"〜ので/〜からです(alasan)","note":"Menjelaskan alasan. Contoh: 「前の晩に出すと、カラスがゴミを散らかすことがあるからです」"}]},"a-n3-11-n2":{"title":"Pentingnya Hou-Ren-Sou (報連相)","topic":"Dunia Kerja","trans":["Saat bekerja di perusahaan Jepang, konsep 「報連相」 banyak disebut sebagai hal yang sangat penting. Ini adalah singkatan yang dibuat dengan mengambil huruf pertama dari tiga kata, yaitu 「報告」「連絡」「相談」 (melapor, menghubungi, dan berkonsultasi). Sekilas tampak seperti kebiasaan sederhana, tetapi ciri khasnya adalah posisinya sebagai fondasi agar pekerjaan berjalan lancar.","Pertama, 報告 (laporan) berarti menyampaikan perkembangan pekerjaan kepada atasan. Terutama saat terjadi masalah, kamu diminta untuk tidak menundanya dan segera melapor. Berikutnya, 連絡 (kabar/informasi) adalah tindakan menyampaikan informasi yang diperlukan dalam pekerjaan kepada orang-orang terkait. Misalnya, ketika jadwal berubah, memberi kabar secepat mungkin sangat dihargai. Yang terakhir, 相談 (konsultasi) adalah meminta pendapat atasan atau rekan kerja tentang hal yang tidak bisa kamu putuskan sendiri. Meskipun hanya hal sepele, kalau kamu berkonsultasi lebih awal, kegagalan besar bisa dicegah sebelum terjadi.","Bagi karyawan asing, kebiasaan 報連相 ini mungkin terasa membebani pada awalnya. Di negara sendiri, kadang sikap mengambil keputusan dan bergerak sendiri justru dihargai, jadi wajar saja kalau ada yang bingung. Melanjutkan pekerjaan tanpa berkonsultasi dengan orang sekitar belum tentu membawa hasil yang baik di Jepang.","Namun, kalau kamu menjalankan 報連相 dengan benar, ada keuntungan berupa lebih mudah mendapatkan kepercayaan di dalam tim. Kalau kamu bekerja di perusahaan Jepang, memahami cara berpikir ini akan sangat membantu. Sambil bingung dengan perbedaan kebiasaan, pasti ada saatnya kamu mau tak mau harus membiasakan diri sedikit demi sedikit."],"vocab":["lancar, mulus","fondasi, dasar","segera, langsung","menghargai, mengutamakan","sepele, remeh","sebelum terjadi, mencegah sejak awal","bingung, kebingungan","penilaian, apresiasi","kepercayaan"],"grammar":[{"t":"〜うえで","note":"Menyatakan \"dalam proses / dalam hal melakukan sesuatu\". Contoh: 「日本の会社で働くうえで、「報連相」という考え方は非常に重要だと広く言われています」"},{"t":"〜にとって","note":"Menyatakan \"bagi / dari sudut pandang seseorang\". Contoh: 「外国人の社員にとっては、この報連相の習慣は、最初のうちは負担に感じられるかもしれません」"},{"t":"〜とは限らない","note":"Menyatakan \"belum tentu selalu begitu\", menyangkal pernyataan yang mutlak. Contoh: 「周囲に相談せず進めることが、日本では必ずしも良い結果につながるとは限らないのです」"},{"t":"〜ざるを得ない","note":"Menyatakan \"terpaksa harus ...\", dengan nuansa tidak ada pilihan lain. Contoh: 「習慣の違いに戸惑いながらも、少しずつ慣れていかざるを得ない場面もあるはずです」"}]},"a-n3-2-n2":{"title":"Hal yang Diajarkan Hidup Sendiri kepadaku","topic":"Kehidupan","trans":["Berawal dari masuk kuliah, untuk pertama kalinya dalam hidup aku mulai tinggal sendiri. Awalnya, aku senang sekali karena bisa memutuskan apa saja dengan bebas tanpa memikirkan pandangan orang tua. Kalau dipikir-pikir sekarang, waktu itu aku belum mengerti bahwa kebebasan itu tentu saja disertai tanggung jawab.","Namun, begitu mulai benar-benar menjalani hidup sendiri, memasak, mencuci, dan bersih-bersih, semuanya terpaksa kukerjakan sendiri. Selagi sibuk dikejar pekerjaan rumah, aku jadi sadar betapa banyak hal yang selama ini dikerjakan orang tuaku seolah-olah itu hal biasa. Seiring perubahan hidup, aku juga mulai serius memikirkan cara memakai uang. Selagi terus mengatur keuangan dengan biaya hidup yang terbatas, aku jadi bisa dengan sendirinya menilai mana yang benar-benar dibutuhkan.","Hidup sendiri memang banyak sulitnya, tetapi ada juga keuntungannya, yaitu kita jadi punya kemampuan untuk mengurus diri sendiri. Selain itu, saat sendirian kadang kita merasa kesepian, tetapi sebagai gantinya, memang benar kita bisa memakai waktu kita dengan bebas. Waktu untuk fokus pada hal yang disukai adalah sesuatu yang sulit didapat saat dulu tinggal bersama keluarga. Mungkin justru karena berada di lingkungan yang tidak bisa mengandalkan siapa pun, orang baru benar-benar memikirkan arti kemandirian.","Dan yang terpenting, aku jadi jauh lebih memahami betapa berharganya keluarga dibandingkan sebelumnya. Kalau dipikir lagi, aku baru menyadari rasa syukur itu setelah mulai tinggal terpisah dari keluarga. Hidup sendiri bukan sekadar perubahan gaya hidup, tetapi bisa dibilang pengalaman berharga yang mengubah cara kita memandang banyak hal."],"vocab":["melanjutkan sekolah (ke jenjang lebih tinggi)","menyertai, disertai","sudah semestinya, hal biasa","tersadarkan, jadi sadar","terbatas","menilai, membedakan dengan cermat","menjadi dikuasai (keterampilan), terbentuk","mandiri, kemandirian","berharga"],"grammar":[{"t":"〜に伴って","note":"Berarti \"seiring berubahnya sesuatu, hal lain ikut berubah\". Contoh: 「生活の変化に伴って、お金の使い方についても真剣に考えるようになった」."},{"t":"〜ざるを得ない","note":"Berarti \"terpaksa harus ...\", dengan nuansa tidak ada pilihan lain (bentuk ない tanpa ない + ざるを得ない). Contoh: 「すべて自分でやらざるを得なかった」."},{"t":"〜てこそ","note":"Menekankan \"justru karena ... barulah bisa ...\", diikuti hasil atau penilaian positif. Contoh: 「誰にも頼れない環境に身を置いてこそ、人は初めて自立の意味を考えるのかもしれない」."},{"t":"〜にとどまらず","note":"Berarti \"tidak hanya terbatas pada ..., tetapi juga ...\", untuk memperluas cakupan. Contoh: 「単なる生活の変化にとどまらず、物の見方を変えてくれる貴重な経験だ」."}]},"a-n3-2-n4":{"title":"Hal yang Kupelajari dari Hidup Sendiri","topic":"Kehidupan","trans":["Setelah masuk kuliah, aku untuk pertama kalinya tinggal sendiri. Awalnya aku senang karena bisa hidup dengan bebas. Tapi, memasak, mencuci, dan bersih-bersih harus kukerjakan sendiri. Saat itulah aku sadar bahwa dulu orang tuaku sudah melakukan banyak hal untukku.","Aku juga mulai memikirkan cara memakai uang. Karena uang yang bisa dipakai tidak banyak, aku memikirkan baik-baik lalu membeli barang yang benar-benar dibutuhkan. Tinggal sendiri memang berat, tapi kita jadi bisa mengurus diri sendiri.","Kalau sendirian, kadang terasa sepi, tapi kita bisa memakai waktu dengan bebas. Selain itu, aku jadi lebih paham daripada sebelumnya betapa pentingnya keluarga. Aku baru menyadari berharganya keluarga setelah tinggal berjauhan."],"vocab":["pertama kali","tinggal","bebas, kebebasan","memasak, masakan","mencuci (pakaian)","perlu, penting","berat, susah","penting, berharga","menyadari, menemukan","berpisah, menjauh"],"grammar":[{"t":"〜なければならない","note":"Berarti \"harus melakukan ~\". Dalam teks: 「自分でしなければならない」, artinya memasak, mencuci, dan bersih-bersih harus dikerjakan sendiri."},{"t":"〜ようになる","note":"Menunjukkan perubahan, dari tidak bisa menjadi bisa, atau kebiasaan yang berubah. Dalam teks: 「考えるようになった」「分かるようになった」."},{"t":"〜ので","note":"Menyatakan sebab atau alasan dengan nuansa lembut. Dalam teks: 「使えるお金が少ないので」, diikuti akibatnya."},{"t":"〜てから","note":"Berarti \"baru setelah melakukan ~\". Dalam teks: 「離れて住んでからだった」, artinya baru sadar setelah tinggal berpisah."}]},"a-n3-3-n2":{"title":"Budaya Sentō (Pemandian Umum)","topic":"Budaya","trans":["Sentō adalah pemandian umum tempat banyak orang berendam bersama, dan dulu menjadi bagian yang tak terpisahkan dari kehidupan sehari-hari. Dulu banyak keluarga yang tidak punya kamar mandi di rumah, sehingga orang-orang terpaksa memakai sentō. Sentō bukan sekadar tempat membersihkan badan, tetapi juga berperan sebagai tempat warga sekitar bertemu dan bersosialisasi.","Namun, seiring dengan semakin meluasnya kamar mandi di setiap rumah, orang yang memakai sentō pun berangsur-angsur berkurang. Akibatnya, jumlah sentō terus menyusut dan dianggap sebagai sesuatu yang ketinggalan zaman. Meski begitu, belakangan ini keunggulan khas sentō mulai dilihat kembali.","Berendam santai di pemandian yang luas tidak hanya menghilangkan lelah di badan, tetapi juga melemaskan ketegangan di hati. Rasa lega dan lapang yang sulit didapat dari bak mandi kecil di rumah inilah yang bisa dibilang sebagai daya tarik sentō. Selain itu, tidak jarang percakapan muncul begitu saja secara alami dengan orang asing yang duduk di sebelahmu, tanpa ada pemicu apa pun. Interaksi dengan orang lain yang dalam keseharian cenderung kita hindari, di sini bisa terjalin tanpa dipaksakan.","Mungkin karena terlalu mengejar kemudahan, kita perlahan-lahan kehilangan hubungan dengan sesama. Justru karena kita hidup di zaman ketika segalanya bisa diselesaikan sendirian, nilai waktu yang dihabiskan di ruang yang sama dengan orang lain jadi semakin menonjol. Di zaman sekarang, sentō adalah tempat berharga yang mengingatkan kita pada jarak yang pas antarmanusia."],"vocab":["pemandian umum (sentō)","tak terpisahkan, sangat dibutuhkan","keberadaan, sesuatu yang ada","interaksi, pergaulan","meluas, menyebar","dilihat ulang, dinilai kembali","perasaan lega dan lapang","tak dikenal, asing","kehilangan","menonjol, mencolok"],"grammar":[{"t":"〜ざるを得ない","note":"Artinya \"terpaksa harus…\", tidak ada pilihan lain. Contoh: 「人々は銭湯を利用せざるを得なかったのである」. Pakai bentuk ない dari kata kerja, buang ない lalu tambahkan ざるを得ない. Khusus する menjadi せざるを得ない."},{"t":"〜に伴って","note":"Artinya \"seiring dengan…\", yaitu saat satu hal berubah, hal lain ikut berubah. Contoh: 「各家庭におふろが広まるに伴って、銭湯を利用する人は次第に減っていった」."},{"t":"〜にとどまらず","note":"Artinya \"tidak terbatas pada…, tetapi juga…\". Contoh: 「銭湯は単に体を洗う場所にとどまらず、地域の人々が顔を合わせる交流の場としての役割も果たしていた」."},{"t":"〜あまり","note":"Artinya \"saking terlalu…, sehingga…\", biasanya berujung pada hasil yang kurang baik. Contoh: 「便利さを追い求めるあまり、私たちは人とのつながりを失いつつあるのかもしれない」."}]},"a-n3-3-n4":{"title":"Budaya Sentō (Pemandian Umum)","topic":"Budaya","trans":["Sentō adalah pemandian besar tempat semua orang berendam bersama. Dulu banyak orang yang tidak punya kamar mandi di rumah, jadi sentō adalah tempat yang penting. Sentō juga menjadi tempat warga sekitar bertemu.","Setelah rumah-rumah punya kamar mandi, jumlah sentō pelan-pelan berkurang. Tapi belakangan ini, makin banyak orang yang kembali melihat sisi baik sentō. Kalau berendam santai di pemandian yang luas, badan dan hati terasa lebih rileks.","Kadang kamu juga bisa mengobrol secara alami dengan orang asing yang duduk di sebelahmu. Di tengah kehidupan yang serba praktis, hubungan antarmanusia mungkin makin melemah. Sentō adalah tempat yang mengingatkan kita pada dekatnya hubungan antarmanusia."],"vocab":["pemandian umum (sentō)","dulu, zaman dahulu","penting, berharga","daerah, lingkungan sekitar","berkurang","belakangan ini","bertambah","alami, secara alami","praktis, mudah","teringat, mengingat kembali"],"grammar":[{"t":"〜と(syarat)","note":"Menyatakan \"kalau A terjadi, B otomatis mengikuti\". Contoh: 「家におふろができると、銭湯の数はだんだん減っていった」."},{"t":"〜ので","note":"Menyatakan sebab atau alasan, nadanya lebih lembut daripada 「から」. Contoh: 「昔は家におふろがない人が多かったので、銭湯は大切な場所だった」."},{"t":"〜ことがある(bentuk potensial+こともある)","note":"Artinya \"kadang…\". Di sini dipakai bersama bentuk potensial 「話せる」. Contoh: 「知らない人と、自然に話せることもある」."},{"t":"〜かもしれない","note":"Artinya \"mungkin…\", saat pembicara tidak terlalu yakin. Contoh: 「人とのつながりは弱くなっているかもしれない」."}]},"a-n3-4-n2":{"title":"進む少子化","topic":"Berita","trans":["Seiring dengan menurunnya angka kelahiran, jumlah anak di Jepang terus berkurang dari tahun ke tahun, dan wujud masyarakat itu sendiri pun akan segera berubah besar-besaran. Yang disebut shoushika (angka kelahiran rendah) adalah fenomena ketika jumlah anak yang lahir menurun dan proporsi anak dalam seluruh masyarakat semakin kecil. Sekilas tampak seperti perubahan yang berlangsung pelan, tetapi dampaknya diperkirakan akan menjangkau berbagai sisi kehidupan kita.","Penyebab angka kelahiran rendah tidak bisa dikerucutkan menjadi satu hal saja. Bisa dikatakan, berbagai faktor saling terkait dengan rumit. Pertama, ada yang menunjukkan bahwa semakin banyak orang yang tidak menikah, sehingga kesempatan untuk memiliki anak memang sudah berkurang dari awal. Selain itu, beban biaya membesarkan anak sangat berat, dan tidak sedikit keluarga yang terpaksa menyerah meskipun ingin punya anak. Lalu, sulitnya menyeimbangkan pekerjaan dan pengasuhan anak juga menjadi alasan besar yang membuat orang ragu untuk melahirkan.","Jika jumlah anak berkurang, jumlah orang yang akan bekerja di masyarakat di masa depan pun pasti ikut berkurang. Kalau jumlah pekerja menurun, ada risiko kekuatan ekonomi melemah, dan kemungkinan hilangnya semangat dan daya hidup perusahaan maupun daerah juga tidak bisa disangkal. Selain itu, kekhawatiran bahwa sistem yang menopang para lansia akan sulit dipertahankan juga mulai meluas. Angka kelahiran rendah bukan masalah bagi generasi yang mengasuh anak saja, melainkan seharusnya dipandang sebagai tantangan yang menyangkut masa depan seluruh masyarakat.","Pemerintah juga menjalankan berbagai langkah penanganan, tetapi bisa dibilang efeknya belum muncul secara memadai. Sebab, meskipun sistem dukungan sudah dibenahi, belum tentu orang langsung jadi lebih mudah melahirkan dan membesarkan anak. Bagaimana seluruh masyarakat bisa menciptakan lingkungan yang ramah untuk membesarkan anak, itulah yang kini kembali dipertanyakan."],"vocab":["shoushika (angka kelahiran rendah, anak makin sedikit)","faktor utama, penyebab","saling terkait, berkelindan","beban","menjalankan dua hal sekaligus, menyeimbangkan","penyangkalan, pengingkaran","sulit dipertahankan, tidak bisa berjalan","langkah penanganan, kebijakan","daya hidup, vitalitas","dipertanyakan, diuji"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring satu hal berubah, hal lain ikut berubah. Contoh: 「少子化に伴って、子どもの数が年々減り続けており」."},{"t":"〜ざるを得ない","note":"Menyatakan terpaksa melakukan sesuatu karena tidak ada pilihan lain. Contoh: 「子どもを持ちたくても諦めざるを得ない家庭も少なくない」."},{"t":"〜とは限らない","note":"Menyatakan bahwa belum tentu selalu begitu. Contoh: 「すぐに子どもを産み育てやすくなるとは限らない」."},{"t":"〜つつある","note":"Menyatakan bahwa suatu perubahan sedang berlangsung. Contoh: 「不安も、広がりつつある」."}]},"a-n3-4-n4":{"title":"へる子どもの数","topic":"Berita","trans":["Sekarang jumlah anak di Jepang terus berkurang. Hal ini disebut 「少子化」 (shoushika, angka kelahiran rendah). Penyebabnya tidak hanya satu. Orang yang tidak menikah makin banyak. Membesarkan anak butuh biaya. Menjalani pekerjaan dan pengasuhan anak sekaligus juga berat.","Kalau anak berkurang, orang yang bekerja di masa depan juga akan berkurang. Kalau begitu, kekuatan ekonomi negara mungkin akan melemah. Sistem untuk membantu para lansia juga sepertinya akan sulit dipertahankan.","Pemerintah sudah melakukan berbagai hal, tetapi masih belum cukup. Penting bagi kita semua untuk memikirkan masyarakat yang mudah untuk membesarkan anak. Katanya, kalau terus begini, menopang masyarakat akan menjadi sulit."],"vocab":["berkurang","penyebab","menikah","bertambah","membesarkan, mengasuh","masa depan","lansia","sistem, struktur","cukup","menopang, mendukung"],"grammar":[{"t":"〜と、…(syarat)","note":"Menyatakan hasil yang pasti terjadi: \"begitu ... pasti ...\". Contoh: 「子どもが減ると、将来働く人も少なくなります」"},{"t":"〜かもしれません","note":"Menyatakan dugaan: \"mungkin ...\". Contoh: 「国のお金の力が弱くなるかもしれません」"},{"t":"〜にくい","note":"Dipasang setelah bentuk ます kata kerja, artinya \"sulit untuk ...\". Contoh: 「続けにくくなりそうです」"},{"t":"〜そうだ(kesan)","note":"Menyatakan kesan berdasarkan keadaan: \"sepertinya akan ...\". Contoh: 「続けにくくなりそうです」"}]},"a-n3-5-n2":{"title":"飲みニケーション","topic":"Tempat Kerja","trans":["Di perusahaan Jepang, kebiasaan pergi minum bersama rekan kerja atau atasan setelah jam kerja masih sering dijumpai sampai sekarang. Pergaulan di acara minum seperti ini menggabungkan alkohol dan komunikasi, sehingga disebut「飲みニケーション」. Karena sudah lama dianggap sebagai perpanjangan dari pekerjaan dan dijalani nyaris sebagai hal yang wajar, pemandangan karyawan baru diajak senior untuk ikut pun bukan hal yang langka.","Di acara minum, ada keuntungan berupa bisa mengungkapkan isi hati yang sulit diucapkan di tempat kerja. Kepada atasan pun, kita jadi lebih santai saat mengajak bicara dibandingkan di ruang rapat. Karena itu, tidak sedikit orang yang menilai 飲みニケーション sebagai kesempatan berharga untuk mempererat hubungan antarmanusia. Soalnya, dengan dorongan suasana saat minum, jarak bisa terasa lebih dekat dan pekerjaan pun kadang berjalan lebih lancar.","Di sisi lain, di kalangan generasi muda, makin banyak orang yang berpikir, \"Waktu setelah kerja ingin kugunakan untuk diriku sendiri.\" Bagi mereka, cara menghabiskan waktu di luar jam kerja pada dasarnya adalah hal yang harus ditentukan bebas oleh masing-masing orang. Meski begitu, tidak sedikit pula orang yang merasa sangat keberatan karena secara praktis dipaksa untuk ikut. Kalau menolak, bisa-bisa dianggap tidak kompak, sehingga ada juga yang terpaksa hadir dengan berat hati.","Seiring cara kerja dan nilai-nilai yang makin beragam, bentuk 飲みニケーション mungkin juga sedikit demi sedikit berubah. Makin banyaknya anak muda zaman sekarang yang ingin memisahkan pekerjaan dan kehidupan pribadi dengan jelas mungkin juga merupakan salah satu tandanya. Bisa membangun rasa saling percaya lewat obrolan sehari-hari tanpa bergantung pada alkohol pada dasarnya bisa dibilang bentuk yang ideal."],"vocab":[{"w":"同僚","m":"rekan kerja"},{"w":"習慣","m":"kebiasaan"},{"w":"本音","m":"isi hati yang sebenarnya"},{"w":"打ち明ける","m":"mengungkapkan dengan terus terang, curhat"},{"w":"貴重","m":"berharga"},{"w":"強制","m":"paksaan, memaksa"},{"w":"抵抗","m":"penolakan, rasa keberatan"},{"w":"不本意","m":"dengan berat hati, tidak sesuai keinginan"},{"w":"多様化","m":"keberagaman, menjadi beragam"},{"w":"信頼関係","m":"hubungan saling percaya"}],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring berubahnya satu hal, hal lain ikut berubah. Contoh: 「働き方や価値観が多様化するのに伴って、飲みニケーションのあり方も少しずつ変わりつつあるのかもしれない」"},{"t":"〜ざるを得ない","note":"Menyatakan bahwa meski tidak mau, keadaan membuat kita tidak punya pilihan selain melakukannya. Contoh: 「断れば付き合いが悪いと見られかねず、不本意ながら出席せざるを得ない人もいる」"},{"t":"〜に対して","note":"Menyatakan sikap atau tindakan yang ditujukan kepada suatu objek. Contoh: 「参加を事実上強制されることに対して、強い抵抗を感じる人も決して少なくない」"},{"t":"〜かねない","note":"Menyatakan kemungkinan terjadinya hal yang buruk (bentuk ます verba tanpa ます + かねない). Contoh: 「断れば付き合いが悪いと見られかねず、不本意ながら出席せざるを得ない人もいる」"}]},"a-n3-5-n4":{"title":"飲みニケーション","topic":"Tempat Kerja","trans":["Di perusahaan Jepang, setelah kerja orang-orang sering pergi minum bersama rekan kerja. Kadang mereka juga pergi bersama atasan. Ini disebut「飲みニケーション」.","Kalau minum, kita bisa membicarakan hal-hal yang biasanya sulit diucapkan. Karena bisa mengobrol santai dengan atasan juga, ada orang yang merasa senang. Banyak juga yang menganggap ini kesempatan bagus untuk mempererat hubungan antarmanusia.","Di antara anak muda, makin banyak orang yang ingin menghargai waktu pribadi setelah kerja. Tidak sedikit juga yang merasa tidak suka kalau dipaksa ikut. Seiring cara kerja dan cara berpikir yang berubah, acara minum bersama sepertinya juga akan berubah sedikit demi sedikit. Yang paling baik adalah bisa membangun rasa percaya lewat obrolan sehari-hari, meski tanpa alkohol."],"vocab":[{"w":"同僚","m":"rekan kerja"},{"w":"上司","m":"atasan"},{"w":"気軽に","m":"dengan santai, tanpa sungkan"},{"w":"関係","m":"hubungan"},{"w":"機会","m":"kesempatan"},{"w":"大切にする","m":"menghargai, memprioritaskan"},{"w":"増えて","m":"bertambah (bentuk て dari 増える)"},{"w":"無理に","m":"dengan memaksa, secara paksa"},{"w":"変わって","m":"berubah (bentuk て dari 変わる)"},{"w":"信頼","m":"kepercayaan"}],"grammar":[{"t":"〜と(syarat)","note":"Menyatakan \"kalau melakukan A, B terjadi dengan sendirinya\". Contoh: 「お酒を飲むと、ふだんは言いにくいことが話せます」。"},{"t":"〜ので","note":"Menyatakan sebab atau alasan, nuansanya lebih lembut daripada「から」. Contoh: 「上司とも気軽に話せるので、楽しいと思う人もいます」。"},{"t":"Bentuk potensial","note":"Menyatakan \"bisa melakukan ~\". Contoh: 「ふだんは言いにくいことが話せます」「信頼を作れるのがいちばんです」。"},{"t":"〜そうです(dugaan dari kondisi)","note":"Bentuk ます verba tanpa ます + そうです, menyatakan dugaan \"sepertinya akan ~\" berdasarkan keadaan saat ini. Contoh: 「飲み会も少しずつ変わりそうです」。"}]},"a-n3-6-n2":{"title":"Empat Musim dan Perayaan Tahunan di Jepang","topic":"Budaya","trans":["Jepang punya empat musim, yaitu semi, panas, gugur, dan dingin, dan perayaan yang sesuai dengan tiap musim masih dijaga dan diwariskan sampai sekarang. Karena pergantian musimnya jelas, sejak dulu orang-orang menyesuaikan ritme hidup mereka dengan perubahan alam. Perayaan adalah wujud nyata dari kearifan hidup seperti itu, dan cara menikmati setiap musim pun berbeda-beda.","Musim semi adalah musim sakura. Sudah menjadi kebiasaan orang-orang berkumpul di taman dan merayakan datangnya musim semi sambil makan di bawah bunga. Ditambah rasa senang karena musim dingin yang menusuk sudah berakhir, hanami bisa dibilang perayaan yang punya makna lebih istimewa daripada sekadar acara makan bersama. Saat musim panas tiba, festival dan pesta kembang api diadakan di berbagai tempat, dan seluruh kota ramai oleh orang-orang yang memakai yukata. Tidak berlebihan jika dikatakan bahwa perayaan musim panas membawa kemeriahan dan semangat khas musim itu ke jalanan kota.","Musim gugur juga disebut \"musim gugur selera makan\" dan \"musim gugur membaca\", dan banyak orang menikmati daun musim gugur yang memerah di udara yang mulai sejuk. Seiring panas yang mereda, orang-orang menghabiskan waktu dengan tenang sesuai selera masing-masing, seperti makan enak atau membaca. Di musim dingin ada Tahun Baru. Biasanya keluarga berkumpul untuk menyantap osechi dan pergi ke kuil untuk hatsumode. Menjauh dari kesibukan sehari-hari dan menyambut tahun baru bersama keluarga dianggap sebagai makna penting dari Tahun Baru.","Perayaan-perayaan ini bukan hanya membuat kita merasakan langsung pergantian musim, tetapi juga menjadi kesempatan berharga untuk mempererat hubungan dengan keluarga dan orang-orang di sekitar. Seiring hidup yang makin praktis, kita jadi bisa hidup tanpa memperhatikan musim, tetapi nilai perayaan itu tidak hilang. Di tengah kemudahan pun, hati yang menghargai ritme alam pasti akan terus diwariskan lintas generasi."],"vocab":[{"w":"受けつがれる","m":"diwariskan, diteruskan"},{"w":"移り変わり","m":"pergantian, perubahan"},{"w":"整える","m":"menyesuaikan, menata"},{"w":"訪れ","m":"kedatangan"},{"w":"恒例","m":"kebiasaan, tradisi rutin"},{"w":"にぎわう","m":"ramai, meriah"},{"w":"過言","m":"berlebihan (dalam ucapan)"},{"w":"和らぐ","m":"mereda, menjadi lembut"},{"w":"初詣","m":"kunjungan pertama ke kuil di Tahun Baru"},{"w":"貴重","m":"berharga"}],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring satu hal berubah, hal lain ikut berubah. Contoh: 「生活が便利になるに伴って、季節を意識しなくても暮らせるようになったが、行事の価値は失われていない」. Bagian awalnya menjelaskan bahwa seiring hidup makin praktis, cara hidup pun ikut berubah."},{"t":"〜につれて","note":"Menyatakan bahwa seiring hal pertama berkembang, hal kedua berubah sedikit demi sedikit. Sering dipakai untuk perubahan bertahap. Contoh: 「暑さが和らぐにつれて、人々は食事や読書など、それぞれの好みに合わせて穏やかな時間を過ごすようになる」."},{"t":"〜と言っても過言ではない","note":"Artinya \"tidak berlebihan jika dikatakan…\", dipakai untuk menegaskan pendapat sendiri. Contoh: 「夏の行事は、季節ならではの華やかさと活気を街にもたらしていると言っても過言ではない」."},{"t":"〜という以上に","note":"Artinya \"lebih dari sekadar…\", menunjukkan bahwa makna sesuatu tidak berhenti di situ saja. Contoh: 「花見は単なる食事会という以上に特別な意味を持つ行事だと言えるだろう」."}]},"a-n3-6-n4":{"title":"Empat Musim dan Perayaan Tahunan di Jepang","topic":"Budaya","trans":["Jepang punya empat musim, dan setiap musim punya perayaannya sendiri. Musim semi adalah musim sakura, dan orang-orang berkumpul di taman. Mereka makan di bawah bunga sambil merayakan datangnya musim semi.","Saat musim panas tiba, ada festival dan pesta kembang api di berbagai tempat. Banyak orang datang dengan memakai yukata, dan suasananya sangat ramai. Musim gugur disebut \"musim gugur selera makan\" dan \"musim gugur membaca\". Karena udara jadi sejuk, banyak orang menikmati pemandangan daun musim gugur yang memerah.","Di musim dingin ada Tahun Baru, dan keluarga berkumpul untuk makan osechi. Lalu, banyak juga orang yang pergi ke kuil untuk hatsumode. Perayaan seperti ini adalah kesempatan untuk merasakan pergantian musim dan kedekatan dengan keluarga. Bahkan di tengah hidup yang praktis, hati yang menghargai alam mungkin akan terus bertahan selamanya."],"vocab":[{"w":"季節","m":"musim"},{"w":"行事","m":"acara, perayaan"},{"w":"集まる","m":"berkumpul"},{"w":"祝う","m":"merayakan"},{"w":"祭り","m":"festival"},{"w":"浴衣","m":"yukata (kimono musim panas)"},{"w":"紅葉","m":"daun musim gugur yang memerah"},{"w":"涼しい","m":"sejuk"},{"w":"正月","m":"Tahun Baru"},{"w":"機会","m":"kesempatan"}],"grammar":[{"t":"〜ながら","note":"Menyatakan dua tindakan yang dilakukan bersamaan. Bentuk ます verba dibuang ます-nya lalu ditambah ながら. Contoh: 「花の下でご飯を食べながら、春が来たことを祝います」"},{"t":"〜と(〜なると)","note":"Menyatakan bahwa begitu situasi tertentu terjadi, hasil tertentu pun muncul. Sering dipakai untuk hal alami atau yang sudah pasti. Contoh: 「夏になると、いろいろな所で祭りや花火大会があります」"},{"t":"〜と言われている","note":"Artinya \"dikatakan/disebut…\", dipakai untuk memperkenalkan sebutan yang umum. Contoh: 「秋は「食欲の秋」や「読書の秋」と言われています」"},{"t":"〜でしょう","note":"Menyatakan dugaan, \"mungkin/kira-kira…\". Contoh: 「自然を大切にする心はずっと続くでしょう」"}]},"a-n3-7-n2":{"title":"Mempersiapkan Diri Menghadapi Sengatan Panas","topic":"Kehidupan","trans":["Beberapa tahun terakhir, antara lain karena pengaruh pemanasan global, musim panas di Jepang makin lama makin berat. Terutama dari Juli sampai Agustus, hari dengan suhu ekstrem di atas 35 derajat sudah bukan hal yang langka lagi.","Seiring panas seperti ini, yang menjadi masalah setiap tahun adalah sengatan panas (heatstroke). Kalau keseimbangan air dan garam dalam tubuh terganggu, kamu bisa mengalami pusing dan sakit kepala, dan jika menjadi parah, bahkan bisa berujung pada kondisi yang membahayakan nyawa.","Dasar pencegahannya adalah rajin minum sebelum merasa haus. Selain itu, sebisa mungkin hindari keluar rumah di jam-jam bertemperatur tinggi, dan mengatur suhu ruangan dengan AC secara tepat juga tidak boleh dilewatkan.","Di sisi lain, anggapan \"aku masih baik-baik saja\" justru sering mengundang bahaya. Gejala belum tentu berkembang tanpa disadari oleh orangnya sendiri, tetapi ada juga kasus ketika baru sadar saat sudah terlambat, sehingga kebiasaan saling mengingatkan dengan orang di sekitar menjadi penting. Mari kita saling memperhatikan dan melewati musim panas yang berat ini tanpa memaksakan diri."],"vocab":["makin lama makin (setiap tahun)","hari panas ekstrem (suhu maksimum 35 derajat ke atas)","hilang keseimbangan, runtuh","menyebabkan, memicu","menjadi parah","pemenuhan, penambahan (asupan)","menahan diri, menghindari","tidak boleh dilewatkan, wajib ada","anggapan sendiri, prasangka","sudah terlambat"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring perubahan suatu hal, hal lain ikut terjadi. Contoh: 「こうした暑さに伴って、毎年問題になるのが熱中症である」"},{"t":"〜かねない","note":"Dipasang pada akar kata kerja bentuk ます; menyatakan kemungkinan terjadinya hasil yang buruk. Contoh: 「命に関わる事態にもなりかねない」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu\"; dipakai untuk menyangkal penilaian yang menyamaratakan. Contoh: 「症状は本人が自覚しないうちに進むとは限らない」"},{"t":"〜に加えて","note":"Berarti \"selain itu\"; menambahkan hal lain di luar yang sudah disebutkan. Contoh: 「それに加えて、気温の高い時間帯の外出はできるだけ控え」"}]},"a-n3-7-n4":{"title":"Hati-hati Sengatan Panas","topic":"Kehidupan","trans":["Akhir-akhir ini musim panas di Jepang jadi sangat panas. Pada bulan Juli dan Agustus, ada juga hari dengan suhu lebih tinggi dari 35 derajat.","Di hari yang panas seperti ini, yang perlu diwaspadai adalah sengatan panas. Kalau tubuh kekurangan air, kepala jadi sakit dan badan terasa limbung. Kalau parah, nyawa bisa terancam.","Untuk mencegah sengatan panas, usahakan minum air sebelum haus. Di jam-jam yang panas, sebaiknya sebisa mungkin jangan keluar rumah. Menggunakan AC dengan baik juga penting. Meski kamu merasa \"masih baik-baik saja\", tubuh bisa saja jadi tidak sehat. Saling mengingatkan dengan orang-orang di sekitar, dan mari menjalani musim panas dengan sehat."],"vocab":["suhu udara","sengatan panas","menjadi kurang","kepala","nyawa","mencegah","luar","pandai, dengan baik","penting","sehat, bersemangat"],"grammar":[{"t":"〜たり〜たりする","note":"Menyebutkan beberapa contoh tindakan atau keadaan. Contoh: 「頭が痛くなったり、ふらふらしたりする」"},{"t":"〜ようにする","note":"Menyatakan usaha untuk membiasakan diri atau berusaha melakukan sesuatu. Contoh: 「のどがかわく前に水を飲むようにする」"},{"t":"〜ないほうがいい","note":"Menyarankan lawan bicara untuk tidak melakukan sesuatu. Contoh: 「できるだけ外に出ないほうがいい」"},{"t":"〜と(條件)","note":"Kalau hal pertama terjadi, hal kedua otomatis mengikuti (syarat). Contoh: 「体の水が足りなくなると、頭が痛くなったり」"}]},"a-n4-1-n2":{"title":"Hanami – Tradisi yang Mewarnai Musim Semi Jepang","topic":"Budaya","trans":["Begitu musim semi tiba, bunga sakura di seluruh penjuru Jepang mulai mekar serentak, dan seluruh kota pun diselimuti warna merah muda yang lembut. Orang-orang berkumpul di taman dan tempat lainnya, lalu merayakan datangnya musim semi sambil makan bekal dan minum sake di bawah pohon sakura. Kebiasaan ini disebut 「お花見」 (hanami), dan dikenal luas serta disukai sebagai acara khas yang melambangkan musim semi Jepang.","Sakura adalah bunga yang sangat indah, tetapi masa dari mekar penuh sampai berguguran sangat singkat, hanya sekitar satu minggu. Itulah ciri khasnya. Justru karena masa mekarnya terbatas, banyak orang yang menantikan musim ini setiap tahun. Saat malam tiba, sakura yang disinari lampu menampilkan suasana magis yang berbeda dari siang hari. Kalau ada kesempatan, datanglah langsung dan buktikan keindahannya dengan mata kepalamu sendiri.","Tradisi hanami sudah berlangsung sejak dulu, dan orang-orang zaman dahulu pun menikmati datangnya musim semi sambil memandangi sakura. Meski zaman berubah, perasaan merasakan pergantian musim lewat sakura mungkin tidak berbeda, baik dulu maupun sekarang. Bisa dibilang, di balik alasan sakura terus dicintai orang-orang, ada kepekaan orang Jepang terhadap alam seperti ini.","Namun, seiring semakin populernya hanami, masalah berebut tempat dan sampah juga semakin terlihat. Meski acaranya menyenangkan, kalau kurang memperhatikan orang di sekitar, bisa-bisa timbul masalah. Agar semua orang bisa menikmati musim semi dengan nyaman, menjaga etika adalah hal yang paling penting."],"vocab":["lembut (warna), pucat","kedatangan, kunjungan","mekar penuh","magis, seperti dalam mimpi","datang langsung, sengaja pergi ke sana","pergantian (musim), perubahan","kepekaan, sensibilitas","berebut tempat (booking tempat)","kepedulian, perhatian"],"grammar":[{"t":"〜に伴って","note":"Menunjukkan bahwa seiring berubahnya satu hal, hal lain ikut berubah. Contoh dalam teks: 「お花見が盛んになるに伴って、場所取りやゴミの問題も目立つようになってきました」"},{"t":"〜かねない","note":"Menunjukkan kemungkinan terjadinya hasil yang buruk; dipakai untuk hal-hal negatif. Contoh dalam teks: 「周りの人への配慮を欠けば、トラブルにつながりかねません」"},{"t":"〜からこそ","note":"Menekankan bahwa justru karena alasan ini, hasil berikutnya terjadi. Contoh dalam teks: 「咲いている期間が限られているからこそ、多くの人がこの時期を毎年心待ちにしているのです」"},{"t":"〜に対する","note":"Menunjukkan objek dari perasaan, sikap, atau tindakan, dan menerangkan kata benda di belakangnya. Contoh dalam teks: 「日本人の自然に対する感性があると言えるでしょう」"}]},"a-n4-1-n3":{"title":"Hanami (Melihat Bunga Sakura)","topic":"Budaya","trans":["Begitu musim semi tiba, sakura mulai mekar di berbagai penjuru Jepang, dan seluruh kota diselimuti suasana yang cerah. Orang-orang berkumpul di taman, lalu bersenang-senang makan bekal dan minum sake di bawah pohon sakura. Menghabiskan waktu sambil melihat sakura seperti ini disebut 「お花見」 (hanami).","Sakura sangat indah, tetapi masa mekarnya hanya sekitar satu minggu. Karena itulah banyak orang yang menantikan musim ini.","Saat malam tiba, sakura yang disinari lampu juga menampilkan keindahan yang berbeda dari siang hari. Kalau ada kesempatan, cobalah pergi sekali untuk melihat sakura di siang dan malam hari.","Tradisi hanami sudah berlangsung sejak dulu, dan orang-orang zaman dahulu pun menikmati datangnya musim semi dengan melihat sakura. Dulu maupun sekarang, sakura bisa dibilang sosok istimewa yang membuat orang merasakan musim semi. Hanya saja, karena ada juga masalah berebut tempat dan sampah, kepedulian terhadap orang di sekitar itu penting. Agar semua orang bisa menikmatinya dengan nyaman, menjaga etika itu penting."],"vocab":[{"w":"包まれる","m":"diselimuti, dibungkus"},{"w":"集まる","m":"berkumpul"},{"w":"期間","m":"periode, masa"},{"w":"心待ち","m":"menantikan, mengharapkan"},{"w":"美しさ","m":"keindahan"},{"w":"習慣","m":"kebiasaan, tradisi"},{"w":"訪れ","m":"kedatangan"},{"w":"場所取り","m":"berebut tempat (booking tempat)"},{"w":"配慮","m":"kepedulian, perhatian"},{"w":"欠かせない","m":"tidak boleh ketinggalan, wajib ada"}],"grammar":[{"t":"〜たり〜たりする","note":"Menyebutkan beberapa contoh tindakan, artinya melakukan hal-hal seperti itu. Contoh: 「お弁当を食べたり、お酒を飲んだりして楽しみます」"},{"t":"〜ながら","note":"Menunjukkan dua tindakan yang dilakukan bersamaan. Contoh: 「このように桜を見ながら過ごすことを」"},{"t":"〜ため","note":"Menunjukkan sebab atau alasan, lebih formal daripada 「から」. Contoh: 「場所取りやゴミの問題もあるため」"},{"t":"〜ように","note":"Menunjukkan tujuan, yaitu agar suatu keadaan bisa terwujud. Contoh: 「誰もが気持ちよく楽しめるように」"}]},"a-n4-10-n2":{"title":"Self-Checkout, Cara Baru Berbelanja","topic":"Kehidupan","trans":["Minggu lalu, aku pertama kalinya memakai kasir swalayan (self-checkout) di supermarket dekat rumah, dan aku kagum dengan cara kerjanya. Ciri khas terbesarnya adalah pelanggan bisa menyelesaikan pembayaran barang sendiri tanpa lewat pegawai toko. Belakangan ini, seiring kekurangan tenaga kerja, semakin banyak toko yang memasang peralatan pembayaran tanpa petugas. Memang praktis, tetapi saat pertama kali memakainya, ada saat-saat ketika aku mau tak mau merasa bingung.","Pertama, keluarkan barang dari keranjang satu per satu, lalu arahkan barcode ke mesin agar terbaca. Kalau terdengar bunyi, itu tandanya barang tersebut sudah terdaftar dengan benar. Selanjutnya, ikuti petunjuk di layar dan pilih mau membayar dengan uang tunai atau kartu. Kalau memilih tunai, kamu memasukkan uang ke lubang masuk yang ditentukan.","Karena baru pertama kali, aku tidak tahu harus menekan bagian mana dan sempat bingung beberapa saat. Namun, pegawai toko yang ada di dekat situ menyadari aku kesulitan, langsung bergegas datang dan membantuku dengan ramah. Meskipun di toko yang serba mesin, tetap menenangkan kalau ada bantuan dari orang.","Kasir swalayan tidak perlu antre di kasir, jadi sangat praktis saat kamu sedang tidak punya banyak waktu. Hanya saja, dibandingkan orang yang sudah terbiasa mengoperasikan mesin, orang yang belum terbiasa mungkin merasa agak sulit. Meski begitu, kalau sudah terbiasa, siapa pun pasti bisa memakainya dengan mudah. Bagi kamu yang akan mencobanya, tenangkan diri dulu dan coba sambil melihat layar."],"vocab":["pembayaran, penghitungan akhir belanjaan","struktur, cara kerja","kagum, terkesan","kekurangan tenaga kerja","penerapan, pengenalan (sistem)","petunjuk, panduan","lubang masuk (untuk uang/koin)","bergegas datang","menenangkan, bisa diandalkan","kelonggaran, waktu luang"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring satu perubahan, perubahan lain juga terjadi bersamaan. Contoh: 「近年は人手不足に伴って」 peralatan kasir tanpa petugas pun ikut bertambah."},{"t":"〜ざるを得ない","note":"Berarti terpaksa melakukan sesuatu atau tidak bisa dihindari. Dipakai dengan bentuk ない kata kerja (tanpa ない). Contoh: 「戸惑わざるを得ない場面もありました」"},{"t":"〜に従って","note":"Menyatakan bertindak sesuai petunjuk, aturan, atau panduan. Contoh: 「画面の案内に従って」 memilih cara pembayaran."},{"t":"〜に対して","note":"Dipakai untuk membandingkan dua pihak atau keadaan. Contoh: 「操作に慣れている人に対して」 orang yang belum terbiasa merasa lebih sulit."}]},"a-n4-10-n3":{"title":"Self-Checkout","topic":"Kehidupan","trans":["Minggu lalu, untuk pertama kalinya seumur hidup aku mencoba memakai kasir swalayan (self-checkout) di supermarket dekat rumah. Kasir swalayan adalah mesin yang memungkinkan kita menghitung dan membayar belanjaan sendiri tanpa bergantung pada pegawai toko. Kurasa mengetahui cara memakainya akan berguna ke depannya.","Pertama, keluarkan barang dari keranjang satu per satu, lalu arahkan barcode ke mesin. Kalau terdengar bunyi \"bip\", itu tandanya barang tersebut sudah terbaca dengan benar. Selanjutnya, sambil mengikuti petunjuk di layar, pilih mau membayar dengan uang tunai atau kartu.","Kalau memilih tunai, kamu membayar dengan memasukkan uang ke tempat memasukkan uang di mesin. Karena baru pertama kali, aku jadi tidak tahu harus menekan bagian mana dan sempat bingung sebentar. Tapi, saat aku kesulitan, pegawai toko yang ada di dekat situ langsung datang membantu, jadi aku merasa lega.","Karena tidak perlu antre di kasir, aku merasa kasir swalayan sangat praktis saat sedang tidak punya waktu. Hanya saja, bagi orang yang belum terbiasa dengan mesin, mungkin terasa agak sulit. Kalau sudah terbiasa dengan cara memakainya, siapa pun bisa memakainya dengan mudah. Bagi kamu yang akan mencobanya nanti, jangan terburu-buru, coba pelan-pelan sambil melihat layar."],"vocab":[{"w":"セルフレジ","m":"kasir swalayan (self-checkout)"},{"w":"精算","m":"pembayaran, penghitungan akhir"},{"w":"取り出す","m":"mengeluarkan"},{"w":"かざす","m":"mengarahkan/mendekatkan (ke depan sesuatu)"},{"w":"読み取る","m":"membaca, memindai"},{"w":"案内","m":"petunjuk, panduan"},{"w":"迷う","m":"bingung, ragu"},{"w":"手伝う","m":"membantu"},{"w":"慣れる","m":"terbiasa, menjadi akrab"},{"w":"試す","m":"mencoba"}],"grammar":[{"t":"〜ておく","note":"Menyatakan melakukan sesuatu lebih dulu sebagai persiapan. Contoh: 「使い方を知っておくと」 artinya kalau tahu cara pakainya lebih dulu, nanti akan berguna."},{"t":"〜ため(alasan)","note":"Cara yang agak formal untuk menyatakan alasan. Contoh: 「私は初めてだったため」 artinya \"karena baru pertama kali\"."},{"t":"〜にとって","note":"Menyatakan sudut pandang seseorang. Contoh: 「機械に慣れていない人にとっては」 artinya \"bagi orang yang belum terbiasa dengan mesin\"."},{"t":"〜ようになる","note":"Menyatakan perubahan kemampuan atau keadaan. Contoh: 「誰でも簡単に使えるようになります」 artinya \"siapa pun akan menjadi bisa memakainya dengan mudah\"."}]},"a-n4-3-n2":{"title":"Menyusuri Kota Kuno Kyoto","topic":"Wisata","trans":["Kyoto adalah kota yang berjaya sebagai ibu kota Jepang lebih dari seribu tahun lalu, dan dikenal sebagai kota yang menyampaikan sejarah panjangnya hingga hari ini. Seiring perubahan zaman, wajah kota ini memang berubah sedikit demi sedikit, tetapi kuil dan tempat suci kuno masih banyak yang bertahan sampai sekarang. Bangunan-bangunan itu bukan sekadar objek wisata, melainkan bisa dibilang sesuatu yang terikat erat dengan kehidupan dan kepercayaan masyarakatnya.","Salah satu daya tarik Kyoto adalah wajahnya yang benar-benar berbeda di setiap musim, seperti bunga sakura di musim semi dan daun merah di musim gugur. Meski di tempat yang sama, kesan yang kamu dapat bisa sangat berbeda tergantung musim kunjunganmu. Karena itu, kamu tidak akan bosan sebanyak apa pun datang ke sana. Malah, tidak sedikit orang yang bilang selalu menemukan hal baru setiap kali berkunjung.","Kalau kamu jalan-jalan ke Kyoto, sebaiknya jangan memadatkan jadwal, dan berkelilinglah dengan santai tanpa terburu-buru. Sebab, hanya dengan berbelok ke satu gang kecil, kamu bisa tiba-tiba bertemu kuil yang tenang atau kafe bergaya lama. Kalau terlalu memaksa mengikuti rencana, mau tak mau kamu akan melewatkan pertemuan kebetulan seperti ini. Tempat yang tercantum di peta belum tentu semua yang ada di Kyoto.","Selain tempat wisata terkenal, kalau kamu juga mampir ke toko-toko kecil yang sering didatangi warga setempat, pesona Kyoto yang sebenarnya akan terlihat. Berbeda dengan kemegahan tempat wisata, di toko kecil kamu bisa merasakan suasana keseharian Kyoto. Kyoto juga kota yang menjaga bangunan kuno dengan penuh perhatian sambil aktif menerima budaya baru. Berdampingannya tradisi dan perubahan secara alami inilah yang bisa dibilang alasan Kyoto terus dicintai dalam waktu lama."],"vocab":["ibu kota","berjaya, makmur (bentuk kamus: 栄える)","kepercayaan, keyakinan","perwakilan, mewakili","ekspresi, wajah (tampilan)","bosan, jenuh","seperti dulu, bergaya lama","kebetulan","hidup berdampingan"],"grammar":[{"t":"〜に伴って","note":"Berarti 「seiring…」, yaitu saat hal pertama berubah, hal kedua ikut berubah. Contoh: 「時代の移り変わりに伴って町の姿は少しずつ変わってきました」"},{"t":"〜ざるを得ない","note":"Berarti 「terpaksa…, mau tak mau…」, dipakai dengan bentuk ない verba (する menjadi せざるを得ない). Contoh: 「偶然の出会いを見逃さざるを得なくなってしまいます」"},{"t":"〜に対して","note":"Menyatakan kontras, 「berbeda dengan…」, untuk membandingkan dua hal. Contoh: 「観光地の華やかさに対して、小さな店には京都の日常の空気が感じられます」"},{"t":"〜とは限らない","note":"Berarti 「belum tentu…」, dipakai untuk menyangkal anggapan bahwa 「semuanya begitu」. Contoh: 「地図に載っている場所だけが京都のすべてとは限らないのです」"}]},"a-n4-3-n3":{"title":"Menyusuri Kota Kuno Kyoto","topic":"Wisata","trans":["Kyoto adalah kota yang lebih dari seribu tahun lalu pernah menjadi ibu kota Jepang, dan sampai sekarang masih banyak kuil dan tempat suci kuno yang bertahan. Sakura di musim semi dan daun merah di musim gugur sangat indah, dan wajah kotanya benar-benar berbeda tiap musim. Karena itu, sebanyak apa pun kamu berkunjung, kamu tidak akan bosan.","Saat jalan-jalan ke Kyoto, sebaiknya berjalanlah dengan santai tanpa terburu-buru. Kalau kamu berbelok ke gang kecil, kadang kamu bisa bertemu kuil yang tenang atau kafe bergaya lama. Pertemuan tak terduga seperti itu bisa dibilang keseruan khas perjalanan dengan berjalan kaki.","Jangan hanya melihat tempat wisata terkenal, cobalah juga mampir ke toko-toko kecil yang sering didatangi warga setempat. Berbeda dengan tempat yang ditujukan untuk turis, di sana kamu bisa merasakan kehidupan sehari-hari Kyoto. Dengan begitu, pesona Kyoto yang sebenarnya akan terlihat sedikit demi sedikit.","Pesona Kyoto terletak pada caranya menjaga bangunan kuno dengan penuh perhatian sambil juga menerima budaya baru. Kota ini tidak sekadar mempertahankan hal-hal lama, tetapi terus berubah mengikuti zaman. Justru karena itulah Kyoto menjadi kota yang menarik banyak orang, dulu maupun sekarang."],"vocab":["ibu kota","banyak, dalam jumlah besar","ekspresi, wajah (tampilan)","mengunjungi","bosan, jenuh","seperti dulu, tradisional","pergi ke, menyempatkan datang","setempat, lokal","pesona, daya tarik","mengadopsi, menyerap"],"grammar":[{"t":"〜によって","note":"Berarti 「tergantung…」 atau 「dengan cara…」. Dalam 「季節によってまったく違う表情を見せてくれます」 artinya berbeda tergantung musim; dalam 「そうすることによって」 artinya dengan melakukan hal itu."},{"t":"〜わけではない","note":"Negasi sebagian, berarti 「bukan berarti…」. Dalam 「昔のものをただ残しているわけではなく」 artinya bukan sekadar mempertahankan benda lama."},{"t":"〜だけでなく","note":"Berarti 「bukan hanya… tetapi juga…」. Dalam 「有名な観光地を見るだけでなく、地元の人が通う小さな店にも足を運んでみてください」 artinya bukan hanya melihat tempat terkenal, tetapi juga mampir ke toko kecil setempat."},{"t":"〜はずだ","note":"Menyatakan dugaan pembicara berdasarkan alasan, 「seharusnya…」. Dalam 「本当の京都の魅力が少しずつ見えてくるはずです」 artinya dugaan bahwa dengan cara itu pesona Kyoto akan terlihat."}]},"a-n4-4-n2":{"title":"Perjalanan Solo Pertamaku","topic":"Perjalanan","trans":["Bulan lalu, aku pergi traveling sendirian untuk pertama kalinya dan memutuskan mengunjungi Kanazawa, kota yang sudah lama menarik perhatianku. Sebelum berangkat, aku tak bisa menahan rasa cemas, tapi menyusun rencana sendiri ternyata jauh lebih seru dari yang kubayangkan. Karena tidak perlu menyesuaikan diri dengan siapa pun, aku bisa bebas memilih tempat yang ingin kukunjungi, dan menurutku itu juga daya tarik yang besar.","Hari itu aku naik Shinkansen pagi-pagi sekali dan tiba di Kanazawa lewat tengah hari. Ukuran stasiunnya yang besar membuatku spontan terpana. Begitu sampai, aku memutuskan untuk melihat taman yang terkenal lebih dulu. Berkat cuaca yang cerah, aku bisa mengambil banyak foto dengan pemandangan taman sebagai latar belakang. Bahkan di tempat yang baru pertama kali dikunjungi, aku bisa berkeliling dengan kecepatanku sendiri. Menurutku, inilah keunggulan khas traveling sendirian.","Saat malam tiba, aku pergi ke pasar dan menikmati hidangan laut segar sepuasnya. Karena sendirian, aku tidak perlu sungkan pada orang lain, jadi bisa memesan makanan yang kusuka sebanyak yang kuinginkan. Dalam perjalanan bersama rombongan, keinginan semua orang belum tentu sama, jadi kebebasan seperti ini terasa berharga. Saat berjalan sendirian di kota yang asing, memang ada saat-saat aku merasa sedikit kesepian, tapi rasa nyaman karena bebas jauh lebih kuat.","Seiring perjalanan berlangsung, rasa cemas sebelum berangkat perlahan memudar, dan hatiku pun jadi lebih lapang. Lewat perjalanan ini, aku mendapat rasa percaya diri bahwa \"sendirian pun aku bisa mengatasinya\", dan itu hasil yang sangat berharga. Rasa enggan untuk bertindak sendirian sepertinya jadi berkurang berkat pengalaman kali ini. Kalau ada kesempatan, aku ingin pergi sendirian lagi ke kota lain."],"vocab":["cemas, tidak tenang","terpana, terkesima","hidangan laut","menikmati, meresapi","sungkan, merasa tidak enak pada orang lain","berharga","kelonggaran, ketenangan","hasil, panen","rasa enggan, rasa menolak"],"grammar":[{"t":"〜ざるを得ない","note":"Berarti \"terpaksa ~, tak punya pilihan selain ~\", dengan nuansa pasrah. Contoh: 「出発する前は不安を感じざるを得なかった」."},{"t":"〜とは限らない","note":"Berarti \"belum tentu ~\", dipakai untuk menyangkal pernyataan yang menyeluruh atau mutlak. Contoh: 「全員の希望が一致するとは限らない」."},{"t":"〜に伴って","note":"Berarti \"seiring dengan ~\", saat hal pertama berubah, hal kedua ikut berubah. Contoh: 「旅が進むに伴って、出発前の不安は少しずつ薄れ」."},{"t":"〜を通して","note":"Berarti \"melalui ~\", menunjukkan hasil yang didapat lewat suatu pengalaman atau cara. Contoh: 「この旅行を通して、一人でも何とかなるという自信がついた」."}]},"a-n4-4-n3":{"title":"Perjalanan Solo Pertamaku","topic":"Perjalanan","trans":["Bulan lalu, untuk pertama kalinya seumur hidup aku pergi traveling sendirian. Tujuannya kota Kanazawa, yang sudah lama menarik perhatianku. Sebelum berangkat memang ada rasa cemas, tapi menyusun rencana sendiri ternyata lebih seru dari yang kubayangkan.","Berkat naik Shinkansen pagi-pagi, aku bisa tiba di Kanazawa lewat tengah hari. Stasiunnya jauh lebih besar dari yang kubayangkan, sampai-sampai aku berhenti melangkah tanpa sadar.","Pertama, aku memutuskan untuk melihat taman yang terkenal di kota ini. Karena cuacanya mendukung, aku bisa mengambil banyak foto dengan pemandangan indah sebagai latar. Malamnya aku pergi ke pasar dan menikmati hidangan laut segar. Karena sendirian, aku senang bisa memesan makanan yang kuinginkan sebanyak yang kumau.","Saat berjalan sendirian di kota yang asing, kadang aku merasa sedikit kesepian. Meski begitu, kebebasan untuk tidak perlu menyesuaikan diri dengan siapa pun terasa sangat nyaman. Lewat perjalanan ini, aku mendapat rasa percaya diri bahwa sendirian pun aku bisa mengatasinya. Kalau ada kesempatan, aku ingin pergi sendirian lagi ke suatu tempat."],"vocab":["rencana","cemas, tidak tenang","bayangan, imajinasi","taman","diberkahi, dianugerahi","segar","menikmati, meresapi","kebebasan","nyaman, enak","percaya diri"],"grammar":[{"t":"〜おかげで","note":"Menyatakan hasil baik yang didapat karena suatu sebab, dengan nuansa rasa terima kasih. Contoh: 「朝早い新幹線に乗ったおかげで、昼過ぎには金沢に着くことができました」"},{"t":"〜ことにする","note":"Menyatakan keputusan yang dibuat sendiri oleh pembicara. Contoh: 「この町で有名な庭園を見に行くことにしました」"},{"t":"〜ため(原因)","note":"Cara yang agak formal atau tulisan untuk menyatakan sebab atau alasan. Contoh: 「天気に恵まれたため、きれいな景色を背景に写真をたくさん撮ることができました」"},{"t":"〜によって","note":"Menunjukkan hasil yang muncul melalui suatu cara atau pengalaman. Contoh: 「この旅行によって、一人でも何とかなるという自信がつきました」"}]},"a-n4-5-n2":{"title":"Sehari Kerja Paruh Waktu","topic":"Pekerjaan","trans":["Sambil kuliah, aku bekerja paruh waktu di kafe. Tiga kali seminggu aku masuk shift dari sore sampai malam. Begitu sampai di toko, hal pertama yang kulakukan adalah mengganti baju dengan seragam lalu mencuci tangan dengan teliti. Itu sudah jadi aturan sebelum mulai bekerja. Di tempat makan, kebersihan tidak boleh diabaikan, jadi menurutku kebiasaan ini terlihat sepele, tetapi sebenarnya punya arti penting.","Pekerjaannya beragam, mulai dari menerima pesanan, membuat kopi, sampai membereskan meja. Di jam sibuk, aku bahkan tidak sempat bernapas dan terpaksa terus bergerak ke sana kemari, jadi cukup melelahkan baik secara fisik maupun mental. Meski begitu, anehnya, begitu pelanggan bilang \"terima kasih\", rasa lelahku langsung hilang seketika.","Waktu baru mulai bekerja, aku sering melakukan kesalahan dan cukup sering ditegur oleh senior. Saat itu, setiap hari aku benar-benar sadar betapa belum matangnya diriku. Namun, seiring bertambahnya pengalaman, pekerjaan yang bisa kulakukan pun bertambah sedikit demi sedikit.","Yang kudapat dari kerja paruh waktu ini tidak hanya penghasilan. Cara berbicara dengan orang lain dan pentingnya bekerja sama dalam tim juga bisa kupelajari langsung di lapangan. Menyeimbangkan pekerjaan dengan kuliah memang tidak bisa dibilang mudah, tetapi aku merasa semakin besar kesulitannya, semakin besar pula yang didapat. Bisa mendapat pengalaman seperti ini sebelum terjun ke masyarakat adalah harta berharga bagiku."],"vocab":["dengan teliti, dengan cermat","segi kebersihan","tidak boleh dilewatkan, sangat diperlukan","mencakup banyak bidang","tanpa sempat bernapas","belum matang, kurang berpengalaman","dipaksa menyadari dengan sangat dalam","menyeimbangkan dua hal, berjalan beriringan","berharga","harta, aset berharga"],"grammar":[{"t":"〜かたわら","note":"Menyatakan sambil menjalani hal utama (pekerjaan atau studi), kita juga terus melakukan hal lain. Contoh: 「大学に通うかたわら、カフェでアルバイトをしており」"},{"t":"〜ざるを得ない","note":"Menyatakan tidak ada pilihan lain selain melakukannya, jadi terpaksa. Contoh: 「息つく暇もなく動き回らざるを得ず」"},{"t":"〜に伴って","note":"Menyatakan seiring terjadinya suatu perubahan, hal lain ikut berubah. Contoh: 「経験を重ねるに伴って、少しずつできる仕事が増えていった」"},{"t":"〜にとどまらない","note":"Menyatakan tidak terbatas pada suatu lingkup, masih ada yang lebih banyak. Contoh: 「得たものは、収入だけにとどまらない」"}]},"a-n4-5-n3":{"title":"Sehari Kerja Paruh Waktu","topic":"Pekerjaan","trans":["Sambil kuliah, aku bekerja paruh waktu di kafe. Karena tiga kali seminggu aku masuk shift dari sore sampai malam, hari-hari itu terasa sangat singkat. Begitu sampai di toko, pertama-tama aku mengganti baju dengan seragam, dan demi kebersihan, ada aturan untuk mencuci tangan dengan benar.","Pekerjaannya antara lain menerima pesanan, membuat kopi, dan membereskan meja. Di jam sibuk, rasanya melelahkan sampai tidak sempat bernapas. Meski begitu, kalau pelanggan bilang \"terima kasih\", rasa lelahku terasa seperti terbang menghilang.","Di awal, aku sering sekali melakukan kesalahan dan sering ditegur senior. Setiap kali gagal aku merasa down, tapi sedikit demi sedikit hal yang bisa kulakukan bertambah. Lewat kerja paruh waktu ini, aku tidak hanya belajar soal uang, tapi juga cara berbicara dengan orang lain dan pentingnya kerja sama tim.","Menyeimbangkan pekerjaan dengan kuliah memang tidak mudah, tapi aku merasa senang karena sudah bertahan sampai sekarang. Menurutku, pengalaman ini jadi pelajaran yang bagus sebelum aku terjun ke masyarakat."],"vocab":["seragam","kebersihan","pesanan","kegagalan, kesalahan","senior, kakak kelas","menegur, peringatan","menyeimbangkan dua hal, berjalan beriringan","masyarakat","pengalaman","pentingnya"],"grammar":[{"t":"〜ため(原因・理由)","note":"Menyatakan sebab atau alasan, nadanya lebih formal daripada「から」. Contoh: 「シフトに入っているため、その日は一日がとても短く感じます」"},{"t":"〜ことになっている","note":"Menyatakan aturan, kebiasaan, atau cara yang sudah ditetapkan. Contoh: 「衛生のためにしっかり手を洗うことになっています」"},{"t":"〜によって","note":"Menyatakan sarana, cara, atau sebab, bisa diartikan \"lewat\" atau \"dengan\". Contoh: 「アルバイトによって、お金だけでなく、人との話し方も学ぶことができました」"},{"t":"〜わけではない","note":"Negasi sebagian, artinya \"bukan berarti ...\". Contoh: 「勉強との両立は簡単なわけではありませんが」"}]},"a-n4-6-n2":{"title":"Daya Tarik Festival Musim Panas","topic":"Budaya","trans":["Di Jepang, begitu musim panas tiba, festival musim panas umumnya diadakan di berbagai penjuru negeri dan disukai banyak orang sebagai ciri khas musim ini. Banyak festival musim panas berasal dari acara kuil Shinto atau kuil Buddha, dan sampai sekarang tetap menjadi kesempatan penting bagi warga setempat untuk berkumpul. Seiring malam semakin larut, banyak orang berpakaian yukata datang berbondong-bondong ke halaman kuil Shinto dan kuil Buddha. Orang yang biasanya berpakaian ala Barat pun cenderung menikmati busana tradisional pada hari ini.","Di lokasi festival, banyak sekali kios berjajar rapat, dan hanya dengan berjalan-jalan saja kamu sudah bisa merasakan suasana meriah yang khas. Ada yang mencicipi takoyaki dan es serut, ada yang mencoba menangkap ikan mas, dan cara menikmatinya berbeda-beda untuk setiap orang. Menurutku, daya tarik festival musim panas ada pada kenyataan bahwa lewat makanan dan permainan, dari anak-anak sampai orang dewasa bisa tersenyum di ruang yang sama.","Saat malam semakin larut dan festival hampir berakhir, akhirnya kembang api besar diluncurkan ke langit malam. Begitu terdengar suara dentuman keras \"dum\", cahaya pun menyebar memenuhi langit yang gelap. Pada saat itu, orang-orang yang berkumpul tak bisa menahan diri untuk berseru \"wah\". Kedahsyatan perpaduan suara dan cahaya belum tentu bisa tersampaikan sepenuhnya hanya lewat foto atau video, jadi layak dialami langsung di tempatnya. Justru karena pemandangan ini hanya bisa dinikmati pada waktu yang terbatas dalam setahun, mungkin itulah sebabnya ia membekas kuat di ingatan banyak orang.","Begitulah, festival musim panas adalah acara yang menjadi kenangan penting musim panas di Jepang, sekaligus kesempatan untuk merasakan musim secara langsung. Kalau ada kesempatan berkunjung ke Jepang, cobalah memakai yukata dan menikmati festival dalam suasana yang sama dengan warga setempat. Mungkin kamu akan bingung dengan pakaian yang belum terbiasa, tetapi itu pun pasti akan menjadi pengalaman perjalanan yang tak terlupakan."],"vocab":["penyelenggaraan, mengadakan","ciri khas musim, simbol musim","area dalam kompleks (kuil Shinto/kuil Buddha)","mengenakan, berbalut (pakaian)","kecenderungan, tren","berjajar rapat (rumah/toko)","semangat, suasana meriah","meluncurkan (kembang api, dll.)","kedahsyatan, daya pukau","bingung, kebingungan"],"grammar":[{"t":"〜につれて","note":"Menyatakan bahwa seiring perubahan hal pertama, hal kedua juga berubah secara bertahap. Contoh: 「夜になるにつれて、浴衣を身にまとった大勢の人々が、神社やお寺の境内へと次々に集まってきます」"},{"t":"〜かと思うと","note":"Menyatakan bahwa begitu hal pertama terjadi, langsung disusul perubahan atau hal kedua. Contoh: 「ドンという大きな音が響いたかと思うと、暗い空いっぱいに光が広がっていきます」"},{"t":"〜ずにはいられない","note":"Menyatakan tidak bisa menahan diri untuk melakukan sesuatu; reaksi yang muncul secara spontan. Contoh: 「集まった人々は思わず『わあ』と声を上げずにはいられません」"},{"t":"〜とは限らない","note":"Menyatakan bahwa sesuatu belum tentu selalu demikian; dipakai untuk menunjukkan kemungkinan pengecualian. Contoh: 「写真や映像で見るだけでは十分に伝わるとは限らず、現地で体験する価値があります」"}]},"a-n4-6-n3":{"title":"Festival Musim Panas","topic":"Budaya","trans":["Di Jepang, begitu musim panas tiba, berbagai festival musim panas diadakan di banyak tempat, jadi setiap tahun banyak orang menantikannya. Saat malam tiba, orang-orang berpakaian yukata sedikit demi sedikit berkumpul di sekitar kuil Shinto dan kuil Buddha. Konon yukata terlihat sejuk, jadi cocok sekali untuk merasakan suasana festival musim panas.","Di lokasi festival berjajar banyak kios, dan hanya dengan berjalan-jalan saja suasana hati jadi senang. Orang-orang makan takoyaki dan es serut, menikmati permainan menangkap ikan mas, dan melewati malam sesuka hati masing-masing. Bukan hanya membeli makanan, bisa tertawa bersama keluarga dan teman lewat permainan juga merupakan daya tarik festival.","Saat festival hampir berakhir, akhirnya kembang api besar diluncurkan ke langit malam. Setelah terdengar suara dentuman keras \"dum\", cahaya menyebar memenuhi langit malam. Orang-orang yang melihat pemandangan indah itu sepertinya tanpa sadar berseru \"wah\".","Festival musim panas adalah acara Jepang yang membuat kita bisa merasakan musim, dan telah menjadi kenangan berharga bagi banyak orang. Kalau ada kesempatan pergi ke Jepang, pilihlah waktu musim panas dan cobalah ikut festival. Kalau pergi dengan memakai yukata, pasti akan menjadi pengalaman musim panas yang istimewa."],"vocab":["diadakan (acara)","yukata (kimono musim panas)","suasana","kios (pedagang kaki lima)","sesuka hati masing-masing","daya tarik","mendekati","diluncurkan (kembang api, dll.)","bergema, menggema","acara, upacara"],"grammar":[{"t":"〜ため(sebab)","note":"Menyatakan sebab atau alasan, lebih formal/tertulis daripada「から」. Contoh: 「各地でさまざまな夏祭りが開かれるため、毎年多くの人が楽しみにしています」"},{"t":"〜だけでなく","note":"Menyatakan \"bukan hanya… tetapi juga…\". Contoh: 「食べ物を買うだけでなく、遊びを通して家族や友達と笑い合えるところも、祭りの魅力です」"},{"t":"〜ようだ","note":"Menyatakan dugaan berdasarkan apa yang dilihat atau didengar, \"sepertinya…\". Contoh: 「思わず「わあ」と声を上げてしまうようです」"},{"t":"〜ば(syarat)","note":"Menyatakan syarat pengandaian, \"kalau…\". Contoh: 「日本に行く機会があれば、ぜひ夏の時期を選んで、祭りに参加してみてください」"}]},"a-n4-7-n2":{"title":"Cara Membuang Sampah","topic":"Kehidupan","trans":["Sejak mulai tinggal di Jepang, hal yang paling mengejutkanku adalah cara membuang sampah yang aturannya jauh lebih rinci daripada yang kubayangkan. Karena di negara asalku aku nyaris tidak pernah memperhatikan hal seperti ini, awalnya aku tidak bisa menahan rasa bingung. Sampah harus dipilah dulu menjadi 「燃えるごみ」(sampah mudah terbakar), 「燃えないごみ」(sampah tidak mudah terbakar), 「資源ごみ」(sampah daur ulang), dan sebagainya sebelum dibuang.","Hari pembuangannya juga ditentukan menurut jenis sampah. Di kota tempatku tinggal, sampah mudah terbakar diambil setiap hari Senin dan Kamis. Waktunya pun ada aturannya: sampah harus dibawa ke tempat yang ditentukan paling lambat pukul delapan pagi. Sampai hafal hari dan jamnya, aku terpaksa mengeceknya berulang kali. Kalau salah memilah, kadang sampahnya tidak diambil, jadi tidak boleh lengah.","Awalnya aku merasa repot dan bertanya-tanya kenapa harus dipilah sampai serinci ini. Namun, lama-lama aku sadar bahwa seiring setiap warga menaati aturan, kenyamanan hidup di seluruh kota pun terjaga. Kalau sudah terbiasa, memilah sampah itu sendiri sama sekali bukan pekerjaan yang sulit. Justru kalau sudah jadi kebiasaan sehari-hari, hampir tidak terasa sebagai beban lagi.","Berkat pemilahan yang dijalankan dengan tuntas, kota selalu terjaga bersih. Cara membuang sampah sekilas tampak seperti masalah sepele, tetapi bisa dibilang itu adalah kesepakatan penting yang menopang kehidupan masyarakat setempat. Memang benar ada sisi yang terasa memberatkan bagi orang asing, tetapi sebagai gantinya, hal yang didapat pun sama sekali tidak sedikit."],"vocab":["kebingungan, rasa bingung","pemilahan, pengelompokan","pengambilan (sampah), pengumpulan","penunjukan, yang ditentukan","kelengahan, sikap lengah","awalnya, pada mulanya","warga, penduduk","tuntas, menyeluruh","bersih, rapi","sepele, remeh"],"grammar":[{"t":"〜ずにはいられない","note":"Artinya 'tidak bisa menahan diri untuk tidak melakukan ~'. Dipakai untuk perasaan yang muncul dengan sendirinya. Contoh: 「最初は戸惑いを覚えずにはいられませんでした」"},{"t":"〜ざるを得ない","note":"Artinya 'terpaksa ~' atau 'tidak ada pilihan selain ~'. Contoh: 「曜日と時間を覚えるまでは、何度も確かめざるを得ませんでした」"},{"t":"〜に伴って","note":"Artinya 'seiring dengan ~'. Saat satu hal berubah, hal lain ikut berubah atau terwujud. Contoh: 「住民が一人一人ルールを守ることに伴って、町全体の暮らしやすさが保たれている」"},{"t":"〜に対して","note":"Artinya 'terhadap ~' atau 'sebagai balasan atas ~' (kontras atau tanggapan). Contoh: 「それに対して得られるものも決して少なくありません」"}]},"a-n4-7-n3":{"title":"Cara Membuang Sampah","topic":"Kehidupan","trans":["Sejak mulai tinggal di Jepang, hal yang paling mengejutkanku adalah cara membuang sampahnya yang sangat rinci. Meski sama-sama sampah, cara membuangnya berbeda-beda tergantung jenisnya, jadi awalnya aku bingung. Sampah harus dipilah menjadi 「燃えるごみ」(sampah mudah terbakar), 「燃えないごみ」(sampah tidak mudah terbakar), 「資源ごみ」(sampah daur ulang), dan sebagainya.","Hari pembuangannya juga ditentukan menurut jenis sampah. Di kotaku, sampah mudah terbakar dibuang pada hari Senin dan Kamis. Kami diminta membawa sampah ke tempat yang ditentukan paling lambat pukul delapan pagi. Kalau cara memilah atau waktunya salah, kadang sampahnya tidak diambil. Karena itu, penting untuk mengeceknya sekali lagi sebelum membuang sampah.","Awalnya aku harus mencari tahu setiap kali, dan rasanya merepotkan. Tapi setelah terbiasa, aku sadar ternyata tidak sesulit itu. Kalau sudah jadi kebiasaan sehari-hari, kita bisa memilah dengan sendirinya tanpa perlu berpikir.","Berkat pemilahan sampah, kota selalu terjaga bersih. Walaupun repot, kalau ingat bahwa ini aturan yang dijaga bersama-sama, aku jadi ingin terus melakukannya."],"vocab":["terkejut, kaget","rinci, detail","jenis","bingung","menentukan, memutuskan","pengecekan, memastikan","repot, merepotkan","terbiasa","kebiasaan","menjaga, mempertahankan"],"grammar":[{"t":"〜によって","note":"Artinya 'tergantung ~' atau 'berdasarkan ~'. Contoh: 「種類によって出し方が変わるため」"},{"t":"〜わけではない","note":"Artinya 'bukan berarti ~'. Ini adalah bentuk negasi sebagian. Contoh: 「それほど難しいわけではないことが分かりました」"},{"t":"〜ようになる","note":"Menyatakan perubahan kemampuan atau keadaan, 'jadi bisa ~'. Contoh: 「自然に分けられるようになります」"},{"t":"〜おかげで","note":"Artinya 'berkat ~', dipakai saat suatu sebab membawa hasil yang baik. Contoh: 「分別のおかげで」"}]},"a-n5-1-n2":{"title":"Satu Hariku","topic":"Kehidupan sehari-hari","trans":["Setiap pagi aku bangun jam enam, cuci muka, lalu sarapan. Itu sudah jadi kebiasaanku. Jam setengah delapan aku berangkat dari rumah dan naik kereta ke kantor untuk berangkat kerja. Kerja mulai jam sembilan, tapi supaya tidak terlambat, aku selalu berusaha berangkat lebih awal.","Makan siang biasanya makan ramen di warung dekat kantor. Rasanya enak sekali, jadi aku puas. Setelah selesai kerja jam enam sore, aku langsung pulang dan memasak makan malam. Dengan masak sendiri dan tidak bergantung pada makan di luar, rasanya aku bisa menjaga ritme hidup meskipun sibuk.","Malam hari aku belajar bahasa Jepang sebentar, lalu tidur jam sebelas. Meskipun tidak bisa belajar lama-lama, menurutku yang penting adalah terus melakukannya setiap hari. Akhir pekan hampir tidak ada pekerjaan, jadi waktuku lebih longgar. Seiring dengan itu, aku mengisi akhir pekan dengan jalan-jalan di taman bersama teman atau nonton film.","Setiap hari memang sibuk, tapi bukan berarti tidak ada hal yang menyenangkan. Aku senang sekali karena bisa merasakan bahasa Jepangku membaik sedikit demi sedikit. Kalau terus begini, aku pasti bisa bicara lebih alami."],"vocab":["kebiasaan","pulang-pergi kerja","puas","makan di luar","bergantung","menjaga, mempertahankan","kelonggaran, waktu luang","menghabiskan (waktu)","merasakan langsung"],"grammar":[{"t":"〜ことにしている","note":"Menyatakan kebiasaan atau prinsip yang kamu putuskan sendiri dan terus dijalankan. Contoh: 「十一時に寝ることにしています」。"},{"t":"〜に伴って","note":"Menyatakan bahwa seiring perubahan satu hal, hal lain juga ikut terjadi. Di teks ini 「それに伴って」 dipakai untuk menyambung kalimat sebelumnya. Contoh: 「それに伴って、友達と公園を散歩したり、映画を見たりして過ごしています」。"},{"t":"〜からといって〜とは限らない","note":"Artinya \"belum tentu begitu hanya karena ada alasan tertentu\", dipakai untuk meluruskan anggapan umum. Contoh: 「忙しいからといって楽しみがないとは限りません」。"},{"t":"〜ず(に)","note":"Bentuk tulis dari 「ない」, menyatakan tidak melakukan sesuatu dan melakukan hal lain; sama dengan 「〜ないで」. Contoh: 「外食に頼らず自分で作ることで」。"}]},"a-n5-1-n3":{"title":"Satu Hariku","topic":"Kehidupan sehari-hari","trans":["Setiap pagi aku bangun jam enam, cuci muka, lalu sarapan. Aku berusaha menjaga kebiasaan ini. Jam setengah delapan aku berangkat dari rumah. Karena naik kereta ke kantor, pagi hari aku tidak bisa santai. Kerja mulai jam sembilan, jadi aku biasa berangkat lebih awal supaya tidak terlambat.","Siang hari aku pergi ke warung dekat kantor dan makan ramen. Ramennya enak banget, jadi aku semangat lagi untuk sore hari. Setelah selesai kerja jam enam sore, aku langsung pulang dan memasak makan malam.","Malam hari aku belajar bahasa Jepang sebentar, lalu tidur jam sebelas. Akhir pekan hampir tidak ada pekerjaan, jadi waktuku lebih longgar. Aku mengisinya dengan jalan-jalan di taman bersama teman atau nonton film.","Setiap hari memang sibuk, tapi berkat terus belajar, bahasa Jepangku membaik sedikit demi sedikit. Meski hari-hariku sibuk, aku senang karena bisa merasakan diriku berkembang."],"vocab":[{"w":"通って","m":"pulang-pergi (kerja/sekolah) (kata kerja「通う」)"},{"w":"遅れない","m":"tidak terlambat (kata kerja「遅れる」)"},{"w":"早めに","m":"lebih awal, agak cepat"},{"w":"気持ち","m":"perasaan, suasana hati"},{"w":"頑張ろう","m":"ayo semangat, berusaha (kata kerja「頑張る」)"},{"w":"余裕","m":"kelonggaran, waktu luang"},{"w":"過ごします","m":"menghabiskan (waktu)"},{"w":"続ける","m":"melanjutkan, terus"},{"w":"成長","m":"pertumbuhan, perkembangan"}],"grammar":[{"t":"〜ようにしている","note":"Menyatakan kebiasaan yang diusahakan untuk dijaga atau dilakukan. Contoh: 「朝ごはんを食べるようにしています」"},{"t":"〜ことにしている","note":"Menyatakan kebiasaan yang kamu putuskan sendiri dan terus dijalankan. Contoh: 「早めに出かけることにしています」"},{"t":"〜ため","note":"Menyatakan sebab atau alasan, nuansanya lebih formal/tertulis daripada 「から」. Contoh: 「電車で会社へ通っているため、朝はあまりゆっくりできません」"},{"t":"〜によって","note":"Menyatakan cara atau sarana, \"dengan\" atau \"melalui\". Contoh: 「勉強を続けることによって、少しずつ日本語が上手になってきました」"}]},"a-n5-2-n2":{"title":"Sarapan di Jepang","topic":"Budaya","trans":["Kalau bicara soal sarapan tradisional Jepang, yang umum adalah paduan makanan Jepang (washoku) dengan nasi dan sup miso sebagai intinya. Biasanya ditambah ikan bakar atau hidangan telur, dan cirinya adalah gizinya yang seimbang. Nori (rumput laut kering) juga sudah lama populer dan bisa dibilang lauk nasi yang selalu ada di meja makan. Karena praktis tetapi tetap kaya rasa, sarapan ini sudah lama disukai banyak keluarga.","Namun, belakangan ini seiring perubahan gaya hidup, semakin banyak orang yang sarapan dengan roti dan kopi. Kecenderungan ini terutama kuat di kalangan generasi muda, dan tidak sedikit yang lebih suka sarapan ala Barat. Tentu saja, tidak semua anak muda memilih roti, dan selera berbeda-beda untuk tiap orang. Meski begitu, pilihan sarapan jelas lebih beragam dibanding dulu.","Di pagi hari yang sibuk, ada orang yang tidak sempat menyiapkan makanan dan cukup makan satu onigiri saja. Demi tidak terlambat ke kantor atau sekolah, mungkin ada kalanya sarapan terpaksa dibuat sesederhana mungkin. Gaya sarapan di Jepang memang makin beragam seperti ini, lalu bagaimana di negaramu? Kamu biasanya sarapan apa?","Kalau saya sendiri, meskipun sarapan roti dan kopi sedang populer, saya tetap suka nasi dan sup miso. Soalnya kalau sarapan dengan benar di pagi hari, tubuh dan pikiran jadi terbangun, dan kita bisa menjalani hari dengan penuh semangat. Menurut saya, sarapan bukan sekadar kebiasaan, tetapi waktu penting untuk menyiapkan kondisi sepanjang hari."],"vocab":["tradisional","tak tergantikan, harus ada","disukai, akrab di hati","belakangan ini, beberapa tahun terakhir","kecenderungan, tren","pilihan","kelonggaran (waktu/tenaga)","diversifikasi, jadi beragam","menyiapkan, mengatur","menyelesaikan seadanya, cukup dengan"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring satu hal berubah, hal lain ikut berubah. Contoh: 「生活スタイルの変化に伴って、パンとコーヒーで朝食を済ませる人も増えています」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu\" atau \"tidak selalu begitu\", dipakai untuk menyangkal generalisasi yang berlebihan. Contoh: 「若い人がみなパンを選ぶとは限らず、好みは人によってさまざまです」"},{"t":"〜ざるを得ない","note":"Berarti terpaksa melakukan sesuatu karena keadaan. Contoh: 「朝食を簡単にせざるを得ない場合もあるのでしょう」"},{"t":"〜に対して","note":"Menyatakan kontras, yaitu dua hal yang saling bertolak belakang. Contoh: 「パンとコーヒーの朝ごはんが人気であるのに対して、やはりごはんとみそしるが好きです」"}]},"a-n5-2-n3":{"title":"Sarapan di Jepang","topic":"Budaya","trans":["Kalau bicara soal sarapan tradisional Jepang, dasarnya adalah nasi dan sup miso. Banyak orang juga memakannya bersama ikan bakar, telur, nori, dan sebagainya, dan sarapan ini sudah disukai sejak dulu.","Belakangan ini, semakin banyak keluarga yang sarapan dengan roti dan kopi. Terutama di kalangan anak muda, sarapan ala Barat populer karena mudah dimakan.","Selain itu, pagi hari itu sibuk, jadi ada juga orang yang berangkat hanya dengan membawa onigiri. Soalnya, walaupun tidak ada waktu, onigiri bisa dimakan sambil berjalan.","Menurutku sarapan roti dan kopi juga praktis dan enak, tapi aku tetap suka nasi dan sup miso. Di negara kalian, sarapan seperti apa yang umum?","Kalau kita membiasakan makan dengan benar di pagi hari, kita bisa menjalani seharian dengan semangat. Karena itu, aku memutuskan untuk tetap sarapan walaupun di hari yang sibuk."],"vocab":["tradisional","dasar","menggabungkan, memadukan","akrab, disukai","keluarga, rumah tangga","praktis, mudah","ala Barat","umum","menyelesaikan seadanya, cukup dengan","menghabiskan (waktu), menjalani"],"grammar":[{"t":"〜といえば","note":"Berarti \"kalau bicara soal 〜\", dipakai untuk mengangkat topik. Contoh: 「日本の伝統的な朝ごはんといえば、ごはんとみそしるが基本です」"},{"t":"〜ため","note":"Menyatakan sebab atau alasan. Contoh: 「手軽に食べられるため、洋風の朝ごはんが人気があります」"},{"t":"〜ようにする","note":"Menyatakan usaha untuk membiasakan sesuatu atau berusaha melakukannya. Contoh: 「朝にしっかり食べるようにすると、一日を元気に過ごせます」"},{"t":"〜ことにしている","note":"Menyatakan kebiasaan yang diputuskan sendiri dan terus dilakukan. Contoh: 「忙しい日でも朝ごはんを食べることにしています」"}]},"a-n5-3-n2":{"title":"Foto Keluarga","topic":"Keluarga","trans":["Ini foto yang memperlihatkan keluargaku, sesuatu yang berharga karena setiap kali melihatnya, hatiku terasa hangat. Di dalam foto ada lima orang dan satu ekor anjing, dan suasana yang ramai itu terasa jelas hanya dari fotonya. Yang berdiri di tengah adalah orang tuaku: ayah bekerja sebagai karyawan kantoran, sedangkan ibu menjadi guru yang mengajar anak-anak.","Yang di sebelah kanan adalah kakak laki-lakiku. Dia seorang mahasiswa, dan kemampuan sepak bolanya menonjol di antara anggota keluarga. Sepak bola bagi kakakku sudah melampaui sekadar hobi, dan kemampuannya sampai membuat orang-orang di sekitarnya mau tidak mau mengakuinya. Anak kecil di sebelah kiri adalah adik perempuanku, usianya sembilan tahun, dan dia paling suka menggambar. Kakak dan adikku memang punya kesukaan yang berbeda, tapi aku merasa mereka mirip dalam hal bisa tenggelam dalam sesuatu yang disukai.","Kalau harus menyebutkan satu ciri khas keluargaku, itu adalah kami semua sangat menyayangi anjing dari lubuk hati. Yang ada di bagian depan foto adalah anjing kami, 「マロ」, yang merupakan bagian yang tak tergantikan bagi keluarga. Di hari libur, kami semua pergi ke taman dan berfoto bersama, dan tanpa terasa itu sudah jadi kebiasaan keluarga kami. Seiring bertambahnya waktu yang kami habiskan bersama anjing, jumlah foto pun mungkin bertambah dengan sendirinya.","Sekarang aku tinggal terpisah dari keluarga, jadi aku tidak bisa bertemu setiap hari seperti dulu. Meski begitu, aku berusaha menelepon mereka sebulan sekali, dan hanya dengan mendengar suara mereka aku sudah merasa tenang. Belum tentu perasaan ikut menjauh hanya karena jarak yang jauh. Bagiku, keluarga adalah harta yang tak tergantikan dan tak ada duanya, sekarang maupun selamanya."],"vocab":["suasana","kemampuan, keahlian","melampaui, melebihi","orang-orang di sekitar","tenggelam dalam sesuatu, asyik","tak tergantikan, tak boleh tidak ada","kebiasaan","berpisah, meninggalkan","tak tergantikan, tak ada duanya"],"grammar":[{"t":"〜ざるを得ない","note":"Artinya \"terpaksa…, tidak bisa tidak…\", dengan nuansa tidak bisa disangkal meski sebenarnya tidak mau. Contoh: 「その腕前は周囲も認めざるを得ないほどです」."},{"t":"〜に伴って","note":"Artinya \"seiring dengan…\"; ketika hal pertama berubah, hal kedua ikut berubah. Contoh: 「犬と一緒に過ごす時間に伴って、写真の枚数も自然と増えていったのかもしれません」."},{"t":"〜わけにはいかない","note":"Artinya \"tidak bisa…\" karena alasan kewajaran atau keadaan. Contoh: 「以前のように毎日顔を合わせるわけにはいきません」."},{"t":"〜とは限らない","note":"Artinya \"belum tentu…, tidak selalu…\", menyangkal pernyataan yang bersifat mutlak. Contoh: 「気持ちまで遠くなるとは限りません」."}]},"a-n5-3-n3":{"title":"Foto Keluarga","topic":"Keluarga","trans":["Ini foto keluargaku. Ada lima orang di dalamnya, dan foto ini salah satu yang paling kusukai. Yang berdiri di tengah foto adalah ayahku yang bekerja sebagai karyawan kantoran, dan ibuku yang berprofesi sebagai guru.","Yang berdiri di sebelah kanan adalah kakak laki-lakiku, sekarang dia seorang mahasiswa. Kakakku sangat jago main sepak bola, dan diam-diam aku juga bangga akan hal itu. Anak kecil di sebelah kiri adalah adik perempuanku, usianya baru sembilan tahun. Adikku suka menggambar, dan kalau ada waktu luang, dia sering menggambar.","Keluargaku mirip dalam hal kami semua sangat suka anjing. Yang ada di depan foto adalah anjing peliharaan kami, 「マロ」. Di hari libur, kami memutuskan untuk pergi ke taman bersama-sama dan berfoto.","Karena sekarang tinggal terpisah, kami tidak bisa bertemu setiap hari. Meski begitu, aku berusaha menelepon mereka sebulan sekali. Bagiku, keluarga adalah harta paling berharga, lebih dari apa pun."],"vocab":["terfoto, tertangkap dalam foto","karyawan kantoran","jago, mahir","kebanggaan","memelihara (hewan)","pergi keluar","berpisah, meninggalkan","harta berharga","suka, merasa cocok"],"grammar":[{"t":"〜として","note":"Menyatakan \"sebagai…\" (kedudukan atau kapasitas). Contoh: 「会社員として働いている父」 artinya ayah bekerja sebagai karyawan kantoran."},{"t":"〜ため(sebab)","note":"Menyatakan sebab atau alasan, dengan nuansa lebih formal/tulisan daripada 「から」. Contoh: 「今は離れて住んでいるため、毎日会うことはできません」."},{"t":"〜ことにしている","note":"Menyatakan keputusan sendiri yang sudah menjadi kebiasaan, \"selalu memutuskan begitu\". Contoh: 「写真を撮ることにしています」."},{"t":"〜ようにしている","note":"Menyatakan usaha agar terus melakukan sesuatu. Contoh: 「月に一度は電話で話すようにしています」."}]},"a-n5-4-n2":{"title":"Minimarket yang Menopang Kehidupan","topic":"Kehidupan sehari-hari","trans":["Aku hampir setiap hari pergi ke minimarket. Karena letaknya persis di sebelah kantor, mampir ke sana tidak merepotkan dan sangat praktis. Di pagi hari aku sering membeli onigiri dan kopi. Totalnya sekitar tiga ratus yen, jadi dompet pun aman. Bisa menyelesaikan sarapan dengan harga murah dan gampang adalah daya tarik yang tidak bisa diabaikan bagi karyawan kantoran yang sibuk.","Peran minimarket tidak hanya sebatas untuk berbelanja. Di sana kamu juga bisa membayar tagihan listrik dan air. Kamu juga bisa mengirim paket dan mengambil uang tunai, jadi sangat membantu bagi orang yang tidak punya waktu untuk pergi ke tempat lain secara khusus. Berkat layanan-layanan ini terkumpul di satu tempat, urusan sehari-hari bisa selesai dalam waktu singkat.","Kalau malam-malam perut terasa lapar, aku sering membeli oden hangat lalu membawanya pulang. Oden sangat populer terutama di musim dingin, dan seiring udara yang makin dingin, pembelinya tampaknya juga makin banyak. Belakangan papan petunjuk berbahasa asing juga bertambah, dan lingkungan yang ramah bagi orang yang datang dari luar negeri pun perlahan terbentuk. Bahkan bagi orang yang belum lancar membaca bahasa Jepang, kini lebih mudah mencari barang yang dibutuhkan. Ini perubahan yang besar.","Meskipun hanya toko kecil, minimarket bisa menyelesaikan berbagai urusan sekaligus. Justru karena pilihan barang dan layanannya lengkap, banyak orang datang hampir setiap hari. Kini, sebagai sesuatu yang menopang kehidupan di Jepang, harus diakui bahwa minimarket sudah menjadi hal yang tidak tergantikan."],"vocab":["bolak-balik, rutin datang","mampir (dalam perjalanan)","berada dalam kisaran (jumlah, batas)","keuangan rumah tangga","tagihan layanan publik (listrik, air, gas, dll.)","membayar","lengkap, memadai","papan petunjuk","tertata, siap","membeli (bahasa tulis)"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring satu hal berubah, hal lain ikut berubah. Contoh: 「寒さが厳しくなるに伴って、買い求める客も増えていくようだ」"},{"t":"〜に対して","note":"Menyatakan sasaran atau objek: \"terhadap…\", \"bagi…\". Contoh: 「外国から来た人に対しても親切な環境が整いつつある」"},{"t":"〜にもかかわらず","note":"Menyatakan hal yang berlawanan dengan dugaan: \"meskipun…, tetapi…\". Contoh: 「コンビニは小さな店であるにもかかわらず、実にさまざまな用事をまとめて済ませることができる」"},{"t":"〜ざるを得ない","note":"Menyatakan bahwa secara logika tidak bisa lain selain mengakui atau melakukan…: \"mau tidak mau harus…\". Contoh: 「なくてはならないものになっていると言わざるを得ない」"}]},"a-n5-4-n3":{"title":"Belanja di Minimarket","topic":"Kehidupan sehari-hari","trans":["Aku hampir setiap hari pergi ke minimarket itu. Karena letaknya di sebelah kantor, bahkan saat tidak punya waktu pun aku bisa mampir dengan mudah. Sangat praktis.","Di pagi hari aku biasa membeli onigiri dan kopi. Totalnya sekitar tiga ratus yen, jadi untuk ukuran sarapan tidak terlalu mahal.","Di minimarket, kamu juga bisa membayar tagihan seperti listrik dan air. Selain itu, kamu juga bisa mengirim paket dan mengambil uang tunai, jadi sangat berguna dalam kehidupan sehari-hari. Bagi orang yang tidak punya waktu pergi ke bank atau kantor pos, ini sangat membantu.","Kalau malam-malam perut lapar, aku membeli oden hangat. Oden sangat populer terutama saat musim dingin, dan di hari yang dingin banyak orang datang untuk membelinya. Belakangan petunjuk berbahasa asing juga bertambah, jadi minimarket makin mudah dipakai oleh orang yang datang dari luar negeri. Meskipun hanya toko kecil, banyak hal bisa dilakukan di sana, jadi menurutku minimarket adalah sesuatu yang tidak bisa dilepaskan dari kehidupan di Jepang."],"vocab":["pergi ke, datang ke","santai, tanpa sungkan","khusus, istimewa","pembayaran","paket kurir","mengambil (uang dari rekening)","bantuan","populer","petunjuk, panduan, informasi","tidak tergantikan"],"grammar":[{"t":"〜ため","note":"Menyatakan sebab atau alasan, sedikit lebih formal daripada「ので」. Contoh: 「会社のとなりにあるため、時間がないときでも気軽に寄れて」"},{"t":"〜ことにしている","note":"Menyatakan kebiasaan yang diputuskan sendiri dan terus dijalankan. Contoh: 「朝はおにぎりとコーヒーを買うことにしています」"},{"t":"〜わけではない","note":"Berarti \"bukan berarti…\", negasi sebagian untuk menghindari salah paham. Contoh: 「朝ごはんとして特別高いわけではありません」"},{"t":"〜ものの","note":"Berarti \"meskipun…, tetapi…\", dua bagian kalimat saling berlawanan. Contoh: 「小さな店ではあるものの、いろいろなことができるので」"}]},"a-n5-5-n2":{"title":"私が暮らす町","topic":"Kehidupan","trans":["Aku tinggal di sebuah kota kecil dekat laut, dan karena dekat dengan laut, udaranya sangat bersih. Memang tidak ada gedung-gedung besar di kota ini, tetapi fasilitas yang tak tergantikan untuk kehidupan sehari-hari seperti kantor pos, rumah sakit, dan supermarket kurang lebih sudah lengkap. Dibandingkan dengan kota besar yang gemerlap, mungkin kota ini terlihat sederhana, tetapi menurutku keberadaan hal-hal yang dibutuhkan di dekat kita memberi rasa aman dalam keseharian.","Dari stasiun ke rumah jaraknya sekitar sepuluh menit berjalan kaki, jadi hampir tidak pernah ada kesulitan dalam bepergian. Di tengah jalan ada sungai yang mengalir, dan aku tidak bisa sampai ke rumah tanpa menyeberangi jembatan. Di sepanjang tepi sungai berjajar pohon sakura yang mekar dengan indah saat musim semi tiba. Pada musim itu, banyak orang datang untuk melihat bunga sakura, dan tepi sungai yang biasanya sepi pun seketika menjadi ramai.","Di dekat sini juga ada kuil tua, dan begitu masuk ke halamannya, entah kenapa hati terasa tenang. Waktu yang dihabiskan dalam keheningan adalah sesuatu yang berharga karena membuat kita lupa akan kesibukan sehari-hari. Di sisi lain, soal berbelanja, harus kuakui agak kurang praktis. Soalnya, belum tentu semua barang yang kita inginkan bisa didapat di sekitar sini.","Meski begitu, semua orang di kota ini ramah, dan suasana yang nyaman terasa di seluruh kota. Menurutku, kehangatan orang-orangnya lebih dari cukup untuk menutupi ketidakpraktisan itu, dan itulah pesona kota ini. Karena alasan-alasan inilah aku sangat menyukai kota ini dan ingin terus tinggal di sini selamanya."],"vocab":["tak tergantikan, sangat penting","fasilitas","kurang lebih, secara garis besar","jarak","tepi sungai, sepanjang sungai","indah, memukau","tujuan, demi…","halaman kuil/kuil Shinto","berharga","menutupi, melengkapi"],"grammar":[{"t":"〜こそ〜が","note":"Menekankan \"memang benar…, tetapi…\": mengakui satu hal dulu, lalu diikuti kontras. Contoh: 「大きなビルこそありませんが、郵便局や病院、スーパーなど、暮らしに欠かせない施設は一通りそろっています」"},{"t":"〜に比べれば","note":"Kalau dibandingkan dengan…; dipakai untuk menyebutkan patokan perbandingan. Contoh: 「華やかな都会に比べれば地味かもしれませんが、必要なものが身近にあることは、日々の安心感につながっていると感じます」"},{"t":"〜ざるを得ない","note":"Terpaksa…, tidak bisa tidak…; menunjukkan tidak ada pilihan lain. Contoh: 「買い物に関しては少し不便だと言わざるを得ません」"},{"t":"〜とは限らない","note":"Belum tentu…, tidak selalu…; menyangkal pernyataan yang bersifat mutlak. Contoh: 「欲しいものがすべて近所で手に入るとは限らないからです」"}]},"a-n5-5-n3":{"title":"私の町","topic":"Kehidupan","trans":["Aku tinggal di sebuah kota kecil dekat laut, dan aku suka karena udaranya bersih. Berkat dekat dengan laut, rasanya setiap hari bisa dilalui dengan nyaman. Di kota ini tidak ada gedung besar, tetapi hal-hal yang dibutuhkan seperti kantor pos, rumah sakit, dan supermarket semuanya ada.","Jalan dari stasiun ke rumah memang pendek, tetapi aku senang berjalan sambil menikmati pemandangan sungai dan jembatan. Dari stasiun ke rumah sekitar sepuluh menit berjalan kaki, dan karena di tengah jalan ada sungai, aku pulang dengan menyeberangi jembatan. Kalau musim semi tiba, pohon sakura di tepi sungai jadi sangat indah, dan banyak orang datang untuk melihat bunga sakura. Di dekat sini juga ada kuil tua, dan saat menghabiskan waktu dengan tenang di sana, hati pun dengan sendirinya menjadi tenang.","Soal belanja, kadang terasa agak kurang praktis, tetapi bukan masalah besar. Semua orang di kota ini ramah, jadi menurutku ini kota yang sangat nyaman untuk ditinggali.","Aku sangat suka kota ini, jadi aku memutuskan untuk terus tinggal di sini ke depannya. Soalnya, menurutku meskipun tidak ada kemudahan seperti di kota besar, asalkan ada kebaikan hati orang-orang dan alam, itu sudah cukup."],"vocab":["udara","kantor pos","perlu, diperlukan","di tengah jalan","jembatan","mengunjungi, datang","menjadi tenang","tidak praktis, tidak nyaman","ramah, baik hati","hidup, tinggal"],"grammar":[{"t":"〜ため(に)","note":"Menyatakan sebab atau tujuan. 「川があるため」 adalah sebab, 「花見のために」 adalah tujuan. Lebih tertulis dan formal daripada 「〜から」."},{"t":"〜ように","note":"Menyatakan \"supaya mencapai suatu keadaan\" atau \"seperti…\". Contoh: 「毎日気持ちよく過ごせるように感じています」, di sini dipakai setelah bentuk potensial untuk menggambarkan keadaan yang dirasakan."},{"t":"〜わけではない","note":"Berarti \"bukan berarti…\"; negasi sebagian. Contoh: 「大きな問題というわけではありません」."},{"t":"〜ことにする","note":"Menyatakan keputusan pembicara sendiri untuk melakukan sesuatu. Contoh: 「ここで暮らすことにしています」, bentuk 「ている」 menunjukkan tekad ini masih berlanjut."}]},"a-n5-6-n2":{"title":"Hobiku adalah Fotografi","topic":"Hobi","trans":["Hobiku adalah memotret. Di hari libur, berjalan-jalan di kota sambil membawa kamera sudah menjadi kesenangan terbesarku. Aku tidak punya tujuan tertentu; aku hanya berjalan sesuka hati dan mengarahkan lensa ke apa pun yang menarik perhatianku. Yang paling sering kupotret adalah bunga dan burung, dan aku juga merasa seru melihat objek foto yang ikut berubah seiring pergantian musim.","Rasa senang saat berhasil mendapatkan satu foto yang sesuai harapan itu besar sekali, dan menurutku justru karena rasa senang itulah aku tidak bisa berhenti dari hobi ini. Tentu saja, tergantung komposisi dan pencahayaan, kesan sebuah foto bisa berbeda total meski diambil di tempat yang sama. Saat berhasil memotret foto yang bahkan aku sendiri puas melihatnya, aku sampai lupa waktu dan berkali-kali melihat layarnya lagi. Semakin bagus hasil sebuah foto, semakin wajar kalau kita ingin orang lain melihatnya.","Karena itu, sesekali aku mengirim foto ke teman-teman dan meminta mereka memberi pendapat. Teman-temanku selalu memuji, \"Bagus ya,\" dan itu jadi penyemangat untuk pemotretan berikutnya. Dengan memperlihatkannya ke orang lain, kadang aku juga bisa menyadari kelebihan foto yang tidak kusadari sendiri. Sebaliknya, kalau tidak ada kesempatan untuk memperlihatkannya ke orang lain, mungkin aku tidak akan bisa menekuninya dengan sesemangat ini.","Belakangan ini, aku jadi ingin punya kamera baru dengan performa yang lebih bagus. Tapi kamera sama sekali bukan barang murah, jadi untuk saat ini aku terpaksa menyerah untuk langsung membelinya. Karena itu, sekarang aku menabung sedikit demi sedikit sambil menantikan datangnya hari ketika aku bisa membelinya."],"vocab":["sesuka hati, mengikuti suasana hati","menarik perhatian, tertangkap mata","pergantian, perubahan","objek foto","komposisi","tingkat, takaran, kondisi (misalnya pencahayaan)","puas","penyemangat, dorongan","kesan, pendapat","performa, spesifikasi"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring berubahnya satu hal, hal lain ikut berubah. Contoh: 「季節の移り変わりに伴って被写体が変わっていく」"},{"t":"〜ざるを得ない","note":"Menyatakan tidak ada pilihan lain selain melakukan hal itu, jadi terpaksa. Contoh: 「今はすぐに買うのをあきらめざるを得ない」"},{"t":"〜からこそ","note":"Menegaskan bahwa justru karena alasan inilah hasil di belakangnya terjadi. Contoh: 「それがあるからこそ、この趣味をやめられない」"},{"t":"〜によって","note":"Menyatakan bahwa hasilnya berbeda tergantung kondisinya. Contoh: 「構図や光の加減によって、同じ場所でも写真の印象はまったく違ったものになってしまう」"}]},"a-n5-6-n3":{"title":"Hobiku adalah Fotografi","topic":"Hobi","trans":["Hobiku adalah memotret, dan di hari libur aku berusaha pergi keluar sambil membawa kamera. Berjalan pelan-pelan di kota sambil mencari hal-hal yang menarik perhatianku adalah salah satu kesenanganku. Aku sering memotret bunga dan burung, dan ternyata mengejar benda yang bergerak itu cukup susah.","Saat berhasil memotret foto indah sesuai bayanganku, aku benar-benar senang. Karena itu, memotret ulang berkali-kali pun bukan hal yang jarang. Foto yang sudah kuambil biasanya sesekali kukirim ke teman. Kalau teman bilang, \"Bagus ya,\" aku jadi ingin memotret lagi.","Aku ingin kamera baru, tapi harganya mahal, jadi tidak bisa langsung kubeli. Karena itu, sekarang aku sedang menabung untuk kamera baru. Menurutku, waktu menunggu barang yang kita inginkan juga bagian dari serunya sebuah hobi."],"vocab":["hobi, kegemaran","menarik perhatian, jadi pikiran","mencari","mengejar","ternyata, di luar dugaan","memotret ulang","tidak sedikit, sering terjadi","harga","menabung (uang)","perasaan, suasana hati"],"grammar":[{"t":"〜ようにしている","note":"Menyatakan kebiasaan yang diusahakan untuk selalu dilakukan. Contoh: 「休みの日にはカメラを持って出かけるようにしています」"},{"t":"〜ことにしている","note":"Menyatakan aturan atau kebiasaan yang diputuskan sendiri dan terus dijalankan. Contoh: 「撮った写真は、ときどき友達に送ることにしています」"},{"t":"〜ため(原因)","note":"Dipakai untuk menjelaskan sebab atau alasan; nuansanya lebih formal/tulisan dibandingkan 「から」. Contoh: 「値段が高いため、すぐに買えるわけではありません」"},{"t":"〜わけではない","note":"Negasi sebagian, artinya \"bukan berarti ...\". Contoh: 「値段が高いため、すぐに買えるわけではありません」"}]},"a-n5-7-n2":{"title":"Mengirim Paket di Kantor Pos","topic":"Kehidupan sehari-hari","trans":["Hari ini aku memutuskan pergi ke kantor pos untuk mengirim paket ke Taiwan. Saat aku bilang di loket, 「これを台湾までお願いします」 (\"Tolong kirim ini sampai Taiwan\"), petugas bertanya soal cara pengirimannya. Ada dua cara mengirim paket, yaitu lewat kapal dan lewat udara, dan kita harus memilih salah satunya.","Aku ditanya, 「船便ですか、航空便ですか」 (\"Lewat kapal atau lewat udara?\"), lalu sedikit bimbang karena membandingkan biaya dan jumlah harinya. Pengiriman lewat kapal biayanya murah, tetapi di sisi lain butuh sekitar satu bulan sampai tiba. Sebaliknya, lewat udara cepat sampai, sedangkan biayanya dipasang lebih tinggi. Jadi, kalau memilih murah, butuh waktu lama; kalau memilih cepat, biayanya membengkak.","Aku merasa terpaksa mengutamakan waktu, jadi aku memilih pengiriman lewat udara. Berikutnya, aku menulis nama dan alamat di formulir, lalu setelah selesai aku membayar. Waktu kutanya kapan paketnya akan sampai, aku diberi tahu sekitar satu minggu. Namun, ini hanya perkiraan, dan belum tentu paket pasti sampai dalam jumlah hari itu.","Dalam perjalanan pulang, aku mampir ke minimarket, membeli perangko, dan sekalian mengirim kartu pos. Urusan bisa beres bukan hanya di kantor pos, tapi juga di minimarket, dan itu sangat membantu orang yang sibuk. Mendengar kata mengirim paket ke luar negeri, kedengarannya sulit, tetapi kalau sudah tahu langkah-langkahnya, ternyata cukup mudah."],"vocab":["loket, meja layanan","pengiriman lewat kapal","pengiriman lewat udara","biaya, tarif","sampai, tiba (kiriman)","prioritas, mengutamakan","formulir, lembar kertas","alamat","patokan, perkiraan","langkah, prosedur"],"grammar":[{"t":"〜反面","note":"Menunjukkan bahwa satu hal punya dua sisi yang berlawanan sekaligus (\"di satu sisi..., di sisi lain...\"). Contoh: 「船便は料金が安い反面、届くまでに一か月ほどかかります」"},{"t":"〜に対して","note":"Dipakai untuk membandingkan/mengontraskan dua hal (\"sedangkan\", \"sebaliknya\"). Contoh: 「航空便は早く届くのに対して、料金は高めに設定されています」"},{"t":"〜ざるを得ない","note":"Berarti tidak ada pilihan lain selain melakukannya, \"terpaksa\". Contoh: 「私は時間を優先せざるを得ないと考え、航空便を選びました」"},{"t":"〜とは限らない","note":"Berarti belum tentu selalu begitu, ada kemungkinan pengecualian. Contoh: 「必ずその日数で届くとは限りません」"}]},"a-n5-7-n3":{"title":"Mengirim Paket di Kantor Pos","topic":"Kehidupan sehari-hari","trans":["Hari ini aku memutuskan pergi ke kantor pos sambil membawa paket yang akan dikirim ke Taiwan. Setelah aku bilang di loket, 「これを台湾までお願いします」 (\"Tolong kirim ini sampai Taiwan\"), petugas melayaniku dengan ramah. Karena ditanya 「船便ですか、航空便ですか」 (\"Lewat kapal atau lewat udara?\"), aku harus memilih cara pengirimannya.","Pengiriman lewat kapal tarifnya murah, jadi cocok untuk orang yang ingin berhemat. Tapi bukan berarti pengiriman lewat kapal itu buruk; katanya butuh sekitar satu bulan sampai tiba. Di sisi lain, pengiriman lewat udara cepat sampai, tetapi tarifnya jadi lebih mahal sebagai gantinya. Cara yang dipilih berbeda-beda, tergantung kamu lebih mementingkan harga murah atau kecepatan.","Aku berpikir lebih baik cepat walaupun agak mahal, jadi aku memilih pengiriman lewat udara. Setelah menulis nama dan alamat di formulir, aku membayar tarifnya. Waktu kutanya 「いつ届きますか」 (\"Kapan sampainya?\"), aku diberi tahu sekitar satu minggu.","Dalam perjalanan pulang, aku memutuskan mampir ke minimarket untuk membeli perangko yang dibutuhkan. Lalu, aku menempelkan perangko yang baru saja kubeli, dan sekalian mengirim kartu pos."],"vocab":["loket, meja layanan","petugas, orang yang bertanggung jawab","pengiriman lewat kapal","pengiriman lewat udara","biaya, tarif","hemat, penghematan","formulir, lembar kertas","alamat","sampai, tiba (kiriman)","perangko"],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan yang dibuat sendiri (\"memutuskan untuk...\"). Contoh: 「今日は台湾へ送る荷物を持って、郵便局へ行くことにしました」"},{"t":"〜ため","note":"Menyatakan sebab atau alasan, lebih formal daripada 「から」. Contoh: 「船便は料金が安いため、お金を節約したい人にはいい方法です」"},{"t":"〜わけではない","note":"Berarti \"bukan berarti...\", negasi sebagian. Contoh: 「船便が悪いわけではなく、届くまでに一か月ぐらいかかるそうです」"},{"t":"〜によって","note":"Berarti \"tergantung pada...\", hasilnya berbeda sesuai kondisi. Contoh: 「安さと早さのどちらを大切にするかによって、選ぶ方法は変わります」"}]},"a-n5-8-n2":{"title":"Membuka Rekening di Bank","topic":"Kehidupan","trans":["Hari ini aku pergi ke bank untuk membuat rekening bank yang sangat penting untuk memulai hidup di Jepang. Petugas di loket berkata, \"Tolong berikan kartu izin tinggal (在留カード) dan stempel,\" jadi aku mengeluarkannya dari tas. Saat orang asing membuka rekening, prosesnya tidak bisa dilanjutkan kalau tidak ada dokumen yang membuktikan identitas.","Selanjutnya, aku harus menulis nama, alamat, dan nomor telepon di formulir. Kanjinya sulit dan aku merasa tidak boleh salah tulis, jadi aku meluangkan waktu dan menulis huruf demi huruf dengan hati-hati. Bagi orang yang bahasa ibunya bukan bahasa Jepang, mengisi dokumen resmi itu jauh lebih menguras pikiran daripada yang dibayangkan. Meskipun berjejer kanji yang belum biasa, kalau menulis dengan tenang tanpa panik, kesalahan pasti bisa dicegah.","Setelah selesai menulis, petugas menjelaskan kartu ATM dengan rinci. Katanya, \"Kartu ATM akan sampai di rumah sekitar dua minggu lagi,\" jadi aku tahu kartunya belum bisa langsung dipakai. Di sisi lain, buku tabungan bisa kuterima pada hari itu juga. Karena ini buku tabungan pertama yang kupegang di Jepang, meskipun hanya buku kecil, aku merasakan bobot yang istimewa.","Selama proses, aku terus merasa tegang, tetapi akhirnya aku bisa menyelesaikannya sampai akhir hanya dengan bahasa Jepang. Saat tinggal di luar negeri, tidak sedikit situasi di mana kita terpaksa menyerah karena kendala bahasa. Justru karena itu, pengalaman kali ini memberiku rasa percaya diri yang besar, dan kekhawatiranku tentang hidup ke depan pun sedikit berkurang."],"vocab":["rekening","tak tergantikan, sangat penting","loket, bagian layanan","petugas, penanggung jawab","mengisi, menuliskan","bahasa ibu","menguras pikiran, butuh perhatian ekstra","buku tabungan","tegang, gugup"],"grammar":[{"t":"〜わけにはいかない","note":"Menyatakan tidak bisa melakukan sesuatu karena posisi atau tuntutan keadaan. Contoh: 「書き間違えるわけにはいかないと思ったので」 artinya karena merasa tidak boleh salah tulis."},{"t":"〜にとって","note":"Menyatakan sudut pandang seseorang. Contoh: 「日本語を母語としない人にとって」 artinya bagi orang yang bahasa ibunya bukan bahasa Jepang."},{"t":"〜にもかかわらず","note":"Menyatakan bahwa meski hal pertama demikian, hasilnya justru berlawanan. Contoh: 「小さな冊子にもかかわらず」 artinya meskipun hanya buku kecil."},{"t":"〜ざるを得ない","note":"Menyatakan terpaksa melakukan sesuatu karena tidak ada pilihan lain. Contoh: 「諦めざるを得ない場面も少なくありません」 artinya tidak sedikit situasi di mana kita terpaksa menyerah."}]},"a-n5-8-n3":{"title":"Membuka Rekening di Bank","topic":"Kehidupan","trans":["Hari ini aku pergi ke bank terdekat untuk membuat rekening bank yang dibutuhkan untuk kehidupan baru. Petugas di loket meminta kartu izin tinggal (在留カード) dan stempel, jadi aku langsung mengeluarkannya.","Selanjutnya, aku diminta menulis nama, alamat, dan nomor telepon di formulir. Karena kanjinya sulit dan aku kurang percaya diri, aku menulis pelan-pelan supaya tidak salah. Aku merasa bagi orang asing, prosedur yang harus ditulis dengan kanji ternyata cukup berat.","Aku diberi tahu bahwa kartu ATM akan sampai di rumah sekitar dua minggu lagi. Di sisi lain, buku tabungan bisa kuterima pada hari itu juga. Karena ini buku tabungan pertama yang kupegang sejak datang ke Jepang, rasanya sangat istimewa.","Selama prosesnya aku agak tegang, tetapi yang paling membuatku senang adalah aku bisa menyelesaikan semuanya hanya dengan bahasa Jepang. Berkat pengalaman ini, aku jadi sedikit lebih percaya diri menjalani hidup di Jepang."],"vocab":["rekening","loket, bagian layanan","kartu izin tinggal","stempel pribadi","formulir, kertas","prosedur, urusan administrasi","buku tabungan","sampai, tiba","tegang, gugup","percaya diri"],"grammar":[{"t":"〜ように言われる","note":"Menyatakan diminta atau diperintah melakukan sesuatu. Contoh dalam teks: 「用紙に名前と住所と電話番号を書くように言われました」"},{"t":"〜ため(に)","note":"Menyatakan sebab atau alasan, lebih formal daripada「ので」. Contoh dalam teks: 「漢字が難しくて自信がなかったため、間違えないようにゆっくり書きました」"},{"t":"〜ことになっている","note":"Menyatakan aturan atau jadwal yang sudah ditetapkan. Contoh dalam teks: 「キャッシュカードは二週間ぐらいで家に届くことになっていると教えてもらいました」"},{"t":"〜によって","note":"Menyatakan sebab atau cara, artinya \"melalui, karena\". Contoh dalam teks: 「この経験によって、日本での生活に少し自信が持てるようになりました」"}]},"a-n5-9-n2":{"title":"Sehari di Taman","topic":"Kehidupan","trans":["Hari Sabtu cuacanya cerah, pas banget untuk keluar rumah, jadi aku sudah janjian dengan temanku untuk pergi ke taman. Tempat bertemunya di stasiun, dan waktunya sudah ditentukan pukul sembilan pagi. Sesuai janji, kami bertemu di stasiun pukul sembilan pagi, lalu pergi ke taman bersama-sama.","Sebenarnya, malam sebelumnya aku sudah menyiapkan bekal berisi telur gulung, onigiri, dan sayuran. Aku membuatnya agak lebih banyak untuk temanku juga, karena kupikir makan bersama pasti lebih menyenangkan. Kami pergi ke taman naik sepeda, dan di sepanjang jalan berjejer banyak pohon sakura. Angin terasa sejuk, dan aku mengayuh pedal sambil merasakan sendiri pergantian musim.","Sesampainya di taman, kami duduk di bangku dan makan bekal. Katanya makan di luar membuat rasa makanan jadi lebih enak, dan memang benar, rasanya enak sekali. Temanku juga bilang 「おいしい」, jadi aku merasa usahaku membuatnya tidak sia-sia. Setelah selesai makan, kami bermain bulu tangkis dan berfoto-foto.","Saat melihat sekeliling, aku terkesan karena semua orang tampak gembira. Waktu pulang ke rumah di sore hari, aku memang agak capek, tapi hatiku puas. Meski begitu, kalau dipikir-pikir lagi, hari itu benar-benar hari yang menyenangkan dan penuh makna. Minggu depan aku ingin pergi ke taman lagi, tapi cuacanya belum tentu selalu bagus."],"vocab":["beruntung, dianugerahi (cuaca bagus dll.)","terbaik, sempurna","janjian bertemu","persiapan, menyiapkan","memasukkan, mengisi penuh","nyaman, menyenangkan","lebih menonjol, makin terasa","nilai, hasil yang sepadan","mengesankan","penuh makna, berisi"],"grammar":[{"t":"〜ものの","note":"Berarti \"meskipun ..., tapi ...\", dengan isi kalimat depan dan belakang yang saling berlawanan. Contoh: 「少し疲れたものの、気持ちは満ち足りていた」"},{"t":"〜甲斐があった","note":"Menyatakan bahwa usaha yang dilakukan membuahkan hasil dan terasa sepadan. Contoh: 「作った甲斐があったと感じた」"},{"t":"〜とはいえ","note":"Berarti \"meski begitu\", dipakai untuk melanjutkan kalimat sebelumnya dengan pandangan lain. Contoh: 「とはいえ、振り返ってみると、とても充実した楽しい一日だったと言える」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu ...\", dipakai untuk menyangkal pernyataan yang bersifat mutlak. Contoh: 「いつも天気に恵まれるとは限らない」"}]},"a-n5-9-n3":{"title":"Sehari Bermain di Taman","topic":"Kehidupan","trans":["Hari Sabtu cuacanya cerah sekali, dan karena aku sudah janjian dengan temanku untuk pergi ke taman, aku sudah menantikannya sejak pagi. Aku bertemu temanku di stasiun pukul sembilan pagi, lalu dari sana kami naik sepeda menuju taman. Di sepanjang jalan ada banyak pohon sakura, anginnya juga sejuk, jadi bersepeda terasa menyenangkan.","Malam sebelumnya, aku sudah membuat bekal berisi telur gulung, onigiri, dan sayuran. Supaya temanku juga bisa ikut makan, aku membuat sedikit porsi untuknya juga. Waktu makan sambil duduk di bangku taman, mungkin karena makan di luar, rasanya jauh lebih enak daripada biasanya.","Temanku juga bilang 「おいしい」, jadi aku merasa usahaku membuatnya tidak sia-sia. Setelah selesai makan, aku dan temanku bermain bulu tangkis dan berfoto-foto. Semua orang tampak gembira sekali, dan melihat suasana itu, aku jadi ikut tersenyum.","Karena sudah sore, aku memutuskan untuk pulang. Aku agak capek, tapi hari ini jadi hari yang sangat menyenangkan karena bisa menghabiskan waktu bersama temanku. Semoga minggu depan aku bisa pergi bermain ke taman lagi seperti ini."],"vocab":["janji","janjian bertemu","menuju, pergi ke arah","malam sebelumnya","telur gulung ala Jepang","porsi, bagian","perasaan, suasana hati","suasana, keadaan","senyuman, wajah tersenyum","sore hari"],"grammar":[{"t":"〜ように","note":"Menyatakan tujuan, \"supaya bisa ...\". Contoh: 「友達にも食べてもらえるように、友達の分も少しだけ作っておきました」"},{"t":"〜ことにする","note":"Menyatakan keputusan yang diambil sendiri untuk melakukan sesuatu. Contoh: 「夕方になったので、私は家に帰ることにしました」"},{"t":"〜せいか","note":"Berarti \"mungkin karena ...\", dipakai saat penyebabnya tidak terlalu pasti, dan biasanya menghasilkan suatu akibat. Contoh: 「外で食べるせいか、いつもよりずっとおいしく感じました」"},{"t":"〜かいがある","note":"Menyatakan bahwa usaha membuahkan hasil dan terasa sepadan. Contoh: 「作ったかいがあったと思いました」"}]},"eh-n4-2-n2":{"title":"Pengalaman Pertama di Kedai Ramen","topic":"Buku Bergambar","trans":["Dekat stasiun ada sebuah kedai ramen yang punya reputasi bagus. Hari ini Tanutaro memberanikan diri untuk masuk ke sana untuk pertama kalinya. Di pintu masuk ada mesin tiket, dan katanya di kedai ini kita harus membeli kupon makan lebih dulu. Namun, tombolnya terlalu banyak sehingga dia sama sekali tidak tahu harus menekan yang mana, dan hanya bisa berdiri terpaku.","Saat itu, Kon yang mengantre di belakangnya dengan ramah memberi tahu, \"Yang paling kiri itu ramen biasa, lho.\" Justru karena di kedai yang baru pertama kali dikunjungi kita sering bingung, satu kalimat seperti ini terasa lebih berharga daripada apa pun. Berkat itu, dia berhasil membeli kupon makan dengan lancar, lalu duduk di kursinya dengan lega.","Setelah menyerahkan kupon makan di kursi, pelayan bertanya, \"Mau mi-nya seperti apa kekenyalannya?\" Di kedai ramen Jepang, sepertinya tidak sedikit kedai yang membolehkan kita memilih tingkat kekenyalan mi sesuai selera. Tanutaro sempat ragu sebentar, tetapi akhirnya memberanikan diri menjawab, \"Tolong yang agak keras.\" Yang disebut 「かため」 adalah mi yang direbus sedikit lebih keras daripada biasanya.","Perpaduan kuah panas dan mi yang agak keras yang disajikan itu rasanya enak sekali, melebihi harapan, benar-benar yang terbaik. Tanutaro makan dengan asyik, dan saat tersadar, kuahnya pun sudah habis diminum semua. Meski sempat bingung di depan mesin tiket, berkat bantuan yang ramah itu, bisa dibilang ini menjadi pengalaman pertama yang tak terlupakan."],"vocab":["reputasi, nama baik","masuk ke kedai (secara harfiah: menyibak tirai noren)","sistem, cara kerja, aturan","perkiraan, gambaran (見当もつかない: sama sekali tidak tahu)","berdiri terpaku, mematung","bingung, kebingungan","bertanya","melebihi, mengungguli","tidak tahu harus berbuat apa, buntu"],"grammar":[{"t":"〜だけに","note":"Berarti \"justru karena ... jadi lebih ...\"; fakta di klausa pertama menghasilkan akibat atau perasaan yang sepadan. Contoh: 「初めての店では戸惑うことが多いだけに、こうした一言は何よりありがたいものである」"},{"t":"〜に合わせて","note":"Menyatakan menyesuaikan dengan suatu kondisi atau selera. Contoh: 「好みに合わせて麺のかたさを選べる店も少なくないようだ」"},{"t":"〜ものの","note":"Berarti \"meskipun ..., tetapi ...\"; klausa kedua biasanya berisi tindakan yang berlawanan dengan dugaan dari klausa pertama. Contoh: 「たぬたろうは少し迷ったものの、「かためでお願いします」と思い切って答えた」"},{"t":"〜とは〜のことだ","note":"Dipakai untuk membuat definisi atau menjelaskan arti suatu kata. Contoh: 「「かため」とは、普通よりも少しかたく茹でた麺のことを指す言葉である」"}]},"eh-n4-2-n3":{"title":"Pengalaman Pertama di Kedai Ramen","topic":"Buku Bergambar","trans":["Dekat stasiun ada sebuah kedai ramen populer yang dikunjungi banyak orang. Hari ini Tanutaro memutuskan untuk masuk pertama kalinya ke kedai yang sudah lama membuatnya penasaran itu.","Di pintu masuk ada mesin tiket, dan katanya di kedai ini kita harus membeli kupon makan lebih dulu. Tombolnya terlalu banyak, dia bingung harus menekan yang mana. Kon yang ada di belakangnya memberi tahu, \"Yang paling kiri itu ramen biasa, lho.\"","Berkat itu, dia berhasil membeli kupon makan dengan lancar, lalu duduk di kursi dan menyerahkan kuponnya kepada pelayan. Lalu pelayan bertanya, \"Mau mi-nya seperti apa kekenyalannya?\" Tanutaro menjawab, \"Tolong yang agak keras.\" 「かため」 adalah mi yang direbus sedikit lebih keras daripada biasanya sehingga teksturnya terasa kenyal.","Kuah panas dan mi yang agak keras yang disajikan itu lebih enak daripada yang dia bayangkan, benar-benar yang terbaik. Tanutaro makan dengan asyik, dan saat tersadar kuahnya sudah habis diminum semua. Tanutaro pun jadi paham kenapa kedai ini populer."],"vocab":["mengunjungi, datang ke","penasaran, terpikir terus","mesin tiket, mesin kupon makan","kupon makan","menekan, mendorong","kesulitan, bingung","pelayan, karyawan toko","tekstur kenyal","asyik, tenggelam dalam sesuatu","alasan"],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan diri sendiri untuk melakukan sesuatu. Contoh dalam teks: 「初めて入ってみることにしました」, artinya dia memutuskan untuk mencoba masuk."},{"t":"〜によって","note":"Menyatakan cara atau sarana, \"dengan, melalui\". Contoh dalam teks: 「少しかたくゆでることによって」, menjelaskan bahwa tekstur kenyal dihasilkan dengan merebus mi sedikit lebih keras."},{"t":"〜ず(に)","note":"Bentuk tulis dari 〜ない, berarti \"tanpa melakukan ...\" atau \"tidak ...\". Contoh dalam teks: 「どれを押せばいいのかわからず困っていました」, artinya dia kesulitan karena tidak tahu harus menekan yang mana."},{"t":"〜以上に","note":"Berarti \"lebih dari ...\", melebihi dugaan. Contoh dalam teks: 「思っていた以上においしく」, artinya lebih enak daripada yang dibayangkan."}]},"eh-n4-3-n2":{"title":"雨の日のプレゼント","topic":"Buku Bergambar","trans":["Sabtu depan adalah hari ulang tahun Kon-chan, teman Tanutarō. Syal biru yang biasa dipakai Kon-chan tampaknya sudah dipakai bertahun-tahun, jadi sekarang sudah benar-benar lusuh. Melihat itu, Tanutarō berpikir untuk memberinya syal baru.","Namun, hari itu hujan turun terus sejak pagi, cuaca yang tidak enak untuk keluar rumah. Supaya sempat sebelum hari ulang tahun, mau tidak mau dia harus berpayung dan pergi ke toko serba ada di kota meski hujan. Syal biru yang dia temukan di toko itu warnanya elegan. Walaupun harganya agak mahal, dia membelinya tanpa ragu. Pegawai toko membungkusnya dengan rapi, jadi tampilannya pun menjadi hadiah yang bagus.","Di perjalanan pulang, hujan jadi makin deras dibanding pagi tadi. Seiring hujan yang makin kuat, kekhawatiran kalau hadiahnya basah juga makin besar. Karena itu, Tanutarō mendekap tasnya erat-erat dan terus berlari, tidak peduli dirinya sendiri basah kuyup.","Saat Tanutarō berkata 「お誕生日おめでとう」 sambil menyodorkan hadiah, Kon-chan terkejut sampai matanya membulat karena tidak menyangka. Perasaan Tanutarō yang susah payah membawa hadiah itu menembus hujan mungkin bisa dirasakan Kon-chan meski tanpa kata-kata. Kon-chan yang sudah mengenakan syal barunya tersenyum bahagia dan berkata, 「ありがとう、ずっと大切にするね」. Barang mahal belum tentu selalu membuat orang senang, tetapi barang yang dipilih dengan memikirkan orangnya akan membekas di hati."],"vocab":[{"w":"当たる","m":"bertepatan dengan, tepat jatuh pada (tanggal tertentu)"},{"w":"身につける","m":"memakai, mengenakan"},{"w":"古びる","m":"menjadi lusuh, usang"},{"w":"値が張る","m":"harganya cukup mahal"},{"w":"包装","m":"pembungkusan, kemasan"},{"w":"激しい","m":"deras, hebat, sengit"},{"w":"抱え込む","m":"mendekap erat"},{"w":"差し出す","m":"menyodorkan, mengulurkan"},{"w":"目を丸くする","m":"membelalak karena terkejut"}],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring berubahnya satu hal, hal lain ikut berubah. Contoh: 「雨が強まるのに伴って、プレゼントが濡れてしまわないかという不安も大きくなった」."},{"t":"〜ざるを得ない","note":"Menyatakan tidak ada pilihan lain selain melakukan hal itu, alias mau tidak mau harus. Contoh: 「雨の中でも傘をさして町の雑貨屋へ出かけざるを得なかった」."},{"t":"〜とはいえ","note":"Mengakui fakta yang disebutkan, tetapi lanjutannya berupa hasil atau penilaian yang berbeda dari dugaan. Artinya \"meskipun begitu\". Contoh: 「少し値が張るとはいえ、迷わず買うことにした」."},{"t":"〜とは限らない","note":"Menyatakan \"belum tentu\" atau \"tidak selalu\", dipakai untuk menyangkal anggapan yang terlalu mutlak. Contoh: 「高価な物が必ずしも喜ばれるとは限らない」."}]},"eh-n4-3-n3":{"title":"雨の日のプレゼント","topic":"Buku Bergambar","trans":["Sabtu depan adalah hari ulang tahun temanku, Kon-chan. Syal biru yang selalu dipakai Kon-chan sudah cukup lusuh karena dipakai lama. Tanutarō memutuskan untuk memberinya syal baru.","Tapi, sejak pagi hari itu hujan turun terus. Tanutarō berpayung dan berjalan ke toko serba ada di kota. Di sana, dia berhasil menemukan syal biru yang cantik.","Harganya agak mahal, tetapi Tanutarō memutuskan untuk membelinya. Pegawai toko membungkus syal itu dengan rapi dan cantik. Di perjalanan pulang, hujan jadi lebih deras daripada pagi tadi. Supaya hadiahnya tidak basah, Tanutarō mendekap tasnya erat-erat dan berlari.","Saat dia berkata 「お誕生日おめでとう」 dan menyerahkan hadiahnya, Kon-chan tampak sangat terkejut. Kon-chan yang melingkarkan syal baru di lehernya tersenyum dan berkata, 「ありがとう、ずっと大切にするね」. Tanutarō merasa usahanya berlari menembus hujan tidak sia-sia, dan dia merasa senang dari lubuk hatinya."],"vocab":[{"w":"だいぶ","m":"cukup, lumayan"},{"w":"贈る","m":"memberi (hadiah)"},{"w":"雑貨屋","m":"toko serba ada"},{"w":"値段","m":"harga"},{"w":"店員","m":"pegawai toko"},{"w":"ていねい","m":"rapi, teliti, sopan"},{"w":"包む","m":"membungkus"},{"w":"抱える","m":"mendekap, memeluk"},{"w":"様子","m":"keadaan, tampaknya"},{"w":"大切","m":"penting, berharga"}],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan yang dibuat sendiri oleh pembicara. Contoh: 「新しいマフラーを贈ることにしました」「買うことにしました」"},{"t":"〜ように","note":"Menyatakan tujuan, yaitu agar suatu keadaan terwujud atau tidak terjadi. Contoh: 「プレゼントがぬれないように、かばんをしっかり抱えて走りました」"},{"t":"〜せいで","note":"Menyatakan sebab atau alasan yang negatif, sering bernada menyalahkan. Contoh: 「長く使ったせいでだいぶ古くなっていました」"},{"t":"〜てくれる","note":"Menyatakan orang lain melakukan sesuatu untuk kita, disertai rasa terima kasih. Contoh: 「そのマフラーをていねいにきれいに包んでくれました」"}]},"a-n2-11-n3":{"title":"「お通し」di Izakaya","topic":"Budaya","trans":["Di izakaya Jepang, begitu kamu duduk, kadang ada hidangan kecil yang datang padahal kamu belum memesannya. Hidangan ini disebut 「お通し」, dan di daerah Kansai sering juga disebut 「突き出し」. Isinya beragam tergantung tokonya, misalnya edamame, makanan rebus, atau sayuran yang dicampur bumbu.","Di antara orang yang baru pertama kali datang ke Jepang, tidak sedikit yang kaget melihat biaya お通し ditambahkan di tagihan. Mereka jadi cemas, jangan-jangan uangnya diambil begitu saja tanpa izin. Biaya お通し sekitar tiga ratus sampai lima ratus yen, dan konon bagi toko biaya ini mirip dengan biaya tempat duduk.","Ada juga yang berpendapat bahwa hidangan ini disajikan sebagai bentuk perhatian toko agar pelanggan tidak bosan sambil menunggu makanan datang. Namun, boleh tidaknya menolak berbeda-beda di tiap toko, dan akhir-akhir ini makin banyak toko yang tidak menyajikan お通し. Kalau kamu merasa penasaran, tanya saja sebentar saat masuk ke toko supaya tenang.","Kalau sudah tahu latar belakangnya, kamu pasti bisa menikmati hidangan kecil yang belum pernah kamu lihat dengan hati senang. お通し bisa dianggap sebagai bagian dari budaya minum di Jepang."],"vocab":[{"w":"注文","m":"memesan"},{"w":"小鉢","m":"mangkuk kecil berisi lauk"},{"w":"会計","m":"pembayaran, tagihan"},{"w":"足す","m":"menambah, menambahkan"},{"w":"不安","m":"cemas, khawatir"},{"w":"退屈","m":"bosan"},{"w":"気を使う","m":"memperhatikan, peduli, menjaga perasaan"},{"w":"断る","m":"menolak"},{"w":"背景","m":"latar belakang"},{"w":"見慣れない","m":"asing, belum pernah dilihat"}],"grammar":[{"t":"〜ように","note":"Menyatakan \"supaya/agar\" untuk mencapai suatu tujuan. Di depannya sering ada bentuk negatif atau bentuk potensial, untuk menjelaskan tujuan suatu tindakan. Contoh: 「客が退屈しないように、店が気を使って出すものだ」"},{"t":"〜によって","note":"Menyatakan \"tergantung pada ...\", yaitu hasilnya berbeda-beda. Contoh: 「中身は枝豆や煮物、和え物など、店によってさまざまである」"},{"t":"〜ば(bentuk pengandaian)","note":"Menyatakan \"kalau ..., maka ...\", dan di belakangnya sering muncul hasil yang baik atau saran. Contoh: 「背景を知っていれば、見慣れない小鉢も気持ちよく楽しめるだろう」"},{"t":"〜のではないか","note":"Menyatakan dugaan atau kekhawatiran pembicara, \"jangan-jangan ...\". Contoh: 「勝手にお金を取られたのではないかと、不安になる」"}]},"a-n2-11-n4":{"title":"「お通し」di Izakaya","topic":"Budaya","trans":["Di izakaya Jepang, begitu duduk, kadang ada hidangan kecil yang datang padahal tidak dipesan. Ini disebut 「お通し」, dan biasanya berupa edamame atau makanan rebus. Di Kansai sering juga disebut 「突き出し」, dan isinya berbeda-beda di setiap toko.","Orang yang baru pertama kali datang ke Jepang kadang kaget melihat biaya お通し di tagihan. Banyak juga yang bingung karena berpikir 「変なお金ではないか」 (jangan-jangan ini biaya yang aneh). Konon biaya お通し sekitar tiga ratus sampai lima ratus yen. Bagi toko, biaya ini punya arti yang sama dengan biaya tempat duduk.","Katanya, ada juga maksud supaya pelanggan tidak bosan sambil menunggu makanan datang. Boleh tidaknya menolak tergantung toko, tetapi akhir-akhir ini makin banyak toko yang tidak menyajikan お通し. Kalau kamu merasa penasaran, tanya saja saat masuk ke toko, pasti aman. Kalau sudah tahu alasannya, hidangan kecil itu juga bisa kamu nikmati sebagai bagian dari budaya minum di Jepang."],"vocab":[{"w":"居酒屋","m":"izakaya (kedai minum ala Jepang)"},{"w":"席","m":"tempat duduk"},{"w":"頼む","m":"memesan, meminta"},{"w":"煮物","m":"makanan rebus"},{"w":"会計","m":"pembayaran, tagihan"},{"w":"驚く","m":"kaget, terkejut"},{"w":"困る","m":"bingung, kerepotan"},{"w":"断る","m":"menolak"},{"w":"増える","m":"bertambah"},{"w":"気になる","m":"penasaran, mengganjal di hati"}],"grammar":[{"t":"〜と(〜ことがある)","note":"Menyatakan hasil yang wajar terjadi, \"begitu ... maka ...\". Bisa dipadukan dengan 「ことがある」 untuk menyatakan bahwa sesuatu kadang terjadi. Contoh: 「席に座ると、頼んでいない小さい料理が来ることがある」"},{"t":"〜ように(tujuan)","note":"Menyatakan tujuan, yaitu supaya suatu keadaan terwujud. Contoh: 「料理が来るまで客が退屈しないように、という気持ちもあるそうだ」"},{"t":"〜ば(bentuk pengandaian)","note":"Menyatakan syarat \"kalau ..., maka ...\". Contoh: 「店に入る時に聞いておけば大丈夫だ」「理由を知れば、小さい料理も楽しめるだろう」"},{"t":"〜そうだ(kabar yang didengar)","note":"Dipasang setelah bentuk biasa untuk menyatakan kabar yang didengar dari orang lain, \"katanya ...\". Contoh: 「という気持ちもあるそうだ」"}]},"a-n2-13-n3":{"title":"Nenkai yang Berubah, Perhatian yang Tak Berubah","topic":"Tempat Kerja","trans":["Menjelang akhir tahun, di tempat kerja Jepang dulu topik soal 「忘年会」 (pesta akhir tahun) biasanya muncul dengan sendirinya. Acara ini untuk melupakan kerja keras setahun dan mempererat hubungan, dan dulu ikut serta dianggap hal yang sewajarnya. Namun belakangan ini, semakin banyak orang yang ingin memakai waktu setelah kerja untuk diri sendiri, sehingga tidak ingin ikut.","Karena itu, makin banyak perusahaan yang menghentikan pesta malam dan menggantinya dengan makan siang bersama, atau membuat kehadiran jadi bebas. Latar belakangnya adalah cara pandang orang yang makin beragam, serta keadaan orang yang ingin lebih mengutamakan keluarga dan perawatan anggota keluarga. Tidak sedikit anak muda yang merasa duduk semeja dengan atasan bukannya menyenangkan, malah hanya melelahkan karena harus menjaga sikap.","Di sisi lain, ada juga yang menyambutnya karena menganggap ini kesempatan berharga untuk mengobrol dengan rekan kerja yang biasanya jarang diajak bicara. Bagi perusahaan, memaksa karyawan ikut hanya akan menambah rasa tidak puas, jadi mereka tidak punya pilihan selain mencari bentuk yang mempertimbangkan keadaan masing-masing. Saat diundang lalu ingin menolak, dasarnya adalah berterima kasih dulu karena sudah diundang.","Kalau kamu bilang 「ありがとうございます、あいにく先約がありまして」 (terima kasih, sayangnya saya sudah ada janji lebih dulu), suasana tidak akan jadi canggung. Alasannya jangan dijelaskan terlalu rinci. Sampaikan singkat saja, lalu tambahkan 「またぜひ」 (lain kali ya). Saat ikut pun, kalau tidak bisa minum alkohol, kamu boleh bersulang dengan teh oolong, dan akan lebih nyaman kalau kamu bilang di awal bahwa kamu akan pulang lebih awal. Kalau panitia menuliskan satu kalimat 「参加は自由です」 (ikut atau tidak bebas) di undangan, beban orang yang menolak pun jadi jauh lebih ringan. Menurutku yang penting adalah meski bentuknya berubah, rasa menghargai keadaan satu sama lain tidak berubah."],"vocab":["tempat kerja","perawatan (merawat anggota keluarga yang butuh bantuan)","rekan kerja","berharga, langka","keadaan, alasan","janji yang sudah ada lebih dulu","menyinggung perasaan, merusak suasana","menambahkan, menyertakan","panitia, penyelenggara acara"],"grammar":[{"t":"〜どころか","note":"Berarti 'jangankan ~, malah ~'. Bagian setelahnya berlawanan dengan yang diharapkan. Contoh: 「上司との席は楽しいどころか、気を使って疲れるだけだと感じる」"},{"t":"〜ため(原因)","note":"Menyatakan sebab atau alasan, lebih formal daripada 「から」. Contoh: 「無理に参加させると不満が高まるため、それぞれの事情を考えた形を探すしかありません」"},{"t":"〜しかない","note":"Berarti 'tidak ada pilihan lain selain ~'. Contoh: 「それぞれの事情を考えた形を探すしかありません」"},{"t":"動詞ます形+すぎる","note":"Menyatakan sesuatu dilakukan berlebihan. Contoh: 「理由は細かく話しすぎず、短く伝えて」 (話しすぎず adalah bentuk tulis dari 話しすぎない)"}]},"a-n2-13-n4":{"title":"Nenkai yang Berubah","topic":"Tempat Kerja","trans":["Menjelang akhir tahun, perusahaan-perusahaan di Jepang sering membicarakan 「忘年会」 (pesta akhir tahun). Dulu, acara ini untuk melupakan lelahnya setahun, dan ikut dianggap hal yang wajar. Sekarang makin banyak orang yang tidak ingin ikut, dan ada juga perusahaan yang menggantinya dengan makan siang bersama.","Setelah kerja, banyak orang ingin menghargai waktu untuk diri sendiri dan keluarga. Ada juga anak muda yang merasa capek karena harus menjaga sikap saat makan bersama atasan. Tapi ada juga yang senang karena bisa mengobrol dengan rekan kerja yang biasanya jarang diajak bicara. Memaksa orang ikut itu merepotkan, jadi perusahaan mempertimbangkan keadaan setiap orang.","Saat menolak, pertama-tama ucapkan 「ありがとうございます」 (terima kasih) karena sudah diundang. Alasannya jangan disampaikan panjang-panjang, cukup bilang 「またぜひ」 (lain kali ya). Kalau panitia menulis 「参加は自由です」 (ikut atau tidak bebas), orang yang menolak akan merasa lebih lega. Yang penting adalah memikirkan perasaan satu sama lain."],"vocab":["nenkai (pesta akhir tahun)","wajar, sudah seharusnya","bertambah","atasan","rekan kerja","keadaan, alasan","menolak","mengundang","panitia acara","menjaga sikap, memperhatikan perasaan orang lain"],"grammar":[{"t":"〜ために","note":"Menyatakan tujuan, 'untuk ~'. Contoh: 「一年の疲れを忘れるために、行くのが当たり前でした」"},{"t":"〜と(條件)","note":"Berarti 'kalau/begitu ~, maka ~', dipakai untuk hasil yang wajar atau saran. Contoh: 「年末になると、日本の会社では「忘年会」の話をよくします」"},{"t":"〜ので","note":"Menyatakan sebab atau alasan, nadanya lebih lembut daripada 「から」. Contoh: 「いつも話せない同僚と話せるので、うれしいと思う人もいます」"},{"t":"〜てくれる","note":"Menyatakan orang lain melakukan sesuatu untuk kita, dengan perasaan terima kasih. Contoh: 「まず誘ってくれたことに「ありがとうございます」と言います」"}]},"a-n2-12-n3":{"title":"Memikirkan Hari Terima Kasih Pekerja","topic":"Masyarakat","trans":["Tanggal 23 November disebut 「勤労感謝の日」, hari libur nasional ketika banyak perusahaan dan sekolah libur. Kalau melihat namanya, orang mudah mengira ini hari untuk para pekerja, tetapi asal-usulnya sedikit berbeda. Sejak dulu di Jepang, setiap musim gugur diadakan 「新嘗祭」, yaitu upacara mempersembahkan hasil panen kepada dewa sebagai ungkapan rasa syukur.","Setelah perang, saat sistem ditinjau ulang, pada tahun 1948 dibuatlah undang-undang dan hari ini menjadi 「勤労感謝の日」. Undang-undang itu menyebutkan bahwa ini adalah hari untuk menghargai pekerjaan dan saling berterima kasih. Kamu bisa memahaminya begini: rasa syukur kepada dewa meluas menjadi rasa terima kasih atas bekerja dan membuat sesuatu.","Sekarang cara bekerja makin beragam, dan gambaran yang muncul di kepala kita saat mendengar kata 「勤労」 pun ikut berubah. Bukan hanya pabrik dan ladang, tetapi juga toko, logistik, layanan kesehatan, perawatan lansia, dan banyak pekerjaan lain yang menopang kehidupan, jumlahnya tak terhitung. Bahkan di hari libur, tidak semua orang bisa istirahat, dan ada pekerjaan yang justru harus dikerjakan lebih keras dari biasanya. Kehidupan kita yang nyaman ini ada berkat usaha orang-orang seperti itu.","Hanya dengan mengucapkan 「ありがとうございます」 kepada orang yang mengantarkan paket, perasaanmu sudah tersampaikan. Di tempat kerja pun, berterima kasih atas pekerjaan rekan kerja bisa langsung kamu mulai dengan momen hari ini. Hanya saja, jadwal kerja dan libur pada hari libur nasional berbeda-beda di tiap perusahaan, jadi untuk detailnya tolong cek penjelasan dari perusahaanmu. Rasa terima kasih baru bermakna kalau diungkapkan lewat kata-kata dalam kehidupan sehari-hari, bukan hanya di hari libur."],"vocab":[{"w":"祝日","m":"hari libur nasional"},{"w":"由来","m":"asal-usul"},{"w":"収穫","m":"panen, hasil panen"},{"w":"供えて","m":"mempersembahkan (供える)"},{"w":"制度","m":"sistem, peraturan"},{"w":"見直される","m":"ditinjau ulang"},{"w":"物流","m":"logistik"},{"w":"支える","m":"menopang, mendukung"},{"w":"成り立って","m":"terbentuk, bertumpu pada (成り立つ)"},{"w":"同僚","m":"rekan kerja"}],"grammar":[{"t":"〜によって","note":"Menyatakan sebab, cara, atau dasar: \"karena…, dengan…, oleh…\". Contoh: 「私たちの便利な生活は、そうした人たちの努力によって成り立っているのだ」"},{"t":"〜わけではない","note":"Negasi sebagian, artinya \"bukan berarti…\"; tidak menyangkal sepenuhnya. Contoh: 「祝日でも、みんなが休めるわけではなく、いつも以上に働く仕事もある」"},{"t":"〜ため","note":"Menyatakan sebab atau alasan, lebih formal daripada「から」dan sering dipakai dalam tulisan. Contoh: 「祝日の勤務や休みは会社ごとに違うため、詳しくは会社の説明を確認してほしい」"},{"t":"〜をきっかけに","note":"Menyatakan menjadikan sesuatu sebagai momen untuk memulai tindakan baru. Contoh: 「同僚の仕事に礼を言うことは、この日をきっかけにすぐ始められる」"}]},"a-n2-12-n4":{"title":"Hari Terima Kasih Pekerja","topic":"Masyarakat","trans":["Tanggal 23 November adalah 「勤労感謝の日」, hari libur ketika perusahaan dan sekolah libur. Melihat namanya, banyak orang mengira ini hari untuk para pekerja. Tetapi aslinya ini adalah 「新嘗祭」, upacara di musim gugur untuk mempersembahkan beras baru kepada dewa dan mengucapkan rasa syukur.","Setelah perang, negara membuat undang-undang baru tentang hari libur. Pada tahun 1948, hari ini menjadi hari libur bernama 「勤労感謝の日」. Rasa syukur kepada dewa meluas menjadi rasa terima kasih atas bekerja dan membuat sesuatu.","Sekarang ada banyak pekerjaan yang menopang kehidupan, seperti di toko dan rumah sakit. Ada juga orang yang tidak bisa libur meski hari libur nasional dan harus bekerja lebih sibuk dari biasanya. Kehidupan kita yang nyaman ini ada berkat orang-orang seperti itu. Kalau kamu bilang 「ありがとう」 kepada orang yang mengantarkan paket, perasaanmu akan tersampaikan. Yuk, coba ungkapkan rasa terima kasih lewat kata-kata dalam kehidupan sehari-hari."],"vocab":[{"w":"祝日","m":"hari libur nasional"},{"w":"感謝","m":"rasa syukur, terima kasih"},{"w":"戦争","m":"perang"},{"w":"法律","m":"undang-undang, hukum"},{"w":"広がる","m":"meluas, menyebar"},{"w":"便利","m":"praktis, nyaman"},{"w":"忙しい","m":"sibuk"},{"w":"届ける","m":"mengantarkan, menyampaikan"},{"w":"気持ち","m":"perasaan"}],"grammar":[{"t":"〜のおかげで","note":"Berarti \"berkat ~\", menunjukkan hasil baik yang didapat karena seseorang atau sesuatu, dengan nuansa terima kasih. Contoh: 「そうした人たちのおかげでできています」"},{"t":"〜てくれる","note":"Menyatakan orang lain melakukan sesuatu untuk kita, dengan nuansa terima kasih. Contoh: 「荷物を届けてくれた人に」"},{"t":"〜ば(bentuk pengandaian)","note":"Menyatakan syarat \"kalau ~, maka ~\". Contoh: 「ありがとう」と言えば、気持ちは伝わります"},{"t":"〜ようにする","note":"Menyatakan usaha untuk membiasakan diri atau berusaha melakukan sesuatu. Contoh: 毎日の生活の中で言葉にするようにしましょう"}]},"a-n3-13-n2":{"title":"Saat Ada Kartu Pemberitahuan Paket Tak Terkirim","topic":"Kehidupan","trans":["Sepulang kerja, aku menyadari ada selembar \"kartu pemberitahuan ketidakhadiran\" dari jasa kurir di kotak surat. Karena paket tiba saat aku tidak di rumah, mau tidak mau aku harus meminta agar paketnya diantar ulang. Prosedur seperti ini disebut 「再配達」 (pengantaran ulang), dan sudah sangat akrab bagi orang yang memakai jasa kurir.","Dulu, biasanya orang menelepon ke nomor yang tertulis di kartu kertas itu, tetapi keadaan berubah seiring menyebarnya smartphone. Sekarang kamu cukup memindai kode QR yang tercetak di kertas, lalu memilih tanggal dan jam yang kamu inginkan untuk mengajukannya. Namun, di kartu itu juga tertulis batas waktu penyimpanan, jadi kamu tidak bisa santai-santai. Kalau tidak segera diurus, paket bisa saja dikembalikan ke pengirim, jadi harus hati-hati.","Di sisi lain, pengantaran ulang punya masalah: bahan bakar truk dan tenaga kerja jadi terpakai lebih banyak. Di masa sekarang, saat kekurangan sopir menjadi masalah sosial, pengguna pun diminta untuk sebisa mungkin menerima paket dalam sekali antar. Karena itu, yang sedang menarik perhatian adalah cara penerimaan seperti 「置き配」 (paket ditaruh di depan pintu) dan kotak paket. Kalau paket diletakkan di teras depan atau di dalam kotak, kamu bisa menerimanya entah sedang di rumah atau tidak.","Aku sendiri belakangan ini, saat belanja online, juga memikirkan cara penerimaan paketnya sekalian. Masing-masing hanyalah usaha kecil, tetapi sikap seperti ini membantu mengurangi beban pihak pengantar. Bagi pengguna pun repot yang sia-sia jadi berkurang, jadi bisa dibilang ini kebiasaan yang menyenangkan bagi kedua belah pihak."],"vocab":["kartu pemberitahuan tidak di rumah","tidak di rumah","pengantaran ulang","penyebaran, meluasnya","tertulis, mencantumkan","dikembalikan, dikirim kembali","bahan bakar","paket ditaruh di depan pintu","beban","sikap peduli, kesadaran untuk memperhatikan"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring berubahnya satu hal, hal lain ikut berubah. Contoh: 「スマートフォンの普及に伴って状況が変わった」"},{"t":"〜ざるを得ない","note":"Berarti terpaksa melakukan sesuatu karena tidak ada pilihan lain. Contoh: 「改めて配達してもらうよう依頼せざるを得ない」"},{"t":"〜かねない","note":"Menyatakan kemungkinan terjadinya hasil yang tidak diinginkan. Contoh: 「荷物が送り主に返送されかねない」"},{"t":"〜にかかわらず","note":"Menyatakan bahwa tidak terpengaruh oleh kondisi di depannya, tetap ……. Contoh: 「在宅しているかどうかにかかわらず受け取ることができる」"}]},"a-n3-13-n4":{"title":"Saat Ada Kartu Pemberitahuan Paket Tak Terkirim","topic":"Kehidupan","trans":["Sepulang kerja, di kotak surat ada selembar kertas. Ini disebut 「不在票」, pemberitahuan bahwa ada paket datang saat aku tidak di rumah. Meminta agar paket diantar sekali lagi disebut 「再配達」 (pengantaran ulang).","Sekarang kamu bisa mengajukannya dengan mudah lewat HP. Cukup pindai kode QR di kertas itu, lalu pilih tanggal dan jam yang kamu mau. Tapi di kartu itu juga tertulis batas waktu penyimpanan paket. Kalau tidak cepat menghubungi, paket bisa dikembalikan ke pengirim.","Pengantaran ulang memakai bensin truk dan juga tenaga orang, jadi sangat merepotkan. Karena itu, 「置き配」 (paket ditaruh di depan pintu) atau kotak paket itu praktis. Belakangan ini, saat belanja online, aku berusaha memikirkan sampai cara menerima paketnya. Menurutku ini kebiasaan yang baik untuk diriku dan juga untuk kurirnya."],"vocab":["kotak surat","tidak di rumah","paket, barang bawaan","mengantarkan","mendaftar, mengajukan","harapan, keinginan","batas waktu","teras depan, pintu masuk","kebiasaan"],"grammar":[{"t":"〜てもらう","note":"Menyatakan meminta orang lain melakukan sesuatu untuk kita. Contoh: 「もう一度届けてもらうように頼むことを」、「荷物を置いてもらう」"},{"t":"〜ないと、〜","note":"Menyatakan bahwa kalau tidak melakukan sesuatu, akan ada akibat buruk. Contoh: 「早く連絡しないと、荷物が送った人に戻されることもある」"},{"t":"〜ようにする","note":"Menyatakan berusaha membiasakan diri atau berhati-hati melakukan sesuatu. Contoh: 「受け取り方まで考えるようにしている」"},{"t":"〜ので","note":"Menyatakan sebab atau alasan, nuansanya lebih lembut daripada 「から」. Contoh: 「トラックのガソリンも人の力も使うので大変だ」"}]},"a-n3-14-n2":{"title":"Ayo Berburu Daun Musim Gugur","topic":"Budaya","trans":["Di akhir Oktober, rekan kerjaku, Tanaka, mengajakku: 「今週末、紅葉を見に行きませんか」(\"Akhir pekan ini, mau pergi melihat daun musim gugur?\"). Di Jepang, saat musim gugur ada kebiasaan menikmati daun-daun yang berubah warna di gunung atau taman. Kebiasaan ini disebut 「紅葉狩り」 dan sudah dicintai sejak zaman dulu. Aku suka daun musim gugur, tapi aku dengar tempat wisata yang terkenal biasanya ramai, jadi jujur saja aku agak khawatir.","Lalu Tanaka mengusulkan, 「人込みを避けるために、朝早く出発するのはどうでしょうか」(\"Supaya terhindar dari keramaian, bagaimana kalau berangkat pagi-pagi?\"). Menjelang siang, tempat parkir dan jalanan jadi padat, jadi katanya kalau sudah sampai di pagi hari, kita bisa berjalan dengan tenang. Hari kerja memang cenderung lebih sepi, tapi belum tentu selalu tenang, jadi sebaiknya jangan berharap terlalu banyak. Karena ini musim yang populer, kita mungkin harus siap menghadapi keramaian sampai batas tertentu.","Selanjutnya, kami memutuskan untuk mencari 「紅葉情報」 (informasi daun musim gugur) yang dipublikasikan di situs asosiasi pariwisata dan situs cuaca. Di sana, kondisi pohon dijelaskan dengan mudah dipahami lewat kata-kata seperti 「色づき始め」 dan 「見ごろ」. Tanaka mengingatkanku bahwa waktu terbaik untuk melihatnya berbeda-beda di tiap tempat, jadi harus selalu dicek sebelum berangkat. Setelah berdiskusi, kami memilih sebuah taman kecil dekat pegunungan dan memutuskan berangkat naik kereta paling pagi.","Hari itu aku agak mengantuk, tapi bangun pagi memang sepadan: di jalan hampir tidak ada orang. Daun-daun merah dan kuning yang disinari cahaya pagi tampak seolah-olah udaranya pun ikut berwarna. Di tengah hari-hari yang sibuk, kesempatan untuk merasakan pergantian musim dengan santai sama sekali tidak banyak. Saat pulang, aku berterima kasih, 「誘ってくださって、ありがとうございました」(\"Terima kasih sudah mengajak saya\"), dan Tanaka tersenyum, 「来年も行きましょう」(\"Tahun depan kita pergi lagi, ya\"). Mendengar itu, aku jadi tidak sabar menunggu musim gugur berikutnya dari sekarang."],"vocab":["berburu daun musim gugur","berubah warna, ternodai warna","keramaian, kerumunan orang","usulan","padat, ramai sesak","kecenderungan","kesiapan mental, tekad","waktu terbaik untuk dinikmati","berbeda","tidak sabar menanti"],"grammar":[{"t":"〜につれて","note":"Menyatakan bahwa seiring berkembangnya satu hal, hal lain ikut berubah. Contoh: 「昼に近づくにつれて駐車場も道路も混み合うため」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu\" atau \"tidak selalu\", dan menyisakan ruang untuk pengecualian. Contoh: 「いつも静かだとは限らない」"},{"t":"〜ざるを得ない","note":"Berarti terpaksa atau tidak ada pilihan selain melakukannya. Contoh: 「ある程度の人出は覚悟せざるを得ない」"},{"t":"〜かいがある","note":"Menyatakan bahwa usaha yang dilakukan membuahkan hasil yang setimpal, jadi terasa sepadan. Contoh: 「早起きしたかいがあって」"}]},"a-n3-14-n4":{"title":"Ayo Pergi Melihat Daun Musim Gugur","topic":"Budaya","trans":["Di akhir Oktober, Tanaka dari kantor yang sama berkata, 「今週末、紅葉を見に行きませんか」(\"Akhir pekan ini, mau pergi melihat daun musim gugur?\"). Di Jepang, melihat daun merah dan kuning di gunung atau taman saat musim gugur disebut 「紅葉狩り」. Aku suka daun musim gugur, tapi aku dengar tempat yang terkenal itu ramai, jadi aku agak khawatir.","Tanaka berkata, 「朝早く出かけるのはどうですか」(\"Bagaimana kalau berangkat pagi-pagi?\"). Kalau sudah siang, tempat parkir dan jalanan penuh orang dan mobil, jadi katanya kalau sampai di pagi hari, kita bisa berjalan santai. Hari kerja memang sering lebih sepi, tapi tidak bisa dibilang selalu tenang.","Selanjutnya, aku mencari 「紅葉情報」 (informasi daun musim gugur) di internet. Di sana, kondisi pohon ditulis dengan kata-kata seperti 「色づき始め」 dan 「見ごろ」. Waktu terbaik untuk melihatnya berbeda-beda tiap tempat, jadi Tanaka mengingatkanku untuk mengeceknya sebelum berangkat. Kami berdua berdiskusi, lalu memilih taman kecil dekat pegunungan dan memutuskan berangkat naik kereta paling pagi.","Hari itu aku agak mengantuk, tapi senang sekali sudah bangun pagi. Di jalan hampir tidak ada orang. Daun merah dan kuning tampak indah dalam cahaya pagi, seolah-olah udaranya pun ikut berwarna. Saat pulang, aku berterima kasih, 「誘ってくれて、ありがとうございました」(\"Terima kasih sudah mengajakku\"). Tanaka tersenyum dan berkata, 「来年も行きましょう」(\"Tahun depan kita pergi lagi, ya\"), jadi aku sudah tidak sabar menunggu musim gugur berikutnya."],"vocab":["daun musim gugur","sama","khawatir","tempat parkir","hari kerja","menjadi sepi, lengang","memilih","mengantuk","ucapan terima kasih","dinanti-nantikan, hal yang menyenangkan"],"grammar":[{"t":"〜ので","note":"Menyatakan sebab atau alasan dengan nada yang lebih lembut. Contoh: 「有名な場所は人が多いと聞いたので、少し心配でした」"},{"t":"〜そうだ(kabar yang didengar)","note":"Menyatakan kabar yang didengar dari orang lain, artinya \"katanya...\". Contoh: 「午前中に着けば、ゆっくり歩けるそうです」"},{"t":"〜ようにと言う/教える","note":"Dipakai untuk menyampaikan kembali permintaan atau saran agar seseorang melakukan sesuatu. Contoh: 「出かける前に見るようにと田中さんが教えてくれました」"},{"t":"〜ことにする","note":"Menyatakan keputusan yang diambil sendiri untuk melakukan sesuatu. Contoh: 「朝一番の電車で行くことにしました」"}]},"a-n3-16-n2":{"title":"Saat Kartu Pos Berkabung Datang","topic":"Budaya","trans":["Awal November, sebuah kartu pos datang dari rekan kerjaku, Pak Tanaka. Saat kubuka, isinya ternyata pemberitahuan bahwa keluarganya sedang berkabung. Kalimat sopan 「喪中につき、年始のご挨拶をご遠慮申し上げます」 (\"Karena sedang berkabung, kami mohon maaf tidak mengirim ucapan Tahun Baru\") memang singkat, tetapi terasa berat dan membekas di mataku. Baru saat itulah aku tahu bahwa ayah Pak Tanaka sudah meninggal pada musim panas tahun ini.","Ini disebut 「喪中はがき」 (kartu pos berkabung), yaitu kartu yang dikirim orang yang keluarganya baru berduka untuk memberi tahu lebih dulu bahwa mereka tidak akan mengirim kartu Tahun Baru (年賀状). Konon kebiasaan ini mengakar dari anggapan bahwa selama masa berkabung kita sebaiknya menahan diri dari perayaan. Kartu ini biasanya tiba sebelum persiapan kartu Tahun Baru dimulai, supaya penerimanya cepat tahu keadaannya dan tidak perlu repot-repot memikirkan hal yang tak perlu. Jadi, kartu berkabung hanyalah pemberitahuan bahwa \"kami tidak bisa mengirim kartu Tahun Baru\", bukan permintaan agar penerimanya membalas.","Aku sempat bingung harus bagaimana, tetapi setelah berkonsultasi dengan rekan kerja, aku memutuskan untuk tidak mengirim kartu Tahun Baru kepada Pak Tanaka. Aku juga diberi tahu bahwa kalau beberapa saat setelah tahun baru aku mengirim 「寒中見舞い」, perasaanku akan tersampaikan. 寒中見舞い adalah kartu salam yang menanyakan kabar dan kesehatan seseorang pada masa dingin yang menusuk, dan ciri khasnya adalah tidak menuliskan ucapan selamat. Dalam isinya, aku secara khusus berusaha menuliskan terima kasih atas kartu posnya dan kata-kata yang menunjukkan kepedulianku pada keluarga Pak Tanaka.","Cara menangani kartu Tahun Baru berbeda-beda di tiap tempat kerja, jadi untuk detailnya sebaiknya kita cek dulu ke penjelasan dari perusahaan. Kebiasaan mengirim kartu Tahun Baru memang perlahan berkurang, tetapi budaya menyampaikan perasaan lewat salam musiman masih dihargai sampai sekarang. Dari pengalaman kali ini, aku belajar bahwa memahami keadaan orang lain dan mengubah bentuk salam juga merupakan etika penting di tempat kerja."],"vocab":["masa berkabung","musibah (di sini: kematian dalam keluarga)","menahan diri, menghindari","mengakar, menjadi kebiasaan","keadaan, alasan","tidak perlu","kekhawatiran, perhatian","surat/kartu salam","berusaha memperhatikan, berupaya","memahami perasaan orang lain, berempati"],"grammar":[{"t":"〜に基づいて","note":"Menyatakan berdasarkan sesuatu sebagai dasar atau landasan. Contoh: 「お祝いごとを慎むべきだという考え方に基づいて、この習慣が根付いた」."},{"t":"〜にすぎない","note":"Berarti \"hanyalah ~\", menekankan bahwa cakupannya terbatas. Contoh: 「『年賀状を出せません』という連絡にすぎず」."},{"t":"〜わけではない","note":"Negasi sebagian, berarti \"bukan berarti ~\", dipakai untuk menyangkal anggapan yang mungkin muncul. Contoh: 「相手に返事を求めているわけではない」."},{"t":"〜を通して/〜を通じて","note":"Menyatakan lewat sarana atau pengalaman tertentu. Contoh: 「季節の挨拶を通して気持ちを伝える文化」「今回の経験を通じて」."}]},"a-n3-16-n4":{"title":"Saat Kartu Pos Berkabung Datang","topic":"Budaya","trans":["Awal November, sebuah kartu pos datang dari Pak Tanaka, teman sekantorku. Saat kubuka, tertulis 「喪中なので、新年のあいさつをしません」 (\"Karena sedang berkabung, kami tidak mengirim ucapan Tahun Baru\"). Baru saat itu aku tahu bahwa ayah Pak Tanaka meninggal pada musim panas.","Ini disebut 「喪中はがき」, yaitu kartu pos untuk memberi tahu bahwa kita tidak mengirim kartu Tahun Baru (年賀状). Ada anggapan bahwa selama keluarga berduka, mereka tidak merayakan apa pun. Kartu ini biasanya tiba sebelum orang mulai menyiapkan kartu Tahun Baru.","Aku sempat bingung, tetapi setelah bertanya ke rekan kerja, aku memutuskan tidak mengirim kartu Tahun Baru. Aku diberi tahu bahwa kalau setelah tahun baru aku mengirim 「寒中見舞い」, perasaanku akan tersampaikan. 寒中見舞い adalah surat yang menunjukkan kepedulian pada seseorang di musim dingin, dan tidak berisi ucapan selamat. Di surat itu, aku berusaha menulis terima kasih atas kartu posnya dan kata-kata yang menunjukkan kepedulianku pada keluarganya. Aku belajar bahwa memikirkan perasaan orang lain dan mengubah cara menyampaikan salam juga merupakan etika yang penting."],"vocab":["tiba, sampai","rekan kerja","meninggal","memberi tahu","persiapan","bingung, ragu","tersampaikan, dipahami","khawatir, peduli","terima kasih, ucapan terima kasih"],"grammar":[{"t":"〜てみると","note":"Setelah mencoba melakukan sesuatu, ternyata menemukan sesuatu. Contoh: 「開けてみると、『喪中なので、新年のあいさつをしません』と書いてあった」."},{"t":"〜ことにする","note":"Menyatakan keputusan sendiri untuk melakukan atau tidak melakukan sesuatu. Contoh: 「年賀状は出さないことにした」."},{"t":"〜てもらう","note":"Menyatakan menerima suatu tindakan atau informasi dari orang lain, dengan nuansa berterima kasih. Contoh: 「気持ちが伝わると教えてもらった」."},{"t":"〜ようにする","note":"Menyatakan berusaha melakukan sesuatu atau membiasakan diri. Contoh: 「家族を思う言葉を書くようにした」."}]},"a-n3-15-n2":{"title":"Tahun Pertamaku Mengurus Penyesuaian Pajak Akhir Tahun","topic":"Tempat Kerja","trans":["Menjelang akhir tahun, bagian HRD mengirimkan email dan dokumen berjudul 「年末調整のご案内」. Di dokumen itu ada kolom untuk mengisi status tanggungan keluarga dan premi asuransi, tapi aku sama sekali tidak tahu harus mulai menulis dari mana. Ini pertama kalinya aku bekerja di Jepang, dan istilah 「年末調整」 sendiri pun belum pernah kudengar sebelumnya.","Aku berkonsultasi dengan Pak Tanaka yang duduk di sebelahku, dan beliau menenangkanku dengan berkata, 「毎年の手続きですから、心配はいりませんよ」 (ini prosedur tahunan, jadi tidak perlu khawatir). Pajak yang dipotong dari gaji tiap bulan ternyata hanyalah perhitungan sementara, dan pada akhir tahun pajak setahun penuh dihitung ulang. Karena jumlah pajak berubah sesuai kondisi keluarga dan premi asuransi yang dibayar, mengisinya dengan benar itu penting. Cara pengisiannya juga belum tentu sama di setiap perusahaan, jadi aku disuruh bertanya langsung ke HRD kalau ada yang tidak jelas.","Keesokan harinya, aku pergi bertanya ke Bu Sato dari HRD. Sambil menunjukkan contoh pengisian, beliau menjelaskan satu per satu dengan sabar. Kalau punya asuransi yang dibayar sendiri, kadang kita juga memerlukan surat keterangan dari perusahaan asuransi. Bukannya aku tidak suka bertanya, tapi aku merasa sungkan menyapa staf HRD yang kelihatannya sibuk. Namun Bu Sato menjawab sambil tersenyum, 「初めてなら聞いて当然ですよ」 (kalau baru pertama kali, wajar kok bertanya), dan perasaanku pun jadi sedikit lebih lega.","Sepulang ke rumah, aku memutuskan untuk mencari dokumen asuransi yang ada di rumah dan memeriksa dengan teliti apa saja yang harus ditulis. Prosedur dan cara pengumpulan yang rinci berbeda-beda di tiap perusahaan, jadi pastikan kamu membaca penjelasan dari perusahaanmu sendiri. Sekilas penyesuaian pajak akhir tahun tampak merepotkan, tapi aku jadi paham bahwa ini adalah prosedur penting untuk menghitung pajak setahun penuh dengan benar."],"vocab":[{"w":"年末調整","m":"年末調整 (prosedur perhitungan ulang pajak setahun di akhir tahun)"},{"w":"扶養","m":"tanggungan (menafkahi anggota keluarga)"},{"w":"記入","m":"mengisi, menuliskan"},{"w":"見当","m":"gambaran, perkiraan"},{"w":"仮","m":"sementara, tidak resmi"},{"w":"仕組み","m":"mekanisme, sistem"},{"w":"証明書","m":"surat keterangan, sertifikat"},{"w":"一見","m":"sekilas, sepintas"},{"w":"精算","m":"perhitungan akhir, penyelesaian"}],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa saat satu hal berubah, hal lain ikut berubah. Contoh: 「年末が近づくに伴って、人事部から「年末調整のご案内」というメールと書類が届いた」"},{"t":"〜に応じて","note":"Menyatakan perubahan sesuai dengan atau menyesuaikan kondisi tertentu. Contoh: 「家族の状況や支払った保険料に応じて税額が変わるため」"},{"t":"〜とは限らない","note":"Menyatakan bahwa belum tentu, tidak selalu demikian (negasi sebagian). Contoh: 「どの会社でも書き方が同じとは限らないので」"},{"t":"〜に対して","note":"Menyatakan sasaran atau objek dari suatu tindakan atau perasaan. Contoh: 「忙しそうな人事の担当者に対して声をかけにくいと感じていた」"}]},"a-n3-15-n4":{"title":"Pertama Kalinya Mengurus Penyesuaian Pajak Akhir Tahun","topic":"Tempat Kerja","trans":["Menjelang akhir tahun, perusahaan mengirimkan email dan dokumen. Isinya penjelasan tentang 「年末調整」. Di dokumen itu ada kolom untuk menulis soal keluarga dan biaya asuransi, tapi aku tidak tahu harus mulai menulis dari mana. Ini pertama kalinya aku bekerja di Jepang, jadi aku bahkan tidak tahu istilah 「年末調整」.","Aku bertanya kepada Pak Tanaka yang duduk di sebelahku, dan beliau berkata, 「毎年することだから、心配しなくていいですよ」 (ini dilakukan setiap tahun, jadi tidak perlu khawatir). Katanya, pajak yang dipotong dari gaji tiap bulan hanyalah perhitungan sementara. Di akhir tahun, pajak untuk satu tahun penuh dihitung sekali lagi. Cara pengisiannya sedikit berbeda di tiap perusahaan, jadi aku disuruh bertanya ke orang HRD kalau ada yang tidak kumengerti.","Keesokan harinya, aku pergi bertanya ke Bu Sato dari HRD. Bu Sato menunjukkan contoh cara pengisian dan mengajariku satu per satu. Katanya, kalau punya asuransi yang dibayar sendiri, kadang juga diperlukan kertas dari perusahaan asuransi. Beliau kelihatan sibuk, jadi aku merasa sungkan untuk menyapa. Tapi Bu Sato berkata sambil tersenyum, 「初めてなら、聞いていいですよ」 (kalau baru pertama kali, boleh kok bertanya).","Setelah pulang ke rumah, aku memutuskan untuk mencari dokumen asuransi dan membacanya pelan-pelan. Cara yang rinci berbeda-beda di tiap perusahaan, jadi bacalah penjelasan dari perusahaanmu dengan saksama. Penyesuaian pajak akhir tahun kelihatannya merepotkan, tapi aku jadi tahu bahwa ini prosedur yang penting."],"vocab":[{"w":"年末","m":"akhir tahun"},{"w":"書類","m":"dokumen, berkas"},{"w":"保険","m":"asuransi"},{"w":"心配","m":"khawatir"},{"w":"税金","m":"pajak"},{"w":"計算","m":"perhitungan"},{"w":"人事","m":"HRD (bagian personalia)"},{"w":"見本","m":"contoh"},{"w":"必要","m":"perlu, dibutuhkan"},{"w":"手続き","m":"prosedur, pengurusan"}],"grammar":[{"t":"〜ので","note":"Menyatakan sebab atau alasan dengan nada lebih lembut daripada 「から」. Contoh: 「日本で働くのは初めてなので、「年末調整」という言葉も知りませんでした」"},{"t":"〜そうだ(kabar yang didengar)","note":"Menyatakan kabar yang didengar dari orang lain, artinya \"katanya…\". Contoh: 「毎月の給料から引かれる税金は、とりあえずの計算だそうです」"},{"t":"〜ように言われる","note":"Menyatakan bahwa seseorang diminta atau diingatkan untuk melakukan sesuatu. Contoh: 「分からないところは人事の人に聞くように言われました」"},{"t":"〜ことにする","note":"Menyatakan keputusan sendiri untuk melakukan sesuatu. Contoh: 「保険の書類を探して、ゆっくり読むことにしました」"}]},"a-n4-12-n2":{"title":"Suntik Vaksin Flu","topic":"Kesehatan","trans":["Begitu masuk bulan Oktober, di pintu masuk klinik dekat rumah dipasang pengumuman bertuliskan 「Vaksin flu sudah mulai dibuka」. Melihat pengumuman itu, aku jadi sadar lagi bahwa musim ini datang lagi tahun ini. Sebenarnya, musim dingin tahun lalu aku terkena flu dan terpaksa izin dari kantor selama satu minggu penuh. Apalagi aku benar-benar merasakan bahwa menjaga kondisi tubuh juga bagian dari pekerjaan, jadi tahun ini aku memutuskan untuk divaksin lebih awal.","Setelah membuat janji lewat telepon, aku pergi ke klinik. Di meja pendaftaran aku diberi formulir pemeriksaan, lalu setelah mengukur suhu tubuh, aku mengisi kondisi badanku. Suntikannya tidak sesakit yang kubayangkan, sampai-sampai aku merasa agak kecewa karena terlalu mudah. Setelah disuntik, aku diminta menunggu sebentar di ruang tunggu untuk diamati. Kondisi tubuh bisa saja berubah tiba-tiba, jadi mengikuti arahan dan beristirahat memang sudah sewajarnya.","Di sisi lain, vaksinasi tidak bisa memakai asuransi kesehatan, jadi biayanya tidak bisa dibilang murah. Katanya harganya berbeda-beda tergantung rumah sakit, dan dalam kasusku biayanya 3.500 yen. Berbeda dengan pengobatan, pencegahan adalah persiapan sebelum sakit, jadi wajar kalau biayanya ditanggung sendiri. Meski begitu, kalau memikirkan kerugian karena harus izin kerja selama seminggu penuh, menurutku ini bukan pengeluaran yang terlalu mahal.","Katanya efeknya baru muncul sekitar dua minggu kemudian, jadi perlu divaksin lebih awal. Kalau baru buru-buru divaksin setelah wabah mulai menyebar, belum tentu keburu. Kalau sudah selesai sebelum musim flu merebak, kamu bisa melewati musim dingin dengan tenang."],"vocab":["pengumuman (kertas) yang ditempel","merasakan dengan sangat dalam","formulir pemeriksaan (anamnesis)","mengisi (formulir)","kecewa karena tidak sesuai ekspektasi, merasa antiklimaks","biaya tanggungan sendiri","kerugian","pengeluaran, biaya","menyebar, mewabah"],"grammar":[{"t":"〜ざるを得ない","note":"Berarti \"terpaksa, tidak punya pilihan selain~\", dengan nuansa pasrah. Contoh: 「一週間も会社を休まざるを得ませんでした」."},{"t":"〜に対して","note":"Menyatakan kontras, \"berbeda dengan~, sedangkan~\". Contoh: 「治療に対して予防は病気になる前の備えである以上」."},{"t":"〜以上","note":"Berarti \"karena~, mengingat~\", diikuti penilaian atau kesimpulan yang wajar. Contoh: 「備えである以上、自己負担になるのも仕方ない」."},{"t":"〜とは限らない","note":"Berarti \"belum tentu~\", menyangkal pernyataan yang mutlak. Contoh: 「流行が始まってから慌てて接種しても、間に合うとは限りません」."}]},"a-n4-12-n3":{"title":"Suntik Vaksin Flu","topic":"Kesehatan","trans":["Begitu masuk bulan Oktober, di klinik dekat rumah ditempel pengumuman 「Vaksinasi sudah dimulai」. Musim dingin tahun lalu aku terkena flu dan harus izin dari kantor selama satu minggu penuh. Karena pengalaman itu, tahun ini aku memutuskan untuk divaksin lebih awal.","Setelah membuat janji lewat telepon, aku pergi ke klinik, dan di meja pendaftaran aku diberi formulir pemeriksaan. Aku diminta mengukur suhu tubuh dulu, lalu menulis kondisi badanku di formulir itu. Suntikannya tidak sesakit yang kukira, jadi aku merasa agak lega.","Setelah selesai, aku diminta beristirahat sebentar di ruang tunggu. Karena vaksinasi tidak bisa memakai asuransi kesehatan, rasanya agak mahal. Katanya harganya berbeda-beda tergantung rumah sakit, dan kali ini aku membayar 3.500 yen.","Katanya efeknya baru muncul sekitar dua minggu kemudian. Kalau divaksin sebelum wabah mulai, kamu bisa melewati musim dingin dengan tenang. Tubuh butuh waktu untuk bersiap, jadi menurutku penting untuk divaksin lebih awal."],"vocab":["vaksinasi, suntik vaksin","formulir pemeriksaan (anamnesis)","meja pendaftaran","ruang tunggu","asuransi kesehatan","efek","wabah, penyebaran (penyakit)","lebih awal","kondisi","harga"],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan yang diambil sendiri. Dalam teks: 「今年は早めに予防接種を受けることにしました」, keputusan yang diambil karena pengalaman tahun lalu."},{"t":"〜ため(sebab)","note":"Menyatakan sebab/alasan dengan nuansa lebih formal dan tertulis daripada「から」. Dalam teks: 「予防接種には健康保険が使えないため、少し高いと感じました」."},{"t":"〜ように言われる","note":"Menyatakan diminta atau disuruh melakukan sesuatu (perintah yang dikutip secara tidak langsung). Dalam teks: 「問診票に書くように言われました」「待合室で休むように言われました」."},{"t":"〜によって","note":"Berarti \"tergantung pada…\", berbeda sesuai orang atau keadaan. Dalam teks: 「値段は病院によって違うそうですが」."}]},"a-n4-13-n2":{"title":"七五三の日","topic":"Budaya","trans":["Pada suatu hari Sabtu di bulan November, aku pergi jalan-jalan ke kuil Shinto di dekat rumah bersama temanku. Begitu melangkah masuk ke halaman kuil, aku melihat banyak anak yang mengenakan kimono yang indah beserta keluarga mereka. Di antaranya, yang paling berkesan bagiku adalah seorang gadis kecil berkimono merah yang berfoto dengan wajah gembira sekali.","Menurut Tanaka, temanku yang orang Jepang, ini adalah tradisi bernama 七五三. 七五三 adalah tradisi untuk merayakan pertumbuhan anak yang genap berusia tiga, lima, dan tujuh tahun, sekaligus bersyukur karena mereka bisa tumbuh dengan selamat sampai sekarang. Pada umumnya, keluarga meminta pendeta kuil mendoakan anak mereka, dengan harapan anak itu akan terus tumbuh sehat. Cara merayakannya memang belum tentu sama di setiap keluarga, tetapi perasaan mendoakan kesehatan anak kemungkinan besar sama di mana pun.","Tanaka menunjuk kantong kertas panjang yang dipegang anak-anak itu, lalu melanjutkan penjelasannya. Di dalam kantong itu ada permen panjang dan tipis bernama 千歳飴, yang katanya mengandung harapan keluarga agar sang anak panjang umur. Tanaka juga memberitahuku bahwa 千歳飴 bisa dibeli di toko kue tradisional Jepang dan tempat-tempat lainnya.","Bagi Tanaka ini adalah tradisi yang akrab, sedangkan bagiku ini pemandangan yang baru pertama kali kulihat, dan rasanya sangat segar. Walaupun hanya permen yang tampilannya sederhana, begitu tahu betapa dalam makna yang terkandung di dalamnya, aku tidak bisa tidak memikirkan arti dari tradisi ini. Kalau kelak punya anak, kurasa aku pun pasti tidak akan tahan untuk menyiapkan 千歳飴 dan merayakan pertumbuhannya."],"vocab":["halaman kuil Shinto atau kuil Buddha","mengenakan, memakai (身にまとう)","berkesan, mengesankan","acara tradisi, upacara adat","pertumbuhan","harapan, doa","sederhana, polos","pemandangan, suasana","sama-sama, umum"],"grammar":[{"t":"〜とは限らない","note":"Artinya \"belum tentu\", menunjukkan bahwa sesuatu tidak selalu begitu. Contoh: 「祝い方は家庭によって同じとは限らないが」 artinya cara merayakannya belum tentu sama di setiap keluarga."},{"t":"〜に対して","note":"Menyatakan kontras: \"A begini, sedangkan B begitu…\". Contoh: 「田中さんにとっては身近な行事であるのに対して、わたしには初めて目にする光景で」 membandingkan perasaan Tanaka dengan perasaan si penulis."},{"t":"〜ざるを得ない","note":"Artinya \"terpaksa harus…\", tidak ada pilihan lain dalam situasi tersebut. Contoh: 「行事の意味を考えざるを得なかった」 artinya mau tidak mau harus memikirkan makna tradisi ini."},{"t":"〜ずにはいられない","note":"Artinya \"tidak tahan untuk…, tanpa sadar jadi…\", yaitu perasaan atau dorongan yang muncul dengan sendirinya. Contoh: 「成長を祝わずにはいられないだろう」 artinya pasti tidak akan tahan untuk merayakan pertumbuhan anak."}]},"a-n4-13-n3":{"title":"七五三の日","topic":"Budaya","trans":["Pada suatu hari Sabtu di bulan November, aku pergi jalan-jalan ke kuil Shinto di dekat rumah bersama temanku. Di halaman kuil, terlihat banyak anak yang mengenakan kimono yang cantik beserta keluarga mereka. Seorang gadis kecil berkimono merah berfoto dengan wajah gembira, difotokan oleh keluarganya. Suasananya jauh lebih ramai daripada kuil biasanya, dan terasa seperti hari yang istimewa.","Tanaka, temanku yang orang Jepang, memberitahuku bahwa ini adalah tradisi bernama 七五三. 七五三 adalah tradisi untuk merayakan pertumbuhan anak yang berusia tiga, lima, dan tujuh tahun. Katanya, keluarga meminta pendeta kuil mendoakan anak mereka, dan memohon agar anak itu tumbuh sehat. Menurutku, bagi keluarga ini juga menjadi kesempatan penting untuk merasakan kembali pertumbuhan anak mereka.","Tanaka menunjuk kantong kertas panjang yang dipegang anak-anak itu. Di dalamnya ada permen panjang dan tipis bernama 千歳あめ. Katanya, permen ini mengandung harapan keluarga agar sang anak panjang umur. Tanaka bilang 千歳あめ bisa dibeli di toko kue tradisional Jepang dan tempat-tempat lainnya. Kalau kelak punya anak, aku juga ingin menyiapkan 千歳あめ dan merayakannya dengan cara yang sama."],"vocab":["halaman (kuil Shinto, kuil Buddha)","acara tradisi, upacara adat","pertumbuhan","merayakan","doa, mendoakan","tumbuh, dibesarkan","harapan, doa","panjang dan tipis","masa depan","persiapan, menyiapkan"],"grammar":[{"t":"〜ように(tujuan・harapan)","note":"Menyatakan melakukan sesuatu atau berdoa agar suatu keadaan tercapai. Contoh: 「子どもが元気に育つようにとお願いするそうです」"},{"t":"〜てもらう","note":"Menyatakan meminta orang lain melakukan sesuatu untuk diri sendiri atau orang dalam kelompok sendiri, dan menerima kebaikannya. Contoh: 「家族に写真をとってもらっていました」「お祈りをしてもらい」"},{"t":"〜てほしい","note":"Menyatakan harapan agar orang lain melakukan sesuatu atau berada dalam keadaan tertentu. Contoh: 「長生きしてほしいという家族の願い」"},{"t":"〜そうです(kabar yang didengar)","note":"Menyatakan informasi yang didengar dari orang lain. Contoh: 「願いがこめられているそうです」"}]},"a-n4-14-n2":{"title":"冬の電気代と上手に付き合う","topic":"Kehidupan","trans":["Musim dingin di Jepang itu dinginnya di luar dugaan, bukan hanya di luar ruangan, tapi juga di dalam rumah. Di kamar tua, udara dingin masuk lewat celah jendela, jadi meski pemanas dinyalakan, ruangan tetap susah hangat. Seiring suhu yang turun, waktu di mana aku terpaksa bergantung pada pemanas pun jadi makin lama. Waktu melihat tagihan yang datang bulan lalu, tagihan listriknya jauh lebih tinggi dari biasanya, dan aku pun refleks kaget.","Waktu aku cerita soal itu ke temanku, aku diajari beberapa trik berhemat. Pertama, pakai selimut listrik untuk menghangatkan futon sebelum tidur. Kalau pemanas menaikkan suhu ruangan, sebaliknya pelembap udara katanya bisa membuat ruangan terasa lebih hangat meski suhunya sama.","Sejak mengganti dengan tirai tebal, dinginnya area dekat jendela jelas berkurang, dan aku benar-benar merasakan besarnya efek itu. Suhu pemanas juga kuatur sedikit lebih rendah, lalu sebagai gantinya aku memakai jaket. Tanaka juga menyarankan agar pemanas di ruangan yang tidak dipakai sebaiknya dimatikan.","Soal paket tarif, daripada menilai sendiri, bertanya detailnya langsung ke perusahaan listrik pasti lebih terpercaya. Menahan dingin belum tentu satu-satunya cara berhemat, dan dengan trik serta cara pemakaian yang cerdas, bebannya juga bisa dikurangi. Kalau terus melakukan usaha-usaha kecil, sepertinya musim dingin ini pun aku bisa melewatinya tanpa terlalu memikirkan tagihan listrik."],"vocab":["(suhu) turun drastis, jadi sangat dingin","celah","tagihan","hemat, penghematan","menghangatkan","mereda, berkurang","merasakan secara nyata","saran, nasihat","bertanya, menanyakan","menahan, bersabar"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring satu hal berubah, hal lain ikut berubah. Dalam teks: 「気温が下がるのに伴って、どうしても暖房に頼らざるを得ない時間が長くなります」"},{"t":"〜ざるを得ない","note":"Berarti terpaksa, tidak ada pilihan selain melakukannya (bentuk ない verba tanpa ない + ざるを得ない). Dalam teks: 「暖房に頼らざるを得ない時間」"},{"t":"〜に対して","note":"Menyatakan kontras, dua hal dibandingkan satu sama lain. Dalam teks: 「暖房が室温を上げるのに対して、加湿器は同じ室温でも暖かく感じさせてくれるそうです」"},{"t":"〜とは限らない","note":"Berarti belum tentu, tidak selalu begitu; dipakai untuk menyangkal anggapan yang terlalu mutlak. Dalam teks: 「寒さを我慢することだけが節約とは限らず」"}]},"a-n4-14-n3":{"title":"冬の電気代","topic":"Kehidupan","trans":["Musim dingin di Jepang terasa lebih dingin dari yang dibayangkan, bahkan saat berada di dalam rumah. Di kamar tua, udara dingin masuk dari jendela, jadi meski pemanas dinyalakan, ruangan susah hangat. Waktu melihat tagihan bulan lalu, tagihan listriknya lebih tinggi dari biasanya, dan aku sangat kaget. Lalu aku berkonsultasi dengan temanku, dan dia mengajariku beberapa trik berhemat.","Pertama, aku memakai selimut listrik dan berusaha menghangatkan futon sebelum tidur. Katanya kalau pelembap udara dinyalakan, ruangan terasa lebih hangat meski suhunya sama. Sejak mengganti dengan tirai tebal, dingin yang terasa di dekat jendela berkurang banyak. Suhu pemanas kuatur sedikit lebih rendah, dan sebagai gantinya aku memutuskan untuk memakai jaket.","Tanaka memberi tahu aku bahwa pemanas di ruangan yang tidak dipakai sebaiknya dimatikan. Soal paket tarif, sebaiknya tanyakan detailnya ke perusahaan listrik. Kalau terus melakukan usaha kecil sekalipun, sepertinya aku bisa melewati musim dingin tanpa terlalu memikirkan tagihan listrik. Aku merasa yang penting bukan menahan dingin, tapi pandai-pandai mencari cara."],"vocab":["pemanas ruangan","tagihan","konsultasi, berdiskusi","hemat, penghematan","pelembap udara","pengaturan","menghabiskan waktu, menjalani hari","akal, trik cerdas","biaya, tarif"],"grammar":[{"t":"〜ため(原因)","note":"Menyatakan sebab atau alasan, lebih formal daripada「から」. Dalam teks: 「古い部屋では窓から冷たい空気が入ってくるため、暖房をつけてもなかなかあたたまりません」"},{"t":"〜ようにしている","note":"Berarti berusaha membiasakan diri atau sebisa mungkin melakukan sesuatu. Dalam teks: 「寝る前にふとんをあたためておくようにしています」"},{"t":"〜ことにする","note":"Menyatakan keputusan yang diambil sendiri untuk melakukan sesuatu. Dalam teks: 「そのかわり上着を着て過ごすことにしました」"},{"t":"〜わけではない","note":"Menyatakan negasi sebagian, \"bukan berarti ...\". Dalam teks: 「寒さをがまんするわけではなく、上手に工夫することが大切だと感じました」"}]},"a-n4-15-n2":{"title":"Awal Bersih-Bersih Besar Akhir Tahun, Lebih Baik Mulai Lebih Awal","topic":"Kehidupan","trans":["Setiap bulan Desember tiba, aku selalu dikejar-kejar bersih-bersih besar sampai kelelahan. Hal itu hampir jadi kebiasaan tahunanku di akhir tahun. Karena itu, tahun ini sebelum masuk bulan Desember, aku mencoba menulis daftar tempat yang perlu dibersihkan. Dapur, kamar mandi, jendela, pintu masuk, dan sebagainya. Setelah benar-benar menuliskannya, aku baru sadar tempatnya lebih banyak dari yang kukira.","Selanjutnya, aku pergi ke toko obat dan kosmetik untuk membeli semua cairan pembersih dan spons yang dibutuhkan. Kata pegawai toko, cairan pembersih untuk kamar mandi juga bisa menghilangkan jamur, jadi itu sangat berguna bagiku. Hanya saja, kalau mencoba menyelesaikan semuanya sekaligus pasti capek, jadi aku memutuskan membersihkan satu tempat saja setiap minggu.","Misalnya minggu ini dapur, minggu depan kamar mandi. Kalau tempatnya ditentukan dulu untuk tiap minggu, kita bisa mengerjakannya tanpa memaksakan diri. Aku menceritakan rencana ini ke teman serumahku, Lin, dan dia bilang mau mengerjakannya bersama. Aku bertugas di dapur dan kamar mandi, sedangkan Lin di jendela dan pintu masuk. Untuk sampah besar, cara membuangnya berbeda-beda tergantung daerah, jadi perlu dicek lewat panduan dari kantor kecamatan.","Kata temanku, kalau mulai lebih awal, bukan hanya pekerjaan bersihnya saja yang terasa ringan, tapi perasaan juga jadi lebih lega. Memang benar, mengerjakannya sambil dikejar waktu di akhir tahun dan mengerjakannya dengan santai pasti terasa sangat berbeda capeknya. Dengan cara ini, sepertinya akhir tahun ini aku bisa istirahat dengan tenang, dan aku sudah menantikannya dari sekarang."],"vocab":["kebiasaan rutin (tahunan)","kelelahan, capek sekali","menuliskan, membuat daftar","membeli semua yang diperlukan","cairan pembersih, deterjen","bertugas, bertanggung jawab","kantor kecamatan (kantor pemerintah distrik)","konfirmasi, memastikan","kelonggaran, sikap santai"],"grammar":[{"t":"〜たところ","note":"Menyatakan bahwa setelah melakukan suatu tindakan, muncul hasil yang tak terduga atau tertentu. Contoh: 「リンさんにこの計画を話したところ、いっしょにやろうと言ってくれました」"},{"t":"〜によると","note":"Menyatakan sumber kabar atau informasi, sering diikuti 「〜そうだ、〜ということだ」. Contoh: 「店の人によると、おふろ用の洗剤はカビも落とせるということで」"},{"t":"〜によって違う","note":"Menyatakan sesuatu berbeda tergantung orang, daerah, atau keadaan. Contoh: 「出し方が地域によって違うため、区役所の案内で確認しておく必要があります」"},{"t":"〜のと〜のとでは","note":"Membandingkan dua cara atau keadaan dan menunjukkan perbedaan yang besar di antara keduanya. Contoh: 「年末に追われながらやるのと、余裕を持って進めるのとでは、疲れ方がまったく違うでしょう」"}]},"a-n4-15-n3":{"title":"Ayo Mulai Bersih-Bersih Besar Akhir Tahun Lebih Awal","topic":"Kehidupan","trans":["Setiap bulan Desember tiba, aku selalu dikejar-kejar bersih-bersih besar sampai lemas kelelahan. Karena itu, tahun ini sebelum masuk Desember, aku mencoba menulis daftar tempat yang mau dibersihkan. Dapur, kamar mandi, jendela, pintu masuk, dan sebagainya. Ternyata lebih banyak dari yang kukira, aku sampai kaget.","Selanjutnya, aku pergi ke toko obat dan kosmetik, lalu membeli cairan pembersih dan spons. Kata pegawai toko, cairan pembersih untuk kamar mandi juga bisa menghilangkan jamur sampai bersih. Karena kalau mengerjakan semuanya sekaligus pasti capek, aku memutuskan membersihkan satu tempat saja setiap minggu. Urutannya sudah kutentukan, misalnya minggu ini dapur, minggu depan kamar mandi, dan seterusnya.","Waktu aku bilang ke teman serumahku, Lin, dia bilang mau mengerjakannya bersama. Aku bertugas di dapur dan kamar mandi, sedangkan Lin di jendela dan pintu masuk. Untuk sampah besar, cara membuangnya perlu dicek dulu lewat panduan dari kantor kecamatan. Kata temanku, kalau mulai lebih awal, hati pun jadi lebih lega. Kurasa dengan cara ini aku bisa terus mengerjakannya tanpa memaksakan diri, jadi akhir tahun pun sepertinya bisa istirahat dengan tenang."],"vocab":["dikejar-kejar, kewalahan","cairan pembersih, deterjen","bisa menghilangkan (noda, dll.)","urutan, giliran","bertugas, bertanggung jawab","kantor kecamatan (kantor pemerintah distrik)","memeriksa, mencari tahu","kelonggaran, ketenangan","terkejut, kaget"],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan yang diambil sendiri. Dalam teks: 「毎週一か所だけそうじすることにしました」 artinya aku memutuskan membersihkan satu tempat saja setiap minggu."},{"t":"〜によると〜そうだ","note":"Mengutip sumber dan menyampaikan informasi yang didengar dari orang lain. Dalam teks: 「店の人によると、おふろ用の洗剤はカビもきれいに落とせるそうです」."},{"t":"〜というように","note":"Dipakai untuk memberi contoh, artinya \"seperti ini\". Dalam teks: 「今週は台所、来週はおふろ、というように、順番を決めておきました」."},{"t":"〜ことになる","note":"Menyatakan hasil atau pengaturan yang menjadi seperti itu (tidak sepenuhnya karena kehendak pribadi). Dalam teks: 「リンさんはまどとげんかんを担当することになりました」."},{"t":"〜ため(sebab)","note":"Menyatakan sebab atau alasan, lebih formal/tertulis daripada 「ので」. Dalam teks: 「一度に全部やろうとすると疲れてしまうため」."}]},"a-n5-10-n2":{"title":"Memesan Makanan di Restoran","topic":"Kehidupan","trans":["Hari ini aku pergi ke restoran bersama temanku. Setelah duduk, aku membandingkan menu dengan teliti dan berpikir matang-matang mau memesan hidangan yang mana. Saat makan di luar, sulit membayangkan rasa hanya dari informasi di menu, jadi tidak jarang aku bingung memilih.","Setelah hidangannya ditentukan, aku memanggil pelayan untuk memesan. Akhirnya aku memutuskan memesan set makan (定食) dan teh, lalu menyampaikannya kepada pelayan. Momen menyebutkan pesanan seperti ini juga merupakan kesempatan berharga untuk langsung memakai bahasa Jepang yang sudah dipelajari.","Tidak lama setelah memesan, hidangan yang kupesan sudah diantar, dan aku sedikit terkejut. Rasanya juga enak sekali, jadi makanan kali ini lebih lezat dari yang kuharapkan. Kalau penyajiannya cepat dan rasanya pun terjamin, tingkat kepuasan pelanggan tentu dengan sendirinya naik.","Setelah selesai makan, aku berdiri dari kursi dan menuju kasir, lalu membayar di sana. Karena bisa pakai kartu, aku tidak perlu membawa banyak uang tunai, dan itu sangat praktis. Seiring makin beragamnya cara pembayaran, toko yang menerima kartu juga menjadi tempat yang menenangkan bagi wisatawan maupun pelajar bahasa. Ada juga toko yang hanya menerima uang tunai, dan tidak semua tempat bisa pakai kartu, jadi kali ini aku sangat terbantu."],"vocab":["makan di luar","membandingkan, melihat sambil membandingkan","membayangkan","pesanan, memesan","berharga","tingkat kepuasan","membayar","penganekaragaman, jadi beragam","menenangkan, bisa diandalkan"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring berubahnya satu hal, hal lain ikut berubah. Contoh:「支払い方法が多様化するに伴って、カードが使える店は旅行者や学習者にとっても心強い存在になっています」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu selalu ...\", yaitu penyangkalan sebagian terhadap pernyataan yang berlaku untuk semua. Contoh:「どこでもカードが使えるとは限らないので、今回は助かりました」"},{"t":"〜うえに","note":"Menambahkan hal lain setelah hal sebelumnya, biasanya untuk hal yang searah. Mirip \"selain ... juga ...\". Contoh:「料理の提供が早いうえに味も確かなら、客にとって満足度は自然と高くなるものです」"},{"t":"〜ことも少なくない","note":"Dengan negasi ganda, berarti \"hal seperti ini tidak jarang terjadi\", dengan nada yang halus. Contoh:「選ぶのに迷うことも少なくありません」"}]},"a-n5-10-n3":{"title":"Memesan di Restoran","topic":"Kehidupan","trans":["Hari ini aku pergi ke restoran bersama temanku untuk makan. Begitu duduk, kami melihat menu dulu sambil memikirkan mau makan apa. Ada banyak pilihan hidangan sehingga aku bingung, tapi akhirnya aku memilih makanan yang ingin kumakan.","Karena sudah memutuskan mau pesan apa, aku memanggil pelayan untuk memesan. Yang kupesan adalah set makan (定食) dan teh, lalu pelayan mencatat pesananku dan kembali. Kukira menunggunya akan lama, tapi hidangannya datang jauh lebih cepat dari perkiraanku.","Makanannya enak sekali, dan meskipun bukan makanan yang istimewa, aku sangat puas. Setelah selesai makan, aku pergi ke kasir dan membayar. Karena bisa bayar pakai kartu juga, aku merasa itu sangat praktis.","Cara pembayaran berbeda-beda tergantung tokonya, jadi bisa pakai kartu itu sangat membantu. Aku jadi ingin datang lagi ke restoran ini bersama temanku."],"vocab":["makan, hidangan","bingung, ragu memilih","memilih","pelayan","pesanan, memesan","set makan, menu paket","perkiraan, dugaan","puas","membayar","pembayaran"],"grammar":[{"t":"〜ために","note":"Menyatakan tujuan, artinya \"untuk melakukan ～\". Contoh:「食事をするためにレストランへ行きました」。"},{"t":"〜ことにする","note":"Menyatakan keputusan yang diambil sendiri untuk melakukan sesuatu. Contoh:「店員さんを呼んで注文することにしました」。"},{"t":"〜わけではない","note":"Berarti \"bukan berarti ～\", dipakai untuk menyangkal sebagian atau mencegah salah paham. Contoh:「特別なものを食べたわけではありませんが」。"},{"t":"〜によって","note":"Berarti \"tergantung ～\", menjelaskan sesuatu yang berubah sesuai keadaan atau orangnya. Contoh:「店によって支払い方法は違うので」。"}]},"a-n5-11-n2":{"title":"Pengalaman Pertama Memakai Kartu IC","topic":"Kehidupan","trans":["Aku yang baru sebentar tinggal di Jepang memutuskan membeli kartu IC pertamaku di mesin stasiun. Setelah memasukkan seribu yen ke mesin dan menyelesaikan prosedurnya, kartunya sudah ada di tanganku dengan mudah sampai terasa tidak nyata. Selama ini aku mengira membeli tiket itu sudah hal yang biasa, jadi aku sedikit kaget dengan kepraktisan ini.","Saat naik kereta, kamu cukup menempelkan kartu di gerbang tiket, lalu terdengar bunyi pendek 「ピッ」. Karena tidak perlu lagi menghabiskan waktu untuk membeli tiket, bergerak di stasiun jadi jauh lebih lancar daripada sebelumnya. Lagi pula, tempat yang bisa memakai kartu ini belum tentu hanya kereta. Kartu ini juga bisa dipakai untuk membayar di bus dan minimarket, jadi berguna di banyak situasi sehari-hari.","Namun kemarin, saat aku hendak melewati gerbang tiket, terdengar bunyi keras 「ピンポーン」. Penyebabnya adalah saldo di kartuku tidak cukup. Menghadapi bunyi keras yang tiba-tiba itu, aku bingung harus berbuat apa dan mau tak mau jadi panik. Saat itu, petugas stasiun dengan ramah memberi tahu, 「あちらの機械でチャージしてください」 (silakan isi saldo di mesin sebelah sana).","Dari pengalaman ini, aku benar-benar sadar bahwa kartu itu bukan berarti selesai begitu dibeli, tetapi mengelola saldo juga penting. Karena itu, sekarang aku selalu memeriksa saldo kartu sebelum masuk stasiun. Meski hanya kebiasaan kecil, hanya dengan itu aku bisa naik kereta tanpa panik."],"vocab":[{"w":"購入","m":"pembelian, membeli"},{"w":"改札","m":"gerbang tiket"},{"w":"不要","m":"tidak perlu"},{"w":"支払い","m":"pembayaran"},{"w":"響く","m":"terdengar menggema, bergema"},{"w":"残高","m":"saldo"},{"w":"戸惑う","m":"bingung, kebingungan"},{"w":"痛感","m":"menyadari dengan sungguh-sungguh"},{"w":"習慣","m":"kebiasaan"},{"w":"駅員","m":"petugas stasiun"}],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring berubahnya satu hal, hal lain ikut berubah. Contoh: 「切符を買う時間が不要になるに伴って、駅での移動は以前よりずっとスムーズになりました」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu\", membantah anggapan yang terlalu mutlak. Contoh: 「このカードが使える場所は、電車だけとは限りません」"},{"t":"〜に対して","note":"Menyatakan reaksi terhadap suatu objek atau situasi. Contoh: 「突然の大きな音に対して、どうすればよいか分からず、戸惑わざるを得ませんでした」"},{"t":"〜ざるを得ない","note":"Berarti \"terpaksa, mau tak mau\", dengan nuansa tidak ada pilihan lain. Contoh: 「戸惑わざるを得ませんでした」"}]},"a-n5-11-n3":{"title":"Kartu IC Pertamaku","topic":"Kehidupan","trans":["Begitu tiba di Jepang, aku membeli kartu IC untuk pertama kalinya di mesin stasiun. Setelah memasukkan seribu yen ke mesin, aku bisa menerima kartunya. Ternyata lebih mudah dari dugaanku, jadi aku merasa lega.","Saat naik kereta, kamu bisa lewat hanya dengan menempelkan kartu di gerbang tiket. Saat itu terdengar bunyi pendek 「ピッ」, jadi kamu langsung tahu kartunya berhasil dipakai.","Kalau punya kartu IC, kita tidak perlu waktu untuk membeli tiket, jadi sangat praktis. Kartu ini bisa dipakai bukan hanya di kereta, tetapi juga di bus dan minimarket, jadi sangat berguna dalam kehidupan sehari-hari.","Namun kemarin, di gerbang tiket terdengar bunyi keras 「ピンポーン」. Penyebabnya, saldo di kartuku tidak cukup.","Saat aku sedang kebingungan, petugas stasiun memberi tahu, 「あちらの機械でチャージしてください」 (silakan isi saldo di mesin sebelah sana). Berkat itu, aku bisa melewati gerbang tiket dengan lancar.","Dari pengalaman ini, aku belajar bahwa memeriksa sisa saldo sebelum memakai kartu itu penting. Sekarang aku memutuskan untuk selalu melihat saldo kartu sebelum masuk stasiun."],"vocab":[{"w":"改札","m":"gerbang tiket"},{"w":"機械","m":"mesin"},{"w":"安心","m":"lega, tenang"},{"w":"切符","m":"tiket"},{"w":"便利","m":"praktis, mudah"},{"w":"役に立つ","m":"berguna, membantu"},{"w":"足りる","m":"cukup"},{"w":"原因","m":"penyebab"},{"w":"チャージ","m":"isi saldo, top up"},{"w":"確認","m":"memeriksa, memastikan"}],"grammar":[{"t":"〜ため(原因・理由)","note":"Menyatakan sebab atau alasan, dengan nuansa lebih formal/tulisan daripada「から」. Contoh: 「切符を買う時間がかからないため、とても便利です」"},{"t":"〜によって","note":"Menyatakan sebab atau cara: \"melalui, karena\". Contoh: 「この経験によって、使う前に残りのお金を確認することが大切だと学びました」"},{"t":"〜ことにする","note":"Menyatakan keputusan yang diambil sendiri untuk melakukan sesuatu. Contoh: 「必ずカードのお金を見ることにしています」"},{"t":"〜だけでなく","note":"Berarti \"bukan hanya ..., tetapi juga ...\". Contoh: 「電車だけでなく、バスやコンビニでも使えます」"}]},"a-n5-12-n2":{"title":"Oden di Minimarket","topic":"Kehidupan","trans":["Di suatu malam musim dingin, seakan tertarik oleh dinginnya udara di luar, aku masuk ke minimarket. Oden berjajar di samping kasir, dan begitu masuk ke dalam toko, aroma yang menggugah selera langsung tercium. Selain aromanya yang harum, perutku juga terasa lapar, sampai-sampai aku merasa mau tak mau harus membeli oden.","Seiring turunnya suhu udara, oden mulai dipajang di depan minimarket. Aku menyapa pegawai toko dan meminta dia memasukkan lobak putih dan telur. Lalu pegawai itu dengan sopan menanyakan apakah aku butuh kuah dan sawi mustard (karashi). Menanggapi pertanyaan itu, aku menjawab kuahnya saja.","Setelah selesai membayar, aku tidak mampir ke mana-mana dan langsung pulang. Sesampainya di rumah, aku berpikir sebaiknya makan sebelum dingin, jadi langsung mulai makan. Begitu oden yang panas masuk ke mulut, tubuhku yang tadinya membeku pelan-pelan menghangat dari dalam. Lobak yang meresap kuah dengan baik terasa luar biasa enak di malam yang dingin.","Dari sisi bisa dengan mudah makan makanan hangat, oden minimarket bisa dibilang sahabat andalan di musim dingin. Rasa puas tidak selalu datang hanya dari masakan mahal; kadang kita juga terselamatkan oleh makanan sederhana di sekitar kita seperti ini. Kalau musim dingin tiba lagi, sepertinya aku bakal ingin makan oden itu lagi."],"vocab":["tercium menyebar, melayang (aroma)","perut kosong, lapar","suhu udara","depan toko, etalase toko","menanyakan","sopan, teliti","menyelesaikan, merampungkan","menjadi dingin, tidak hangat lagi","luar biasa, istimewa","dekat dengan keseharian, akrab"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring satu perubahan terjadi, perubahan lain ikut berlangsung. Contoh: 「気温が下がるのに伴って、コンビニの店頭にはおでんが並ぶようになる」"},{"t":"〜ざるを得ない","note":"Berarti \"terpaksa ~, mau tak mau harus ~\", yaitu pilihan yang tak terhindarkan karena keadaan. Contoh: 「おでんを買わざるを得ない気持ちになった」"},{"t":"〜に対して","note":"Menunjukkan sasaran suatu tindakan atau sikap, sering diterjemahkan \"terhadap, menanggapi\". Contoh: 「店員の質問に対して、私はつゆだけお願いしますと答えた」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu ~\", dipakai untuk menyangkal pernyataan yang terlalu mutlak. Contoh: 「高価な料理だけが満足感を与えるとは限らず」"}]},"a-n5-12-n3":{"title":"Oden di Minimarket","topic":"Kehidupan","trans":["Pada suatu malam musim dingin yang sangat dingin, aku ingin makan sesuatu yang hangat, lalu masuk ke minimarket. Aku melihat oden diletakkan di samping kasir. Aroma yang harum tercium, dan tiba-tiba perutku jadi lapar.","Saat melihat oden, semuanya tampak enak sehingga aku bingung, tapi akhirnya aku memutuskan memilih lobak putih dan telur. Aku bilang ke pegawai toko, \"Tolong lobak putih dan telurnya.\" Lalu pegawai itu bertanya apakah aku butuh kuah dan sawi mustard (karashi). Setelah berpikir sebentar, aku menjawab, \"Kuahnya saja, tolong.\"","Sesampainya di rumah, aku memutuskan untuk langsung makan sebelum dingin. Saat makan oden yang panas, tubuhku yang tadinya dingin perlahan-lahan menjadi hangat. Di malam yang dingin, aku merasa bersyukur ada makanan hangat yang bisa dibeli dengan mudah seperti ini."],"vocab":["menyadari, memperhatikan","tiba-tiba","bingung, ragu","memilih","pegawai toko","perlu, dibutuhkan","menjadi dingin (makanan/minuman)","menjadi dingin, kedinginan","sedikit demi sedikit, perlahan","patut disyukuri, membuat bersyukur"],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan yang dibuat sendiri oleh pembicara. Dalam teks: keputusan masuk ke minimarket, 「だいこんとたまごを選ぶことにしました」, dan 「すぐ食べることにしました」."},{"t":"〜うちに","note":"Menyatakan melakukan sesuatu selagi suatu keadaan masih berlangsung, atau terjadi perubahan selama suatu tindakan berlangsung. Dalam teks: 「冷めないうちにすぐ食べる」, 「食べているうちに、冷えていた体がだんだん温かくなってきました」."},{"t":"〜かどうか","note":"Berarti \"apakah ... atau tidak\", menyisipkan pertanyaan ya/tidak ke dalam kalimat. Dalam teks: 「つゆとからしが必要かどうかを聞いてくれました」."},{"t":"〜てくる","note":"Menyatakan perubahan atau keadaan yang mulai muncul secara bertahap, mendekat ke arah pembicara. Dalam teks: 「いいにおいがしてきて」, 「だんだん温かくなってきました」."}]},"a-n5-14-n2":{"title":"Malam Musim Dingin Mengelilingi Hot Pot Bersama Teman","topic":"Kehidupan","trans":["Pada suatu hari ketika cuaca dingin makin menggigit, aku memutuskan untuk makan hot pot di rumah bersama teman-teman. Hot pot persiapannya relatif mudah, jadi menurutku pas banget kalau mau kumpul dan makan bareng. Pertama, supaya bahan-bahannya lengkap, kami semua pergi ke supermarket.","Di toko, sambil berdiskusi ke sana kemari, kami memutuskan membeli sawi putih, tahu, dan daging. Banyak orang yang bilang hot pot musim dingin tidak lengkap tanpa sawi putih, dan aku salah satunya. Belanja saja terasa lebih seru daripada biasanya kalau bersama teman.","Sesampainya di rumah, kami langsung memotong sayuran dan bersiap memasukkannya ke panci. Kami memasaknya dengan urutan sayuran dulu, lalu dagingnya ditambahkan belakangan. Daging mudah matang, jadi kalau dimasukkan terlalu awal, kadang malah jadi keras. Seiring panci mulai mendidih, ruangan pun perlahan menjadi hangat.","Meskipun di luar malam yang dingin, di dalam ruangan kami dikelilingi uap yang hangat. Makan sambil mencomot dari panci yang sama bersama-sama membuat rasa makanannya terasa jauh lebih enak. Tapi, adanya makanan enak di meja belum tentu membuat waktunya jadi menyenangkan. Justru karena bisa menghabiskan waktu bersama teman dekat yang tidak perlu sungkan, aku merasa senang dari lubuk hati meski di malam yang dingin."],"vocab":["mengelilingi, berkumpul mengitari","relatif, secara perbandingan","bahan, bahan makanan","tak tergantikan, harus ada","mulai mengerjakan","menambahkan","matang, mendidih","uap, uap panas","akrab dan tidak perlu sungkan"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring satu hal berubah, hal lain ikut berubah. Contoh di teks: 「鍋が煮えるに伴って、部屋の中もだんだん暖かくなっていった」"},{"t":"〜にもかかわらず","note":"Berarti \"meskipun ..., tetapi ...\"; isi bagian depan dan belakang bertentangan dengan dugaan. Contoh di teks: 「外は寒い夜だったにもかかわらず、部屋の中は温かい湯気に包まれていた」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu ...\"; dipakai untuk menyangkal anggapan yang terlalu mutlak. Contoh di teks: 「おいしい料理が食卓にあるからといって、必ず楽しい時間になるとは限らない」"},{"t":"〜からこそ","note":"Menekankan \"justru karena ... maka ...\", menunjukkan alasan yang sebenarnya. Contoh di teks: 「気の置けない友達と一緒に過ごせたからこそ、寒い夜でも心から楽しかったのだと思う」"}]},"a-n5-14-n3":{"title":"Hot Pot Musim Dingin Bersama Teman","topic":"Kehidupan","trans":["Pada suatu hari di musim dingin ketika cuaca makin dingin, aku memutuskan untuk makan hot pot di rumahku bersama teman-teman. Untuk persiapan, pertama-tama kami semua pergi belanja ke supermarket. Yang kami beli adalah sawi putih, tahu, dan daging, dan menurutku itu bahan-bahan yang pas untuk hot pot.","Sesampainya di rumah, kami langsung memotong sayuran dan memasukkannya ke panci satu per satu. Karena sayuran sulit matang, kami memasukkannya lebih dulu, sedangkan dagingnya dimasukkan belakangan. Seiring panci mulai mendidih, ruangan perlahan menjadi hangat. Berkat uapnya, kami sampai lupa dinginnya di luar.","Kalau makan bersama-sama, rasanya jauh lebih enak daripada makan sendirian. Meski di luar malam yang dingin, kami bisa menghabiskan waktu yang menyenangkan. Menurutku hot pot bukan hanya sekadar makanan, tapi juga sesuatu yang bisa mendekatkan satu orang dengan orang lain."],"vocab":[{"w":"鍋","m":"panci; hidangan hot pot"},{"w":"白菜","m":"sawi putih"},{"w":"豆腐","m":"tahu"},{"w":"材料","m":"bahan, bahan makanan"},{"w":"順番","m":"urutan, berurutan"},{"w":"煮える","m":"matang, mendidih"},{"w":"暖かい","m":"hangat"},{"w":"湯気","m":"uap, uap panas"},{"w":"過ごす","m":"menghabiskan (waktu)"},{"w":"近づける","m":"mendekatkan"}],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan si pembicara sendiri untuk melakukan sesuatu. Contoh: 「友達と私の家で鍋をすることにしました」"},{"t":"〜ため(に)","note":"Menyatakan sebab atau alasan, dipakai setelah bentuk biasa. Contoh: 「野菜は火が通りにくいため、先に入れて」"},{"t":"〜ようにする","note":"Menyatakan usaha untuk membiasakan atau memastikan sesuatu terjadi. Contoh: 「肉は後から入れるようにしました」"},{"t":"〜につれて","note":"Menyatakan bahwa seiring satu hal berubah, hal lain ikut berubah. Contoh: 「鍋が煮えてくるにつれて、部屋の中がだんだん暖かくなりました」"}]},"eh-n4-1-n2":{"title":"Hari Aku Masuk Angin","topic":"Buku Bergambar","trans":["Begitu bangun pagi, kepalanya sakit seperti mau pecah, tenggorokannya pun seperti bengkak, dan bicara saja terasa sakit. Badannya juga terasa berat. Tanuki Taro merasa mungkin dia demam, jadi mau tak mau dia memutuskan bahwa dia tidak bisa pergi kerja. Lalu dia menelepon kantor dan berkata, 「かぜをひいてしまったので、今日はお休みをいただけないでしょうか」 (\"Saya masuk angin, boleh saya izin tidak masuk hari ini?\").","Setelah selesai menelepon, Tanuki Taro pergi ke klinik di dekat rumahnya. Di meja resepsionis, dia menunjukkan kartu asuransi kesehatan, mengisi formulir anamnesis yang berisi gejala dan lainnya, lalu menunggu gilirannya. Begitu masuk ruang periksa, dokter bertanya, 「いつから具合が悪いのですか」 (\"Sejak kapan kamu merasa tidak enak badan?\"). Tanuki Taro menjelaskan gejalanya satu per satu: 「昨日の夜からで、せきも出ます」 (\"Sejak tadi malam, dan saya juga batuk\").","Setelah pemeriksaan, dokter berkata, 「ただのかぜですね」 (\"Ini hanya masuk angin biasa\") dan menjelaskan bahwa ini bukan penyakit serius. Dokter juga menyarankan agar dia tidak memaksakan diri: 「薬を飲んで、ゆっくり休んだほうがいいですよ」 (\"Sebaiknya minum obat dan istirahat yang cukup\"). Setelah menebus obat dan pulang, Tanuki Taro berbaring seharian sesuai kata dokter. Malam itu, Kon yang khawatir datang membawakan bubur.","Bubur hangat itu terasa lembut di badan, dan rasanya enak sekali, seakan meresap ke tubuhnya yang lemah. Setelah itu, berkat obat dan istirahat, tiga hari kemudian Tanuki Taro sudah benar-benar sehat kembali. Dia merasa bahwa pergi ke rumah sakit di Jepang yang belum biasa baginya memang agak menakutkan, tetapi setelah dicoba ternyata tidak semengkhawatirkan yang dia kira."],"vocab":["penilaian, memutuskan","menunjukkan, mengajukan","formulir anamnesis","gejala","kondisi (badan)","pemeriksaan, berobat","serius, parah","menyarankan, menganjurkan","istirahat, pemulihan"],"grammar":[{"t":"〜ざるを得ない","note":"Artinya \"mau tak mau harus ~\", yaitu tidak ada pilihan lain selain melakukannya. Contoh: 「仕事に行くのは無理だと判断せざるを得ませんでした」"},{"t":"〜どおり","note":"Artinya \"sesuai ~, sama seperti ~\", dipasang setelah kata benda. Contoh: 「お医者さんの言葉どおり一日中横になって過ごしました」"},{"t":"〜ものの","note":"Artinya \"meskipun ~, tetapi ~\", isi bagian depan dan belakang saling bertentangan. Contoh: 「少し怖かったものの、行ってみれば心配するほどではなかった」"},{"t":"〜おかげで","note":"Artinya \"berkat ~\", menyatakan penyebab dari hasil yang baik. Contoh: 「薬と休養のおかげで、三日後にはすっかり元気になりました」"}]},"eh-n4-1-n3":{"title":"Hari Aku Masuk Angin","topic":"Buku Bergambar","trans":["Begitu bangun pagi, kepalanya sakit sekali dan tenggorokannya juga sakit, jadi dia berpikir jangan-jangan dia demam. Tanuki Taro menelepon kantor dan bilang bahwa dia masuk angin dan ingin izin hari ini. Setelah itu dia pergi ke klinik di dekat rumah, menunjukkan kartu asuransi di resepsionis, lalu mengisi formulir anamnesis.","Dokter bertanya 「いつからですか」 (\"Sejak kapan?\"), jadi dia menjawab bahwa sejak tadi malam. Waktu dia bilang dia juga batuk, dokter berkata 「ただのかぜですね」 (\"Ini hanya masuk angin biasa\"). Lalu dokter menyarankan agar dia minum obat dan istirahat yang cukup.","Malam itu, Kon datang membawakan bubur. Buburnya hangat, dan rasanya enak sekali, membuat bukan hanya badan, tapi hati pun ikut terasa lega. Kalau tidur sendirian, kita bisa merasa cemas, tapi kalau ada orang yang datang menemani, rasanya jadi tenang.","Tiga hari kemudian, Tanuki Taro sudah benar-benar sehat. Dia dulu mengira pergi ke rumah sakit di Jepang agak menakutkan, tetapi setelah benar-benar pergi, ternyata tidak ada masalah. Berkat pengalaman kali ini, kalau nanti dia sakit lagi, dia bisa pergi ke rumah sakit dengan tenang."],"vocab":[{"w":"受付","m":"resepsionis, meja penerimaan"},{"w":"保険証","m":"kartu asuransi kesehatan"},{"w":"問診票","m":"formulir anamnesis"},{"w":"伝える","m":"menyampaikan, memberi tahu"},{"w":"おかゆ","m":"bubur"},{"w":"不安","m":"cemas, tidak tenang"},{"w":"心強い","m":"menenangkan, bisa diandalkan"},{"w":"すっかり","m":"sepenuhnya, benar-benar"},{"w":"実際に","m":"sungguh-sungguh, secara nyata"},{"w":"具合","m":"kondisi (badan)"}],"grammar":[{"t":"〜のではないかと思う","note":"Artinya \"kupikir jangan-jangan ...\", dipakai untuk menyatakan dugaan secara halus. Contoh: 「熱があるのではないかと思いました」"},{"t":"〜ようなN","note":"Memakai \"seperti ...\" untuk perumpamaan atau menggambarkan perasaan. Contoh: 「心までほっとするようなおいしさでした」"},{"t":"〜てみると","note":"Artinya \"setelah benar-benar mencoba, ternyata ...\", diikuti hal yang ditemukan atau hasilnya. Contoh: 「実際に行ってみると問題ありませんでした」"},{"t":"〜によって","note":"Menyatakan sebab, cara, atau \"melalui ...\". Contoh: 「今回の経験によって、次に具合が悪くなっても安心して病院へ行けるようになりました」"}]},"eh-n5-1-n2":{"title":"Pertama Kali ke Minimarket","topic":"Buku Bergambar","trans":["Tanutaro baru saja tiba di Jepang kemarin, dan hari ini dia memutuskan untuk pergi ke minimarket Jepang untuk pertama kalinya. Di dalam toko ternyata lebih terang dari yang dia bayangkan, dan onigiri, roti, serta minuman tertata penuh di rak. Meski kaget melihat banyaknya jenis barang, Tanutaro tetap berkeliling dengan hati-hati.","Setelah bimbang cukup lama, Tanutaro memilih satu bento dan satu botol teh, lalu membawanya ke kasir. Pegawai toko bertanya 「温めますか」, tetapi Tanutaro tidak mengerti artinya sehingga tidak bisa menjawab pertanyaan itu. 「温めますか」 artinya \"Mau dipanaskan?\", yaitu pertanyaan apakah bento mau dipanaskan di tempat. Setelah tahu artinya, Tanutaro menjawab, 「はい、お願いします」.","Selanjutnya pegawai toko bertanya 「袋は要りますか」, dan kali ini dia langsung mengerti artinya. Seiring bertambahnya pengalaman berbelanja, dia mungkin akan makin terbiasa sedikit demi sedikit dengan ungkapan-ungkapan baku seperti ini. Tanutaro bisa menjawab dengan tenang, 「大丈夫です」. Di situasi yang baru pertama kali dihadapi, kita memang mudah merasa tegang, tapi begitu tahu artinya, lain kali kamu bisa menghadapinya dengan percaya diri.","Bento yang sudah dipanaskan itu masih mengepul panas dan rasanya lebih enak dari yang dibayangkan. Tanutaro tampaknya merasa bahwa meski belum paham bahasanya, belanja belum tentu sulit. Karena pengalaman ini membuatnya lebih percaya diri, Tanutaro berpikir ingin pergi ke minimarket lagi dalam waktu dekat."],"vocab":["datang ke Jepang","sengaja pergi mengunjungi","tertata penuh sesak","hati-hati","memanaskan","bertanya","terbiasa","menghadapi, menangani","mengepul panas","percaya diri"],"grammar":[{"t":"〜た末(に)","note":"Menyatakan hasil akhir setelah melalui keraguan atau usaha yang panjang. Contoh: 「迷った末、たぬたろうは弁当を一つとお茶を一つ選び」"},{"t":"〜に対して","note":"Menyatakan reaksi terhadap suatu lawan bicara atau persoalan. Contoh: 「その質問に対して、たぬたろうは意味が分からず答えられなかった」"},{"t":"〜に伴って","note":"Menyatakan bahwa seiring berubahnya satu hal, hal lain ikut berubah. Contoh: 「買い物の経験が増えるに伴って、こうした決まり文句にも少しずつ慣れていくのだろう」"},{"t":"〜とは限らない","note":"Menyatakan bahwa belum tentu demikian; menyangkal anggapan yang terlalu mutlak. Contoh: 「言葉が分からないからといって、買い物が難しいとは限らない」"}]},"eh-n5-1-n3":{"title":"Pertama Kali ke Minimarket","topic":"Buku Bergambar","trans":["Tanutaro baru tiba di Jepang kemarin, dan hari ini dia memutuskan untuk mencoba pergi ke minimarket untuk pertama kalinya. Di dalam toko sangat terang, dan onigiri, roti, minuman, dan lainnya tertata penuh di rak.","Tanutaro memilih satu bento dan satu botol teh, lalu membawanya ke kasir. Lalu pegawai toko bertanya 「温めますか」, tetapi dia tidak mengerti artinya. 「温めますか」 adalah pertanyaan yang artinya \"Mau dipanaskan?\". Setelah tahu artinya, Tanutaro menjawab, 「はい、お願いします」.","Berikutnya pegawai toko bertanya 「袋はいりますか」. Kali ini dia mengerti arti pertanyaannya, jadi dia bisa menjawab dengan tenang, 「大丈夫です」.","Bento yang hangat itu jauh lebih enak dari yang dia kira. Lewat pengalaman ini, Tanutaro jadi percaya diri dan mulai ingin pergi ke minimarket lagi."],"vocab":["tiba, sampai","tertata, berjajar","memilih","pegawai toko","memanaskan","arti, makna","pertanyaan","tenang, tidak panik","pengalaman","percaya diri"],"grammar":[{"t":"〜たばかり","note":"Menyatakan sesuatu baru saja terjadi. Contoh: 「昨日日本に着いたばかりで」 artinya baru saja tiba di Jepang."},{"t":"〜ことにする","note":"Menyatakan keputusan yang dibuat sendiri oleh pembicara. Contoh: 「行ってみることにしました」 artinya memutuskan untuk mencoba pergi."},{"t":"〜ことができる","note":"Menyatakan kemampuan atau kemungkinan. Contoh: 「落ち着いて答えることができました」 artinya bisa menjawab dengan tenang."},{"t":"〜によって／〜ようになる","note":"「によって」menyatakan sebab atau cara, sedangkan 「ようになる」menyatakan perubahan. Contoh: 「この経験によって自信がつき」「思うようになりました」."}]},"eh-n5-2-n2":{"title":"駅で迷子","topic":"Buku Bergambar","trans":["Hari ini cuacanya cerah, jadi Tanutarō memutuskan naik kereta untuk pergi ke pantai. Tapi begitu sampai di stasiun, ternyata stasiunnya jauh lebih besar dari yang dia bayangkan. Di dalam stasiun penuh sesak dengan orang, sampai-sampai dia sulit memutuskan harus pergi ke arah mana. Tanutarō sama sekali tidak tahu kereta ke pantai berangkat dari peron nomor berapa.","Dia melihat peta untuk mencari petunjuk, tetapi informasinya terlalu banyak sehingga malah makin bingung. Waktu belum tentu masih longgar, jadi Tanutarō makin lama makin panik. Saat dia berdiri terpaku karena kebingungan, Kon si rubah kebetulan lewat dan menyapanya, \"Ada apa?\"","Tanutarō memberanikan diri bertanya, \"Permisi, kereta ke pantai di mana ya?\" Kon sama sekali tidak keberatan dan dengan ramah memberi tahu, \"Di peron 3, silakan naik tangga di sana.\" Bertanya kepada orang yang tidak dikenal memang butuh keberanian, tetapi berkat bertanya, kebingungannya langsung hilang. Saat sedang kesulitan, meminta bantuan orang di sekitar biasanya lebih cepat menyelesaikan masalah daripada memikirkannya sendirian.","Tanutarō mengucapkan \"Terima kasih\", lalu buru-buru berlari menaiki tangga. Meskipun waktu keberangkatan sudah mepet, dia berhasil mengejar kereta. Berkat bertemu orang yang baik hati, hari Tanutarō menuju pantai pun dimulai dengan lancar."],"vocab":["area dalam (stasiun dsb.), di dalam stasiun","sama sekali tidak tahu / tidak bisa menebak","petunjuk, pegangan","kekacauan, kebingungan","rasa gelisah, panik","(perasaan) makin lama makin kuat","berdiri terpaku di tempat","penyelesaian, hilangnya (masalah)","berlari naik","sempat, berhasil mengejar"],"grammar":[{"t":"〜ものの","note":"Berarti \"meskipun ..., tetapi ...\". Diikuti hasil yang berlawanan dengan harapan. Contoh: 「地図を確認したものの、情報が多すぎてかえって混乱してしまった」"},{"t":"〜とは限らない","note":"Berarti \"belum tentu ...\", menyangkal anggapan yang berlaku untuk semua kasus. Contoh: 「時間に余裕があるとは限らないので」"},{"t":"〜一方だ","note":"Menunjukkan suatu keadaan terus berkembang ke satu arah (memburuk atau menguat), \"makin lama makin ...\". Contoh: 「たぬたろうの焦りは募る一方だった」"},{"t":"〜にもかかわらず","note":"Berarti \"meskipun ..., tetap ...\". Klausa kedua berupa hasil yang tidak sesuai dengan kondisi klausa pertama. Contoh: 「発車時刻が迫っていたにもかかわらず、何とか電車に間に合うことができた」"}]},"eh-n5-2-n3":{"title":"駅で迷子","topic":"Buku Bergambar","trans":["Hari ini cuacanya cerah sekali, jadi Tanutarō memutuskan naik kereta untuk pergi ke pantai. Tapi ternyata stasiunnya jauh lebih besar dari yang dia bayangkan, dan banyak orang berjalan dengan terburu-buru. Tanutarō sama sekali tidak tahu kereta ke pantai berangkat dari peron nomor berapa.","Dia berpikir kalau melihat peta pasti akan tahu, tetapi malah jadi makin bingung. Waktu juga terus berlalu sedikit demi sedikit, jadi Tanutarō lama-lama merasa cemas. Saat itu, Kon si rubah kebetulan lewat, menyadari dia sedang kesulitan, lalu menyapanya.","Tanutarō bertanya dengan sopan, \"Permisi, kereta ke pantai berangkat dari mana ya?\" Kon menjawab sambil tersenyum, \"Dari peron 3. Silakan naik tangga di sana.\" Karena waktu keberangkatan kereta sudah dekat, Tanutarō mengucapkan terima kasih lalu langsung berlari.","Berkat buru-buru menaiki tangga, Tanutarō akhirnya berhasil mengejar kereta. Dia sangat berterima kasih karena ada yang menyapanya saat sedang kesulitan."],"vocab":["pergi keluar, berangkat","bayangan; membayangkan","nomor peron","malah, justru","cemas, tidak tenang","kebetulan lewat","keadaan, kondisi","sopan, teliti","keberangkatan (kereta)","sempat, berhasil mengejar"],"grammar":[{"t":"〜ことにする","note":"Menyatakan keputusan yang dibuat oleh pembicara sendiri. Contoh: 「電車に乗って海へ出かけることにしました」 artinya Tanutarō sendiri memutuskan untuk pergi ke pantai."},{"t":"〜ため(原因)","note":"Dipakai untuk menyatakan sebab atau alasan, sedikit lebih formal daripada「から」. Contoh: 「時間も少しずつ過ぎていくため、たぬたろうはだんだん不安になってきました」"},{"t":"〜おかげで","note":"Menyatakan hasil baik yang didapat berkat suatu sebab, dengan nuansa terima kasih. Contoh: 「階段を急いで上がったおかげで、たぬたろうはなんとか電車に間に合いました」"},{"t":"〜てしまう","note":"Menyatakan hasil yang disayangkan atau di luar dugaan, bisa juga menyatakan sesuatu telah selesai. Contoh: 「かえって分からなくなってしまいました」"}]},"a-n5-13-n3":{"title":"Belanja Musim Dingin","topic":"Kehidupan sehari-hari","trans":["Belakangan ini cuaca tiba-tiba jadi dingin, jadi aku berpikir untuk membeli pakaian musim dingin yang baru. Hari Sabtu, aku memutuskan pergi berbelanja ke toko bersama temanku. Aku sudah lama ingin punya mantel hitam, jadi aku berniat mencarinya.","Tapi temanku bilang, \"Yang merah juga bagus, lho,\" jadi aku sedikit bimbang. Aku tidak harus yang berwarna hitam, jadi aku memutuskan untuk bertanya kepada pegawai toko. Waktu aku bertanya, \"Boleh dicoba?\", pegawai toko dengan senang hati mengizinkanku mencobanya.","Setelah dicoba, mantel merah itu jauh lebih bagus daripada yang kubayangkan. Akhirnya, selain mantel itu, aku juga membeli sarung tangan dan syal. Semuanya warna kesukaanku, jadi aku tidak sabar memadupadankannya. Dengan ini, sepertinya aku bisa pergi keluar dengan nyaman meskipun musim dinginnya dingin."],"vocab":[{"m":"tiba-tiba, mendadak"},{"m":"mencari"},{"m":"bimbang, ragu"},{"m":"sangat memperhatikan, berpegang teguh pada (sesuatu)"},{"m":"mencoba pakaian"},{"m":"dengan senang hati, dengan rela"},{"m":"akhirnya, pada akhirnya"},{"m":"sarung tangan"},{"m":"memadupadankan, menggabungkan"},{"m":"hal yang dinantikan, kesenangan"}],"grammar":[{"t":"〜ため(に)","note":"Menyatakan sebab atau alasan, lebih formal (bahasa tulis) daripada「から」. Contoh: 「最近は急に寒くなってきたため」"},{"t":"〜ことにする","note":"Menyatakan keputusan pembicara sendiri untuk melakukan sesuatu. Contoh: 「友だちと一緒に店へ買い物に行くことにしました」"},{"t":"〜わけではない","note":"Berarti \"bukan berarti begitu\", yaitu negasi sebagian. Contoh: 「黒い色にこだわっていたわけではないので」"},{"t":"〜そうだ(dugaan dari penampilan)","note":"Dipasang pada bentuk ます kata kerja (tanpa ます) atau akar kata sifat untuk menyatakan dugaan berdasarkan penampilan atau keadaan. Contoh: 「これなら気持ちよく出かけられそうです」"}]},"a-n3-11-n4":{"title":"Pentingnya 報連相","topic":"Dunia Kerja","trans":["Di perusahaan Jepang, 「報連相」 dikatakan sangat penting. Ini adalah istilah gabungan dari tiga hal: 「報告」「連絡」「相談」, yaitu melapor, mengabari, dan berkonsultasi.","Menyampaikan kepada atasan sejauh mana pekerjaan sudah berjalan disebut melapor (報告). Kalau ada masalah, kamu harus segera melapor. Mengabari (連絡) berarti menyampaikan hal yang diperlukan kepada orang yang terkait. Saat jadwal berubah, penting untuk segera mengabari.","Berkonsultasi (相談) berarti menanyakan hal yang tidak bisa kamu putuskan sendiri kepada atasan atau rekan satu perusahaan. Bahkan untuk hal kecil, kalau kamu berkonsultasi, kamu bisa terhindar dari kesalahan besar. Bagi orang asing, mungkin awalnya terasa sulit. Sebab, di negara sendiri, memikirkan dan menjalankan pekerjaan sendirian kadang justru dinilai baik. Namun, kalau kamu menjalankan 報連相 dengan benar, kamu akan lebih mudah dipercaya oleh anggota tim. Kalau kamu ingin bekerja di perusahaan Jepang, memahami cara berpikir ini akan sangat berguna."],"vocab":["laporan, melapor","kabar, menghubungi","konsultasi, berunding","masalah","rencana, jadwal","penting, berharga","kegagalan, kesalahan","orang asing","percaya","berguna, bermanfaat"],"grammar":[{"t":"〜たら","note":"Menyatakan \"kalau ～ / begitu ～\". Contoh: 「問題が起きたら、すぐに報告しなければなりません」"},{"t":"〜なければなりません","note":"Menyatakan \"harus ～\". Contoh: 「すぐに報告しなければなりません」"},{"t":"〜ば","note":"Menyatakan syarat \"asalkan ～ maka\". Contoh: 「小さなことでも相談すれば、大きな失敗をしないで済みます」"},{"t":"〜かもしれません","note":"Menyatakan \"mungkin ～\", untuk menyampaikan kemungkinan. Contoh: 「最初は難しいと思うかもしれません」"}]},"a-n5-13-n2":{"title":"Belanja di Musim Dingin","topic":"Kehidupan","trans":["Akhir-akhir ini dingin di pagi dan malam hari makin menusuk, sampai terasa langsung di kulit bahwa musim dingin yang sesungguhnya telah tiba. Seiring suhu yang turun, aku mulai berpikir sebentar lagi butuh pakaian penghangat baru. Maka pada hari Sabtu, aku memutuskan pergi ke sebuah toko untuk berbelanja bersama temanku.","Aku ingin mantel hitam, jadi dari awal aku berniat hanya mencari yang serba hitam. Tapi temanku bilang mantel merah mungkin juga cocok untukku, lalu menyarankan pilihan lain. Aku pikir memang belum tentu hitam adalah satu-satunya jawaban yang benar, jadi aku mencoba mengambil mantel merah yang menarik perhatianku. Setelah bertanya kepada pegawai toko, 「着てもいいですか」, aku pun benar-benar mencobanya.","Setelah benar-benar kupakai, mantel merah itu lebih indah daripada yang kubayangkan, sampai-sampai aku terpana memandangnya. Akhirnya, aku memutuskan membeli mantel merah itu, bukan yang hitam. Selain itu, aku juga membeli sarung tangan dan syal sekalian, sehingga persiapan menghadapi dingin pun hampir lengkap. Ketiga barang yang kupilih semuanya berwarna kesukaanku, dan aku juga suka dengan keserasian warnanya secara keseluruhan.","Sebelum berbelanja, aku mengira 「黒でなければならない」, tetapi berkat satu kalimat dari temanku, wawasanku jadi lebih luas. Dengan tidak terpaku pada selera sendiri dan mau mendengarkan pendapat orang lain, kadang muncul penemuan baru. Justru karena ini musim dingin yang keras, aku ingin mengenakan pakaian yang kusukai dan menjalani musim dingin ini dengan perasaan positif."],"vocab":["suhu yang turun drastis, dingin yang makin menusuk","pakaian penghangat","cocok, serasi","merekomendasikan, menyarankan","mengenakan (pakaian)","terpana, terpesona memandang","secara garis besar, hampir semuanya","bersikeras, kukuh pada pendapat sendiri","wawasan, cakrawala pandang"],"grammar":[{"t":"〜に伴って","note":"Menyatakan bahwa seiring satu perubahan terjadi, perubahan lain juga terjadi bersamaan. Contoh: 「気温が下がるに伴って、そろそろ新しい防寒着が必要だと考えるようになった」"},{"t":"〜とは限らない","note":"Menyatakan \"belum tentu\" atau \"tidak selalu\", untuk menyangkal anggapan yang terlalu mutlak. Contoh: 「確かに黒だけが正解とは限らないと思い」"},{"t":"〜ず(に)","note":"Bentuk negatif ragam tulis dari 「ない」, setara dengan 「〜ないで」. する menjadi 「せず」. Contoh: 「自分の好みに固執せず」"},{"t":"〜からこそ","note":"Menekankan \"justru karena alasan ini\", dengan nada yang tegas. Contoh: 「寒さの厳しい季節だからこそ」"}]}};
